-- Carga solo las preguntas del Auxiliar del Ayuntamiento de Madrid (aux-ayto-mad) sin tocar las demás.
-- Equivale a las filas de esta oposición en p01..p10; úsalo para no tener que recargar todo el banco.
delete from public.preguntas where oposicion='aux-ayto-mad';
on conflict (id) do update set oposicion=excluded.oposicion,tema=excluded.tema,pregunta=excluded.pregunta,opciones=excluded.opciones,correcta=excluded.correcta,articulo=excluded.articulo,explicacion=excluded.explicacion,examen=excluded.examen;
