insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:1-4e230788ef','aux-ayto-mad',1,'¿Cuáles son los valores superiores del ordenamiento jurídico según la Constitución?','["La justicia, la paz, la igualdad y la democracia", "La libertad, la justicia, la igualdad y el pluralismo político", "La libertad, la seguridad, la igualdad y la solidaridad"]'::jsonb,1,'Art. 1.1 CE','España propugna como valores superiores la libertad, la justicia, la igualdad y el pluralismo político.',null),
('aux-ayto-mad:1-04262b2364','aux-ayto-mad',1,'Según la Constitución, la soberanía nacional reside en:','["El pueblo español", "El Rey", "La Nación y las Comunidades Autónomas"]'::jsonb,0,'Art. 1.2 CE','La soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado.',null),
('aux-ayto-mad:1-c8fa2d2b37','aux-ayto-mad',1,'La forma política del Estado español es:','["La Monarquía constitucional", "La Monarquía parlamentaria", "El Estado autonómico"]'::jsonb,1,'Art. 1.3 CE','La forma política del Estado español es la Monarquía parlamentaria.',null),
('aux-ayto-mad:1-4f7ac99224','aux-ayto-mad',1,'Respecto al castellano, todos los españoles tienen:','["El deber de conocerlo y el derecho a usarlo", "El derecho a conocerlo y el deber de usarlo", "Solo el deber de conocerlo"]'::jsonb,0,'Art. 3.1 CE','Todos los españoles tienen el deber de conocer el castellano y el derecho a usarlo.',null),
('aux-ayto-mad:1-b2b5de77ad','aux-ayto-mad',1,'¿Cómo es la bandera de España según la Constitución?','["Tres franjas verticales roja, amarilla y roja, siendo la amarilla de doble anchura que cada roja", "Tres franjas horizontales roja, amarilla y roja, siendo la amarilla de doble anchura que cada roja", "Tres franjas horizontales amarilla, roja y amarilla, siendo la roja de doble anchura que cada amarilla"]'::jsonb,1,'Art. 4.1 CE','Tres franjas horizontales roja, amarilla y roja, siendo la amarilla de doble anchura que cada una de las rojas.',null),
('aux-ayto-mad:1-2768ee756b','aux-ayto-mad',1,'¿Cuál es la capital del Estado según la Constitución?','["La sede del Gobierno, sea cual sea", "La villa de Madrid", "La que determine una ley orgánica"]'::jsonb,1,'Art. 5 CE','La capital del Estado es la villa de Madrid.',null),
('aux-ayto-mad:1-2e31638cad','aux-ayto-mad',1,'Según el art. 6, los partidos políticos:','["Necesitan autorización administrativa previa", "Expresan el pluralismo político", "Pueden tener estructura interna no democrática"]'::jsonb,1,'Art. 6 CE','Los partidos expresan el pluralismo político y su estructura interna y funcionamiento deben ser democráticos.',null),
('aux-ayto-mad:1-bfc1c0f01c','aux-ayto-mad',1,'¿Cuál de estos principios NO garantiza el art. 9.3 de la Constitución?','["La interdicción de la arbitrariedad de los poderes públicos", "La jerarquía normativa", "La retroactividad de las disposiciones sancionadoras desfavorables"]'::jsonb,2,'Art. 9.3 CE','Se garantiza lo contrario: la irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales.',null),
('aux-ayto-mad:1-229a35ba34','aux-ayto-mad',1,'Las normas sobre derechos fundamentales se interpretan de conformidad con:','["La jurisprudencia del Tribunal Supremo y los tratados ratificados por España, en ese orden de prelación", "La Declaración Universal de Derechos Humanos y las leyes orgánicas que los desarrollen", "La Declaración Universal de Derechos Humanos y los tratados ratificados por España"]'::jsonb,2,'Art. 10.2 CE','Se interpretan conforme a la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales ratificados por España.',null),
('aux-ayto-mad:1-47b46601ce','aux-ayto-mad',1,'Según la Constitución, ¿puede un español de origen ser privado de su nacionalidad?','["Sí, por sentencia firme", "No, en ningún caso", "Sí, por decisión del Gobierno"]'::jsonb,1,'Art. 11.2 CE','Ningún español de origen podrá ser privado de su nacionalidad.',null),
('aux-ayto-mad:1-f8078461b2','aux-ayto-mad',1,'¿A qué edad son mayores de edad los españoles según la Constitución?','["21 años", "18 años", "La fija cada Comunidad Autónoma"]'::jsonb,1,'Art. 12 CE','Los españoles son mayores de edad a los dieciocho años.',null),
('aux-ayto-mad:1-e711cb1036','aux-ayto-mad',1,'Los extranjeros pueden ejercer el derecho de sufragio activo y pasivo:','["En las elecciones municipales, sin necesidad de criterios de reciprocidad", "En las elecciones municipales y autonómicas, atendiendo a criterios de reciprocidad", "En las elecciones municipales, atendiendo a criterios de reciprocidad"]'::jsonb,2,'Art. 13.2 CE','Solo los españoles son titulares del art. 23, salvo el sufragio activo y pasivo en las elecciones municipales con reciprocidad. Este apartado se reformó en 1992.',null),
('aux-ayto-mad:1-b31d95397f','aux-ayto-mad',1,'Según el art. 15 de la Constitución, la pena de muerte:','["Queda abolida, salvo lo que dispongan las leyes penales militares para tiempos de guerra", "Queda abolida en todo caso, sin ninguna excepción en el texto constitucional", "Queda abolida, salvo para los delitos de terrorismo que determine una ley orgánica"]'::jsonb,0,'Art. 15 CE','Queda abolida la pena de muerte, salvo lo que puedan disponer las leyes penales militares para tiempos de guerra.',null),
('aux-ayto-mad:1-58ebff311d','aux-ayto-mad',1,'¿Cuánto puede durar como máximo la detención preventiva antes de poner al detenido en libertad o a disposición judicial?','["5 días", "72 horas", "48 horas"]'::jsonb,1,'Art. 17.2 CE','La detención preventiva no puede durar más de lo estrictamente necesario y, como máximo, 72 horas.',null),
('aux-ayto-mad:1-73620ada06','aux-ayto-mad',1,'¿Qué procedimiento regula la ley para la inmediata puesta a disposición judicial de toda persona detenida ilegalmente?','["La cuestión prejudicial", "El habeas corpus", "El recurso de inconstitucionalidad"]'::jsonb,1,'Art. 17.4 CE','La ley regula el procedimiento de habeas corpus.',null),
('aux-ayto-mad:1-f288a8f0a9','aux-ayto-mad',1,'¿En qué casos se puede entrar en un domicilio según la Constitución?','["Con consentimiento del titular, resolución judicial o en caso de flagrante delito", "Solo con resolución judicial o en caso de flagrante delito", "Con consentimiento del titular, resolución judicial o autorización de la autoridad gubernativa"]'::jsonb,0,'Art. 18.2 CE','Ninguna entrada o registro sin consentimiento del titular o resolución judicial, salvo flagrante delito.',null),
('aux-ayto-mad:1-37f88a9c1d','aux-ayto-mad',1,'El secuestro de publicaciones y otros medios de información solo puede acordarse:','["Por orden del Ministerio del Interior", "Por la autoridad gubernativa en casos urgentes", "En virtud de resolución judicial"]'::jsonb,2,'Art. 20.5 CE','Solo podrá acordarse el secuestro en virtud de resolución judicial.',null),
('aux-ayto-mad:1-9ff2bc8d8e','aux-ayto-mad',1,'Para reuniones en lugares de tránsito público y manifestaciones se exige:','["Comunicación previa a la autoridad", "Autorización judicial", "Autorización previa de la autoridad"]'::jsonb,0,'Art. 21.2 CE','Se da comunicación previa a la autoridad, que solo puede prohibirlas por razones fundadas de alteración del orden público.',null),
('aux-ayto-mad:1-8d21a65a7a','aux-ayto-mad',1,'¿Qué asociaciones prohíbe expresamente la Constitución?','["Las no inscritas en el registro y las de carácter paramilitar", "Las de carácter paramilitar y las formadas solo por extranjeros", "Las secretas y las de carácter paramilitar"]'::jsonb,2,'Art. 22.5 CE','Se prohíben las asociaciones secretas y las de carácter paramilitar.',null),
('aux-ayto-mad:1-feeb15f476','aux-ayto-mad',1,'El art. 23.2 reconoce el derecho a acceder a las funciones y cargos públicos:','["En condiciones de igualdad, siempre que se posea la nacionalidad española de origen", "Conforme a los méritos que libremente aprecie cada Administración", "En condiciones de igualdad, con los requisitos que señalen las leyes"]'::jsonb,2,'Art. 23.2 CE','Los ciudadanos tienen derecho a acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen las leyes.',null),
('aux-ayto-mad:1-8abe10e485','aux-ayto-mad',1,'Según el art. 24.2, todos tienen derecho:','["A elegir el juez que les juzgue", "Al Juez ordinario predeterminado por la ley", "A un tribunal especial según su profesión"]'::jsonb,1,'Art. 24.2 CE','Todos tienen derecho al Juez ordinario predeterminado por la ley, a la defensa y a la asistencia de letrado, entre otros.',null),
('aux-ayto-mad:1-d436929f28','aux-ayto-mad',1,'La Administración civil puede imponer sanciones que impliquen privación de libertad:','["Sí, en casos graves", "Solo durante el estado de alarma", "No, en ningún caso"]'::jsonb,2,'Art. 25.3 CE','La Administración civil no podrá imponer sanciones que, directa o subsidiariamente, impliquen privación de libertad.',null),
('aux-ayto-mad:1-c44dcc6246','aux-ayto-mad',1,'Según la Constitución, la enseñanza básica es:','["Obligatoria y de pago", "Obligatoria y gratuita", "Voluntaria y de pago"]'::jsonb,1,'Art. 27.4 CE','La enseñanza básica es obligatoria y gratuita.',null),
('aux-ayto-mad:1-664bf032b9','aux-ayto-mad',1,'El derecho a la huelga de los trabajadores se reconoce en:','["El art. 35.1", "El art. 37.2", "El art. 28.2"]'::jsonb,2,'Art. 28.2 CE','El art. 28.2 reconoce el derecho a la huelga de los trabajadores para la defensa de sus intereses.',null),
('aux-ayto-mad:1-f00371600c','aux-ayto-mad',1,'Según el art. 30.1, defender a España es para los españoles:','["Una obligación exclusiva de las Fuerzas Armadas", "Solo un derecho", "Un derecho y un deber"]'::jsonb,2,'Art. 30.1 CE','Los españoles tienen el derecho y el deber de defender a España.',null),
('aux-ayto-mad:1-6d2a942269','aux-ayto-mad',1,'El art. 32.1 reconoce el derecho a contraer matrimonio:','["Al hombre y la mujer, con plena igualdad jurídica", "Al hombre y la mujer, a partir de la edad que fije cada Comunidad Autónoma", "Al hombre y la mujer, previa autorización del Registro Civil"]'::jsonb,0,'Art. 32.1 CE','El hombre y la mujer tienen derecho a contraer matrimonio con plena igualdad jurídica.',null),
('aux-ayto-mad:1-0a0b33a6b2','aux-ayto-mad',1,'¿Qué artículo modificó la reforma constitucional de 2024?','["El art. 69.3, sobre la elección de los senadores provinciales", "El art. 135, sobre estabilidad presupuestaria", "El art. 49, sobre las personas con discapacidad"]'::jsonb,2,'Art. 49 CE','La reforma de febrero de 2024 modificó el art. 49. Las anteriores fueron la de 1992 (art. 13.2) y la de 2011 (art. 135); la de mayo de 2026 modificó el art. 69.3.',null),
('aux-ayto-mad:1-e5e8d587c5','aux-ayto-mad',1,'Según el art. 53.1, el ejercicio de los derechos del Capítulo II solo puede regularse:','["Por ley de las Comunidades Autónomas exclusivamente", "Por ley, que deberá respetar su contenido esencial", "Por reglamento del Gobierno"]'::jsonb,1,'Art. 53.1 CE','Vinculan a todos los poderes públicos y solo por ley, que respete su contenido esencial, podrá regularse su ejercicio.',null),
('aux-ayto-mad:1-b03e4bc908','aux-ayto-mad',1,'¿Qué derechos pueden protegerse mediante recurso de amparo ante el Tribunal Constitucional?','["Todos los derechos del Capítulo II del Título I, incluida su Sección 2.ª", "La Sección 1.ª del Capítulo II, pero no la igualdad del art. 14", "El art. 14, la Sección 1.ª del Capítulo II y la objeción de conciencia del art. 30"]'::jsonb,2,'Art. 53.2 CE','Cabe amparo para el art. 14, la Sección 1.ª del Capítulo II y la objeción de conciencia del art. 30, en su caso tras acudir a los tribunales ordinarios.',null),
('aux-ayto-mad:1-e2f4f0525e','aux-ayto-mad',1,'El Defensor del Pueblo es:','["Alto comisionado de las Cortes Generales, designado por estas", "Alto comisionado del Gobierno, designado por el Consejo de Ministros", "Alto comisionado de las Cortes Generales, designado por el Rey"]'::jsonb,0,'Art. 54 CE','Es alto comisionado de las Cortes Generales, designado por ellas para la defensa de los derechos del Título I.',null),
('aux-ayto-mad:1-72720b6729','aux-ayto-mad',1,'Según el art. 55.1, los derechos pueden suspenderse cuando se declare el estado de:','["Alarma, excepción o sitio", "Solo sitio", "Excepción o sitio"]'::jsonb,2,'Art. 55.1 CE','La suspensión general cabe en el estado de excepción o de sitio, no en el de alarma.',null),
('aux-ayto-mad:1-813d15f5a8','aux-ayto-mad',1,'La suspensión individual de derechos para investigaciones sobre bandas armadas o terrorismo se regula mediante:','["Ley orgánica", "Ley ordinaria", "Real decreto"]'::jsonb,0,'Art. 55.2 CE','Una ley orgánica puede determinar la suspensión individual de los derechos de los arts. 17.2 y 18.2 y 3 en esas investigaciones.',null),
('aux-ayto-mad:1-13b6602a03','aux-ayto-mad',1,'¿Qué principios garantiza el art. 9.3 de la Constitución en relación con las normas?','["La legalidad, la jerarquía normativa y la retroactividad de las normas favorables", "La legalidad, la jerarquía normativa y la publicidad de las normas", "La legalidad, la competencia normativa y la publicidad de las normas"]'::jsonb,1,'Art. 9.3 CE','Garantiza, entre otros, el principio de legalidad, la jerarquía normativa y la publicidad de las normas.',null),
('aux-ayto-mad:1-28cdf5fb8b','aux-ayto-mad',1,'Según el art. 17.1, toda persona tiene derecho a:','["Un trabajo remunerado", "La libertad y a la seguridad", "La asistencia jurídica gratuita en cualquier caso"]'::jsonb,1,'Art. 17.1 CE','Toda persona tiene derecho a la libertad y a la seguridad.',null),
('aux-ayto-mad:1-658e78e4db','aux-ayto-mad',1,'Según el art. 31.2, la programación y ejecución del gasto público responden a los criterios de:','["Rentabilidad y beneficio", "Discrecionalidad política", "Eficiencia y economía"]'::jsonb,2,'Art. 31.2 CE','El gasto público realizará una asignación equitativa de los recursos públicos, y su programación y ejecución responderán a los criterios de eficiencia y economía.',null),
('aux-ayto-mad:1-05165f7d86','aux-ayto-mad',1,'Según el art. 18.4, la ley limitará el uso de:','["Los medios de comunicación social de titularidad pública", "Las armas de fuego, para garantizar la seguridad ciudadana", "La informática, para garantizar el honor y la intimidad"]'::jsonb,2,'Art. 18.4 CE','La ley limitará el uso de la informática para garantizar el honor y la intimidad personal y familiar.',null),
('aux-ayto-mad:1-3f91d2acbc','aux-ayto-mad',1,'El ejercicio de la libertad de expresión e información:','["Puede someterse a censura previa en estados de alarma, excepción y sitio, por ley orgánica", "Requiere autorización previa en los medios de titularidad pública", "No puede restringirse mediante ningún tipo de censura previa"]'::jsonb,2,'Art. 20.2 CE','El ejercicio de estos derechos no puede restringirse mediante ningún tipo de censura previa.',null),
('aux-ayto-mad:1-3186f16bd4','aux-ayto-mad',1,'El secreto de las comunicaciones puede levantarse:','["Por decisión del Gobierno", "Mediante resolución judicial", "Por orden policial"]'::jsonb,1,'Art. 18.3 CE','Se garantiza el secreto de las comunicaciones, salvo resolución judicial.',null),
('aux-ayto-mad:1-d9834042ea','aux-ayto-mad',1,'Las demás lenguas españolas distintas del castellano:','["Solo son oficiales en el ámbito educativo de cada Comunidad Autónoma", "Son oficiales en las respectivas Comunidades Autónomas, pero solo cuando lo establezca una ley orgánica estatal", "Son también oficiales en las respectivas Comunidades Autónomas de acuerdo con sus Estatutos"]'::jsonb,2,'Art. 3.2 CE','Son oficiales en sus Comunidades Autónomas de acuerdo con sus Estatutos.',null),
('aux-ayto-mad:1-773b494482','aux-ayto-mad',1,'Mediante ley podrán regularse los deberes de los ciudadanos en los casos de:','["Crisis económica grave declarada por el Gobierno", "Cambio de Gobierno o estado de alarma", "Grave riesgo, catástrofe o calamidad pública"]'::jsonb,2,'Art. 30.4 CE','Podrán regularse los deberes de los ciudadanos en los casos de grave riesgo, catástrofe o calamidad pública.',null),
('aux-ayto-mad:1-6f015125b8','aux-ayto-mad',1,'La libertad ideológica, religiosa y de culto tiene como única limitación en sus manifestaciones:','["La necesaria para el mantenimiento del orden público protegido por la ley", "La autorización gubernativa previa", "La moral pública y las buenas costumbres, según determine la ley"]'::jsonb,0,'Art. 16.1 CE','Sin más limitación, en sus manifestaciones, que la necesaria para el mantenimiento del orden público protegido por la ley.',null),
('aux-ayto-mad:1-136f7c32d9','aux-ayto-mad',1,'Según el art. 16.3, ¿alguna confesión tendrá carácter estatal?','["No, ninguna confesión tendrá carácter estatal", "Sí, la católica", "Las que tengan más de un millón de fieles"]'::jsonb,0,'Art. 16.3 CE','Ninguna confesión tendrá carácter estatal, aunque los poderes públicos mantendrán relaciones de cooperación con la Iglesia Católica y las demás confesiones.',null),
('aux-ayto-mad:1-ee2847158a','aux-ayto-mad',1,'Los principios del Capítulo III del Título I (principios rectores de la política social y económica):','["Solo vinculan al Parlamento, y son directamente exigibles ante los tribunales ordinarios por cualquier ciudadano", "Informarán la legislación positiva, la práctica judicial y la actuación de los poderes públicos", "Informarán la legislación positiva, pero no la práctica judicial ni la actuación de la Administración"]'::jsonb,1,'Art. 53.3 CE','Informarán la legislación positiva, la práctica judicial y la actuación de los poderes públicos; solo podrán alegarse ante la jurisdicción ordinaria según las leyes que los desarrollen.',null),
('aux-ayto-mad:1-d4181563d2','aux-ayto-mad',1,'El derecho a comunicar o recibir información, según el art. 20.1 d), se refiere a información:','["Autorizada", "Veraz", "Oficial"]'::jsonb,1,'Art. 20.1 d) CE','Se reconoce el derecho a comunicar o recibir libremente información veraz por cualquier medio de difusión.',null),
('aux-ayto-mad:1-eed8ce60ff','aux-ayto-mad',1,'Los poderes públicos garantizan el derecho de los padres a que sus hijos reciban:','["Educación en su lengua materna en todo caso", "La formación religiosa y moral que esté de acuerdo con sus propias convicciones", "La formación religiosa y moral de la confesión mayoritaria, salvo renuncia expresa de los padres o tutores"]'::jsonb,1,'Art. 27.3 CE','Garantizan que los hijos reciban la formación religiosa y moral acorde con las convicciones de sus padres.',null),
('aux-ayto-mad:1-8831d69530','aux-ayto-mad',1,'El principio de legalidad del art. 25.1 establece que nadie puede ser condenado o sancionado por acciones u omisiones que:','["En el momento de dictarse la resolución no constituyan delito, falta o infracción administrativa", "En el momento de producirse no constituyan delito según la ley penal, aunque sí infracción según un reglamento", "En el momento de producirse no constituyan delito, falta o infracción administrativa, según la legislación vigente"]'::jsonb,2,'Art. 25.1 CE','Nadie puede ser condenado o sancionado por acciones u omisiones que, cuando se produjeron, no constituían delito, falta o infracción administrativa.',null),
('aux-ayto-mad:1-b25ce1e2ad','aux-ayto-mad',1,'Según el art. 14, los españoles son iguales ante la ley sin que pueda prevalecer discriminación por razón de:','["Sexo, raza, nacionalidad, ideología y orientación sexual, pero no por cualquier otra condición o circunstancia personal o social", "Nacimiento, raza, sexo, religión, opinión o cualquier otra condición, salvo las circunstancias económicas y sociales, que regulan las leyes", "Nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social"]'::jsonb,2,'Art. 14 CE','No puede prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.',null),
('aux-ayto-mad:1-1f3c680b81','aux-ayto-mad',1,'Son ilegales las asociaciones que:','["Persigan fines o utilicen medios tipificados como delito", "Reciban subvenciones públicas sin haberse inscrito previamente en el registro", "No estén inscritas en un registro"]'::jsonb,0,'Art. 22.2 CE','Las asociaciones que persigan fines o utilicen medios tipificados como delito son ilegales.',null),
('aux-ayto-mad:1-57c67ff28f','aux-ayto-mad',1,'La nacionalidad española se adquiere, se conserva y se pierde:','["Por decisión del Gobierno, mediante real decreto acordado en Consejo de Ministros", "Solo por nacimiento o por residencia legal continuada", "De acuerdo con lo establecido por la ley"]'::jsonb,2,'Art. 11.1 CE','Se adquiere, conserva y pierde de acuerdo con lo establecido por la ley.',null),
('aux-ayto-mad:1-518bf2e642','aux-ayto-mad',1,'El art. 40.2 encomienda a los poderes públicos garantizar el descanso necesario mediante:','["La limitación de la jornada laboral y las vacaciones periódicas retribuidas", "La limitación de la jornada laboral y los permisos retribuidos que fije cada convenio colectivo", "La semana laboral de cuatro días y la jornada continua"]'::jsonb,0,'Art. 40.2 CE','Mediante la limitación de la jornada laboral, las vacaciones periódicas retribuidas y la promoción de centros adecuados.',null),
('aux-ayto-mad:1-f7ff3996e0','aux-ayto-mad',1,'El derecho de reunión pacífica y sin armas:','["No necesita autorización previa", "Requiere autorización del Delegado del Gobierno", "Solo se ejerce en locales cerrados"]'::jsonb,0,'Art. 21.1 CE','Se reconoce el derecho de reunión pacífica y sin armas, cuyo ejercicio no necesita autorización previa.',null),
('aux-ayto-mad:1-2c769a8fd5','aux-ayto-mad',1,'Según el art. 10.1, son fundamento del orden político y de la paz social:','["La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás", "La monarquía parlamentaria, la soberanía nacional y la unidad de la Nación española", "La unidad de mercado y la libertad de empresa"]'::jsonb,0,'Art. 10.1 CE','Lo son la dignidad de la persona, sus derechos inviolables, el libre desarrollo de la personalidad y el respeto a la ley y a los derechos de los demás.',null),
('aux-ayto-mad:1-47ddda9cb4','aux-ayto-mad',1,'La estructura interna y el funcionamiento de los Colegios Profesionales deberán ser:','["Secretos", "Fijados por el Gobierno", "Democráticos"]'::jsonb,2,'Art. 36 CE','La ley regulará los Colegios Profesionales, cuya estructura interna y funcionamiento deberán ser democráticos.',null),
('aux-ayto-mad:1-50bfc7b225','aux-ayto-mad',1,'Según el art. 7, los sindicatos de trabajadores y las asociaciones empresariales deben tener:','["Una estructura interna y un funcionamiento democráticos", "Autorización administrativa previa", "Un número mínimo de afiliados que fije la ley orgánica correspondiente"]'::jsonb,0,'Art. 7 CE','Su estructura interna y funcionamiento deberán ser democráticos.',null),
('aux-ayto-mad:1-781c737fe7','aux-ayto-mad',1,'La riqueza de las distintas modalidades lingüísticas de España es, según la Constitución:','["Un límite a la libertad de expresión", "Un asunto de las Comunidades sin protección constitucional", "Un patrimonio cultural objeto de especial respeto y protección"]'::jsonb,2,'Art. 3.3 CE','Es un patrimonio cultural que será objeto de especial respeto y protección.',null),
('aux-ayto-mad:1-b8461aa55d','aux-ayto-mad',1,'La ley garantiza el derecho a la negociación colectiva laboral y:','["La prohibición de los convenios de empresa", "La fuerza vinculante de los convenios", "La aprobación de los convenios por el Gobierno"]'::jsonb,1,'Art. 37.1 CE','La ley garantizará el derecho a la negociación colectiva laboral, así como la fuerza vinculante de los convenios.',null),
('aux-ayto-mad:1-72f00df4e3','aux-ayto-mad',1,'Los extranjeros gozan en España de las libertades públicas del Título I:','["En ningún caso, salvo los derechos inherentes a la dignidad humana", "En igualdad absoluta con los españoles, incluido el derecho de sufragio en todas las elecciones", "En los términos que establezcan los tratados y la ley"]'::jsonb,2,'Art. 13.1 CE','Gozarán de las libertades públicas que garantiza el Título I en los términos que establezcan los tratados y la ley.',null),
('aux-ayto-mad:1-202234a551','aux-ayto-mad',1,'Las libertades del art. 20 tienen su límite, especialmente, en:','["La seguridad nacional, el orden público, los intereses económicos del Estado y las instrucciones del Gobierno en materia de comunicación", "El derecho al honor, a la intimidad, a la propia imagen y la protección de la juventud y de la infancia", "La opinión mayoritaria de la sociedad, los intereses económicos del Estado y las instrucciones del Gobierno sobre la información pública"]'::jsonb,1,'Art. 20.4 CE','Tienen su límite en los demás derechos del Título I y, especialmente, en el honor, la intimidad, la propia imagen y la protección de la juventud y la infancia.',null),
('aux-ayto-mad:1-3f16595c92','aux-ayto-mad',1,'Las penas privativas de libertad y las medidas de seguridad están orientadas a:','["La reeducación y la reinserción social, y no pueden consistir en trabajos forzados", "La reeducación y la reinserción social, y pueden incluir trabajos forzados en los casos que prevea la ley", "El trabajo obligatorio en beneficio de la comunidad y la compensación económica a la víctima del delito"]'::jsonb,0,'Art. 25.2 CE','Están orientadas hacia la reeducación y reinserción social y no podrán consistir en trabajos forzados.',null),
('aux-ayto-mad:1-3bc242387e','aux-ayto-mad',1,'Las Fuerzas Armadas están constituidas, según la Constitución, por:','["El Ejército de Tierra, la Armada y el Ejército del Aire", "El Ejército de Tierra y la Policía Nacional", "Las Fuerzas y Cuerpos de Seguridad del Estado"]'::jsonb,0,'Art. 8.1 CE','Las constituyen el Ejército de Tierra, la Armada y el Ejército del Aire.',null),
('aux-ayto-mad:1-6dfea1c45c','aux-ayto-mad',1,'Según el art. 33.3, nadie podrá ser privado de sus bienes y derechos sino:','["Por causa justificada de utilidad pública o interés social, sin indemnización cuando así lo decida el Gobierno mediante real decreto", "Por deudas con particulares reconocidas en sentencia firme", "Por causa justificada de utilidad pública o interés social, mediante la correspondiente indemnización y de conformidad con la ley"]'::jsonb,2,'Art. 33.3 CE','Solo por causa justificada de utilidad pública o interés social, con indemnización y conforme a la ley.',null),
('aux-ayto-mad:1-782a8d0457','aux-ayto-mad',1,'Según el art. 30.3, podrá establecerse:','["Un impuesto especial para la defensa nacional y la protección civil", "Un servicio civil para el cumplimiento de fines de interés general", "Un servicio militar universitario"]'::jsonb,1,'Art. 30.3 CE','Podrá establecerse un servicio civil para el cumplimiento de fines de interés general.',null),
('aux-ayto-mad:1-a1d3c9fa09','aux-ayto-mad',1,'Según el art. 43.3, los poderes públicos fomentarán:','["La educación sanitaria, la educación física y el deporte", "La educación física y el deporte escolar, pero no la educación sanitaria", "La medicina preventiva privada mediante conciertos con las mutuas sanitarias"]'::jsonb,0,'Art. 43.3 CE','Fomentarán la educación sanitaria, la educación física y el deporte, y facilitarán la adecuada utilización del ocio.',null),
('aux-ayto-mad:1-76e027ed85','aux-ayto-mad',1,'Según el art. 33.1, se reconoce el derecho:','["A la propiedad privada y a una vivienda en propiedad para cada familia", "A la herencia, pero solo entre cónyuges y descendientes", "A la propiedad privada y a la herencia"]'::jsonb,2,'Art. 33.1 CE','Se reconoce el derecho a la propiedad privada y a la herencia.',null),
('aux-ayto-mad:1-b5138fc439','aux-ayto-mad',1,'Según el art. 38, se reconoce la libertad de empresa en el marco de:','["La economía de mercado", "La economía cooperativa exclusivamente", "La planificación central obligatoria"]'::jsonb,0,'Art. 38 CE','Se reconoce la libertad de empresa en el marco de la economía de mercado.',null),
('aux-ayto-mad:1-6f8a17b183','aux-ayto-mad',1,'Según el art. 35.1, todos los españoles tienen:','["Solo el derecho al trabajo", "Derecho a no trabajar sin consecuencias", "El deber de trabajar y el derecho al trabajo"]'::jsonb,2,'Art. 35.1 CE','Tienen el deber de trabajar y el derecho al trabajo, a la libre elección de profesión u oficio y a una remuneración suficiente.',null),
('aux-ayto-mad:1-f57d7307b4','aux-ayto-mad',1,'Según el art. 28.1, respecto a la libertad sindical:','["Nadie podrá ser obligado a afiliarse a un sindicato", "La afiliación es obligatoria para los funcionarios", "Solo pueden sindicarse los trabajadores fijos"]'::jsonb,0,'Art. 28.1 CE','Todos tienen derecho a sindicarse libremente y nadie podrá ser obligado a afiliarse a un sindicato.',null),
('aux-ayto-mad:1-fe0b778e7e','aux-ayto-mad',1,'El derecho de petición, según el art. 29.1:','["Requiere abogado", "Es individual y colectivo, por escrito", "Solo es individual y verbal"]'::jsonb,1,'Art. 29.1 CE','Todos los españoles tienen el derecho de petición individual y colectiva, por escrito.',null),
('aux-ayto-mad:1-5f7947f5b0','aux-ayto-mad',1,'El art. 43 reconoce el derecho a:','["La protección de la salud", "La elección libre de médico en todo caso", "La asistencia sanitaria privada gratuita"]'::jsonb,0,'Art. 43.1 CE','Se reconoce el derecho a la protección de la salud.',null),
('aux-ayto-mad:1-18b7c98a6d','aux-ayto-mad',1,'El art. 47 reconoce a todos los españoles el derecho a:','["Disfrutar de una vivienda digna, que los poderes públicos deben adjudicar directamente a quien la solicite", "Una ayuda pública al alquiler en todo caso, de cuantía fija", "Disfrutar de una vivienda digna y adecuada"]'::jsonb,2,'Art. 47 CE','Todos los españoles tienen derecho a disfrutar de una vivienda digna y adecuada.',null),
('aux-ayto-mad:1-58d2add35f','aux-ayto-mad',1,'Los poderes públicos garantizarán la conservación y promoverán el enriquecimiento de:','["Los bienes de la Corona", "El patrimonio histórico, cultural y artístico de titularidad pública, pero no el de titularidad privada", "El patrimonio histórico, cultural y artístico de los pueblos de España"]'::jsonb,2,'Art. 46 CE','Garantizarán la conservación y promoverán el enriquecimiento del patrimonio histórico, cultural y artístico.',null),
('aux-ayto-mad:1-af927f69d1','aux-ayto-mad',1,'Según el art. 24.1, todas las personas tienen derecho a obtener la tutela efectiva de los jueces y tribunales:','["Solo en asuntos penales y contencioso-administrativos", "Sin que, en ningún caso, pueda producirse indefensión", "Solo si están asistidas de abogado y procurador"]'::jsonb,1,'Art. 24.1 CE','Tienen derecho a la tutela judicial efectiva sin que, en ningún caso, pueda producirse indefensión.',null),
('aux-ayto-mad:1-db05bacbe2','aux-ayto-mad',1,'¿Qué prohíbe el art. 26 de la Constitución?','["Los colegios profesionales con adscripción obligatoria", "Los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales", "Los tribunales militares en tiempo de guerra y en los supuestos de estado de sitio declarados por el Congreso"]'::jsonb,1,'Art. 26 CE','Se prohíben los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales.',null),
('aux-ayto-mad:1-f69aaa356a','aux-ayto-mad',1,'El art. 18.1 garantiza el derecho:','["A la libertad de empresa en el marco de la economía de mercado", "A la propiedad privada y a la herencia", "Al honor, a la intimidad personal y familiar y a la propia imagen"]'::jsonb,2,'Art. 18.1 CE','Garantiza el derecho al honor, a la intimidad personal y familiar y a la propia imagen.',null),
('aux-ayto-mad:1-555369c915','aux-ayto-mad',1,'El derecho de fundación se reconoce:','["Solo a las empresas y sociedades mercantiles", "Para fines de interés general, con arreglo a la ley", "Para cualquier fin, incluido el lucrativo, con arreglo a la ley"]'::jsonb,1,'Art. 34.1 CE','Se reconoce el derecho de fundación para fines de interés general, con arreglo a la ley.',null),
('aux-ayto-mad:1-2eb6b39db8','aux-ayto-mad',1,'Según el art. 9.1, están sujetos a la Constitución y al resto del ordenamiento jurídico:','["Solo los funcionarios y los poderes públicos", "Solo los poderes públicos y los funcionarios", "Los ciudadanos y los poderes públicos"]'::jsonb,2,'Art. 9.1 CE','Los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico.',null),
('aux-ayto-mad:1-5ed6960240','aux-ayto-mad',1,'Las prestaciones personales o patrimoniales de carácter público solo pueden establecerse:','["Con arreglo a la ley", "Por acuerdo municipal", "Por orden ministerial"]'::jsonb,0,'Art. 31.3 CE','Solo podrán establecerse prestaciones personales o patrimoniales de carácter público con arreglo a la ley.',null),
('aux-ayto-mad:1-eb0e62cebb','aux-ayto-mad',1,'Según el art. 44.2, los poderes públicos promoverán:','["La investigación militar y de defensa, y la cooperación científica con las Fuerzas Armadas aliadas", "La ciencia y la investigación científica y técnica en beneficio del interés general", "La investigación privada exclusivamente, mediante incentivos fiscales a las empresas"]'::jsonb,1,'Art. 44.2 CE','Promoverán la ciencia y la investigación científica y técnica en beneficio del interés general.',null),
('aux-ayto-mad:1-55db44c18c','aux-ayto-mad',1,'¿Quién establece los términos en que extranjeros y apátridas pueden gozar del derecho de asilo?','["El Defensor del Pueblo", "El Ministerio del Interior por orden", "La ley"]'::jsonb,2,'Art. 13.4 CE','La ley establecerá los términos en que los ciudadanos de otros países y los apátridas podrán gozar del derecho de asilo.',null),
('aux-ayto-mad:1-0c62f88686','aux-ayto-mad',1,'¿Qué regula la ley según el art. 20.3?','["El control gubernamental de todos los medios de comunicación social, públicos y privados, a través de una autoridad independiente", "Las tarifas publicitarias y el régimen de concesión de licencias de los medios de comunicación privados de ámbito estatal", "El control parlamentario de los medios de comunicación social dependientes del Estado o de cualquier ente público"]'::jsonb,2,'Art. 20.3 CE','La ley regulará la organización y el control parlamentario de los medios dependientes del Estado o de cualquier ente público.',null),
('aux-ayto-mad:1-0bcfd9408c','aux-ayto-mad',1,'Respecto a la extradición, la Constitución establece que:','["No se consideran delitos políticos los actos de terrorismo", "Solo la concede el Gobierno, sin intervención judicial", "Se concede sin necesidad de tratado ni de ley, por reciprocidad"]'::jsonb,0,'Art. 13.3 CE','La extradición se concede en cumplimiento de un tratado o de la ley, atendiendo a la reciprocidad; los actos de terrorismo no se consideran delitos políticos.',null),
('aux-ayto-mad:1-2becdd418c','aux-ayto-mad',1,'Toda persona detenida debe ser informada:','["Solo cuando sea puesta a disposición judicial, en presencia de su abogado y en el plazo de setenta y dos horas", "De forma inmediata y comprensible de sus derechos y de las razones de su detención", "En el plazo máximo de 72 horas, una vez puesta a disposición judicial y en presencia de su abogado"]'::jsonb,1,'Art. 17.3 CE','Debe ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos y de las razones de su detención.',null),
('aux-ayto-mad:1-8bfccf6fea','aux-ayto-mad',1,'Según la Constitución, ¿puede alguien ser obligado a declarar sobre su ideología, religión o creencias?','["No", "Solo los funcionarios", "Sí, en los censos oficiales"]'::jsonb,0,'Art. 16.2 CE','Nadie podrá ser obligado a declarar sobre su ideología, religión o creencias.',null),
('aux-ayto-mad:1-be824633f8','aux-ayto-mad',1,'Respecto al medio ambiente, el art. 45.1 reconoce:','["El derecho a disfrutar de un medio ambiente adecuado, sin establecer ningún deber de conservarlo", "El derecho a disfrutar de un medio ambiente adecuado y el deber de conservarlo", "El deber de conservarlo, pero no el derecho a disfrutarlo, que se regula en los Estatutos"]'::jsonb,1,'Art. 45.1 CE','Todos tienen el derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona, así como el deber de conservarlo.',null),
('aux-ayto-mad:1-52247bf595','aux-ayto-mad',1,'Las banderas propias de las Comunidades Autónomas:','["Las aprueba el Gobierno de la Nación a propuesta de cada Comunidad", "Sustituyen a la bandera de España en los edificios y actos oficiales de su territorio, si así lo dispone su Estatuto", "Pueden ser reconocidas por los Estatutos y se utilizan junto a la bandera de España en sus edificios y actos oficiales"]'::jsonb,2,'Art. 4.2 CE','Los Estatutos pueden reconocerlas; se usan junto a la bandera de España en sus edificios públicos y actos oficiales.',null),
('aux-ayto-mad:1-2eb081ae83','aux-ayto-mad',1,'Las asociaciones solo pueden ser disueltas o suspendidas en sus actividades:','["Por decisión de la Delegación del Gobierno", "En virtud de resolución judicial motivada", "Por orden del Ministerio del Interior"]'::jsonb,1,'Art. 22.4 CE','Solo podrán ser disueltas o suspendidas en virtud de resolución judicial motivada.',null),
('aux-ayto-mad:1-4d7f109854','aux-ayto-mad',1,'Según el art. 27.2, la educación tiene por objeto:','["La formación profesional exclusivamente", "El pleno desarrollo de la personalidad humana en el respeto a la religión mayoritaria y a las tradiciones de cada Comunidad Autónoma", "El pleno desarrollo de la personalidad humana en el respeto a los principios democráticos y a los derechos fundamentales"]'::jsonb,2,'Art. 27.2 CE','Tiene por objeto el pleno desarrollo de la personalidad humana en el respeto a los principios democráticos de convivencia y a los derechos y libertades fundamentales.',null),
('aux-ayto-mad:1-371c0284d6','aux-ayto-mad',1,'Según el art. 2, la Constitución se fundamenta en:','["La soberanía compartida del Estado y de las Comunidades Autónomas, y reconoce su derecho a la autodeterminación", "El pacto entre los territorios históricos", "La indisoluble unidad de la Nación española, y reconoce el derecho a la autonomía de las nacionalidades y regiones"]'::jsonb,2,'Art. 2 CE','Se fundamenta en la indisoluble unidad de la Nación española y reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones y la solidaridad entre todas ellas.',null),
('aux-ayto-mad:1-96f368ceb7','aux-ayto-mad',1,'¿Quién inspecciona y homologa el sistema educativo?','["Las asociaciones de padres", "Los colegios profesionales", "Los poderes públicos"]'::jsonb,2,'Art. 27.8 CE','Los poderes públicos inspeccionarán y homologarán el sistema educativo para garantizar el cumplimiento de las leyes.',null),
('aux-ayto-mad:1-aa5383d295','aux-ayto-mad',1,'Según el art. 41, los poderes públicos mantendrán:','["Un régimen público de Seguridad Social para todos los ciudadanos", "Un seguro médico solo para los trabajadores por cuenta ajena", "Mutualidades profesionales obligatorias"]'::jsonb,0,'Art. 41 CE','Mantendrán un régimen público de Seguridad Social para todos los ciudadanos.',null),
('aux-ayto-mad:1-35069d249e','aux-ayto-mad',1,'Según el art. 39.1, los poderes públicos aseguran:','["La protección social, económica y jurídica de la familia, pero solo de la fundada en el matrimonio", "Una vivienda digna a cada familia", "La protección social, económica y jurídica de la familia"]'::jsonb,2,'Art. 39.1 CE','Los poderes públicos aseguran la protección social, económica y jurídica de la familia.',null),
('aux-ayto-mad:1-a6d9ce8634','aux-ayto-mad',1,'Según el art. 50, los poderes públicos garantizarán a los ciudadanos durante la tercera edad:','["La gratuidad del transporte público", "Una pensión igual para todos, independientemente de lo cotizado", "Pensiones adecuadas y periódicamente actualizadas"]'::jsonb,2,'Art. 50 CE','Garantizarán, mediante pensiones adecuadas y periódicamente actualizadas, la suficiencia económica en la tercera edad.',null),
('aux-ayto-mad:1-d8e8c93954','aux-ayto-mad',1,'El sistema tributario, según el art. 31.1, debe ser justo, inspirado en la igualdad y la progresividad, y:','["Exclusivamente estatal", "En ningún caso tendrá alcance confiscatorio", "Igual para todos los contribuyentes, con independencia de su renta"]'::jsonb,1,'Art. 31.1 CE','Se basa en la igualdad y la progresividad, y en ningún caso tendrá alcance confiscatorio.',null),
('aux-ayto-mad:1-4048766e7f','aux-ayto-mad',1,'Se reconoce a las personas físicas y jurídicas la libertad de:','["Fijar libremente los planes de estudio oficiales", "Creación de centros docentes, dentro del respeto a los principios constitucionales", "Creación de centros docentes, que solo podrán impartir enseñanzas no regladas"]'::jsonb,1,'Art. 27.6 CE','Se reconoce la libertad de creación de centros docentes, dentro del respeto a los principios constitucionales.',null),
('aux-ayto-mad:1-905af9f9c0','aux-ayto-mad',1,'Según el art. 9.2, corresponde a los poderes públicos:','["Limitar la participación política", "Promover las condiciones para que la libertad y la igualdad sean reales y efectivas, y remover los obstáculos que lo impidan", "Garantizar la igualdad de resultados económicos entre todos los ciudadanos y territorios, y suprimir las diferencias de renta que lo impidan"]'::jsonb,1,'Art. 9.2 CE','Deben promover esas condiciones, remover los obstáculos y facilitar la participación de todos los ciudadanos.',null),
('aux-ayto-mad:1-b6a08e2a97','aux-ayto-mad',1,'¿Qué regula la ley según el art. 30.2?','["La participación de España en organizaciones internacionales de defensa", "Las obligaciones militares de los españoles y la objeción de conciencia", "El servicio militar obligatorio, su duración y las causas de exención"]'::jsonb,1,'Art. 30.2 CE','La ley fijará las obligaciones militares de los españoles y regulará la objeción de conciencia.',null),
('aux-ayto-mad:1-d418cf1cb0','aux-ayto-mad',1,'Según el art. 42, el Estado orientará su política hacia el retorno de:','["Los trabajadores españoles en el extranjero", "Los funcionarios destinados en el exterior", "Los capitales invertidos fuera"]'::jsonb,0,'Art. 42 CE','El Estado velará por los derechos de los trabajadores españoles en el extranjero y orientará su política hacia su retorno.',null),
('aux-ayto-mad:1-bbacab7d4d','aux-ayto-mad',1,'El contenido del derecho de propiedad y de herencia lo delimita:','["Su función social, de acuerdo con las leyes", "Las ordenanzas fiscales de cada municipio", "La voluntad del propietario"]'::jsonb,0,'Art. 33.2 CE','La función social de estos derechos delimitará su contenido, de acuerdo con las leyes.',null),
('aux-ayto-mad:1-27bb7687b4','aux-ayto-mad',1,'Según el art. 23.1, los ciudadanos participan en los asuntos públicos:','["Directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal", "Directamente o por medio de representantes elegidos en elecciones periódicas por sufragio censitario", "Por medio de representantes designados por las Cortes Generales y por los Parlamentos autonómicos"]'::jsonb,0,'Art. 23.1 CE','Participan directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal.',null),
('aux-ayto-mad:1-370b32da86','aux-ayto-mad',1,'Las bases de la organización militar se regulan mediante:','["Una ley ordinaria", "Una ley orgánica", "Una orden del Ministerio de Defensa"]'::jsonb,1,'Art. 8.2 CE','Una ley orgánica regulará las bases de la organización militar.',null),
('aux-ayto-mad:1-d16b73b933','aux-ayto-mad',1,'Según el art. 51.1, los poderes públicos garantizarán la defensa de:','["Los consumidores y usuarios, protegiendo mediante procedimientos eficaces su seguridad, salud e intereses económicos", "Los comerciantes minoristas exclusivamente", "Las empresas frente a la competencia desleal y los productores frente a las importaciones de terceros países"]'::jsonb,0,'Art. 51.1 CE','Garantizarán la defensa de los consumidores y usuarios mediante procedimientos eficaces.',null),
('aux-ayto-mad:1-21aba73e70','aux-ayto-mad',1,'En el control y la gestión de los centros sostenidos con fondos públicos intervienen:','["Los profesores, los padres y, en su caso, los alumnos", "Solo el director del centro y el titular, en el caso de los centros concertados", "Los sindicatos más representativos y la Administración"]'::jsonb,0,'Art. 27.7 CE','Intervienen los profesores, los padres y, en su caso, los alumnos, en los términos que la ley establezca.',null),
('aux-ayto-mad:1-0b58913945','aux-ayto-mad',1,'Según el art. 19, los españoles tienen derecho a:','["Cambiar de nacionalidad libremente y entrar y salir de España sin requisitos", "Elegir libremente su residencia y a circular por el territorio nacional", "Viajar sin pasaporte a cualquier país y residir en el extranjero sin requisitos"]'::jsonb,1,'Art. 19 CE','Tienen derecho a elegir libremente su residencia y a circular por el territorio nacional.',null),
('aux-ayto-mad:1-b79c0feb4b','aux-ayto-mad',1,'¿Quiénes pueden ejercer la iniciativa de reforma constitucional?','["Gobierno, Congreso, Senado, Asambleas de las CCAA y la iniciativa popular con 500.000 firmas", "Gobierno, Congreso, Senado y Asambleas de las CCAA, pero no la iniciativa popular", "Gobierno, Congreso y Senado, y también la iniciativa popular respaldada por un millón de firmas"]'::jsonb,1,'Art. 166 CE','La iniciativa se ejerce según los apartados 1 y 2 del art. 87, que no incluyen la iniciativa popular del art. 87.3.',null),
('aux-ayto-mad:1-d1f8d2052f','aux-ayto-mad',1,'Por el procedimiento ordinario del art. 167 CE, los proyectos de reforma constitucional deben aprobarse por:','["Mayoría de tres quintos de cada una de las Cámaras", "Mayoría de dos tercios de cada una de las Cámaras", "Mayoría de tres quintos del Congreso y absoluta del Senado"]'::jsonb,0,'Art. 167.1 CE','Si no hay acuerdo entre las Cámaras, se intenta obtenerlo mediante una comisión de composición paritaria de Diputados y Senadores.',null),
('aux-ayto-mad:1-ae34cdba4c','aux-ayto-mad',1,'Si no se logra la aprobación de una reforma por el procedimiento del art. 167.1 CE, el Congreso podrá aprobarla:','["Por mayoría de dos tercios, siempre que el texto hubiera obtenido la mayoría absoluta del Senado", "Por mayoría de tres quintos, siempre que el texto se someta después a referéndum obligatorio de todos los españoles", "Por mayoría absoluta, siempre que el texto hubiera obtenido la mayoría de tres quintos del Senado"]'::jsonb,0,'Art. 167.2 CE','Así lo prevé el art. 167.2 CE.',null),
('aux-ayto-mad:1-2a265e5ec4','aux-ayto-mad',1,'En la reforma por el procedimiento del art. 167 CE, el referéndum es:','["Facultativo: se celebra si lo solicita, en los 15 días siguientes a la aprobación, una décima parte de los miembros de cualquiera de las Cámaras", "Obligatorio en todo caso, y se celebra en los 15 días siguientes a la aprobación del texto por las Cortes Generales, con independencia de lo que soliciten las Cámaras", "Facultativo: se celebra si lo solicita, en los 15 días siguientes, la mayoría absoluta del Congreso"]'::jsonb,0,'Art. 167.3 CE','En el procedimiento agravado del art. 168, en cambio, el referéndum es obligatorio.',null),
('aux-ayto-mad:1-b8fc57e319','aux-ayto-mad',1,'La revisión total de la Constitución o una parcial que afecte al Título preliminar, a la Sección 1.ª del Capítulo II del Título I o al Título II exige:','["Aprobación por mayoría absoluta de cada Cámara, disolución inmediata de las Cortes y referéndum obligatorio", "Aprobación por dos tercios de cada Cámara, disolución inmediata de las Cortes, ratificación por las nuevas Cámaras y referéndum", "Aprobación por dos tercios del Congreso y mayoría absoluta del Senado, y después referéndum obligatorio"]'::jsonb,1,'Art. 168 CE','Las nuevas Cámaras deben ratificar la decisión, estudiar el nuevo texto y aprobarlo por mayoría de dos tercios de ambas.',null),
('aux-ayto-mad:1-6ecc0664d7','aux-ayto-mad',1,'¿Cuándo no podrá iniciarse la reforma constitucional?','["En tiempo de guerra o de vigencia de alguno de los estados del art. 116", "Durante el último año de la legislatura o mientras haya un proceso electoral convocado", "Mientras esté pendiente de resolver un recurso de inconstitucionalidad contra una ley orgánica"]'::jsonb,0,'Art. 169 CE','Los estados del art. 116 son los de alarma, excepción y sitio.',null),
('aux-ayto-mad:1-81a47f308b','aux-ayto-mad',1,'Según el art. 54 CE, el Defensor del Pueblo es:','["Alto comisionado de las Cortes Generales, designado por estas para la defensa de los derechos del Título I", "Alto comisionado de las Cortes Generales, designado por el Rey a propuesta del Congreso", "Órgano del Poder Judicial encargado de la defensa de los derechos fundamentales"]'::jsonb,0,'Art. 54 CE','Puede supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.',null),
('aux-ayto-mad:1-91090c828d','aux-ayto-mad',1,'La reforma del artículo 49 de la Constitución aprobada en 2024 sustituyó la expresión «disminuidos físicos, sensoriales y psíquicos» por:','["Personas con diversidad funcional", "Personas con capacidades diferentes", "Personas con discapacidad"]'::jsonb,2,'Art. 49 CE (reforma de 17 de febrero de 2024)','Fue la tercera reforma de la Constitución, tras las de 1992 (art. 13.2) y 2011 (art. 135).',null),
('aux-ayto-mad:2-604380f875','aux-ayto-mad',2,'Según el art. 152.1 CE, el Tribunal Superior de Justicia:','["Depende del Gobierno autonómico, que nombra a su Presidente", "Es el órgano de gobierno de los jueces de la Comunidad Autónoma", "Culmina la organización judicial en el ámbito territorial de la Comunidad Autónoma, sin perjuicio de la jurisdicción del Tribunal Supremo"]'::jsonb,2,'Art. 152.1 CE','Las sucesivas instancias procesales se agotan ante órganos radicados en el mismo territorio de la CA en que esté el órgano competente en primera instancia.',null),
('aux-ayto-mad:2-b2b813b4d1','aux-ayto-mad',2,'Según el artículo 137 de la Constitución, el Estado se organiza territorialmente en:','["Municipios, islas y Comunidades Autónomas", "Provincias, Comunidades Autónomas y Ciudades Autónomas", "Municipios, provincias y Comunidades Autónomas"]'::jsonb,2,'Art. 137 CE','Todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses.',null),
('aux-ayto-mad:2-aef8afe342','aux-ayto-mad',2,'Según la Constitución, el gobierno y la administración de los municipios corresponde a:','["Sus respectivos Ayuntamientos, integrados por los Alcaldes y los Concejales", "Los Delegados del Gobierno, con la colaboración de los Concejales elegidos por los vecinos", "Las Diputaciones Provinciales, a través de sus delegaciones comarcales en cada municipio"]'::jsonb,0,'Art. 140 CE','Los Concejales son elegidos por los vecinos por sufragio universal, igual, libre, directo y secreto.',null),
('aux-ayto-mad:2-168fbe0745','aux-ayto-mad',2,'Según el artículo 140 de la Constitución, los Alcaldes serán elegidos:','["Por el Pleno de la Diputación Provincial", "Por el Delegado del Gobierno, a propuesta de los Concejales", "Por los Concejales o por los vecinos"]'::jsonb,2,'Art. 140 CE','La ley regula las condiciones en las que procede el régimen del concejo abierto.',null),
('aux-ayto-mad:2-4cd26132ea','aux-ayto-mad',2,'¿Qué tipo de ley es necesaria para alterar los límites provinciales?','["Una ley de la Comunidad Autónoma afectada, previo informe estatal", "Una ley orgánica aprobada por las Cortes Generales", "Una ley ordinaria de las Cortes Generales, por mayoría absoluta"]'::jsonb,1,'Art. 141.1 CE','La provincia es una entidad local con personalidad jurídica propia, agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado.',null),
('aux-ayto-mad:2-47070daf94','aux-ayto-mad',2,'En los archipiélagos, las islas tendrán además su administración propia en forma de:','["Mancomunidades insulares", "Diputaciones forales", "Cabildos o Consejos"]'::jsonb,2,'Art. 141.4 CE','Los Cabildos existen en Canarias y los Consejos Insulares en Baleares.',null),
('aux-ayto-mad:2-7bc468b7be','aux-ayto-mad',2,'Según el artículo 143.2 de la Constitución, la iniciativa del proceso autonómico corresponde a todas las Diputaciones interesadas o al órgano interinsular correspondiente y a:','["La mitad de los municipios de cada provincia, sea cual sea su población", "Las dos terceras partes de los municipios cuya población represente, al menos, la mayoría del censo electoral de cada provincia o isla", "Los municipios que representen un tercio del censo electoral de la región histórica"]'::jsonb,1,'Art. 143.2 CE','Los requisitos deben cumplirse en el plazo de seis meses desde el primer acuerdo de una Corporación local.',null),
('aux-ayto-mad:2-aec88f0685','aux-ayto-mad',2,'¿En qué plazo deben cumplirse los requisitos de iniciativa autonómica del artículo 143.2 de la Constitución?','["Un año desde la publicación de la Constitución en el Boletín Oficial del Estado y en los diarios oficiales", "Dos años desde que se constituya la asamblea de parlamentarios", "Seis meses desde el primer acuerdo adoptado por alguna de las Corporaciones locales interesadas"]'::jsonb,2,'Art. 143.2 CE','Si la iniciativa no prospera, solo puede reiterarse pasados cinco años.',null),
('aux-ayto-mad:2-97650b28ae','aux-ayto-mad',2,'Si la iniciativa autonómica del artículo 143 no prospera:','["Solo podrá reiterarse pasados cinco años", "No podrá volver a plantearse nunca", "Podrá reiterarse pasados tres años"]'::jsonb,0,'Art. 143.3 CE','Así lo dispone el artículo 143.3 de la Constitución.',null),
('aux-ayto-mad:2-6b70a12d98','aux-ayto-mad',2,'Según el artículo 144 de la Constitución, las Cortes Generales, mediante ley orgánica y por motivos de interés nacional, podrán:','["Disolver una Comunidad Autónoma que incumpla de forma grave las obligaciones que le imponen la Constitución u otras leyes", "Integrar dos Comunidades Autónomas limítrofes en una sola, sin necesidad de referéndum", "Autorizar la constitución de una Comunidad Autónoma cuyo ámbito territorial no supere el de una provincia y no reúna las condiciones del artículo 143.1"]'::jsonb,2,'Art. 144 a) CE','El artículo 155 no permite disolver Comunidades, sino adoptar medidas para obligarlas a cumplir.',null),
('aux-ayto-mad:2-578cf0a5ee','aux-ayto-mad',2,'¿Qué prohíbe el artículo 145 de la Constitución?','["Los convenios entre Comunidades Autónomas", "Que una Comunidad Autónoma tenga varias provincias", "La federación de Comunidades Autónomas"]'::jsonb,2,'Art. 145.1 CE','Sí se permiten convenios entre Comunidades para la gestión de servicios propios, que deben comunicarse a las Cortes Generales.',null),
('aux-ayto-mad:2-a1a3f5553b','aux-ayto-mad',2,'Los acuerdos de cooperación entre Comunidades Autónomas, distintos de los convenios para gestión de servicios propios, requieren:','["El dictamen del Consejo de Estado", "La autorización de las Cortes Generales", "Una simple comunicación a las Cortes Generales"]'::jsonb,1,'Art. 145.2 CE','Los convenios para la gestión y prestación de servicios propios solo deben comunicarse a las Cortes.',null),
('aux-ayto-mad:2-dc4a9d2f56','aux-ayto-mad',2,'Según el artículo 147 de la Constitución, el Estatuto de Autonomía es:','["Un tratado entre el Estado y la Comunidad Autónoma", "La norma institucional básica de cada Comunidad Autónoma", "Un reglamento del Gobierno de la Nación para cada Comunidad"]'::jsonb,1,'Art. 147.1 CE','El Estado lo reconoce y ampara como parte integrante de su ordenamiento jurídico.',null),
('aux-ayto-mad:2-b0a31954c1','aux-ayto-mad',2,'¿Cuál de los siguientes contenidos NO exige la Constitución que figure en los Estatutos de Autonomía?','["La lengua cooficial de la Comunidad", "La delimitación de su territorio", "Las competencias asumidas"]'::jsonb,0,'Art. 147.2 CE','El art. 147.2 exige denominación, delimitación del territorio, denominación, organización y sede de las instituciones propias y competencias asumidas.',null),
('aux-ayto-mad:2-1225cf18a1','aux-ayto-mad',2,'La reforma de los Estatutos de Autonomía requiere, en todo caso:','["Un referéndum en todo el territorio nacional", "La aprobación por las Cortes Generales mediante ley orgánica", "La aprobación por el Gobierno de la Nación mediante real decreto"]'::jsonb,1,'Art. 147.3 CE','El procedimiento lo fija cada Estatuto.',null),
('aux-ayto-mad:2-6cddd03be1','aux-ayto-mad',2,'Según el artículo 148.2 de la Constitución, las Comunidades Autónomas podían ampliar sucesivamente sus competencias transcurridos:','["Cinco años", "Dos años", "Diez años"]'::jsonb,0,'Art. 148.2 CE','Mediante la reforma de sus Estatutos, dentro del marco del artículo 149.',null),
('aux-ayto-mad:2-919efdc726','aux-ayto-mad',2,'Las materias no atribuidas expresamente al Estado por la Constitución podrán corresponder a las Comunidades Autónomas:','["En virtud de sus respectivos Estatutos", "Por acuerdo de la Conferencia de Presidentes", "Siempre, de forma automática"]'::jsonb,0,'Art. 149.3 CE','Las no asumidas por los Estatutos corresponden al Estado, cuyo derecho es en todo caso supletorio del de las Comunidades Autónomas.',null),
('aux-ayto-mad:2-7376a00e68','aux-ayto-mad',2,'En caso de conflicto, las normas del Estado prevalecen sobre las de las Comunidades Autónomas:','["Solo si la norma estatal es posterior", "Solo en materia de relaciones internacionales", "En todo lo que no esté atribuido a la exclusiva competencia de estas"]'::jsonb,2,'Art. 149.3 CE','Es la cláusula de prevalencia del derecho estatal.',null),
('aux-ayto-mad:2-8c3860d05b','aux-ayto-mad',2,'¿Qué leyes permiten a las Cortes atribuir a las Comunidades Autónomas la facultad de dictar normas legislativas en el marco de principios, bases y directrices fijados por una ley estatal?','["Las leyes marco", "Las leyes de bases", "Las leyes de armonización"]'::jsonb,0,'Art. 150.1 CE','Las leyes de bases sirven para delegar en el Gobierno la elaboración de textos articulados.',null),
('aux-ayto-mad:2-4ae9a8eba5','aux-ayto-mad',2,'La transferencia o delegación a las Comunidades Autónomas de facultades de titularidad estatal se hace mediante:','["Real decreto legislativo", "Ley ordinaria", "Ley orgánica"]'::jsonb,2,'Art. 150.2 CE','Debe prever la correspondiente transferencia de medios financieros y las formas de control que se reserve el Estado.',null),
('aux-ayto-mad:2-07134ade62','aux-ayto-mad',2,'¿Quién aprecia la necesidad de dictar una ley de armonización?','["El Gobierno de la Nación, previo dictamen favorable del Consejo de Estado", "Las Cortes Generales, por mayoría absoluta de cada Cámara", "El Tribunal Constitucional, a instancia del Gobierno o de cincuenta diputados"]'::jsonb,1,'Art. 150.3 CE','Lo exige el interés general, aunque se trate de materias atribuidas a la competencia de las Comunidades Autónomas.',null),
('aux-ayto-mad:2-3a2cbf751b','aux-ayto-mad',2,'En la vía del artículo 151 de la Constitución, la iniciativa autonómica debía ratificarse mediante referéndum por:','["El voto afirmativo de la mayoría absoluta de los electores de cada provincia", "La mayoría absoluta de los votos válidos emitidos en el conjunto de toda España", "La mayoría simple de los votos emitidos en el conjunto del territorio de la futura Comunidad"]'::jsonb,0,'Art. 151.1 CE','Además, la iniciativa debía acordarse por las Diputaciones y por las tres cuartas partes de los municipios de cada provincia.',null),
('aux-ayto-mad:2-547938a8bf','aux-ayto-mad',2,'Según el artículo 152 de la Constitución, el Presidente de la Comunidad Autónoma es:','["Elegido por el Senado entre los senadores de la Comunidad", "Elegido directamente por los ciudadanos de la Comunidad en las elecciones autonómicas y nombrado por el Rey", "Elegido por la Asamblea Legislativa de entre sus miembros y nombrado por el Rey"]'::jsonb,2,'Art. 152.1 CE','Dirige el Consejo de Gobierno y ostenta la suprema representación de la Comunidad y la ordinaria del Estado en ella.',null),
('aux-ayto-mad:2-ae14d24d4f','aux-ayto-mad',2,'El control económico y presupuestario de los órganos de las Comunidades Autónomas corresponde, según el artículo 153 de la Constitución, a:','["El Tribunal de Cuentas", "El Tribunal Constitucional", "La jurisdicción contencioso-administrativa"]'::jsonb,0,'Art. 153 d) CE','El TC controla las disposiciones con fuerza de ley y la jurisdicción contencioso-administrativa, la administración autónoma y sus reglamentos.',null),
('aux-ayto-mad:2-2058df9442','aux-ayto-mad',2,'¿Quién controla las funciones delegadas a las Comunidades Autónomas conforme al artículo 150.2 de la Constitución?','["El Tribunal Constitucional, previo recurso del Senado", "El Gobierno, previo dictamen del Consejo de Estado", "El Tribunal de Cuentas, previo informe de la Intervención General"]'::jsonb,1,'Art. 153 b) CE','Es una de las cuatro vías de control de la actividad autonómica que enumera el artículo 153.',null),
('aux-ayto-mad:2-47a92222a4','aux-ayto-mad',2,'Para aplicar las medidas del artículo 155 de la Constitución, el Gobierno necesita:','["La aprobación del Consejo de Estado y del Congreso", "Un dictamen favorable del Tribunal Constitucional", "Requerir previamente al Presidente de la Comunidad Autónoma y la aprobación de la mayoría absoluta del Senado"]'::jsonb,2,'Art. 155.1 CE','Se aplica si una Comunidad no cumple las obligaciones de la Constitución o las leyes o actúa contra el interés general de España.',null),
('aux-ayto-mad:2-c037f6d984','aux-ayto-mad',2,'¿Qué fondo prevé el artículo 158.2 de la Constitución para corregir desequilibrios económicos interterritoriales?','["El Fondo de Compensación", "El Fondo de Suficiencia Global", "El Fondo de Garantía de Servicios Públicos Fundamentales"]'::jsonb,0,'Art. 158.2 CE','Sus recursos se distribuyen por las Cortes Generales entre las Comunidades Autónomas y provincias.',null),
('aux-ayto-mad:2-a4eefe77ec','aux-ayto-mad',2,'Según la Constitución, los municipios, las provincias y las Comunidades Autónomas gozan de autonomía:','["Política y financiera ilimitada", "Legislativa y reglamentaria plena", "Para la gestión de sus respectivos intereses"]'::jsonb,2,'Art. 137 CE','Todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses (art. 137 CE).',null),
('aux-ayto-mad:2-17535c1174','aux-ayto-mad',2,'Según el artículo 140 de la Constitución, el gobierno y la administración de los municipios corresponde a:','["Las Diputaciones provinciales, integradas por los diputados provinciales", "Los Alcaldes, elegidos siempre por los vecinos mediante sufragio directo", "Sus respectivos Ayuntamientos, integrados por los Alcaldes y los Concejales"]'::jsonb,2,'Art. 140 CE','El art. 140 CE atribuye el gobierno y la administración municipal a los Ayuntamientos, integrados por Alcaldes y Concejales, y garantiza la autonomía municipal y la personalidad jurídica plena.',null),
('aux-ayto-mad:2-9b6da87409','aux-ayto-mad',2,'Según la Constitución, los Concejales son elegidos por:','["El Pleno de la Diputación Provincial, por mayoría absoluta de sus miembros", "Los Alcaldes de la comarca, mediante sufragio indirecto y secreto", "Los vecinos del municipio mediante sufragio universal, igual, libre, directo y secreto"]'::jsonb,2,'Art. 140 CE','Según el art. 140 CE, los Concejales son elegidos por los vecinos mediante sufragio universal, igual, libre, directo y secreto, en la forma que establezca la ley.',null),
('aux-ayto-mad:2-07fa68f26d','aux-ayto-mad',2,'Según la Constitución, los Alcaldes serán elegidos:','["Siempre por los vecinos, mediante sufragio directo", "Por el Pleno de la Diputación Provincial", "Por los Concejales o por los vecinos"]'::jsonb,2,'Art. 140 CE','El art. 140 CE dice que los Alcaldes serán elegidos por los Concejales o por los vecinos.',null),
('aux-ayto-mad:2-61fde70498','aux-ayto-mad',2,'La Constitución prevé que la ley regule las condiciones en las que proceda el régimen de:','["Mancomunidad obligatoria", "Concejo abierto", "Tutela provincial"]'::jsonb,1,'Art. 140 CE','El art. 140 CE remite a la ley la regulación de las condiciones en que proceda el régimen del concejo abierto.',null),
('aux-ayto-mad:2-32fc74198c','aux-ayto-mad',2,'Según el artículo 141 de la Constitución, la provincia es:','["Una división administrativa de la Comunidad Autónoma, sin personalidad jurídica propia, para prestar sus servicios", "Una entidad territorial con autonomía legislativa en las materias que le atribuya su Estatuto", "Una entidad local con personalidad jurídica propia, determinada por la agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado"]'::jsonb,2,'Art. 141.1 CE','El art. 141.1 CE la define como entidad local con personalidad jurídica propia, determinada por la agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado.',null),
('aux-ayto-mad:2-3388062b6e','aux-ayto-mad',2,'Cualquier alteración de los límites provinciales habrá de ser aprobada por:','["El Gobierno mediante real decreto", "Las Cortes Generales mediante ley orgánica", "Las Asambleas Legislativas de las Comunidades Autónomas afectadas"]'::jsonb,1,'Art. 141.1 CE','Según el art. 141.1 CE, cualquier alteración de los límites provinciales habrá de ser aprobada por las Cortes Generales mediante ley orgánica.',null),
('aux-ayto-mad:2-6be4749128','aux-ayto-mad',2,'Según la Constitución, el gobierno y la administración autónoma de las provincias estarán encomendados a:','["Los Consejos de Gobierno de las Comunidades Autónomas", "Diputaciones u otras Corporaciones de carácter representativo", "Los Delegados del Gobierno y, en su caso, los Subdelegados del Gobierno en la provincia"]'::jsonb,1,'Art. 141.2 CE','El art. 141.2 CE encomienda el gobierno y la administración autónoma de las provincias a Diputaciones u otras Corporaciones de carácter representativo.',null),
('aux-ayto-mad:2-b7f29be81b','aux-ayto-mad',2,'La Constitución permite crear agrupaciones de municipios diferentes de la provincia:','["Sí, se podrán crear agrupaciones de municipios diferentes de la provincia", "Solo en los archipiélagos balear y canario", "No, la única agrupación de municipios es la provincia"]'::jsonb,0,'Art. 141.3 CE','Según el art. 141.3 CE, se podrán crear agrupaciones de municipios diferentes de la provincia.',null),
('aux-ayto-mad:2-8bb84d0ad0','aux-ayto-mad',2,'Según el artículo 142 de la Constitución, las Haciendas locales se nutrirán fundamentalmente de:','["Tributos propios y de participación en los del Estado y de las Comunidades Autónomas", "Las transferencias del Fondo de Compensación Interterritorial y de los fondos europeos", "Los precios públicos, las multas y las contribuciones especiales"]'::jsonb,0,'Art. 142 CE','El art. 142 CE dice que deberán disponer de medios suficientes y se nutrirán fundamentalmente de tributos propios y de participación en los del Estado y de las CCAA.',null),
('aux-ayto-mad:2-ea4467816e','aux-ayto-mad',2,'Según el artículo 142 de la Constitución, las Haciendas locales deberán disponer de los medios suficientes para:','["Garantizar el equilibrio económico entre las distintas partes del territorio", "Financiar todos los servicios públicos que presten en su territorio", "El desempeño de las funciones que la ley atribuye a las Corporaciones respectivas"]'::jsonb,2,'Art. 142 CE','El art. 142 CE recoge el principio de suficiencia financiera para el desempeño de las funciones atribuidas por la ley.',null),
('aux-ayto-mad:2-888f097807','aux-ayto-mad',2,'Según la Constitución, ¿qué tienen los municipios?','["Soberanía para la gestión de sus intereses", "Personalidad jurídica plena", "Potestad legislativa en las materias de su competencia"]'::jsonb,1,'Art. 140 CE','El art. 140 CE garantiza la autonomía de los municipios, que gozan de personalidad jurídica plena.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:2-84345015e1','aux-ayto-mad',2,'Según la Ley 7/1985, la provincia y, en su caso, la isla gozan:','["De autonomía legislativa limitada a su territorio y a sus competencias", "De idéntica autonomía que los municipios para la gestión de los intereses respectivos", "De una autonomía subordinada a la de los municipios que la integran"]'::jsonb,1,'Art. 1.2 LBRL','Según el art. 1.2 LBRL, la provincia y, en su caso, la isla gozan asimismo de idéntica autonomía para la gestión de los intereses respectivos.',null),
('aux-ayto-mad:2-e1c8c65ad0','aux-ayto-mad',2,'Para la efectividad de la autonomía local, la legislación sectorial debe atribuir competencias a las entidades locales de conformidad con los principios de:','["Descentralización, proximidad, eficacia y eficiencia", "Solidaridad, igualdad y unidad", "Jerarquía, competencia y coordinación"]'::jsonb,0,'Art. 2.1 LBRL','El art. 2.1 LBRL cita los principios de descentralización, proximidad, eficacia y eficiencia, con sujeción a la normativa de estabilidad presupuestaria.',null),
('aux-ayto-mad:2-ec0f953c80','aux-ayto-mad',2,'Según la Ley 7/1985, las relaciones recíprocas entre la Administración Local y las demás Administraciones públicas se ajustarán a los deberes de:','["Información mutua, colaboración, coordinación y respeto a los ámbitos competenciales respectivos", "Subordinación de las entidades locales a las Comunidades Autónomas en todo caso", "Jerarquía, tutela financiera y control de oportunidad de sus acuerdos"]'::jsonb,0,'Art. 10.1 LBRL','El art. 10.1 LBRL establece estos deberes y el art. 10.4 añade que la coordinación es compatible con la autonomía local.',null),
('aux-ayto-mad:2-61fe9f2682','aux-ayto-mad',2,'Según la Ley 7/1985, las funciones de coordinación de las entidades locales por otras Administraciones:','["Serán compatibles con la autonomía de las Entidades Locales", "Solo pueden ejercerlas los Tribunales", "Suspenden la autonomía local mientras duren"]'::jsonb,0,'Art. 10.4 LBRL','Según el art. 10.4 LBRL, las funciones de coordinación serán compatibles con la autonomía de las Entidades Locales.',null),
('aux-ayto-mad:2-011e959541','aux-ayto-mad',2,'Las entidades locales territoriales están legitimadas para impugnar las disposiciones y actos del Estado y de las Comunidades Autónomas que:','["Lesionen su autonomía tal como la garantizan la Constitución y la Ley 7/1985", "Reduzcan su financiación respecto al año anterior sin la memoria económica exigida", "Afecten a cualquier vecino del municipio, aunque no lesionen la autonomía local"]'::jsonb,0,'Art. 63.2 LBRL','El art. 63.2 LBRL las legitima en todo caso para impugnar las disposiciones y actos que lesionen su autonomía.',null),
('aux-ayto-mad:2-a33f237cdd','aux-ayto-mad',2,'Las entidades locales pueden promover ante el Tribunal Constitucional la impugnación de leyes del Estado o de las Comunidades Autónomas que lesionen la autonomía local mediante:','["El recurso de amparo ante el Tribunal Constitucional, interpuesto por el Alcalde", "El conflicto en defensa de la autonomía local, en los términos del artículo 119 de la Ley 7/1985", "La cuestión de inconstitucionalidad planteada por el Pleno"]'::jsonb,1,'Art. 63.3 LBRL','El art. 63.3 LBRL las legitima para promover la impugnación ante el TC de esas leyes, en los términos del art. 119 (conflicto en defensa de la autonomía local).',null),
('aux-ayto-mad:2-c37a64a4dc','aux-ayto-mad',2,'El Consejo de Ministros puede disolver los órganos de las corporaciones locales por gestión gravemente dañosa para los intereses generales, mediante real decreto y previo acuerdo favorable de:','["El Congreso de los Diputados", "La Asamblea Legislativa de la Comunidad Autónoma", "El Senado"]'::jsonb,2,'Art. 61.1 LBRL','El art. 61.1 LBRL exige real decreto del Consejo de Ministros y, en todo caso, previo acuerdo favorable del Senado.',null),
('aux-ayto-mad:3-f03b03ad3b','aux-ayto-mad',3,'Los actos administrativos producen efectos:','["Desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa", "Desde su notificación, sin que puedan disponer otra cosa", "Desde que son firmes en vía administrativa, salvo que se disponga otra cosa"]'::jsonb,0,'Art. 39.1 Ley 39/2015','Se presumen válidos y producen efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.',null),
('aux-ayto-mad:3-168927eb67','aux-ayto-mad',3,'¿En qué plazo debe cursarse la notificación de un acto administrativo?','["15 días hábiles desde que el acto se dictó o se firmó", "10 días desde que el acto se dictó", "1 mes desde que el acto se dictó"]'::jsonb,1,'Art. 40.2 Ley 39/2015','La notificación debe cursarse dentro de los diez días siguientes a la fecha en que el acto se dictó.',null),
('aux-ayto-mad:3-82756fb435','aux-ayto-mad',3,'Una notificación electrónica se entiende rechazada cuando pasan sin que se acceda a su contenido:','["5 días hábiles desde su puesta a disposición", "15 días naturales desde su puesta a disposición", "10 días naturales desde su puesta a disposición"]'::jsonb,2,'Art. 43.2 Ley 39/2015','Se entiende rechazada cuando han pasado diez días naturales desde su puesta a disposición sin acceder a su contenido.',null),
('aux-ayto-mad:3-a6d3ae69a2','aux-ayto-mad',3,'Cuando la notificación ha resultado infructuosa, se hace por medio de un anuncio en:','["El tablón de la sede del órgano", "El boletín oficial de la provincia", "El Boletín Oficial del Estado"]'::jsonb,2,'Art. 44 Ley 39/2015','La notificación se hace por medio de un anuncio publicado en el BOE.',null),
('aux-ayto-mad:3-c205ac9335','aux-ayto-mad',3,'¿Cuál de estos actos es nulo de pleno derecho?','["El dictado por un órgano manifiestamente incompetente por razón de la materia o del territorio", "El que incurre en desviación de poder o en cualquier otra infracción del ordenamiento jurídico aplicable", "El que tiene un defecto de forma que no causa indefensión al interesado ni impide que el acto alcance su fin"]'::jsonb,0,'Art. 47.1 b) Ley 39/2015','La incompetencia manifiesta por razón de la materia o del territorio es causa de nulidad de pleno derecho. Las otras opciones son, como mucho, causas de anulabilidad.',null),
('aux-ayto-mad:3-d66cda3281','aux-ayto-mad',3,'Un acto dictado prescindiendo total y absolutamente del procedimiento legalmente establecido es:','["Una irregularidad no invalidante", "Válido si se convalida", "Nulo de pleno derecho"]'::jsonb,2,'Art. 47.1 e) Ley 39/2015','Es una de las causas de nulidad de pleno derecho.',null),
('aux-ayto-mad:3-1a94e38234','aux-ayto-mad',3,'Los actos que incurren en desviación de poder son:','["Válidos", "Anulables", "Nulos de pleno derecho"]'::jsonb,1,'Art. 48.1 Ley 39/2015','Son anulables los actos que incurren en cualquier infracción del ordenamiento, incluso la desviación de poder.',null),
('aux-ayto-mad:3-b88906dab0','aux-ayto-mad',3,'El defecto de forma determina la anulabilidad del acto:','["Nunca, porque el defecto de forma solo genera irregularidades no invalidantes", "Solo cuando el acto carece de los requisitos formales indispensables o da lugar a indefensión", "Siempre, aunque el acto alcance su fin, reúna los requisitos formales indispensables y no cause indefensión"]'::jsonb,1,'Art. 48.2 Ley 39/2015','Solo cuando el acto carece de los requisitos formales indispensables para alcanzar su fin o da lugar a indefensión.',null),
('aux-ayto-mad:3-075bd6592c','aux-ayto-mad',3,'La realización de actuaciones fuera del tiempo establecido implica la anulabilidad del acto:','["Siempre, cualquiera que sea la naturaleza del término o plazo", "Solo si el retraso supera el doble del plazo establecido para la actuación", "Solo cuando lo imponga la naturaleza del término o plazo"]'::jsonb,2,'Art. 48.3 Ley 39/2015','Solo implica anulabilidad cuando así lo imponga la naturaleza del término o plazo.',null),
('aux-ayto-mad:3-b26fc882e5','aux-ayto-mad',3,'¿Qué actos puede convalidar la Administración subsanando los vicios de que adolezcan?','["Los nulos de pleno derecho", "Los anulables", "Cualquier acto"]'::jsonb,1,'Art. 52.1 Ley 39/2015','La Administración puede convalidar los actos anulables, subsanando los vicios de que adolezcan.',null),
('aux-ayto-mad:3-48cbe0ea4b','aux-ayto-mad',3,'¿Cuál es el plazo máximo para resolver que puede fijar una norma reguladora de un procedimiento?','["1 año, salvo que una norma con rango de ley o el Derecho de la Unión Europea establezcan uno menor", "6 meses, salvo que una norma con rango de ley establezca uno mayor o lo prevea el Derecho de la UE", "3 meses, salvo que una norma con rango de ley establezca uno mayor"]'::jsonb,1,'Art. 21.2 Ley 39/2015','El plazo no puede exceder de seis meses, salvo que una norma con rango de ley establezca uno mayor o lo prevea el Derecho de la UE.',null),
('aux-ayto-mad:3-a9f81e97e1','aux-ayto-mad',3,'Si la norma reguladora de un procedimiento no fija plazo máximo para resolver, este será de:','["3 meses", "1 mes", "10 días"]'::jsonb,0,'Art. 21.3 Ley 39/2015','Cuando las normas no fijen el plazo máximo, será de tres meses.',null),
('aux-ayto-mad:3-9a694079bb','aux-ayto-mad',3,'En los procedimientos iniciados a solicitud del interesado, el silencio administrativo es, como regla general:','["Desestimatorio, salvo las excepciones legales", "Estimatorio, salvo las excepciones legales", "Desestimatorio, sin excepción"]'::jsonb,1,'Art. 24.1 Ley 39/2015','El vencimiento del plazo sin resolución expresa legitima al interesado para entender estimada su solicitud, salvo las excepciones previstas.',null),
('aux-ayto-mad:3-9bcfb8da59','aux-ayto-mad',3,'En los procedimientos iniciados de oficio en los que la Administración ejerce potestades sancionadoras o de intervención, el vencimiento del plazo sin resolución produce:','["La desestimación por silencio", "La estimación por silencio", "La caducidad"]'::jsonb,2,'Art. 25.1 b) Ley 39/2015','En esos procedimientos se produce la caducidad.',null),
('aux-ayto-mad:3-6784d76fda','aux-ayto-mad',3,'Cuando los plazos se señalan por días, se entiende que son:','["Naturales, salvo que una ley disponga otro cómputo", "Hábiles, excluyéndose los sábados, los domingos y los festivos", "Hábiles, excluyéndose solo los domingos y los declarados festivos"]'::jsonb,1,'Art. 30.2 Ley 39/2015','Los plazos por días son hábiles y se excluyen sábados, domingos y festivos.',null),
('aux-ayto-mad:3-56593c39b4','aux-ayto-mad',3,'Los plazos señalados por horas no pueden tener una duración superior a:','["72 horas", "24 horas", "48 horas"]'::jsonb,1,'Art. 30.1 Ley 39/2015','Son hábiles todas las horas de un día hábil y no pueden superar 24 horas; si no, se expresan en días.',null),
('aux-ayto-mad:3-5df790e24b','aux-ayto-mad',3,'Los plazos fijados en meses o años se computan:','["Por días hábiles, a partir del día siguiente a la notificación o publicación", "A partir del día siguiente a la notificación o publicación del acto", "Por días naturales, desde el mismo día de la notificación o publicación"]'::jsonb,1,'Art. 30.4 Ley 39/2015','Se computan a partir del día siguiente a la notificación o publicación, de fecha a fecha.',null),
('aux-ayto-mad:3-3c7c09bfbf','aux-ayto-mad',3,'La ampliación de los plazos establecidos no puede exceder de:','["Tres meses", "La mitad de los mismos", "El doble de los mismos"]'::jsonb,1,'Art. 32.1 Ley 39/2015','La ampliación no puede exceder de la mitad del plazo.',null),
('aux-ayto-mad:3-f589b61b04','aux-ayto-mad',3,'¿Qué sistema de identificación electrónica menciona expresamente el art. 9.2 de la Ley 39/2015?','["El número de teléfono móvil asociado a una cuenta bancaria del interesado", "Los certificados electrónicos cualificados de firma electrónica", "La huella dactilar registrada en el DNI"]'::jsonb,1,'Art. 9.2 Ley 39/2015','Menciona los certificados cualificados de firma, los de sello electrónico y cualquier otro sistema que las Administraciones consideren válido.',null),
('aux-ayto-mad:3-bfa343ab92','aux-ayto-mad',3,'Con carácter general, para realizar cualquier actuación en el procedimiento, los interesados deben:','["Presentarse en persona", "Acreditar previamente su identidad", "Aportar un certificado de antecedentes"]'::jsonb,1,'Art. 11.1 Ley 39/2015','Basta con que acrediten previamente su identidad.',null),
('aux-ayto-mad:3-a1cadbcaca','aux-ayto-mad',3,'¿Para cuál de estas actuaciones exige la Ley 39/2015 el uso de la firma?','["Pedir información general", "Consultar el estado de un expediente", "Interponer recursos"]'::jsonb,2,'Art. 11.2 Ley 39/2015','Se exige firma para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos.',null),
('aux-ayto-mad:3-37c68f84ee','aux-ayto-mad',3,'¿Cuál es uno de los requisitos de validez de los documentos administrativos electrónicos?','["Incorporar la fecha de emisión y estar disponibles en papel, con la firma original del titular del órgano", "Llevar firma manuscrita escaneada y el sello del órgano emisor en cada página", "Incorporar la fecha de emisión y los metadatos mínimos exigidos"]'::jsonb,2,'Art. 26.2 Ley 39/2015','Deben contener información en soporte electrónico, datos de identificación, firmas electrónicas, fecha de emisión y metadatos mínimos.',null),
('aux-ayto-mad:3-1c95d2fc57','aux-ayto-mad',3,'Los interesados, ¿están obligados a aportar documentos elaborados por cualquier Administración?','["Solo en papel", "No", "Sí, si son originales"]'::jsonb,1,'Art. 28.2 Ley 39/2015','No están obligados a aportar documentos elaborados por cualquier Administración; esta puede consultarlos salvo oposición del interesado.',null),
('aux-ayto-mad:3-0a8d2b1c71','aux-ayto-mad',3,'La presentación de un documento en el registro electrónico en un día inhábil se entiende realizada:','["En la primera hora del primer día hábil siguiente", "En la última hora del último día hábil anterior al de la presentación", "El mismo día inhábil, a la hora en que se presentó"]'::jsonb,0,'Art. 31.2 b) Ley 39/2015','Se entiende realizada en la primera hora del primer día hábil siguiente, salvo que una norma permita la recepción en día inhábil.',null),
('aux-ayto-mad:3-d3397762ba','aux-ayto-mad',3,'Cuando en una solicitud figuren varios interesados, las actuaciones se efectuarán:','["Con todos a la vez, de forma obligatoria y en igualdad de condiciones, salvo renuncia expresa de alguno de ellos por escrito", "Con el representante o interesado que expresamente hayan señalado y, en su defecto, con el que figure en primer término", "Con el de mayor edad, salvo que todos hayan señalado expresamente a otro, y en su defecto con todos los interesados a la vez"]'::jsonb,1,'Art. 7 Ley 39/2015','En defecto de designación, con el que figure en primer término.',null),
('aux-ayto-mad:3-d092663f29','aux-ayto-mad',3,'La estimación por silencio administrativo tiene a todos los efectos la consideración de:','["Propuesta de resolución vinculante para el órgano competente", "Mera ficción sin efectos hasta que se dicte resolución expresa", "Acto administrativo finalizador del procedimiento"]'::jsonb,2,'Art. 24.2 Ley 39/2015','La desestimación por silencio solo permite interponer el recurso que proceda.',null),
('aux-ayto-mad:3-08ea13e759','aux-ayto-mad',3,'Son nulas de pleno derecho las disposiciones administrativas que:','["Establezcan la retroactividad de disposiciones favorables o ampliatorias de derechos individuales", "Establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales", "Se aprueben por el Consejo de Ministros"]'::jsonb,1,'Art. 47.2 Ley 39/2015','También las que vulneren la Constitución, las leyes o disposiciones de rango superior o regulen materias reservadas a la ley.',null),
('aux-ayto-mad:3-01062f1bea','aux-ayto-mad',3,'Los titulares de las unidades administrativas que tengan a su cargo la resolución o despacho de los asuntos:','["Responden solo ante los tribunales penales", "No tienen responsabilidad directa sobre la tramitación, que corresponde en exclusiva al titular del órgano superior jerárquico del que dependan", "Serán responsables directos de su tramitación y adoptarán las medidas para remover los obstáculos que retrasen el ejercicio de los derechos de los interesados"]'::jsonb,2,'Art. 20.1 Ley 39/2015','Son responsables directos de la tramitación.',null),
('aux-ayto-mad:3-9d7652f20b','aux-ayto-mad',3,'La Administración instructora deberá traducir al castellano:','["Los documentos que deban surtir efecto fuera del territorio de la Comunidad y los dirigidos a interesados que lo soliciten expresamente", "Solo los documentos dirigidos a interesados que residan fuera de la Comunidad Autónoma", "Los documentos que deban surtir efecto en la Comunidad, y los dirigidos a interesados que no conozcan la lengua cooficial aunque no lo pidan"]'::jsonb,0,'Art. 15.3 Ley 39/2015','Se traducen los que deban surtir efecto fuera de la Comunidad y los que pidan los interesados.',null),
('aux-ayto-mad:3-8204fb4895','aux-ayto-mad',3,'Tienen la consideración de Administraciones Públicas según el art. 2.3:','["La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local y los organismos públicos y entidades de derecho público del art. 2.2 a)", "La AGE, las Administraciones de las CCAA y las Entidades Locales, pero no los organismos públicos vinculados o dependientes", "La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local, las universidades privadas, los colegios profesionales y todas las empresas con capital público"]'::jsonb,0,'Art. 2.3 Ley 39/2015','Son AAPP la AGE, las CCAA, las Entidades Locales y los organismos y entidades de derecho público vinculados o dependientes.',null),
('aux-ayto-mad:3-1d7a62338e','aux-ayto-mad',3,'Según su art. 1.1, la Ley 39/2015 regula, entre otros aspectos:','["La organización interna de la AGE y de su sector público institucional, y el régimen de los órganos colegiados de todas las Administraciones", "Los requisitos de validez y eficacia de los actos administrativos y el procedimiento administrativo común a todas las Administraciones", "La jurisdicción contencioso-administrativa y sus procedimientos, así como el régimen de los recursos judiciales contra los actos de las Administraciones"]'::jsonb,1,'Art. 1.1 Ley 39/2015','Incluye el procedimiento sancionador, el de responsabilidad patrimonial y los principios de iniciativa legislativa y potestad reglamentaria.',null),
('aux-ayto-mad:3-d33e2419f9','aux-ayto-mad',3,'La comparecencia de las personas ante las oficinas públicas solo será obligatoria cuando:','["Así esté previsto en una norma con rango de ley", "Lo decida motivadamente el instructor del procedimiento", "Lo establezca una circular o instrucción interna del órgano"]'::jsonb,0,'Art. 19.1 Ley 39/2015','Solo es obligatoria si una norma con rango de ley lo prevé.',null),
('aux-ayto-mad:3-c6b07d350d','aux-ayto-mad',3,'¿Quién determina los órganos que tienen atribuidas las competencias de expedición de copias auténticas?','["Cada Administración Pública", "El Ministerio de Justicia para todas", "El Consejo de Estado"]'::jsonb,0,'Art. 27.1 Ley 39/2015','Cada Administración determina los órganos competentes para expedir copias auténticas.',null),
('aux-ayto-mad:3-fe18cacc28','aux-ayto-mad',3,'El registro electrónico de cada Administración permitirá la presentación de documentos:','["Todos los días del año durante las veinticuatro horas", "Solo en días hábiles, durante las veinticuatro horas", "Solo en horario de oficina de cada órgano"]'::jsonb,0,'Art. 31.2 Ley 39/2015','El registro electrónico funciona 24 horas los 365 días.',null),
('aux-ayto-mad:3-4e735c9c37','aux-ayto-mad',3,'El silencio será desestimatorio, entre otros, en los procedimientos relativos a:','["Inscripción en registros públicos", "El ejercicio del derecho de petición del art. 29 de la Constitución", "Las solicitudes de subvenciones de concurrencia competitiva, sin excepción"]'::jsonb,1,'Art. 24.1 Ley 39/2015','También en los de dominio o servicio público, medio ambiente, responsabilidad patrimonial, impugnación de actos y revisión de oficio a solicitud.',null),
('aux-ayto-mad:3-8a3ea9fa4d','aux-ayto-mad',3,'La representación podrá acreditarse mediante:','["Únicamente escritura notarial de apoderamiento, que deberá presentarse en papel en el registro del órgano competente en cada uno de los procedimientos en que se actúe", "Cualquier medio válido en Derecho que deje constancia fidedigna, comparecencia personal o electrónica, o inscripción en el registro de apoderamientos", "Cualquier medio, incluida una llamada telefónica o un correo electrónico sin firma, siempre que el funcionario que lo recibe deje constancia escrita en el expediente"]'::jsonb,1,'Art. 5.4 Ley 39/2015','Se admite cualquier medio válido en Derecho que deje constancia fidedigna.',null),
('aux-ayto-mad:3-4a2541a0af','aux-ayto-mad',3,'Los interesados podrán firmar a través de cualquier medio que permita acreditar:','["Su identidad, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, y la integridad e inalterabilidad del documento"]'::jsonb,2,'Art. 10.1 Ley 39/2015','La firma debe acreditar autenticidad de la voluntad y la integridad del documento.',null),
('aux-ayto-mad:3-5ce80bd773','aux-ayto-mad',3,'Si el interesado actúa por medio de representante:','["Se requiere poder notarial en todo caso", "Las actuaciones se entienden siempre con el interesado, y solo se comunican al representante a título informativo", "Las actuaciones se entenderán con el representante, salvo manifestación expresa en contrario del interesado"]'::jsonb,2,'Art. 5.1 Ley 39/2015','Se entienden con el representante salvo manifestación expresa en contrario.',null),
('aux-ayto-mad:3-9ef89a0600','aux-ayto-mad',3,'En los procedimientos iniciados de oficio, si el procedimiento se paraliza por causa imputable al interesado:','["Se archiva sin más trámite y se declara la caducidad del procedimiento de forma automática", "Se suspenderá el cómputo del plazo, pero solo si así lo acuerda el órgano por resolución motivada notificada al interesado", "Se interrumpirá el cómputo del plazo para resolver y notificar la resolución"]'::jsonb,2,'Art. 25.2 Ley 39/2015','La paralización imputable al interesado interrumpe el cómputo del plazo.',null),
('aux-ayto-mad:3-5455e5f1d0','aux-ayto-mad',3,'Cuando el último día del plazo sea inhábil:','["Se entenderá prorrogado al primer día hábil siguiente", "El plazo vence ese mismo día", "Se entenderá prorrogado al tercer día hábil siguiente"]'::jsonb,0,'Art. 30.5 Ley 39/2015','Se prorroga al primer día hábil siguiente.',null),
('aux-ayto-mad:3-203bd2bfd3','aux-ayto-mad',3,'Cuando la condición de interesado deriva de una relación jurídica transmisible, el derecho-habiente:','["Sucederá en tal condición cualquiera que sea el estado del procedimiento", "Sucederá en tal condición solo si el procedimiento no ha concluido la fase de audiencia a los interesados", "No sucede, debiendo iniciar un nuevo procedimiento en el plazo de diez días"]'::jsonb,0,'Art. 4.3 Ley 39/2015','Sucede en la condición de interesado en cualquier estado del procedimiento.',null),
('aux-ayto-mad:3-ec47b2e8b7','aux-ayto-mad',3,'Una notificación que contenga el texto íntegro del acto pero omita otro requisito surte efecto:','["Nunca", "Desde que el interesado realice actuaciones que supongan el conocimiento del contenido o interponga el recurso procedente", "A los seis meses de su práctica, si el interesado no ha reclamado"]'::jsonb,1,'Art. 40.3 Ley 39/2015','Surte efecto desde que el interesado realiza actuaciones que suponen conocer su contenido e alcance o interpone recurso.',null),
('aux-ayto-mad:3-31c364584f','aux-ayto-mad',3,'Las asociaciones y organizaciones representativas de intereses económicos y sociales son titulares de:','["Derechos fundamentales propios en todo procedimiento administrativo que afecte a sus asociados o al sector", "Intereses legítimos colectivos en los términos que la ley reconozca", "Intereses individuales de cada uno de sus asociados"]'::jsonb,1,'Art. 4.2 Ley 39/2015','Son titulares de intereses legítimos colectivos.',null),
('aux-ayto-mad:3-3b789524c9','aux-ayto-mad',3,'Los documentos presentados de manera presencial ante las Administraciones deberán ser:','["Digitalizados por la oficina de asistencia en materia de registros, devolviéndose los originales al interesado", "Archivados en papel sin digitalizar en la oficina que los recibió", "Enviados por correo postal al órgano competente para su digitalización en destino, junto con el resto del expediente"]'::jsonb,0,'Art. 16.5 Ley 39/2015','Se digitalizan y se devuelven los originales, salvo que la norma determine la custodia obligatoria.',null),
('aux-ayto-mad:3-f1e3659218','aux-ayto-mad',3,'La AGE, las CCAA y las Entidades Locales dispondrán de:','["Un registro electrónico general de apoderamientos", "Un registro notarial propio", "Un registro único estatal compartido obligatoriamente"]'::jsonb,0,'Art. 6.1 Ley 39/2015','Cada una dispone de un registro electrónico general de apoderamientos.',null),
('aux-ayto-mad:3-e1500a698c','aux-ayto-mad',3,'Los actos administrativos serán objeto de publicación cuando:','["Lo pida cualquier ciudadano interesado en conocerlos", "Lo establezcan las normas reguladoras de cada procedimiento o lo aconsejen razones de interés público", "Lo establezcan las normas reguladoras de cada procedimiento, pero nunca por razones de interés público apreciadas por el órgano"]'::jsonb,1,'Art. 45.1 Ley 39/2015','Se publican cuando lo establezcan sus normas reguladoras o lo aconsejen razones de interés público apreciadas por el órgano competente.',null),
('aux-ayto-mad:3-b26463d044','aux-ayto-mad',3,'Las notificaciones se practicarán preferentemente:','["Por medios electrónicos y, en todo caso, cuando el interesado esté obligado a recibirlas por esta vía", "Mediante anuncio en el BOE, salvo que el interesado señale un domicilio", "Por medios electrónicos o en papel, a elección del órgano que dicte el acto"]'::jsonb,0,'Art. 41.1 Ley 39/2015','Se practicarán preferentemente por medios electrónicos.',null),
('aux-ayto-mad:3-4d332a9177','aux-ayto-mad',3,'En los casos de estimación por silencio, la resolución expresa posterior:','["Deberá someterse a dictamen previo del Consejo de Estado", "Podrá ser confirmatoria o desestimatoria, según el resultado de la instrucción y las alegaciones de los interesados", "Solo podrá dictarse de ser confirmatoria del mismo"]'::jsonb,2,'Art. 24.3 a) Ley 39/2015','La resolución expresa posterior a la estimación por silencio solo puede confirmarla.',null),
('aux-ayto-mad:3-7e4f19d595','aux-ayto-mad',3,'Son interesados en el procedimiento, según el art. 4.1 a):','["Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos", "Quienes lo promuevan como titulares de derechos subjetivos, pero no de intereses legítimos colectivos", "Quienes tengan derechos que puedan resultar afectados por la decisión, aunque no se hayan personado"]'::jsonb,0,'Art. 4.1 a) Ley 39/2015','También los que tengan derechos que puedan resultar afectados y los titulares de intereses legítimos que se personen antes de la resolución definitiva.',null),
('aux-ayto-mad:3-bd3a0e1ff0','aux-ayto-mad',3,'Contra el acuerdo que resuelva sobre la ampliación del plazo máximo de resolución:','["Cabe recurso de reposición", "No cabrá recurso alguno", "Cabe recurso extraordinario de revisión"]'::jsonb,1,'Art. 23.2 Ley 39/2015','Ese acuerdo no es recurrible.',null),
('aux-ayto-mad:3-2a1f9b7625','aux-ayto-mad',3,'La ampliación excepcional del plazo máximo de resolución no podrá ser superior:','["Al plazo establecido para la tramitación del procedimiento", "A la mitad del plazo establecido para la tramitación del procedimiento", "A un año, cualquiera que sea el plazo inicial"]'::jsonb,0,'Art. 23.1 Ley 39/2015','Contra el acuerdo de ampliación no cabe recurso.',null),
('aux-ayto-mad:3-5d86571727','aux-ayto-mad',3,'Si concurren varios interesados en un procedimiento de la AGE y existe discrepancia en cuanto a la lengua:','["Lo decide el interesado que figure en primer lugar", "Se tramitará en ambas lenguas", "El procedimiento se tramitará en castellano"]'::jsonb,2,'Art. 15.1 Ley 39/2015','En caso de discrepancia, se tramita en castellano.',null),
('aux-ayto-mad:3-8c2010408f','aux-ayto-mad',3,'La ampliación de un plazo y su solicitud deberán producirse:','["En cualquier momento", "En todo caso antes del vencimiento del plazo de que se trate", "Hasta diez días después del vencimiento del plazo, si se justifica la causa"]'::jsonb,1,'Art. 32.3 Ley 39/2015','En ningún caso podrá ampliarse un plazo ya vencido.',null),
('aux-ayto-mad:3-c6697305f8','aux-ayto-mad',3,'A efectos de entender cumplida la obligación de notificar dentro del plazo máximo, basta:','["Con publicar un anuncio en el tablón de edictos de la sede electrónica, aunque no se haya intentado la notificación personal", "La notificación que contenga el texto íntegro de la resolución y el intento de notificación debidamente acreditado", "Con firmar la resolución dentro del plazo máximo, aunque su notificación se intente después de vencido ese plazo legal"]'::jsonb,1,'Art. 40.4 Ley 39/2015','Es suficiente la notificación con el texto íntegro y el intento de notificación debidamente acreditado.',null),
('aux-ayto-mad:3-6262dc49c5','aux-ayto-mad',3,'Según el art. 35.1 i), deben motivarse también:','["Los actos reglados, sin excepción, aunque no limiten derechos ni intereses", "Los actos de trámite que no decidan el fondo ni produzcan indefensión", "Los actos que se dicten en el ejercicio de potestades discrecionales"]'::jsonb,2,'Art. 35.1 i) Ley 39/2015','Se motivan los actos dictados en ejercicio de potestades discrecionales y los que deban serlo por disposición legal.',null),
('aux-ayto-mad:3-c0817556bb','aux-ayto-mad',3,'El órgano que declare la nulidad o anule las actuaciones dispondrá siempre la conservación de:','["Los actos de trámite anteriores a la infracción, aunque su contenido hubiera variado de no cometerse esta", "Aquellos actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción", "Ningún acto del procedimiento"]'::jsonb,1,'Art. 51 Ley 39/2015','Es el principio de conservación de actos y trámites.',null),
('aux-ayto-mad:3-ce593da9ca','aux-ayto-mad',3,'Cuando razones de interés público lo aconsejen, podrá acordarse la tramitación de urgencia, que supone:','["Reducir a la mitad los plazos del procedimiento ordinario, salvo los relativos a la presentación de solicitudes y recursos", "Reducir todos los plazos a cinco días, incluidos los de recursos", "Reducir a la mitad todos los plazos del procedimiento, incluidos los de presentación de solicitudes y recursos"]'::jsonb,0,'Art. 33.1 Ley 39/2015','Se reducen los plazos a la mitad, salvo los de solicitudes y recursos.',null),
('aux-ayto-mad:3-148d991a65','aux-ayto-mad',3,'Solicitado el certificado acreditativo del silencio, este deberá emitirse en el plazo máximo de:','["Quince días", "Tres meses", "Un mes"]'::jsonb,0,'Art. 24.4 Ley 39/2015','El certificado del silencio se emite en un máximo de quince días.',null),
('aux-ayto-mad:3-fba6c27b91','aux-ayto-mad',3,'Si un plazo fijado en meses vence en un mes en el que no hay día equivalente al de la notificación:','["El plazo se considera vencido el día 28", "El plazo expira el último día del mes", "El plazo expira el primer día del mes siguiente"]'::jsonb,1,'Art. 30.4 Ley 39/2015','Si no hay día equivalente, el plazo expira el último día del mes.',null),
('aux-ayto-mad:3-f6f0ef721c','aux-ayto-mad',3,'Si durante la instrucción de un procedimiento no publicado se advierte la existencia de personas titulares de derechos o intereses legítimos que puedan resultar afectados:','["Se suspenderá el procedimiento hasta que soliciten personarse", "Se archivará el procedimiento", "Se comunicará a dichas personas la tramitación del procedimiento"]'::jsonb,2,'Art. 8 Ley 39/2015','Se les comunica la tramitación.',null),
('aux-ayto-mad:3-4dbe9a4154','aux-ayto-mad',3,'La Administración está obligada a dictar resolución expresa y a notificarla:','["En todos los procedimientos, cualquiera que sea su forma de iniciación", "En todos los procedimientos, salvo en los iniciados de oficio, en que basta la caducidad", "Solo en los procedimientos iniciados a solicitud del interesado"]'::jsonb,0,'Art. 21.1 Ley 39/2015','La obligación de resolver alcanza a todos los procedimientos, salvo las excepciones legales.',null),
('aux-ayto-mad:3-3b5031fcda','aux-ayto-mad',3,'Si un día es hábil en el municipio del interesado e inhábil en la sede del órgano administrativo, o a la inversa:','["Se considerará hábil en todo caso", "Se aplica el calendario del interesado", "Se considerará inhábil en todo caso"]'::jsonb,2,'Art. 30.6 Ley 39/2015','En caso de discrepancia, se considera inhábil.',null),
('aux-ayto-mad:3-3fc801a179','aux-ayto-mad',3,'La falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto, siempre que se aporte o subsane en el plazo de:','["Un mes desde el requerimiento", "Diez días, o el plazo superior que establezca el órgano cuando las circunstancias lo requieran", "Cinco días improrrogables desde el requerimiento, sin que el órgano pueda establecer otro plazo"]'::jsonb,1,'Art. 5.6 Ley 39/2015','El plazo para subsanar es de diez días.',null),
('aux-ayto-mad:3-24c426a89c','aux-ayto-mad',3,'Los interesados que conozcan datos que permitan identificar a otros interesados que no hayan comparecido en el procedimiento:','["Solo deben comunicarlos ante un juez", "Pueden comunicarlos voluntariamente, sin estar obligados a ello", "Tienen el deber de proporcionárselos a la Administración actuante"]'::jsonb,2,'Art. 18.2 Ley 39/2015','Existe el deber de proporcionar esos datos a la Administración.',null),
('aux-ayto-mad:3-a406bc6c92','aux-ayto-mad',3,'La publicación sustituye a la notificación, entre otros casos, cuando el acto:','["Sea una sanción leve impuesta a un interesado identificado y con domicilio conocido", "Tenga por destinatario a una pluralidad indeterminada de personas", "Se dicte en un procedimiento iniciado de oficio que afecte a varios interesados identificados"]'::jsonb,1,'Art. 45.1 a) Ley 39/2015','También en los actos de procedimientos selectivos o de concurrencia competitiva.',null),
('aux-ayto-mad:3-f003ddcbea','aux-ayto-mad',3,'Las Administraciones están obligadas a verificar la identidad de los interesados mediante la comprobación de:','["Su nombre y apellidos o denominación o razón social, que consten en el DNI o documento identificativo equivalente", "Su huella dactilar o cualquier otro dato biométrico que conste en el DNI o en el documento identificativo equivalente", "Su dirección de correo electrónico"]'::jsonb,0,'Art. 9.1 Ley 39/2015','Se verifica con el nombre y apellidos o razón social del DNI o documento equivalente.',null),
('aux-ayto-mad:3-731a06679a','aux-ayto-mad',3,'Si nadie se hace cargo de la notificación en papel en el domicilio, se repetirá:','["No se repite, y se publica directamente en el BOE", "Una sola vez y en la misma hora dentro de los cinco días siguientes", "Una sola vez y en una hora distinta dentro de los tres días siguientes"]'::jsonb,2,'Art. 42.2 Ley 39/2015','Se repite por una sola vez y en hora distinta dentro de los tres días siguientes.',null),
('aux-ayto-mad:3-98f44c75fd','aux-ayto-mad',3,'El incumplimiento de la obligación de dictar resolución expresa en plazo dará lugar a:','["La estimación automática de la solicitud en todo caso, sin ninguna otra consecuencia para el órgano o para el personal responsable", "La exigencia de responsabilidad disciplinaria, sin perjuicio de la que hubiere lugar de acuerdo con la normativa aplicable", "La nulidad de pleno derecho del procedimiento"]'::jsonb,1,'Art. 21.6 Ley 39/2015','El personal y los titulares de órganos son responsables directos y responden disciplinariamente.',null),
('aux-ayto-mad:3-5b000b5042','aux-ayto-mad',3,'Deben ser motivados, con sucinta referencia de hechos y fundamentos de derecho:','["Los actos que limiten derechos subjetivos o intereses legítimos", "Solo las disposiciones de carácter general y los actos que pongan fin a la vía administrativa", "Todos los actos de trámite, aunque no limiten derechos ni decidan el fondo"]'::jsonb,0,'Art. 35.1 a) Ley 39/2015','El art. 35.1 a) exige motivar los actos que limiten derechos subjetivos o intereses legítimos.',null),
('aux-ayto-mad:3-ca2f2146ae','aux-ayto-mad',3,'Deberá acreditarse la representación para:','["Consultar el estado del expediente", "Cualquier acto de mero trámite, incluida la consulta del expediente, la obtención de copias y la petición de información general", "Formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos"]'::jsonb,2,'Art. 5.3 Ley 39/2015','Para los actos de mero trámite la representación se presume.',null),
('aux-ayto-mad:3-d56c78890a','aux-ayto-mad',3,'Las copias auténticas de documentos realizadas por los órganos competentes:','["Solo tienen validez dentro del mismo procedimiento en el que se expidieron", "Tendrán la misma validez y eficacia que los documentos originales", "Tienen menos valor probatorio que el original, salvo que se compulsen ante notario"]'::jsonb,1,'Art. 27.2 Ley 39/2015','Las copias auténticas tienen la misma validez y eficacia que los originales.',null),
('aux-ayto-mad:3-a49f6b04fe','aux-ayto-mad',3,'¿Cuál de los siguientes es un sistema de identificación electrónica previsto en el art. 9.2?','["Una llamada telefónica grabada", "Los sistemas basados en certificados electrónicos cualificados de firma electrónica", "El envío de una fotocopia escaneada del DNI por correo electrónico, junto con la solicitud firmada a mano"]'::jsonb,1,'Art. 9.2 Ley 39/2015','También los certificados cualificados de sello electrónico y otros sistemas que las AAPP consideren válidos.',null),
('aux-ayto-mad:3-8839e7738a','aux-ayto-mad',3,'Según el art. 38, los actos de las Administraciones sujetos al Derecho Administrativo son:','["Ejecutivos solo cuando sean firmes en vía administrativa y no se haya interpuesto recurso contencioso-administrativo", "Ejecutivos con arreglo a lo dispuesto en la Ley", "Meramente declarativos hasta que se confirmen judicialmente"]'::jsonb,1,'Art. 38 Ley 39/2015','Los actos sujetos al Derecho Administrativo serán ejecutivos con arreglo a lo dispuesto en la Ley.',null),
('aux-ayto-mad:3-fd84a372e2','aux-ayto-mad',3,'¿Cuál de las siguientes es una tipología de apoderamiento inscribible en el registro electrónico de apoderamientos?','["Un poder otorgado verbalmente ante el funcionario", "Un poder general para que el apoderado actúe en nombre del poderdante en cualquier actuación ante cualquier Administración", "Un poder sin identificar al apoderado"]'::jsonb,1,'Art. 6 Ley 39/2015','Las tipologías son: poder general, poder ante una Administración u Organismo concreto y poder para trámites específicos.',null),
('aux-ayto-mad:3-2deb8983c5','aux-ayto-mad',3,'Se entiende por documentos públicos administrativos:','["Cualquier documento firmado electrónicamente por un ciudadano y presentado en la sede electrónica de una Administración", "Los válidamente emitidos por los órganos de las Administraciones Públicas", "Los documentos autorizados por notario, exclusivamente"]'::jsonb,1,'Art. 26.1 Ley 39/2015','Se emiten por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma.',null),
('aux-ayto-mad:3-aee1e3e2f0','aux-ayto-mad',3,'La ampliación de plazos por el tiempo máximo permitido se aplicará en todo caso a los procedimientos tramitados por:','["Los Ayuntamientos de municipios de gran población, y los que exijan algún trámite en otra Comunidad Autónoma", "Las misiones diplomáticas y oficinas consulares, y los que exijan algún trámite en el extranjero", "Los órganos colegiados de cualquier Administración, y los que exijan algún trámite en otra Comunidad Autónoma"]'::jsonb,1,'Art. 32.2 Ley 39/2015','Se aplica a misiones diplomáticas, oficinas consulares y trámites en el extranjero o con interesados residentes fuera de España.',null),
('aux-ayto-mad:3-02af3d4894','aux-ayto-mad',3,'Las Administraciones no exigirán a los interesados la presentación de documentos originales:','["Salvo que, con carácter excepcional, la normativa reguladora aplicable establezca lo contrario", "Salvo que el funcionario que tramite el procedimiento lo considere oportuno para comprobar su autenticidad", "En ningún caso, sin excepciones"]'::jsonb,0,'Art. 28.3 Ley 39/2015','La regla es no exigir originales; solo excepcionalmente por normativa.',null),
('aux-ayto-mad:3-74cd0e674c','aux-ayto-mad',3,'Excepcionalmente, se podrá otorgar eficacia retroactiva a los actos cuando:','["Se trate de actos de gravamen que restrinjan derechos individuales y así lo prevea expresamente una norma reglamentaria", "Sean sanciones más favorables que las anteriores", "Se dicten en sustitución de actos anulados o produzcan efectos favorables al interesado"]'::jsonb,2,'Art. 39.3 Ley 39/2015','Cabe retroactividad cuando se dicten en sustitución de actos anulados o produzcan efectos favorables, si los supuestos de hecho existían y no se lesionan derechos de terceros.',null),
('aux-ayto-mad:3-0024559e3c','aux-ayto-mad',3,'Cuando se soliciten informes preceptivos a un órgano, el plazo máximo para resolver puede suspenderse por el tiempo que medie entre la petición y la recepción del informe, sin que pueda exceder de:','["Diez días", "Un mes", "Tres meses"]'::jsonb,2,'Art. 22.1 d) Ley 39/2015','Esta suspensión no puede exceder en ningún caso de tres meses.',null),
('aux-ayto-mad:3-f70620e0bf','aux-ayto-mad',3,'Los titulares de intereses legítimos que puedan resultar afectados por la resolución son interesados si:','["Lo solicitan antes del inicio del procedimiento", "Lo autoriza el instructor", "Se personan en el procedimiento en tanto no haya recaído resolución definitiva"]'::jsonb,2,'Art. 4.1 c) Ley 39/2015','Deben personarse antes de la resolución definitiva.',null),
('aux-ayto-mad:3-8a456851f8','aux-ayto-mad',3,'La nulidad o anulabilidad de un acto:','["Implica siempre la nulidad de todo el procedimiento", "Implica la de todos los actos posteriores del procedimiento, aunque sean independientes del primero", "No implica la de los sucesivos en el procedimiento que sean independientes del primero"]'::jsonb,2,'Art. 49.1 Ley 39/2015','No se extiende a los actos sucesivos que sean independientes del primero.',null),
('aux-ayto-mad:3-b67cd4d46b','aux-ayto-mad',3,'En caso de desestimación por silencio, la resolución expresa posterior:','["Se adoptará por la Administración sin vinculación alguna al sentido del silencio", "No puede dictarse", "Debe ser necesariamente desestimatoria, en coherencia con el sentido del silencio producido"]'::jsonb,0,'Art. 24.3 b) Ley 39/2015','En la estimación por silencio, en cambio, la resolución posterior solo puede ser confirmatoria.',null),
('aux-ayto-mad:3-89c491485c','aux-ayto-mad',3,'Tienen capacidad de obrar ante las Administraciones Públicas:','["Solo los mayores de 21 años y las personas jurídicas inscritas en un registro público", "Las personas físicas o jurídicas que la ostenten con arreglo a las normas civiles", "Las personas físicas o jurídicas con certificado digital, aunque no tengan capacidad conforme a las normas civiles"]'::jsonb,1,'Art. 3 a) Ley 39/2015','Tienen capacidad las personas que la tengan según las normas civiles.',null),
('aux-ayto-mad:3-2e210d0c84','aux-ayto-mad',3,'En los procedimientos iniciados de oficio de los que pudiera derivarse el reconocimiento de derechos o situaciones favorables, el vencimiento del plazo sin resolución permite a los interesados:','["Entender estimadas sus pretensiones por silencio administrativo positivo", "Solicitar que se declare la caducidad del procedimiento", "Entender desestimadas sus pretensiones por silencio administrativo"]'::jsonb,2,'Art. 25.1 a) Ley 39/2015','En estos procedimientos el silencio es desestimatorio.',null),
('aux-ayto-mad:3-9610fb5881','aux-ayto-mad',3,'Según el art. 3 c), los grupos de afectados y las entidades sin personalidad jurídica tienen capacidad de obrar:','["Cuando se inscriban en el registro correspondiente de la Administración ante la que actúen", "Cuando la ley así lo declare expresamente", "Siempre, cualquiera que sea su número de miembros"]'::jsonb,1,'Art. 3 c) Ley 39/2015','Grupos de afectados, uniones y entidades sin personalidad y patrimonios independientes tienen capacidad cuando la ley lo declare expresamente.',null),
('aux-ayto-mad:3-d69d8d567d','aux-ayto-mad',3,'Si el vicio de un acto consiste en incompetencia no determinante de nulidad, la convalidación podrá realizarse por:','["El interesado afectado, mediante escrito en el que manifieste su conformidad con el acto viciado", "El órgano competente, cuando sea superior jerárquico del que dictó el acto viciado", "El propio órgano que dictó el acto, mediante una resolución posterior que subsane el vicio de incompetencia"]'::jsonb,1,'Art. 52.3 Ley 39/2015','La incompetencia no determinante de nulidad se convalida por el órgano competente superior jerárquico.',null),
('aux-ayto-mad:3-3b7b2ed1f4','aux-ayto-mad',3,'Las Administraciones podrán practicar notificaciones por medios no electrónicos cuando:','["Sea fin de semana", "Para asegurar la eficacia de la actuación sea necesario practicarla por entrega directa de un empleado público", "El interesado esté obligado a relacionarse electrónicamente con la Administración y no haya accedido a la notificación"]'::jsonb,1,'Art. 41.2 b) Ley 39/2015','También cuando el interesado comparezca espontáneamente en una oficina de asistencia y solicite la comunicación personal.',null),
('aux-ayto-mad:3-a1341b5988','aux-ayto-mad',3,'Si el órgano aprecia que la publicación íntegra de un acto lesiona derechos o intereses legítimos:','["Se limitará a publicar una somera indicación del contenido y del lugar donde los interesados pueden comparecer para conocerlo", "No se publicará ni notificará el acto, y el órgano se limitará a comunicar a los interesados que existe una resolución que les afecta", "Se publicará íntegramente igualmente, sin perjuicio de la responsabilidad patrimonial que proceda por los daños causados a los interesados afectados"]'::jsonb,0,'Art. 46 Ley 39/2015','Se publica una somera indicación del contenido y del lugar donde comparecer en el plazo que se establezca.',null),
('aux-ayto-mad:3-9fae110f35','aux-ayto-mad',3,'Las notificaciones por medios electrónicos se entienden practicadas:','["Cuando el interesado contesta", "Cuando se envía al interesado el aviso de puesta a disposición por correo electrónico o SMS", "En el momento en que se produzca el acceso a su contenido"]'::jsonb,2,'Art. 43.2 Ley 39/2015','Se entienden practicadas en el momento del acceso a su contenido.',null),
('aux-ayto-mad:3-a478b4aca7','aux-ayto-mad',3,'En el asiento de registro debe constar, entre otros datos:','["Un número, epígrafe expresivo de su naturaleza, fecha y hora de presentación, identificación del interesado y referencia al contenido", "Un número, fecha de presentación, identificación del interesado y del órgano destinatario, pero no la hora de presentación ni ninguna referencia a su contenido", "El sentido previsible de la resolución"]'::jsonb,0,'Art. 16.2 Ley 39/2015','Se emite recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada.',null),
('aux-ayto-mad:3-cae94648ea','aux-ayto-mad',3,'Los términos y plazos establecidos en las leyes obligan:','["A las autoridades y personal al servicio de las Administraciones competentes para la tramitación, así como a los interesados", "Solo a la Administración, que debe resolver en el plazo máximo", "A las autoridades y personal de la Administración, pero no a los interesados, que pueden cumplir los trámites en cualquier momento"]'::jsonb,0,'Art. 29 Ley 39/2015','Los plazos obligan tanto a la Administración como a los interesados.',null),
('aux-ayto-mad:3-10fdba1a84','aux-ayto-mad',3,'La eficacia de un acto quedará demorada cuando:','["Así lo exija su contenido o esté supeditada a su notificación, publicación o aprobación superior", "Así lo decida el funcionario instructor, aunque su contenido no lo exija ni dependa de notificación o aprobación", "Se haya dictado en el mes de agosto o en un periodo vacacional, salvo que el interesado solicite su eficacia inmediata"]'::jsonb,0,'Art. 39.2 Ley 39/2015','La eficacia se demora cuando lo exija el contenido del acto o esté supeditada a notificación, publicación o aprobación superior.',null),
('aux-ayto-mad:3-bd94dc34c3','aux-ayto-mad',3,'No se tendrán por presentados en el registro:','["Aquellos documentos e información cuyo régimen especial establezca otra forma de presentación", "Los presentados por un representante cuya representación no esté inscrita", "Los presentados en las oficinas de Correos sin sello de fechas"]'::jsonb,0,'Art. 16.8 Ley 39/2015','No se tienen por presentados los que tengan un régimen especial con otra forma de presentación.',null),
('aux-ayto-mad:3-6a32645e0a','aux-ayto-mad',3,'Como regla general, los actos administrativos se producirán:','["Por escrito en papel, salvo que el interesado esté obligado a relacionarse electrónicamente", "De la forma que elija el interesado en su solicitud, por escrito o verbalmente, en papel o electrónicamente", "Por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma"]'::jsonb,2,'Art. 36.1 Ley 39/2015','Se producen por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada.',null),
('aux-ayto-mad:3-f040c78c5e','aux-ayto-mad',3,'Las resoluciones administrativas de carácter particular no podrán vulnerar una disposición de carácter general:','["Aunque procedan de un órgano de igual o superior jerarquía al que dictó la disposición", "Salvo que lo autorice expresamente el Consejo de Ministros", "Salvo que sean favorables al interesado"]'::jsonb,0,'Art. 37.1 Ley 39/2015','Es el principio de inderogabilidad singular de los reglamentos.',null),
('aux-ayto-mad:3-27ef07925d','aux-ayto-mad',3,'Los plazos expresados en días se contarán:','["Desde el día en que se dictó el acto, aunque se notifique o publique con posterioridad a esa fecha", "Desde el mismo día de la notificación o publicación del acto", "A partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto"]'::jsonb,2,'Art. 30.3 Ley 39/2015','Se cuentan desde el día siguiente a la notificación o publicación.',null),
('aux-ayto-mad:3-837aa7c69b','aux-ayto-mad',3,'Según el art. 34.1 de la Ley 39/2015, los actos administrativos se producirán:','["Por el órgano competente, aunque no se ajusten al procedimiento establecido si el contenido es conforme a Derecho", "Por el funcionario que tramite el expediente, con el visto bueno del titular del órgano", "Por el órgano competente, ajustándose a los requisitos y al procedimiento establecido"]'::jsonb,2,'Art. 34.1 Ley 39/2015','Los actos se producen por el órgano competente ajustándose a los requisitos y al procedimiento establecido.',null),
('aux-ayto-mad:3-69b3b20382','aux-ayto-mad',3,'La obligación de notificar en plazo se entiende cumplida, en las notificaciones electrónicas, con:','["La puesta a disposición de la notificación en la sede electrónica o en la dirección electrónica habilitada única", "El envío del aviso al correo electrónico del interesado, aunque no se ponga a disposición la notificación", "La publicación de un anuncio en el BOE"]'::jsonb,0,'Art. 43.3 Ley 39/2015','Se entiende cumplida con la puesta a disposición en la sede electrónica o la dirección electrónica habilitada única.',null),
('aux-ayto-mad:3-5722026762','aux-ayto-mad',3,'¿A quién debe notificar el órgano que dicte una resolución?','["A todos los vecinos del municipio afectado", "A los interesados cuyos derechos e intereses sean afectados por ella", "Al superior jerárquico, que da traslado a los interesados"]'::jsonb,1,'Art. 40.1 Ley 39/2015','Se notifica a los interesados cuyos derechos e intereses sean afectados por las resoluciones y actos.',null),
('aux-ayto-mad:3-9d0a3ccb96','aux-ayto-mad',3,'La nulidad en parte de un acto no implica la de las partes independientes, salvo que:','["La parte viciada sea de tal importancia que sin ella el acto no se habría dictado", "Se haya notificado conjuntamente y en un mismo documento a todos los interesados afectados", "Lo solicite el interesado en el recurso que interponga contra el acto, justificando su conexión"]'::jsonb,0,'Art. 49.2 Ley 39/2015','Las partes independientes se mantienen, salvo que la parte viciada fuera esencial.',null),
('aux-ayto-mad:3-1e418f3e75','aux-ayto-mad',3,'En los procedimientos tramitados por la AGE, la lengua será:','["El castellano, aunque los interesados que se dirijan a órganos con sede en una Comunidad con lengua cooficial podrán utilizar también esta", "El castellano, sin que los interesados puedan utilizar ninguna otra lengua, aunque se dirijan a órganos con sede en una Comunidad Autónoma con lengua cooficial", "La que elija el funcionario que tramite el procedimiento, castellano o lengua cooficial, sin que el interesado pueda solicitar que se utilice otra"]'::jsonb,0,'Art. 15.1 Ley 39/2015','La lengua de la AGE es el castellano, con posibilidad de usar la cooficial ante órganos con sede en esa Comunidad.',null),
('aux-ayto-mad:3-fbfc6fba38','aux-ayto-mad',3,'Según el art. 47.1 f), son nulos los actos expresos o presuntos contrarios al ordenamiento por los que se adquieren facultades o derechos:','["Cuando sean favorables al interesado y no haya terceros afectados por ellos", "Cuando se hayan publicado en el boletín oficial sin haberse notificado a los interesados", "Cuando se carezca de los requisitos esenciales para su adquisición"]'::jsonb,2,'Art. 47.1 f) Ley 39/2015','Son nulos si se adquieren facultades o derechos careciendo de los requisitos esenciales.',null),
('aux-ayto-mad:3-3fa5fe4d20','aux-ayto-mad',3,'Los poderes inscritos en el registro electrónico de apoderamientos tendrán una validez máxima de:','["Diez años a contar desde la fecha de inscripción", "Indefinida, hasta su revocación", "Cinco años a contar desde la fecha de inscripción"]'::jsonb,2,'Art. 6.6 Ley 39/2015','Validez máxima de cinco años; pueden revocarse o prorrogarse, la prórroga por un máximo de cinco años.',null),
('aux-ayto-mad:3-02123756ea','aux-ayto-mad',3,'Es nulo de pleno derecho el acto que:','["Se dicte fuera del plazo establecido", "Lesione los derechos y libertades susceptibles de amparo constitucional", "Incurra en desviación de poder o en cualquier otra infracción del ordenamiento"]'::jsonb,1,'Art. 47.1 a) Ley 39/2015','La lesión de derechos susceptibles de amparo es causa de nulidad de pleno derecho.',null),
('aux-ayto-mad:3-c186415fe6','aux-ayto-mad',3,'Contra el acuerdo que declare la tramitación de urgencia:','["No cabrá recurso alguno, sin perjuicio del procedente contra la resolución que ponga fin al procedimiento", "Cabe recurso potestativo de reposición en el plazo de un mes desde su notificación, que no suspende la tramitación", "Cabe recurso contencioso-administrativo inmediato"]'::jsonb,0,'Art. 33.2 Ley 39/2015','El acuerdo de urgencia no es recurrible.',null),
('aux-ayto-mad:3-f25d679a62','aux-ayto-mad',3,'Si en la notificación en papel en el domicilio el interesado no está presente, podrá hacerse cargo de ella:','["Cualquier persona mayor de 14 años que se encuentre en el domicilio y haga constar su identidad", "Solo un familiar mayor de 18 años", "Cualquier persona mayor de 16 años que se encuentre en el domicilio, sin necesidad de hacer constar su identidad"]'::jsonb,0,'Art. 42.2 Ley 39/2015','Puede recogerla cualquier persona mayor de catorce años que esté en el domicilio y haga constar su identidad.',null),
('aux-ayto-mad:3-b38912d1b6','aux-ayto-mad',3,'Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto producirán los efectos de este. Esto se denomina:','["Conservación de actos y trámites", "Conversión de actos viciados", "Convalidación"]'::jsonb,1,'Art. 50 Ley 39/2015','Es la conversión de actos viciados.',null),
('aux-ayto-mad:3-92f40a8b4a','aux-ayto-mad',3,'Las Administraciones deben publicar y mantener actualizadas en el portal web:','["Las relaciones de procedimientos de su competencia, con los datos de los interesados y el estado de tramitación de cada expediente", "Las relaciones de procedimientos de su competencia, con indicación de los plazos máximos de duración y de los efectos del silencio administrativo", "Las resoluciones judiciales que les afecten"]'::jsonb,1,'Art. 21.4 Ley 39/2015','Deben publicar los procedimientos, sus plazos máximos y los efectos del silencio.',null),
('aux-ayto-mad:3-9d669884e5','aux-ayto-mad',3,'Según el art. 1.2, solo podrán incluirse trámites adicionales o distintos de los de la Ley 39/2015:','["Por decisión del órgano instructor", "Mediante reglamento, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento", "Mediante ley, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento"]'::jsonb,2,'Art. 1.2 Ley 39/2015','Solo mediante ley y de forma motivada.',null),
('aux-ayto-mad:3-f02b4e97b0','aux-ayto-mad',3,'Es nulo de pleno derecho el acto:','["Que sea constitutivo de infracción penal o se dicte como consecuencia de esta", "Que incurra en cualquier infracción del ordenamiento jurídico, incluida la desviación de poder", "Dictado un día inhábil"]'::jsonb,0,'Art. 47.1 d) Ley 39/2015','Los actos constitutivos de infracción penal o dictados como consecuencia de esta son nulos.',null),
('aux-ayto-mad:3-72c2a71fa8','aux-ayto-mad',3,'Para los actos y gestiones de mero trámite, la representación:','["Se presumirá", "Debe inscribirse en el registro de apoderamientos", "No está permitida"]'::jsonb,0,'Art. 5.3 Ley 39/2015','En los actos de mero trámite se presume la representación.',null),
('aux-ayto-mad:3-3e60451f0e','aux-ayto-mad',3,'Son nulos de pleno derecho los actos:','["Que no indiquen los recursos", "Que tengan un contenido imposible", "Dictados por órgano jerárquicamente incompetente"]'::jsonb,1,'Art. 47.1 c) Ley 39/2015','El contenido imposible es causa de nulidad (art. 47.1 c).',null),
('aux-ayto-mad:3-d6e062bcb5','aux-ayto-mad',3,'Si la Administración no envía el aviso al dispositivo o correo electrónico del interesado de que tiene una notificación electrónica:','["La notificación debe repetirse en papel en el domicilio", "El plazo para acceder a la notificación se amplía diez días", "La notificación puede considerarse plenamente válida"]'::jsonb,2,'Art. 41.6 Ley 39/2015','La falta de práctica del aviso no impide que la notificación sea considerada plenamente válida.',null),
('aux-ayto-mad:3-a4b841e063','aux-ayto-mad',3,'Con carácter general, ¿pueden las Administraciones exigir a los interesados la presentación de documentos originales?','["No, salvo que excepcionalmente la normativa reguladora aplicable establezca lo contrario", "No, en ningún caso, ni siquiera cuando lo establezca una norma reguladora", "Sí, siempre que el procedimiento se haya iniciado a solicitud del interesado"]'::jsonb,0,'Art. 28.3 Ley 39/2015','Las Administraciones no exigen originales, salvo que con carácter excepcional la normativa aplicable establezca lo contrario.',null),
('aux-ayto-mad:3-35e487fcd5','aux-ayto-mad',3,'Si existen dudas derivadas de la calidad de la copia aportada por el interesado, la Administración puede:','["Exigir que el interesado aporte en el plazo de un mes una copia compulsada por notario o por el secretario de un ayuntamiento", "Solicitar de manera motivada el cotejo de la copia, requiriendo la exhibición del original", "Tener la copia por no presentada y archivar el procedimiento de oficio"]'::jsonb,1,'Art. 28.5 Ley 39/2015','Excepcionalmente, la Administración puede solicitar motivadamente el cotejo y requerir la exhibición del documento original.',null),
('aux-ayto-mad:3-07e314b2b9','aux-ayto-mad',3,'Según el art. 28.7 de la Ley 39/2015, de la veracidad de los documentos que presentan responden:','["El órgano instructor del procedimiento", "Los interesados", "El funcionario que digitaliza los documentos"]'::jsonb,1,'Art. 28.7 Ley 39/2015','Los interesados se responsabilizarán de la veracidad de los documentos que presenten.',null),
('aux-ayto-mad:3-42f085c79f','aux-ayto-mad',3,'La presentación de documentos en el registro electrónico en un día inhábil se entiende realizada:','["En el mismo día inhábil, a todos los efectos", "Al día siguiente, aunque también sea inhábil", "En la primera hora del primer día hábil siguiente, salvo que una norma permita expresamente la recepción en día inhábil"]'::jsonb,2,'Art. 31.2 b) Ley 39/2015','Los documentos se consideran presentados por el orden de hora efectiva en el que lo fueron en el día inhábil.',null),
('aux-ayto-mad:3-75bb967412','aux-ayto-mad',3,'El registro electrónico de cada Administración permite la presentación de documentos:','["Todos los días del año, pero solo en el horario de atención al público", "Todos los días del año, durante las veinticuatro horas", "En días hábiles, de 9 a 14 horas, como las oficinas presenciales"]'::jsonb,1,'Art. 31.2 a) Ley 39/2015','El cómputo de plazos se rige por la fecha y hora oficial de la sede electrónica.',null),
('aux-ayto-mad:3-8ede17cf74','aux-ayto-mad',3,'Las copias auténticas de documentos públicos administrativos o privados realizadas por las Administraciones:','["Son válidas dentro de la Administración que las expide y en sus organismos públicos", "Tienen valor informativo y no pueden aportarse a otros procedimientos", "Tienen la misma validez y eficacia que los documentos originales"]'::jsonb,2,'Art. 27.2 Ley 39/2015','Pueden expedirse en papel o en soporte electrónico.',null),
('aux-ayto-mad:3-be87d9ad15','aux-ayto-mad',3,'Según el artículo 9 de la Ley 39/2015, ¿cuál de los siguientes es un sistema válido para que los interesados se identifiquen electrónicamente ante las Administraciones?','["El número de teléfono móvil", "La fotocopia del DNI enviada por correo electrónico", "Los sistemas de clave concertada"]'::jsonb,2,'Art. 9.2 Ley 39/2015','También los certificados electrónicos cualificados de firma y de sello y cualquier otro sistema que las Administraciones consideren válido en los términos y condiciones que se establezcan.',null),
('aux-ayto-mad:3-29730b0800','aux-ayto-mad',3,'Según el artículo 43 de la Ley 39/2015, la notificación por medios electrónicos se entiende rechazada cuando:','["Han transcurrido diez días naturales desde su puesta a disposición sin que se acceda a su contenido", "Han transcurrido cinco días hábiles desde su envío sin que el interesado haya contestado ni presentado alegaciones", "El interesado no contesta en veinticuatro horas al aviso enviado a su dirección de correo electrónico o a su móvil"]'::jsonb,0,'Art. 43.2 Ley 39/2015','Se entiende practicada en el momento en que se produce el acceso a su contenido.',null),
('aux-ayto-mad:3-a96393bd5d','aux-ayto-mad',3,'Según la Ley 39/2015, toda notificación debe cursarse dentro del plazo de:','["Tres días a partir de la fecha en que el acto haya adquirido firmeza", "Diez días a partir de la fecha en que el acto haya sido dictado", "Quince días a partir de la fecha en que el acto haya sido publicado"]'::jsonb,1,'Art. 40.2 Ley 39/2015','Debe contener el texto íntegro de la resolución, si pone fin o no a la vía administrativa y los recursos que procedan.',null),
('aux-ayto-mad:3-91e59dff84','aux-ayto-mad',3,'¿Qué es la Dirección Electrónica Habilitada única (DEHú)?','["La dirección postal que el interesado designa para recibir las notificaciones en papel cuando no está obligado a relacionarse electrónicamente", "El punto donde el interesado puede consultar las notificaciones electrónicas que le remitan las Administraciones", "El correo electrónico oficial que la Administración asigna a cada ciudadano y a cada empresa para recibir sus comunicaciones oficiales"]'::jsonb,1,'Art. 43 Ley 39/2015 y RD 203/2021','Las notificaciones pueden practicarse por comparecencia en la sede electrónica o a través de la DEHú.',null),
('aux-ayto-mad:3-b47bda38c3','aux-ayto-mad',3,'Según la Ley 39/2015, los interesados no estarán obligados a aportar documentos que:','["Estén redactados en una lengua cooficial distinta del castellano", "Hayan sido firmados electrónicamente por el propio interesado o por su representante con un certificado cualificado expedido por un prestador de confianza", "Hayan sido elaborados por cualquier Administración o que hayan sido aportados anteriormente por el interesado a cualquier Administración"]'::jsonb,2,'Art. 28.2 y 28.3 Ley 39/2015','La Administración los consultará o recabará, salvo oposición expresa del interesado o que una ley especial exija su consentimiento expreso.',null),
('aux-ayto-mad:4-1bc75968f3','aux-ayto-mad',4,'La revisión de oficio de los actos nulos de pleno derecho requiere:','["Informe favorable del servicio jurídico y audiencia previa de todos los interesados", "Dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma", "Sentencia judicial previa que declare la nulidad, a instancia de la Administración"]'::jsonb,1,'Art. 106.1 Ley 39/2015','Requiere dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma, si lo hubiere.',null),
('aux-ayto-mad:4-c32104058a','aux-ayto-mad',4,'La declaración de lesividad de un acto favorable anulable no puede adoptarse una vez transcurridos desde que se dictó:','["1 año", "6 meses", "4 años"]'::jsonb,2,'Art. 107.2 Ley 39/2015','No puede adoptarse una vez transcurridos cuatro años desde que se dictó el acto.',null),
('aux-ayto-mad:4-b9f19e721d','aux-ayto-mad',4,'¿Qué actos pueden revocar las Administraciones mientras no haya transcurrido el plazo de prescripción?','["Las disposiciones generales", "Los actos firmes de cualquier tipo", "Los actos de gravamen o desfavorables"]'::jsonb,2,'Art. 109.1 Ley 39/2015','Pueden revocar sus actos de gravamen o desfavorables mientras no haya transcurrido el plazo de prescripción.',null),
('aux-ayto-mad:4-09a158f48e','aux-ayto-mad',4,'Los errores materiales, de hecho o aritméticos de los actos pueden rectificarse:','["En el plazo de un mes desde la notificación, de oficio o a instancia de los interesados", "Solo a instancia de los interesados, mediante el correspondiente recurso de reposición", "En cualquier momento, de oficio o a instancia de los interesados"]'::jsonb,2,'Art. 109.2 Ley 39/2015','Pueden rectificarse en cualquier momento, de oficio o a instancia de los interesados.',null),
('aux-ayto-mad:4-83f314bc47','aux-ayto-mad',4,'Contra las resoluciones y los actos de trámite cualificados caben los recursos de:','["Alzada y potestativo de reposición", "Reposición obligatoria y alzada", "Alzada y extraordinario de revisión, únicamente"]'::jsonb,0,'Art. 112.1 Ley 39/2015','Caben el recurso de alzada y el potestativo de reposición.',null),
('aux-ayto-mad:4-f94346326a','aux-ayto-mad',4,'La interposición de un recurso administrativo, como regla general:','["Suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "No suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "No suspende la ejecución del acto, sin que ninguna disposición normativa pueda establecer otra cosa"]'::jsonb,1,'Art. 117.1 Ley 39/2015','La interposición de cualquier recurso no suspende la ejecución del acto impugnado, salvo disposición en contrario.',null),
('aux-ayto-mad:4-48638cae86','aux-ayto-mad',4,'Si se solicita la suspensión de la ejecución al recurrir y no hay resolución expresa, la ejecución se entiende suspendida cuando pasa:','["3 meses desde la solicitud", "10 días desde la solicitud", "1 mes desde la solicitud"]'::jsonb,2,'Art. 117.3 Ley 39/2015','Se entiende suspendida si transcurre un mes desde la solicitud sin resolución expresa.',null),
('aux-ayto-mad:4-4031a68b3e','aux-ayto-mad',4,'El recurso de alzada se interpone contra:','["Disposiciones de carácter general y actos que no ponen fin a la vía administrativa", "Actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó", "Resoluciones y actos que no ponen fin a la vía administrativa, ante el órgano superior jerárquico"]'::jsonb,2,'Art. 121.1 Ley 39/2015','Procede contra los actos que no ponen fin a la vía administrativa y se resuelve por el superior jerárquico.',null),
('aux-ayto-mad:4-5a560a5eaf','aux-ayto-mad',4,'Si el acto es expreso, el plazo para interponer recurso de alzada es de:','["3 meses", "2 meses", "1 mes"]'::jsonb,2,'Art. 122.1 Ley 39/2015','Es de un mes si el acto es expreso; si no lo es, puede interponerse en cualquier momento desde el día siguiente a los efectos del silencio.',null),
('aux-ayto-mad:4-39608f52bc','aux-ayto-mad',4,'¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso de alzada?','["3 meses; pasado ese plazo sin resolución expresa, se entenderá siempre estimado", "1 mes; pasado ese plazo, se podrá entender estimado", "3 meses; pasado ese plazo, se podrá entender desestimado"]'::jsonb,2,'Art. 122.2 Ley 39/2015','El plazo es de tres meses. Transcurrido sin resolución, se podrá entender desestimado el recurso, salvo excepción.',null),
('aux-ayto-mad:4-b683521523','aux-ayto-mad',4,'El recurso de reposición:','["Es obligatorio, contra actos que ponen fin a la vía administrativa, ante el mismo órgano", "Es potestativo, contra actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó", "Es obligatorio antes de acudir a los tribunales contencioso-administrativos"]'::jsonb,1,'Art. 123.1 Ley 39/2015','Es potestativo y se interpone ante el mismo órgano que dictó el acto que pone fin a la vía administrativa.',null),
('aux-ayto-mad:4-e1ece96309','aux-ayto-mad',4,'¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso de reposición?','["1 mes", "15 días", "2 meses"]'::jsonb,0,'Art. 124.2 Ley 39/2015','El plazo máximo es de un mes.',null),
('aux-ayto-mad:4-67b031968f','aux-ayto-mad',4,'El recurso extraordinario de revisión por error de hecho que resulte de los documentos del expediente se interpone en el plazo de:','["3 meses desde la notificación de la resolución", "4 años desde la notificación de la resolución", "1 año desde la notificación de la resolución"]'::jsonb,1,'Art. 125.2 Ley 39/2015','Cuatro años desde la notificación en la causa a); tres meses en las demás causas.',null),
('aux-ayto-mad:4-53d2bf665e','aux-ayto-mad',4,'Contra la resolución de un recurso de alzada:','["Cabe recurso potestativo de reposición ante el mismo órgano que resolvió la alzada", "Solo cabe recurso potestativo de reposición ante el mismo órgano, en los casos del art. 125.1", "Solo cabe el recurso extraordinario de revisión, en los casos del art. 125.1"]'::jsonb,2,'Art. 122.3 Ley 39/2015','No cabe ningún otro recurso administrativo, salvo el extraordinario de revisión en los casos previstos.',null),
('aux-ayto-mad:4-56bf67a278','aux-ayto-mad',4,'¿Cuál de las siguientes NO es una forma de iniciación de oficio del procedimiento?','["Petición razonada de otros órganos", "Solicitud del interesado", "Orden superior"]'::jsonb,1,'Art. 58 Ley 39/2015','De oficio se inicia por propia iniciativa, orden superior, petición razonada de otros órganos o denuncia. La solicitud del interesado es la otra vía de inicio.',null),
('aux-ayto-mad:4-a900825d93','aux-ayto-mad',4,'Si la solicitud no reúne los requisitos exigidos, se requiere al interesado para que la subsane en el plazo de:','["10 días, con indicación de que si no lo hace se declarará la caducidad", "10 días, con indicación de que si no lo hace se le tendrá por desistido", "5 días, con indicación de que si no lo hace se archivará sin más trámite"]'::jsonb,1,'Art. 68.1 Ley 39/2015','Se le da un plazo de diez días, con apercibimiento de que, si no lo hace, se le tendrá por desistido.',null),
('aux-ayto-mad:4-e2d15c754a','aux-ayto-mad',4,'El periodo de prueba en el procedimiento administrativo tiene una duración:','["No superior a 15 días ni inferior a 5", "No superior a 30 días ni inferior a 10", "De 20 días exactos"]'::jsonb,1,'Art. 77.2 Ley 39/2015','El periodo de prueba no puede ser superior a treinta días ni inferior a diez.',null),
('aux-ayto-mad:4-d21078c34f','aux-ayto-mad',4,'Salvo disposición expresa en contrario, los informes son:','["Preceptivos y vinculantes", "Preceptivos y no vinculantes", "Facultativos y no vinculantes"]'::jsonb,2,'Art. 80.1 Ley 39/2015','Salvo disposición expresa, los informes son facultativos y no vinculantes.',null),
('aux-ayto-mad:4-0578029b60','aux-ayto-mad',4,'Salvo que se fije otro plazo, los informes deben emitirse en:','["3 días", "15 días", "10 días"]'::jsonb,2,'Art. 80.2 Ley 39/2015','Los informes se emiten en el plazo de diez días, salvo que una disposición o el cumplimiento del resto de plazos exija otro.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:4-c8954e2747','aux-ayto-mad',4,'En el trámite de audiencia, los interesados disponen de un plazo:','["De 20 días", "No inferior a 15 días ni superior a 30", "No inferior a 10 días ni superior a 15"]'::jsonb,2,'Art. 82.2 Ley 39/2015','El plazo de audiencia no puede ser inferior a diez días ni superior a quince.',null),
('aux-ayto-mad:4-f670c16acb','aux-ayto-mad',4,'El plazo del trámite de información pública no puede ser inferior a:','["20 días", "10 días", "1 mes"]'::jsonb,0,'Art. 83.2 Ley 39/2015','El plazo de información pública no puede ser inferior a veinte días.',null),
('aux-ayto-mad:4-88c1e7470d','aux-ayto-mad',4,'¿Cuál de las siguientes NO pone fin al procedimiento administrativo?','["La interposición de un recurso", "La declaración de caducidad", "El desistimiento"]'::jsonb,0,'Art. 84.1 Ley 39/2015','Ponen fin al procedimiento la resolución, el desistimiento, la renuncia y la caducidad, y también la imposibilidad material sobrevenida.',null),
('aux-ayto-mad:4-2d9f4991e7','aux-ayto-mad',4,'En un procedimiento iniciado a solicitud que se paraliza por causa del interesado, la Administración le advierte de que se producirá la caducidad pasados:','["3 meses", "10 días", "1 mes"]'::jsonb,0,'Art. 95.1 Ley 39/2015','Transcurridos tres meses tras la advertencia sin que el interesado actúe, se produce la caducidad.',null),
('aux-ayto-mad:4-650f2ca73b','aux-ayto-mad',4,'¿Cuál de los siguientes NO es un medio de ejecución forzosa de los actos administrativos?','["La revocación del acto", "La ejecución subsidiaria", "El apremio sobre el patrimonio"]'::jsonb,0,'Art. 100.1 Ley 39/2015','Los medios son el apremio sobre el patrimonio, la ejecución subsidiaria, la multa coercitiva y la compulsión sobre las personas.',null),
('aux-ayto-mad:4-d00511eeff','aux-ayto-mad',4,'Se podrá prescindir del trámite de audiencia cuando:','["Lo acuerde motivadamente el instructor por razones de urgencia, aunque se tengan en cuenta hechos nuevos no aportados por el interesado", "No figuren ni sean tenidos en cuenta otros hechos, alegaciones o pruebas que los aducidos por el interesado", "El interesado sea una persona jurídica obligada a relacionarse electrónicamente"]'::jsonb,1,'Art. 82.4 Ley 39/2015','Si solo se valora lo aportado por el interesado, la audiencia puede omitirse.',null),
('aux-ayto-mad:4-c5da52c35e','aux-ayto-mad',4,'Si el recurso de alzada se interpone ante el órgano que dictó el acto, este deberá remitirlo al competente:','["En el plazo de quince días, sin necesidad de informe", "En el plazo de diez días, con su informe y una copia completa y ordenada del expediente", "En el plazo de tres días, con el expediente original"]'::jsonb,1,'Art. 121.2 Ley 39/2015','Debe remitirlo en 10 días con informe y copia del expediente.',null),
('aux-ayto-mad:4-68dde4b813','aux-ayto-mad',4,'A los interesados que no cumplan lo dispuesto en un trámite:','["Se les tendrá por desistidos de su solicitud y se archivará el procedimiento sin más trámite", "Se les podrá declarar decaídos en su derecho al trámite correspondiente", "Se declara la caducidad"]'::jsonb,1,'Art. 73.3 Ley 39/2015','Se admitirá su actuación si se produce antes o dentro del día en que se notifique la resolución que tenga por transcurrido el plazo.',null),
('aux-ayto-mad:4-1338d7e6bb','aux-ayto-mad',4,'Según el art. 98.1, tampoco son inmediatamente ejecutivos los actos:','["Que hayan sido notificados con indicación de los recursos procedentes", "Que pongan fin a la vía administrativa y no hayan sido recurridos", "Que necesiten aprobación o autorización superior"]'::jsonb,2,'Art. 98.1 d) Ley 39/2015','Tampoco cuando se acuerde su suspensión o una disposición establezca lo contrario.',null),
('aux-ayto-mad:4-4e63a37d0e','aux-ayto-mad',4,'Cuando hayan de tenerse en cuenta nuevos hechos o documentos no recogidos en el expediente original, se pondrán de manifiesto a los interesados para alegaciones en un plazo:','["No inferior a diez días ni superior a quince", "De veinte días hábiles, prorrogable por otros diez", "De un mes, prorrogable por otro mes a petición del interesado"]'::jsonb,0,'Art. 118.1 Ley 39/2015','El plazo es de 10 a 15 días.',null),
('aux-ayto-mad:4-e41ecaad16','aux-ayto-mad',4,'Es un derecho del interesado en el procedimiento:','["Elegir al instructor del procedimiento", "Conocer en cualquier momento el estado de tramitación de cualquier procedimiento de la Administración, aunque no tenga la condición de interesado", "Conocer en cualquier momento el estado de la tramitación de los procedimientos en los que sea interesado"]'::jsonb,2,'Art. 53.1 a) Ley 39/2015','También el sentido del silencio, el órgano competente y obtener copia de los documentos.',null),
('aux-ayto-mad:4-d7a70c24c1','aux-ayto-mad',4,'La declaración responsable es el documento por el que el interesado manifiesta, bajo su responsabilidad:','["Que cumple los requisitos de la normativa vigente, dispone de la documentación que lo acredita y la pondrá a disposición de la Administración cuando se le requiera", "Que pone en conocimiento de la Administración sus datos identificativos", "Que cumple los requisitos de la normativa vigente y aporta en ese momento toda la documentación que lo acredita, sin que la Administración pueda requerírsela después"]'::jsonb,0,'Art. 69.1 Ley 39/2015','Definición legal de la declaración responsable.',null),
('aux-ayto-mad:4-4847964097','aux-ayto-mad',4,'¿Pueden revisarse de oficio las disposiciones administrativas nulas del art. 47.2?','["Sí, previo dictamen favorable del Consejo de Estado u órgano consultivo autonómico equivalente", "No, la revisión de oficio solo alcanza a los actos, no a las disposiciones", "Sí, previo dictamen no vinculante del Consejo de Estado u órgano consultivo equivalente, y a instancia del interesado"]'::jsonb,0,'Art. 106.2 Ley 39/2015','Las Administraciones pueden declarar de oficio la nulidad de disposiciones del art. 47.2 previo dictamen favorable.',null),
('aux-ayto-mad:4-1c0d767f46','aux-ayto-mad',4,'En ningún caso podrá imponerse a los administrados una obligación pecuniaria que:','["No estuviese establecida en una norma de rango reglamentario aprobada por el Consejo de Gobierno o el Consejo de Ministros", "No estuviese establecida con arreglo a una norma de rango legal", "Supere los 3.000 euros sin autorización judicial previa y expresa"]'::jsonb,1,'Art. 101.2 Ley 39/2015','Las obligaciones pecuniarias requieren base en una norma de rango legal.',null),
('aux-ayto-mad:4-b338cf6a6b','aux-ayto-mad',4,'La petición razonada de iniciación:','["Solo puede formularla un ciudadano afectado", "No vincula al órgano competente, que deberá comunicar los motivos por los que, en su caso, no inicia", "Equivale a una denuncia y obliga a iniciar el procedimiento"]'::jsonb,1,'Art. 61.2 Ley 39/2015','No es vinculante, pero hay que comunicar los motivos de no iniciar.',null),
('aux-ayto-mad:4-c3a4ca4835','aux-ayto-mad',4,'La multa coercitiva:','["Sustituye a la sanción que corresponda", "Es incompatible con las sanciones, de modo que si se impone una multa coercitiva no puede imponerse sanción por los mismos hechos", "Es independiente de las sanciones que puedan imponerse y compatible con ellas"]'::jsonb,2,'Art. 103.2 Ley 39/2015','La multa coercitiva es independiente de las sanciones y compatible con ellas.',null),
('aux-ayto-mad:4-5a9ddbb788','aux-ayto-mad',4,'No podrá acordarse la caducidad del procedimiento por la simple inactividad del interesado en la cumplimentación de trámites:','["Si el interesado es persona jurídica obligada a relacionarse electrónicamente", "Aunque sean indispensables para dictar resolución, si ha transcurrido el plazo", "Siempre que no sean indispensables para dictar resolución"]'::jsonb,2,'Art. 95.2 Ley 39/2015','La inactividad en trámites no indispensables no da lugar a caducidad.',null),
('aux-ayto-mad:4-9d413f9e8e','aux-ayto-mad',4,'También es causa del recurso extraordinario de revisión que la resolución se haya dictado como consecuencia de:','["Prevaricación, cohecho, violencia, maquinación fraudulenta u otra conducta punible declarada en sentencia judicial firme", "Una denuncia de un tercero por prevaricación o cohecho, aunque todavía no haya recaído sentencia judicial firme", "Un error de calificación del recurso"]'::jsonb,0,'Art. 125.1 d) Ley 39/2015','Exige que la conducta se haya declarado en sentencia judicial firme.',null),
('aux-ayto-mad:4-178ca38921','aux-ayto-mad',4,'En los procedimientos sancionadores, el presunto responsable tiene derecho, además:','["A no declarar contra sí mismo, pero no a la presunción de inocencia, que es exclusiva del proceso penal", "A la presunción de no existencia de responsabilidad administrativa mientras no se demuestre lo contrario", "A que se le notifique la sanción"]'::jsonb,1,'Art. 53.2 b) Ley 39/2015','Es la presunción de inocencia en el ámbito sancionador.',null),
('aux-ayto-mad:4-307b923373','aux-ayto-mad',4,'Las Administraciones pueden imponer multas coercitivas:','["Cuando lo autorice un reglamento, en la forma y cuantía que determine el órgano que ordena la ejecución", "Cuando así lo autoricen las leyes, y en la forma y cuantía que estas determinen", "Solo en materia tributaria"]'::jsonb,1,'Art. 103.1 Ley 39/2015','Requieren autorización legal y se reiteran por lapsos de tiempo suficientes para cumplir lo ordenado.',null),
('aux-ayto-mad:4-6bca3a7545','aux-ayto-mad',4,'La efectividad de las reducciones por reconocimiento o pago voluntario está condicionada a:','["El desistimiento o renuncia de cualquier acción o recurso en vía administrativa contra la sanción", "El desistimiento o renuncia de cualquier acción o recurso, tanto en vía administrativa como contencioso-administrativa", "La conformidad de la víctima o del denunciante y la renuncia expresa a la vía contencioso-administrativa"]'::jsonb,0,'Art. 85.3 Ley 39/2015','El infractor debe desistir o renunciar a recursos administrativos.',null),
('aux-ayto-mad:4-71a61f6c97','aux-ayto-mad',4,'Si para la ejecución forzosa fuese necesario entrar en el domicilio del afectado, se requiere:','["Basta la resolución administrativa que ordena la ejecución, notificada al afectado", "Su consentimiento o, en su defecto, la oportuna autorización judicial", "Su consentimiento o, en su defecto, autorización del órgano superior jerárquico del que ordenó la ejecución"]'::jsonb,1,'Art. 100.3 Ley 39/2015','Se necesita el consentimiento del afectado o autorización judicial.',null),
('aux-ayto-mad:4-530218746d','aux-ayto-mad',4,'La resolución de un recurso será congruente con las peticiones del recurrente:','["Salvo en materia de personal, en que puede agravarse su situación inicial", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Sin que en ningún caso pueda agravarse su situación inicial"]'::jsonb,2,'Art. 119.3 Ley 39/2015','Es la prohibición de la reformatio in peius.',null),
('aux-ayto-mad:4-bd8e94774e','aux-ayto-mad',4,'Si el acto no es expreso, el recurso de alzada podrá interponerse:','["En el plazo de tres meses desde la presentación de la solicitud", "En el plazo de un mes desde el día siguiente a aquel en que se produzcan los efectos del silencio", "En cualquier momento a partir del día siguiente a aquel en que se produzcan los efectos del silencio"]'::jsonb,2,'Art. 122.1 Ley 39/2015','Contra actos presuntos, en cualquier momento desde que se producen los efectos del silencio.',null),
('aux-ayto-mad:4-4fca5eeaca','aux-ayto-mad',4,'Interpuesto un recurso de reposición, no se podrá interponer recurso contencioso-administrativo hasta que:','["Lo autorice el órgano que dictó el acto", "Sea resuelto expresamente o se haya producido su desestimación presunta", "Sea resuelto expresamente, sin que baste la desestimación presunta"]'::jsonb,1,'Art. 123.2 Ley 39/2015','Hay que esperar a la resolución expresa o la desestimación presunta.',null),
('aux-ayto-mad:4-1303f7bb60','aux-ayto-mad',4,'También pone fin a la vía administrativa:','["El acuerdo de iniciación del procedimiento sancionador o de responsabilidad", "El informe preceptivo y vinculante emitido por un órgano consultivo", "La resolución de los procedimientos de responsabilidad patrimonial"]'::jsonb,2,'Art. 114.1 e) Ley 39/2015','Las resoluciones en materia de responsabilidad patrimonial ponen fin a la vía administrativa, cualquiera que sea el tipo de relación.',null),
('aux-ayto-mad:4-df75e4dc49','aux-ayto-mad',4,'En la AGE, son competentes para la revisión de oficio de sus propios actos y de los dictados por los Ministros:','["El Presidente del Gobierno en solitario", "El Consejo de Ministros", "El Consejo de Estado"]'::jsonb,1,'Art. 111 a) Ley 39/2015','El Consejo de Ministros revisa sus propios actos y disposiciones y los de los Ministros.',null),
('aux-ayto-mad:4-344d6b6b52','aux-ayto-mad',4,'Los procedimientos caducados:','["Interrumpen la prescripción", "Producen por sí solos la prescripción de las acciones", "No interrumpirán el plazo de prescripción"]'::jsonb,2,'Art. 95.3 Ley 39/2015','La caducidad no produce por sí sola la prescripción, pero el procedimiento caducado no la interrumpe.',null),
('aux-ayto-mad:4-ba97c85ccc','aux-ayto-mad',4,'En los procedimientos de responsabilidad patrimonial es preceptivo solicitar informe al servicio cuyo funcionamiento haya ocasionado la presunta lesión, que deberá emitirse en un plazo máximo de:','["Dos meses", "Diez días", "Quince días"]'::jsonb,1,'Art. 81.1 Ley 39/2015','El informe del servicio no puede exceder de diez días.',null),
('aux-ayto-mad:4-71d10c1be4','aux-ayto-mad',4,'En los procedimientos sancionadores, los hechos declarados probados por resoluciones judiciales penales firmes:','["Vincularán a las Administraciones solo si la sentencia penal es condenatoria y se dictó antes de iniciarse el procedimiento", "Solo vinculan si el interesado lo solicita expresamente en sus alegaciones al acuerdo de iniciación", "Vincularán a las Administraciones Públicas en los procedimientos sancionadores que substancien"]'::jsonb,2,'Art. 77.4 Ley 39/2015','Los hechos probados en sentencia penal firme vinculan a la Administración.',null),
('aux-ayto-mad:4-13d4082e8c','aux-ayto-mad',4,'La resolución del procedimiento se dictará:','["Por escrito en papel, firmado por el titular del órgano", "Electrónicamente, garantizando la identidad del órgano competente y la autenticidad e integridad del documento", "Electrónicamente o en papel, a elección del órgano, garantizando solo la identidad del firmante y no la integridad del documento"]'::jsonb,1,'Art. 88.4 Ley 39/2015','La resolución se dicta electrónicamente.',null),
('aux-ayto-mad:4-09adbc376f','aux-ayto-mad',4,'¿Quién puede acordar un período de información pública?','["El instructor del procedimiento, a petición de cualquier interesado y siempre que lo autorice el órgano superior jerárquico", "El órgano al que corresponda la resolución del procedimiento, cuando su naturaleza lo requiera", "Cualquier interesado, comunicándolo al órgano instructor, siempre que lo considere útil para su defensa"]'::jsonb,1,'Art. 83.1 Ley 39/2015','Lo acuerda el órgano competente para resolver.',null),
('aux-ayto-mad:4-f30d8fae50','aux-ayto-mad',4,'Contra las disposiciones administrativas de carácter general:','["Cabe recurso de alzada", "Cabe recurso extraordinario de revisión", "No cabe recurso en vía administrativa"]'::jsonb,2,'Art. 112.3 Ley 39/2015','Contra las disposiciones de carácter general no cabe recurso administrativo.',null),
('aux-ayto-mad:4-64ae115d72','aux-ayto-mad',4,'Excepcionalmente, cuando al iniciar el procedimiento sancionador no existan elementos suficientes para la calificación inicial de los hechos, esta podrá realizarse en una fase posterior mediante:','["Un nuevo acuerdo de iniciación", "La elaboración de un Pliego de cargos, que no se notifica a los interesados hasta la propuesta de resolución definitiva del instructor", "La elaboración de un Pliego de cargos, que deberá ser notificado a los interesados"]'::jsonb,2,'Art. 64.3 Ley 39/2015','Se elabora un Pliego de cargos que se notifica a los interesados.',null),
('aux-ayto-mad:4-c94eee2eeb','aux-ayto-mad',4,'NO será inmediatamente ejecutiva la resolución:','["De un procedimiento sancionador contra la que quepa recurso de alzada, pero no si solo cabe el potestativo de reposición", "De un procedimiento sancionador contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición", "De un recurso de alzada"]'::jsonb,1,'Art. 98.1 b) Ley 39/2015','Las sanciones no son ejecutivas mientras quepa recurso administrativo.',null),
('aux-ayto-mad:4-1f8257c215','aux-ayto-mad',4,'Iniciado un procedimiento sancionador, si el infractor reconoce su responsabilidad:','["Se podrá resolver el procedimiento sin imponer sanción, salvo que la infracción sea muy grave o el infractor sea reincidente", "Se archiva el procedimiento sin imponer sanción, si el infractor paga voluntariamente", "Se podrá resolver el procedimiento con la imposición de la sanción que proceda"]'::jsonb,2,'Art. 85.1 Ley 39/2015','El reconocimiento permite resolver con la sanción procedente.',null),
('aux-ayto-mad:4-6369c0b58c','aux-ayto-mad',4,'La ejecución subsidiaria procede respecto de actos que:','["Sean personalísimos de hacer y el obligado se niegue a realizarlos en el plazo fijado", "Por no ser personalísimos puedan ser realizados por sujeto distinto del obligado", "Impongan obligaciones de no hacer o de soportar, previo apercibimiento al obligado"]'::jsonb,1,'Art. 102.1 Ley 39/2015','Cabe cuando el acto no es personalísimo y otro sujeto puede realizarlo.',null),
('aux-ayto-mad:4-a0ad387fd2','aux-ayto-mad',4,'Si antes del vencimiento del plazo de audiencia los interesados manifiestan su decisión de no efectuar alegaciones:','["Se ampliará de oficio el plazo para que puedan reconsiderar su decisión, que no será vinculante hasta su vencimiento", "Se tendrá por decaído su derecho y se archivará el procedimiento", "Se tendrá por realizado el trámite"]'::jsonb,2,'Art. 82.3 Ley 39/2015','El trámite se tiene por realizado.',null),
('aux-ayto-mad:4-6d53ceefe5','aux-ayto-mad',4,'Si el procedimiento de revisión de oficio se inició de oficio y transcurren seis meses sin resolución, se produce:','["La nulidad automática del acto", "La caducidad del mismo", "La estimación por silencio"]'::jsonb,1,'Art. 106.5 Ley 39/2015','Iniciado de oficio: caducidad. Iniciado a solicitud: se podrá entender desestimada.',null),
('aux-ayto-mad:4-e62938e91b','aux-ayto-mad',4,'Transcurrido el plazo de seis meses desde la iniciación del procedimiento de lesividad sin que se haya declarado, se produce:','["La estimación del interesado por silencio", "La declaración automática de lesividad", "La caducidad del procedimiento"]'::jsonb,2,'Art. 107.3 Ley 39/2015','Pasados seis meses sin declaración de lesividad, el procedimiento caduca.',null),
('aux-ayto-mad:4-4e3e1cb72c','aux-ayto-mad',4,'Si el órgano competente para resolver considera que la infracción o la sanción revisten mayor gravedad que la propuesta, se notificará al inculpado para alegaciones en un plazo de:','["Cinco días", "Diez días", "Quince días"]'::jsonb,2,'Art. 90.2 Ley 39/2015','El inculpado dispone de quince días para alegar.',null),
('aux-ayto-mad:4-2c0183f7c5','aux-ayto-mad',4,'Iniciado un procedimiento de revisión de oficio o de lesividad, el órgano competente podrá suspender la ejecución del acto cuando:','["Lo solicite cualquier tercero, aunque no acredite la condición de interesado ni perjuicio alguno", "El acto sea favorable al interesado y este lo solicite antes de que se dicte la resolución", "Esta pudiera causar perjuicios de imposible o difícil reparación"]'::jsonb,2,'Art. 108 Ley 39/2015','Puede suspenderse si la ejecución causaría perjuicios de imposible o difícil reparación.',null),
('aux-ayto-mad:4-6174ad27c0','aux-ayto-mad',4,'¿Ante quién se interpone el recurso extraordinario de revisión?','["Ante el superior jerárquico del órgano que dictó el acto, previo dictamen del Consejo de Estado", "Ante el superior jerárquico del órgano que dictó el acto, que es competente para resolverlo", "Ante el órgano administrativo que dictó el acto, que también es competente para resolverlo"]'::jsonb,2,'Art. 125.1 Ley 39/2015','Se interpone y resuelve por el mismo órgano que dictó el acto.',null),
('aux-ayto-mad:4-7eedc2ddca','aux-ayto-mad',4,'Los trámites que deban ser cumplimentados por los interesados se realizarán, salvo plazo distinto, en el plazo de:','["Quince días a partir del siguiente al de la notificación del correspondiente acto", "Diez días a partir del siguiente al de la notificación del correspondiente acto", "Diez días a partir del mismo día de la notificación"]'::jsonb,1,'Art. 73.1 Ley 39/2015','El plazo general es de diez días.',null),
('aux-ayto-mad:4-cff07adb1b','aux-ayto-mad',4,'La ejecución forzosa de los actos administrativos se efectuará:','["Respetando el principio de eficacia, por el medio más rápido disponible aunque no sea el menos restrictivo de la libertad individual", "Solo con autorización judicial previa", "Respetando siempre el principio de proporcionalidad y por los medios menos restrictivos de la libertad individual"]'::jsonb,2,'Art. 99 Ley 39/2015','La ejecución forzosa respeta la proporcionalidad y elige el medio menos restrictivo.',null),
('aux-ayto-mad:4-86964e93b4','aux-ayto-mad',4,'Según el art. 54, los procedimientos podrán iniciarse:','["De oficio, a solicitud del interesado o por orden judicial", "Solo de oficio, por propia iniciativa del órgano", "De oficio o a solicitud del interesado"]'::jsonb,2,'Art. 54 Ley 39/2015','Las dos clases de iniciación son de oficio y a solicitud del interesado.',null),
('aux-ayto-mad:4-5ed5f0c671','aux-ayto-mad',4,'La Administración puede abstenerse de resolver alegando silencio, oscuridad o insuficiencia de los preceptos legales:','["Sí, si lo autoriza el superior", "En ningún caso", "Sí, cuando la ley sea oscura"]'::jsonb,1,'Art. 88.5 Ley 39/2015','Nunca puede abstenerse por esos motivos, aunque puede inadmitir solicitudes de derechos no previstos o manifiestamente carentes de fundamento.',null),
('aux-ayto-mad:4-1aaf95d6fa','aux-ayto-mad',4,'En el procedimiento sancionador se podrá adoptar la tramitación simplificada cuando:','["La infracción sea muy grave y urgente, o lo solicite expresamente el denunciante", "Existan elementos de juicio suficientes para calificar la infracción como leve", "Existan elementos de juicio suficientes para calificar la infracción como leve o grave"]'::jsonb,1,'Art. 96.5 Ley 39/2015','Procede si la infracción se califica como leve.',null),
('aux-ayto-mad:4-fb987443fe','aux-ayto-mad',4,'Las actuaciones complementarias deberán practicarse en un plazo no superior a:','["Tres meses", "Un mes", "Quince días"]'::jsonb,2,'Art. 87 Ley 39/2015','El plazo para resolver queda suspendido hasta su terminación.',null),
('aux-ayto-mad:4-7d986be6e9','aux-ayto-mad',4,'El apremio sobre el patrimonio procede cuando, en virtud del acto, haya de satisfacerse:','["Una obligación personalísima", "Una cantidad líquida", "Una obligación de soportar"]'::jsonb,1,'Art. 101.1 Ley 39/2015','Si hay que satisfacer cantidad líquida se sigue el procedimiento de apremio.',null),
('aux-ayto-mad:4-1e1a1ba098','aux-ayto-mad',4,'También producirá la terminación del procedimiento:','["La imposibilidad material de continuarlo por causas sobrevenidas, mediante resolución motivada", "El cambio del funcionario instructor, o la falta de crédito presupuestario adecuado para continuarlo", "La imposibilidad material de continuarlo, que se produce automáticamente sin necesidad de resolución"]'::jsonb,0,'Art. 84.2 Ley 39/2015','La resolución que se dicte deberá ser motivada en todo caso.',null),
('aux-ayto-mad:4-009cb5019a','aux-ayto-mad',4,'Los actos de instrucción necesarios para determinar, conocer y comprobar los hechos se realizarán:','["Por el órgano que tramite el procedimiento, en papel y sin uso de medios electrónicos, sin que los interesados puedan proponer actuaciones complementarias", "Solo a instancia de los interesados y en papel, que deben proponer las actuaciones necesarias, sin que el órgano que tramite el procedimiento pueda acordarlas de oficio", "De oficio y por medios electrónicos por el órgano que tramite el procedimiento, sin perjuicio del derecho de los interesados a proponer actuaciones"]'::jsonb,2,'Art. 75.1 Ley 39/2015','La instrucción se hace de oficio.',null),
('aux-ayto-mad:4-987dd37958','aux-ayto-mad',4,'En las Entidades Locales, la declaración de lesividad corresponde a:','["El Pleno de la Corporación o, en su defecto, el órgano colegiado superior de la entidad", "La Junta de Gobierno Local en todo caso, previo dictamen del órgano consultivo autonómico", "El Alcalde, dando cuenta al Pleno"]'::jsonb,0,'Art. 107.5 Ley 39/2015','La adopta el Pleno o, en su defecto, el órgano colegiado superior.',null),
('aux-ayto-mad:4-bc2a142547','aux-ayto-mad',4,'En los procedimientos de responsabilidad patrimonial, el acuerdo alcanzado entre el interesado y el órgano competente deberá fijar:','["La cuantía y el modo de indemnización", "La cuantía de la indemnización, pero no el modo, que fija después el órgano competente", "La sanción disciplinaria del empleado público responsable"]'::jsonb,0,'Art. 86.5 Ley 39/2015','El acuerdo fija la cuantía y el modo de indemnización.',null),
('aux-ayto-mad:4-c107384809','aux-ayto-mad',4,'En los procedimientos iniciados de oficio, la Administración podrá desistir:','["Motivadamente, en cualquier supuesto, sin necesidad de previsión legal", "Motivadamente, en los supuestos y con los requisitos previstos en las leyes", "Libremente y sin necesidad de motivación"]'::jsonb,1,'Art. 93 Ley 39/2015','El desistimiento de la Administración debe ser motivado y legalmente previsto.',null),
('aux-ayto-mad:4-6908fd67de','aux-ayto-mad',4,'Las Administraciones podrán celebrar acuerdos, pactos, convenios o contratos que pongan fin al procedimiento siempre que:','["No sean contrarios al ordenamiento jurídico ni versen sobre materias no susceptibles de transacción", "Lo autorice un juez", "El interesado sea una persona jurídica y el acuerdo se refiera a materias de contenido económico o patrimonial"]'::jsonb,0,'Art. 86.1 Ley 39/2015','Es la terminación convencional.',null),
('aux-ayto-mad:4-b4a1b02a11','aux-ayto-mad',4,'Las Administraciones no iniciarán ninguna actuación material de ejecución que limite derechos de los particulares:','["Sin el consentimiento expreso y por escrito del particular afectado por la actuación", "Sin autorización judicial en todo caso", "Sin que previamente haya sido adoptada la resolución que le sirva de fundamento jurídico"]'::jsonb,2,'Art. 97.1 Ley 39/2015','Es necesario un título previo: la resolución que sirve de fundamento jurídico.',null),
('aux-ayto-mad:4-1b35b4fc42','aux-ayto-mad',4,'El instructor solo podrá rechazar las pruebas propuestas por los interesados cuando:','["Sean costosas para la Administración, aunque sean pertinentes y necesarias, mediante resolución motivada", "Se propongan fuera del plazo de diez días", "Sean manifiestamente improcedentes o innecesarias, mediante resolución motivada"]'::jsonb,2,'Art. 77.3 Ley 39/2015','El rechazo de pruebas debe ser motivado y basarse en su improcedencia o innecesariedad manifiesta.',null),
('aux-ayto-mad:4-b6b8a225ed','aux-ayto-mad',4,'Ponen fin a la vía administrativa:','["Los actos de órganos con superior jerárquico, como regla general", "Las resoluciones de los recursos de alzada", "Las propuestas de resolución"]'::jsonb,1,'Art. 114.1 a) Ley 39/2015','Las resoluciones de alzada ponen fin a la vía administrativa.',null),
('aux-ayto-mad:4-3f8ce00f9a','aux-ayto-mad',4,'El procedimiento está sometido al principio de:','["Oralidad, y se impulsará a instancia de los interesados en cada uno de sus trámites, en papel", "Rogación exclusiva del interesado, que lo impulsa en todos sus trámites mediante escritos sucesivos", "Celeridad, y se impulsará de oficio en todos sus trámites y a través de medios electrónicos"]'::jsonb,2,'Art. 71.1 Ley 39/2015','El impulso es de oficio, con respeto a la transparencia y la publicidad.',null),
('aux-ayto-mad:4-4c6f4e8cb1','aux-ayto-mad',4,'En la petición de un informe se concretará:','["El nombre del funcionario que debe emitirlo", "El plazo de tres meses para su emisión y el sentido del informe", "El extremo o extremos acerca de los que se solicita"]'::jsonb,2,'Art. 79.2 Ley 39/2015','Hay que concretar los extremos sobre los que se pide el informe.',null),
('aux-ayto-mad:4-93655e1bfb','aux-ayto-mad',4,'El órgano que resuelva el recurso podrá suspender la ejecución del acto impugnado cuando:','["El acto sea favorable", "La impugnación se fundamente en alguna de las causas de nulidad de pleno derecho del art. 47.1", "La impugnación se fundamente en cualquier causa de anulabilidad, aunque la ejecución no cause perjuicios"]'::jsonb,1,'Art. 117.2 b) Ley 39/2015','También cuando la ejecución pueda causar perjuicios de imposible o difícil reparación.',null),
('aux-ayto-mad:4-987f4f6850','aux-ayto-mad',4,'La acumulación de procedimientos exige, entre otros requisitos, que:','["Estén en la misma fase de tramitación y se refieran al mismo interesado o a interesados distintos", "Sea el mismo órgano quien deba tramitar y resolver el procedimiento", "Los interesados sean los mismos y los procedimientos estén en la misma fase"]'::jsonb,1,'Art. 57 Ley 39/2015','Se acumulan los que guarden identidad sustancial o íntima conexión y los tramite y resuelva el mismo órgano.',null),
('aux-ayto-mad:4-08a7e699ab','aux-ayto-mad',4,'Según el art. 53.1 d), los interesados pueden formular alegaciones y aportar documentos:','["Solo en la solicitud inicial", "Solo en el período de prueba", "En cualquier fase del procedimiento anterior al trámite de audiencia"]'::jsonb,2,'Art. 53.1 d) Ley 39/2015','Hasta el trámite de audiencia, que deberán ser tenidos en cuenta al redactar la propuesta de resolución.',null),
('aux-ayto-mad:4-956308028b','aux-ayto-mad',4,'Contra la resolución de un recurso de reposición:','["Cabe recurso de reposición ante el superior", "No puede interponerse de nuevo dicho recurso", "Cabe recurso de alzada"]'::jsonb,1,'Art. 124.3 Ley 39/2015','No cabe reiterar la reposición.',null),
('aux-ayto-mad:4-2aee0ea9e6','aux-ayto-mad',4,'Los interesados podrán aducir alegaciones y aportar documentos:','["En cualquier momento, incluso tras la resolución", "Solo tras la propuesta de resolución", "En cualquier momento del procedimiento anterior al trámite de audiencia"]'::jsonb,2,'Art. 76.1 Ley 39/2015','Serán tenidos en cuenta al redactar la propuesta de resolución.',null),
('aux-ayto-mad:4-77664ac3a4','aux-ayto-mad',4,'Si en un procedimiento simplificado el dictamen preceptivo del Consejo de Estado se manifiesta en contra del fondo de la propuesta de resolución:','["El órgano competente acordará un nuevo trámite de audiencia y resolverá por la tramitación simplificada", "Se archiva el procedimiento", "El órgano competente acordará continuar el procedimiento con arreglo a la tramitación ordinaria"]'::jsonb,2,'Art. 96.7 Ley 39/2015','Se pasa a la tramitación ordinaria.',null),
('aux-ayto-mad:4-e8e782e24b','aux-ayto-mad',4,'Cuando la sanción tenga únicamente carácter pecuniario, el reconocimiento de responsabilidad y el pago voluntario dan lugar a reducciones de:','["Exactamente el 50 % del importe de la sanción propuesta, no acumulables", "Al menos el 20 % sobre el importe de la sanción propuesta, acumulables entre sí", "El 30 % solo por pronto pago"]'::jsonb,1,'Art. 85.3 Ley 39/2015','Las reducciones son de al menos el 20 % cada una, acumulables, y pueden incrementarse reglamentariamente.',null),
('aux-ayto-mad:4-fd2c2e2413','aux-ayto-mad',4,'Las cuestiones incidentales que se susciten en el procedimiento, incluso las que se refieran a la nulidad de actuaciones:','["No suspenderán la tramitación del procedimiento, salvo la recusación", "Determinan el archivo provisional del procedimiento hasta su resolución por el órgano superior", "Suspenden siempre la tramitación"]'::jsonb,0,'Art. 74 Ley 39/2015','Solo la recusación suspende el procedimiento.',null),
('aux-ayto-mad:4-ac94c16326','aux-ayto-mad',4,'Según el principio de simplificación administrativa, se acordarán en un solo acto:','["La iniciación, la instrucción y la resolución, cuando el procedimiento se tramite por la vía simplificada y lo solicite el interesado", "Todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo", "Todos los recursos de un mismo interesado frente a actos distintos"]'::jsonb,1,'Art. 72.1 Ley 39/2015','Concentración de trámites.',null),
('aux-ayto-mad:4-267b8a27cd','aux-ayto-mad',4,'Al declarar la nulidad de una disposición o acto, las Administraciones podrán:','["Establecer en la misma resolución las indemnizaciones que proceda reconocer a los interesados", "Imponer sanciones a los interesados que se beneficiaron del acto nulo, sin necesidad de procedimiento", "Exigir a los interesados el reintegro de lo percibido sin necesidad de procedimiento ni audiencia previa"]'::jsonb,0,'Art. 106.4 Ley 39/2015','Pueden fijar indemnizaciones si concurren los requisitos de responsabilidad patrimonial.',null),
('aux-ayto-mad:4-2e4205f269','aux-ayto-mad',4,'Es causa de inadmisión de un recurso:','["Que se presente en una oficina de Correos sin sello de fechas", "Que el recurrente haya calificado erróneamente el recurso, aunque se deduzca su verdadero carácter", "Haber transcurrido el plazo para su interposición"]'::jsonb,2,'Art. 116 d) Ley 39/2015','Otras causas: incompetencia, falta de legitimación, acto no recurrible y carecer manifiestamente de fundamento.',null),
('aux-ayto-mad:4-f6aa332667','aux-ayto-mad',4,'La compulsión sobre las personas procede, en los casos que la ley expresamente lo autorice, para:','["Cualquier acto, a elección de la Administración", "Actos que impongan una obligación personalísima de no hacer o soportar", "Obligaciones no personalísimas de hacer que puedan cumplirse por otro"]'::jsonb,1,'Art. 104.1 Ley 39/2015','Se aplica a obligaciones personalísimas de no hacer o soportar, respetando la dignidad y los derechos constitucionales.',null),
('aux-ayto-mad:4-541374d827','aux-ayto-mad',4,'Si la resolución va a pronunciarse sobre cuestiones conexas no planteadas por los interesados, el órgano competente debe ponerlo de manifiesto a estos por un plazo:','["No superior a quince días", "No inferior a veinte días", "De un mes"]'::jsonb,0,'Art. 88.1 Ley 39/2015','Se da audiencia por plazo no superior a quince días.',null),
('aux-ayto-mad:4-aedaa02da6','aux-ayto-mad',4,'En los procedimientos sancionadores, la fase instructora y la sancionadora:','["Corresponderán al mismo órgano, salvo que la ley disponga otra cosa", "Se encomendarán a órganos distintos", "Las realiza el denunciante y el órgano competente, respectivamente"]'::jsonb,1,'Art. 63.1 Ley 39/2015','Los procedimientos sancionadores se inician siempre de oficio y separan instrucción y resolución.',null),
('aux-ayto-mad:4-ea50714007','aux-ayto-mad',4,'En la notificación de la práctica de una prueba se consignará el lugar, fecha y hora, con la advertencia de que el interesado:','["Puede nombrar técnicos para que le asistan", "Debe comparecer acompañado de notario o de abogado colegiado", "Debe abonar en todo caso los gastos de la prueba"]'::jsonb,0,'Art. 78.2 Ley 39/2015','Se le advierte que puede nombrar técnicos que le asistan.',null),
('aux-ayto-mad:4-7f515189d8','aux-ayto-mad',4,'En los procedimientos sancionadores, la orden superior de iniciación expresará, en la medida de lo posible:','["El nombre del abogado defensor del presunto responsable y la sanción que corresponde imponerle según la tipificación", "El sentido de la resolución que deba dictarse", "La persona o personas presuntamente responsables, las conductas o hechos, su tipificación y el lugar y fecha"]'::jsonb,2,'Art. 60.2 Ley 39/2015','La orden superior debe concretar responsables, hechos, tipificación, lugar y fecha.',null),
('aux-ayto-mad:4-784801d78d','aux-ayto-mad',4,'En la ejecución subsidiaria, el importe de los gastos podrá liquidarse:','["Solo tras la ejecución, de forma definitiva y sin posibilidad de liquidación provisional", "Por el doble de su coste, en concepto de sanción", "De forma provisional y realizarse antes de la ejecución, a reserva de la liquidación definitiva"]'::jsonb,2,'Art. 102.4 Ley 39/2015','Cabe liquidación provisional previa a reserva de la definitiva; los gastos corren a cargo del obligado.',null),
('aux-ayto-mad:4-627574c8bd','aux-ayto-mad',4,'Requerirán en todo caso la aprobación expresa del Consejo de Ministros u órgano equivalente de las CCAA:','["Los acuerdos de los Ayuntamientos", "Los acuerdos que versen sobre materias de la competencia directa de dicho órgano", "Los acuerdos de cuantía superior a 6.000 €"]'::jsonb,1,'Art. 86.3 Ley 39/2015','Solo los que versen sobre materias de su competencia directa.',null),
('aux-ayto-mad:4-7ba074db56','aux-ayto-mad',4,'En la AGE, los procedimientos de responsabilidad patrimonial se resolverán, como regla general, por:','["El Delegado del Gobierno", "El Ministro respectivo", "El Presidente del Gobierno"]'::jsonb,1,'Art. 92 Ley 39/2015','Por el Consejo de Ministros en los casos del art. 32.3 LRJSP o cuando una ley lo disponga.',null),
('aux-ayto-mad:4-c47621dff8','aux-ayto-mad',4,'Transcurridos tres meses desde la interposición del recurso extraordinario de revisión sin resolución:','["Se entenderá estimado, salvo que el recurso se base en un error de hecho resultante de los documentos del expediente", "Se entenderá desestimado, quedando expedita la vía contencioso-administrativa", "Se prorrogará otros tres meses"]'::jsonb,1,'Art. 126.3 Ley 39/2015','El silencio en el recurso extraordinario de revisión es desestimatorio.',null),
('aux-ayto-mad:4-b3a4330e57','aux-ayto-mad',4,'En ningún caso se podrá imponer una sanción:','["A una persona jurídica", "Sin que el infractor esté asistido de abogado", "Sin que se haya tramitado el oportuno procedimiento"]'::jsonb,2,'Art. 63.2 Ley 39/2015','La sanción exige siempre procedimiento previo.',null),
('aux-ayto-mad:4-f332b4ba40','aux-ayto-mad',4,'El error o la ausencia de calificación del recurso por parte del recurrente:','["Determina su inadmisión, salvo que el recurrente lo subsane en el plazo de diez días desde el requerimiento", "No será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter", "Solo puede subsanarse si el recurrente está asistido de abogado"]'::jsonb,1,'Art. 115.2 Ley 39/2015','Lo importante es que se deduzca el verdadero carácter del recurso.',null),
('aux-ayto-mad:4-3fddc0a3d7','aux-ayto-mad',4,'Los vicios y defectos que hagan anulable un acto:','["Pueden alegarse por cualquier persona, incluidos quienes los hubieran causado", "No podrán ser alegados por quienes los hubieren causado", "Determinan siempre la nulidad de pleno derecho del acto, aunque no causen indefensión"]'::jsonb,1,'Art. 115.3 Ley 39/2015','Quien causó el vicio no puede alegarlo.',null),
('aux-ayto-mad:4-25bf106ef7','aux-ayto-mad',4,'El acuerdo de realización de actuaciones complementarias se notificará a los interesados, concediéndoles un plazo para alegaciones tras su finalización de:','["Siete días", "Quince días", "Cinco días"]'::jsonb,0,'Art. 87 Ley 39/2015','Plazo de siete días para alegaciones; las actuaciones se practican en un máximo de quince días y el plazo para resolver queda suspendido.',null),
('aux-ayto-mad:4-02e39bd8bd','aux-ayto-mad',4,'La comparecencia en el trámite de información pública:','["Solo pueden hacerla los vecinos del municipio afectado", "No otorga, por sí misma, la condición de interesado", "Es obligatoria para poder recurrir después la resolución"]'::jsonb,1,'Art. 83.3 Ley 39/2015','La incomparecencia tampoco impide a los interesados recurrir la resolución.',null),
('aux-ayto-mad:4-01cab17fbe','aux-ayto-mad',4,'Contra el acuerdo de acumulación de procedimientos:','["Cabe recurso extraordinario de revisión", "No procederá recurso alguno", "Cabe recurso de reposición"]'::jsonb,1,'Art. 57 Ley 39/2015','La acumulación procede si hay identidad sustancial o íntima conexión y el mismo órgano tramita y resuelve.',null),
('aux-ayto-mad:4-e72eaf3b3d','aux-ayto-mad',4,'Si la Administración acuerda de oficio la tramitación simplificada y algún interesado manifiesta su oposición expresa:','["Se mantiene la tramitación simplificada si el órgano lo motiva por razones de interés público", "La Administración deberá seguir la tramitación ordinaria", "Se mantiene la tramitación simplificada si el órgano lo motiva"]'::jsonb,1,'Art. 96.2 Ley 39/2015','La oposición expresa de un interesado obliga a la tramitación ordinaria.',null),
('aux-ayto-mad:4-079126dec2','aux-ayto-mad',4,'La resolución que ponga fin al procedimiento sancionador será ejecutiva cuando:','["Se dicte por el órgano competente, aunque quepa contra ella recurso de alzada", "No quepa contra ella ningún recurso ordinario en vía administrativa", "Se notifique al interesado, aunque quepa contra ella recurso de alzada"]'::jsonb,1,'Art. 90.3 Ley 39/2015','Puede suspenderse cautelarmente si el interesado manifiesta que interpondrá recurso contencioso-administrativo.',null),
('aux-ayto-mad:4-b8b592a182','aux-ayto-mad',4,'Si la cuestión suscitada entrañase interés general, la Administración ante un desistimiento o renuncia:','["Deberá aceptarlo de plano y declarar concluso el procedimiento para todos los interesados", "Podrá limitar sus efectos al interesado y seguirá el procedimiento", "Deberá archivar el procedimiento"]'::jsonb,1,'Art. 94.5 Ley 39/2015','El procedimiento continúa por el interés general.',null),
('aux-ayto-mad:4-8389d4f7a0','aux-ayto-mad',4,'Si un informe preceptivo no se emite en plazo:','["Se podrá suspender el transcurso del plazo máximo legal para resolver el procedimiento", "Se entiende desfavorable a la pretensión del interesado y se continúa el procedimiento hasta su resolución", "Se entiende favorable"]'::jsonb,0,'Art. 80.3 Ley 39/2015','Si no es preceptivo, se pueden proseguir las actuaciones.',null),
('aux-ayto-mad:4-3db38ddf14','aux-ayto-mad',4,'Si un interesado solicita la tramitación simplificada y el órgano considera que no procede, podrá desestimarla en el plazo de:','["Cinco días desde su presentación, con recurso potestativo de reposición", "Un mes desde su presentación, con recurso de alzada", "Cinco días desde su presentación, sin posibilidad de recurso"]'::jsonb,2,'Art. 96.3 Ley 39/2015','Transcurrido el plazo sin resolver, se entiende desestimada.',null),
('aux-ayto-mad:4-46a23ee086','aux-ayto-mad',4,'El recurso de alzada se interpone ante:','["El Tribunal Superior de Justicia de la Comunidad Autónoma", "El mismo órgano que dictó el acto, que lo resuelve en el plazo de un mes, sin que pueda presentarse ante el superior jerárquico ni ante otro órgano", "El órgano superior jerárquico del que dictó el acto, pudiendo presentarse ante el que lo dictó o ante el competente para resolver"]'::jsonb,2,'Art. 121.1 Ley 39/2015','Lo resuelve el superior jerárquico; puede presentarse ante cualquiera de los dos.',null),
('aux-ayto-mad:4-d31e320daa','aux-ayto-mad',4,'Los expedientes tendrán formato electrónico y se formarán mediante la agregación ordenada de documentos, con:','["Un índice numerado de todos los documentos que contenga cuando se remita", "Un resumen elaborado por el instructor con la relación de los interesados y de los trámites realizados", "La firma de todos los interesados en cada uno de los documentos que contenga"]'::jsonb,0,'Art. 70.2 Ley 39/2015','Deben incluir un índice numerado de todos los documentos.',null),
('aux-ayto-mad:4-92ea779caa','aux-ayto-mad',4,'La resolución en un procedimiento de responsabilidad patrimonial deberá pronunciarse sobre:','["La existencia o no de relación de causalidad, la valoración del daño y la cuantía y modo de indemnización", "La existencia de culpa o dolo del empleado, que es requisito para que nazca la responsabilidad de la Administración", "La responsabilidad penal del empleado público que causó el daño y la sanción disciplinaria que le corresponda imponer"]'::jsonb,0,'Art. 91.2 Ley 39/2015','Son los extremos obligatorios de la resolución.',null),
('aux-ayto-mad:4-064acf5e63','aux-ayto-mad',4,'No se podrán adoptar medidas provisionales que:','["Puedan causar perjuicio de difícil o imposible reparación a los interesados o impliquen violación de derechos amparados por las leyes", "Afecten a la actividad económica del interesado o a su patrimonio, aunque no le causen ningún perjuicio de difícil o imposible reparación ni vulneren sus derechos", "Sean proporcionadas al objetivo que se pretende garantizar, aunque se adopten antes del inicio del procedimiento en casos de urgencia"]'::jsonb,0,'Art. 56.4 Ley 39/2015','Las medidas provisionales tienen ese límite.',null),
('aux-ayto-mad:4-b663de3794','aux-ayto-mad',4,'En la tramitación simplificada, el trámite de audiencia solo se realiza cuando:','["La resolución vaya a ser desfavorable para el interesado", "Nunca, porque la tramitación simplificada lo suprime en todo caso", "Lo pida cualquier tercero que no sea interesado"]'::jsonb,0,'Art. 96.6 d) Ley 39/2015','Las alegaciones al inicio se formulan en cinco días.',null),
('aux-ayto-mad:4-84cb6abca5','aux-ayto-mad',4,'Cuando la Administración establezca expresamente modelos específicos de presentación de solicitudes en un procedimiento concreto, estos serán:','["Solo orientativos", "De uso voluntario", "De uso obligatorio por los interesados"]'::jsonb,2,'Art. 66.6 Ley 39/2015','Los modelos específicos establecidos expresamente son de uso obligatorio.',null),
('aux-ayto-mad:4-a7091ee71b','aux-ayto-mad',4,'Si fueran varios los medios de ejecución admisibles, se elegirá:','["El menos restrictivo de la libertad individual", "El más económico para la Administración actuante", "El que elija el interesado de entre los admisibles"]'::jsonb,0,'Art. 100.2 Ley 39/2015','Se elige el menos restrictivo de la libertad individual.',null),
('aux-ayto-mad:4-b3dd1e1445','aux-ayto-mad',4,'Según el art. 105, no se admitirán a trámite contra las actuaciones de los órganos administrativos realizadas en materia de su competencia y de acuerdo con el procedimiento legal:','["Las reclamaciones de responsabilidad", "Las acciones posesorias", "Los recursos contencioso-administrativos"]'::jsonb,1,'Art. 105 Ley 39/2015','No se admiten acciones posesorias contra esas actuaciones.',null),
('aux-ayto-mad:4-b5af49985a','aux-ayto-mad',4,'De las solicitudes y escritos que presenten los interesados, estos podrán exigir:','["Una resolución inmediata sobre la admisión de la solicitud presentada", "El correspondiente recibo que acredite la fecha y hora de presentación", "La devolución de las tasas abonadas"]'::jsonb,1,'Art. 66.3 Ley 39/2015','Pueden exigir recibo con fecha y hora de presentación.',null),
('aux-ayto-mad:4-324d1d9e2f','aux-ayto-mad',4,'La Administración aceptará de plano el desistimiento o la renuncia, salvo que terceros interesados personados insten la continuación en el plazo de:','["Cinco días desde que fueron notificados", "Diez días desde que fueron notificados", "Un mes desde que fueron notificados"]'::jsonb,1,'Art. 94.4 Ley 39/2015','Los terceros tienen diez días para pedir la continuación.',null),
('aux-ayto-mad:4-7f989d537c','aux-ayto-mad',4,'Si se trata de obligaciones personalísimas de hacer y no se realiza la prestación, el obligado deberá:','["Resarcir los daños y perjuicios, cuya liquidación y cobro solo pueden exigirse en vía judicial civil", "Resarcir los daños y perjuicios, a cuya liquidación y cobro se procederá en vía administrativa", "Ser objeto de compulsión sobre su persona hasta que realice la prestación, sin resarcimiento alguno"]'::jsonb,1,'Art. 104.2 Ley 39/2015','El obligado debe resarcir daños y perjuicios.',null),
('aux-ayto-mad:4-2db81da03c','aux-ayto-mad',4,'Con anterioridad al inicio del procedimiento, el órgano competente podrá abrir:','["Un período de información o actuaciones previas para conocer las circunstancias del caso y la conveniencia de iniciar", "El trámite de información pública", "El trámite de audiencia a los posibles interesados para que aleguen sobre la conveniencia de iniciar el procedimiento"]'::jsonb,0,'Art. 55.1 Ley 39/2015','Las actuaciones previas sirven para valorar si procede iniciar el procedimiento.',null),
('aux-ayto-mad:4-cac77c595b','aux-ayto-mad',4,'El órgano competente podrá inadmitir sin dictamen las solicitudes de revisión de oficio formuladas por interesados cuando:','["Se refieran a actos favorables", "Carezcan manifiestamente de fundamento", "Se presenten en papel"]'::jsonb,1,'Art. 106.3 Ley 39/2015','También cuando no se basen en causas de nulidad o se hayan desestimado en cuanto al fondo otras sustancialmente iguales.',null),
('aux-ayto-mad:4-87aa1f3635','aux-ayto-mad',4,'¿Cuál de las siguientes NO es causa de inadmisión del art. 116?','["Carecer de legitimación el recurrente", "Que el recurso se haya calificado erróneamente", "Carecer el recurso manifiestamente de fundamento"]'::jsonb,1,'Art. 116 Ley 39/2015','El error en la calificación no impide la tramitación (art. 115.2).',null),
('aux-ayto-mad:4-02df8f911c','aux-ayto-mad',4,'Las facultades de revisión no podrán ejercerse cuando:','["Por prescripción de acciones, tiempo transcurrido u otras circunstancias, su ejercicio resulte contrario a la equidad, la buena fe, el derecho de los particulares o las leyes", "Lo solicite el propio interesado", "Haya transcurrido un año desde la notificación del acto, cualquiera que sea el vicio que lo afecte y aunque su ejercicio no resulte contrario a la equidad, la buena fe ni el derecho de los particulares"]'::jsonb,0,'Art. 110 Ley 39/2015','Son los límites de la revisión.',null),
('aux-ayto-mad:4-b77acd6c36','aux-ayto-mad',4,'En el procedimiento sancionador, el órgano instructor resolverá la finalización con archivo de actuaciones, sin formular propuesta de resolución, cuando:','["Los hechos probados no constituyan, de modo manifiesto, infracción administrativa", "El denunciante lo solicite expresamente y retire la denuncia antes de la propuesta de resolución", "El presunto infractor reconozca su responsabilidad y pague voluntariamente la sanción"]'::jsonb,0,'Art. 89.1 c) Ley 39/2015','También por inexistencia de los hechos, falta de prueba, falta de responsable o prescripción de la infracción.',null),
('aux-ayto-mad:4-68b7efb004','aux-ayto-mad',4,'Transcurridos seis meses desde el inicio de un procedimiento de responsabilidad patrimonial sin resolución ni acuerdo:','["El procedimiento caduca y se archivan las actuaciones sin pronunciamiento sobre la indemnización", "Se paga automáticamente la indemnización", "Podrá entenderse que la resolución es contraria a la indemnización del particular"]'::jsonb,2,'Art. 91.3 Ley 39/2015','El silencio en responsabilidad patrimonial es desestimatorio.',null),
('aux-ayto-mad:4-371a9390c5','aux-ayto-mad',4,'Las medidas provisionales adoptadas antes de iniciar el procedimiento deberán ser confirmadas, modificadas o levantadas en el acuerdo de iniciación, que deberá efectuarse:','["Dentro de los quince días siguientes a su adopción", "Dentro de los tres meses siguientes", "Dentro de los diez días siguientes a su adopción"]'::jsonb,0,'Art. 56.2 Ley 39/2015','Si no se inicia en ese plazo o el acuerdo no se pronuncia, las medidas quedan sin efecto.',null),
('aux-ayto-mad:4-b13a27852a','aux-ayto-mad',4,'Los documentos formalizados por funcionarios con la condición de autoridad en los que se recojan hechos constatados por ellos:','["Harán prueba de estos salvo que se acredite lo contrario", "Tienen valor absoluto e irrebatible", "Solo tienen valor probatorio si los ratifica un juez o el instructor del procedimiento"]'::jsonb,0,'Art. 77.5 Ley 39/2015','Gozan de presunción de veracidad salvo prueba en contrario.',null),
('aux-ayto-mad:4-288d693237','aux-ayto-mad',4,'Salvo que reste menos para su tramitación ordinaria, los procedimientos de tramitación simplificada deberán resolverse en:','["Seis meses desde el inicio del procedimiento", "Quince días desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Treinta días desde el siguiente al que se notifique el acuerdo de tramitación simplificada"]'::jsonb,2,'Art. 96.6 Ley 39/2015','El plazo es de treinta días.',null),
('aux-ayto-mad:4-7214768c1b','aux-ayto-mad',4,'Se entiende por propia iniciativa:','["La denuncia de un particular que pone los hechos en conocimiento del órgano competente para iniciar, sin que este tenga conocimiento directo de las circunstancias", "La actuación derivada del conocimiento directo o indirecto de las circunstancias o hechos por el órgano que tiene la competencia de iniciación", "La orden emitida por un órgano superior jerárquico del competente para iniciar, tras conocer los hechos por una denuncia o por una petición razonada de otro órgano"]'::jsonb,1,'Art. 59 Ley 39/2015','Es el conocimiento directo o indirecto por el propio órgano competente.',null),
('aux-ayto-mad:4-23cc3b7c45','aux-ayto-mad',4,'En la resolución del procedimiento sancionador no se podrán aceptar hechos distintos de los determinados en el curso del procedimiento:','["Con independencia de su diferente valoración jurídica", "Salvo en las infracciones leves, en las que sí pueden aceptarse", "Salvo que resulten más graves, en cuyo caso se notificarán al inculpado para que formule alegaciones"]'::jsonb,0,'Art. 90.2 Ley 39/2015','Se protege el derecho de defensa del inculpado.',null),
('aux-ayto-mad:4-0379def616','aux-ayto-mad',4,'En el procedimiento de responsabilidad patrimonial iniciado de oficio, el acuerdo de iniciación se notificará a los presuntos lesionados, concediéndoles un plazo para alegaciones y pruebas de:','["Diez días", "Cinco días", "Quince días"]'::jsonb,0,'Art. 65.2 Ley 39/2015','Se les concede diez días para aportar alegaciones, documentos o información y proponer pruebas.',null),
('aux-ayto-mad:4-eb6c8b17a5','aux-ayto-mad',4,'En los procedimientos tramitados a solicitud del interesado, la resolución será congruente con las peticiones formuladas:','["Pudiendo agravar su situación inicial si así lo exige el interés público", "Sin que en ningún caso pueda agravar su situación inicial", "Solo si el instructor lo propone y el interesado no se opone"]'::jsonb,1,'Art. 88.2 Ley 39/2015','Sin perjuicio de la potestad de incoar de oficio un nuevo procedimiento.',null),
('aux-ayto-mad:4-0269490eae','aux-ayto-mad',4,'La presentación de una denuncia:','["Requiere asistencia de abogado", "Convierte al denunciante en interesado en el procedimiento sancionador que se inicie", "No confiere, por sí sola, la condición de interesado en el procedimiento"]'::jsonb,2,'Art. 62.5 Ley 39/2015','El denunciante no es interesado por el solo hecho de denunciar.',null),
('aux-ayto-mad:4-7924fdca60','aux-ayto-mad',4,'Según el art. 62.1, se entiende por denuncia:','["La orden de un superior", "La propuesta de iniciación formulada por un órgano administrativo sin competencia para iniciar, que tiene conocimiento de los hechos por razón de sus funciones de inspección, averiguación o investigación", "El acto por el que cualquier persona, en cumplimiento o no de una obligación legal, pone en conocimiento de un órgano administrativo un hecho que pudiera justificar la iniciación de oficio"]'::jsonb,2,'Art. 62.1 Ley 39/2015','Definición legal de la denuncia.',null),
('aux-ayto-mad:4-a6248c9330','aux-ayto-mad',4,'Si existe vicio de forma y no se estima procedente resolver sobre el fondo, el órgano que resuelve el recurso:','["Inadmitirá el recurso", "Dictará resolución favorable", "Ordenará la retroacción del procedimiento al momento en que el vicio fue cometido"]'::jsonb,2,'Art. 119.2 Ley 39/2015','Se ordena retrotraer el procedimiento al momento del vicio.',null),
('aux-ayto-mad:4-ba666ef274','aux-ayto-mad',4,'En los procedimientos de responsabilidad patrimonial ante la AGE, es preceptivo el dictamen del Consejo de Estado cuando la indemnización reclamada sea de cuantía igual o superior a:','["50.000 euros", "30.000 euros", "100.000 euros"]'::jsonb,0,'Art. 81.2 Ley 39/2015','Desde 50.000 € (o la cuantía fijada por la legislación autonómica) es preceptivo el dictamen.',null),
('aux-ayto-mad:4-5600e61bf0','aux-ayto-mad',4,'Cuando deban resolverse una pluralidad de recursos derivados de un mismo acto y se haya interpuesto recurso judicial contra una resolución administrativa o contra el correspondiente acto presunto:','["El órgano administrativo podrá acordar la suspensión del plazo para resolver hasta que recaiga pronunciamiento judicial", "Deberá estimar todos los recursos", "Deberá resolver todos los recursos en el plazo ordinario, sin esperar al pronunciamiento judicial, para no perjudicar a los interesados que no han acudido a los tribunales"]'::jsonb,0,'Art. 120.1 Ley 39/2015','El órgano puede suspender el plazo hasta que haya pronunciamiento judicial.',null),
('aux-ayto-mad:4-90fc2d9bb8','aux-ayto-mad',4,'En el despacho de los expedientes se guardará:','["El orden alfabético de los interesados, salvo orden motivada en contrario del superior jerárquico del instructor", "El orden de prioridad que fije cada interesado en su solicitud, o el que indique el superior jerárquico en cada caso concreto", "El orden riguroso de incoación en asuntos de homogénea naturaleza, salvo orden motivada en contrario"]'::jsonb,2,'Art. 71.2 Ley 39/2015','Su incumplimiento puede dar lugar a responsabilidad disciplinaria.',null),
('aux-ayto-mad:4-127ef4412c','aux-ayto-mad',4,'El órgano que ordene un acto de ejecución material de resoluciones está obligado a:','["Notificar al particular interesado la resolución que autorice la actuación administrativa", "Esperar a que el acto sea firme en vía administrativa y solicitar autorización judicial para ejecutarlo", "Publicarlo en el BOE y en el boletín autonómico antes de iniciar la actuación material, sin necesidad de notificación personal"]'::jsonb,0,'Art. 97.2 Ley 39/2015','Debe notificar al particular la resolución que autorice la actuación.',null),
('aux-ayto-mad:4-b6065f3393','aux-ayto-mad',4,'El recurso extraordinario de revisión se interpone contra:','["Las disposiciones de carácter general, cuando concurra alguna de las circunstancias del art. 125.1", "Los actos firmes en vía administrativa, cuando concurra alguna de las circunstancias del art. 125.1", "Los actos que no ponen fin a la vía administrativa, en cualquier momento"]'::jsonb,1,'Art. 113 Ley 39/2015','Procede contra actos firmes en vía administrativa en los casos del art. 125.1.',null),
('aux-ayto-mad:4-9eaf6a6a5f','aux-ayto-mad',4,'NO forma parte del expediente administrativo:','["La información auxiliar o de apoyo, como notas, borradores u opiniones, salvo los informes solicitados antes de la resolución", "Las notificaciones practicadas", "Los informes preceptivos, que se incorporan a un expediente auxiliar distinto del principal y no se remiten al juzgado"]'::jsonb,0,'Art. 70.4 Ley 39/2015','Notas, borradores, opiniones, resúmenes y comunicaciones internas no forman parte del expediente.',null),
('aux-ayto-mad:4-049166e70a','aux-ayto-mad',4,'Las declaraciones responsables y las comunicaciones permiten el reconocimiento o ejercicio de un derecho o el inicio de una actividad:','["Tras la resolución expresa que reconozca el derecho, que deberá dictarse en un mes", "Desde el día de su presentación, sin que la Administración pueda comprobar después lo declarado", "Desde el día de su presentación, sin perjuicio de las facultades de comprobación de la Administración"]'::jsonb,2,'Art. 69.3 Ley 39/2015','Producen efectos desde su presentación.',null),
('aux-ayto-mad:4-16afbfd33e','aux-ayto-mad',4,'Si el escrito de iniciación se formuló por dos o más interesados, el desistimiento o la renuncia:','["Requiere el acuerdo unánime de todos los que firmaron el escrito de iniciación", "No está permitido una vez iniciado el procedimiento", "Solo afectará a aquellos que la hubiesen formulado"]'::jsonb,2,'Art. 94.2 Ley 39/2015','El desistimiento solo afecta a quien lo formula.',null),
('aux-ayto-mad:4-43056a1bb1','aux-ayto-mad',4,'Es causa del recurso extraordinario de revisión:','["Que el acto sea desfavorable y el interesado aporte cualquier documento nuevo, aunque no evidencie error alguno en la resolución", "Que aparezcan documentos de valor esencial para la resolución que evidencien el error de la resolución recurrida", "Que haya transcurrido el plazo para interponer el recurso de alzada sin haberlo hecho, por causa no imputable al interesado"]'::jsonb,1,'Art. 125.1 b) Ley 39/2015','Las causas son: error de hecho, documentos esenciales nuevos, documentos o testimonios falsos declarados en sentencia firme y conducta punible declarada en sentencia firme.',null),
('aux-ayto-mad:4-a458f8a2a4','aux-ayto-mad',4,'La declaración de lesividad de los actos favorables anulables tiene como finalidad:','["Sancionar al interesado que se benefició del acto", "Su posterior impugnación ante el orden jurisdiccional contencioso-administrativo", "Convertirlos en actos nulos de pleno derecho para poder revisarlos de oficio en cualquier momento"]'::jsonb,1,'Art. 107.1 Ley 39/2015','La Administración declara la lesividad para impugnarlos después ante la jurisdicción contencioso-administrativa.',null),
('aux-ayto-mad:4-c35f13229a','aux-ayto-mad',4,'Según la Ley 39/2015, el expediente administrativo es:','["La carpeta física en la que se archivan los escritos de los interesados", "El conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento a la resolución administrativa, y las diligencias encaminadas a ejecutarla", "El acto administrativo que pone fin al procedimiento"]'::jsonb,1,'Art. 70.1 Ley 39/2015','Los expedientes tienen formato electrónico.',null),
('aux-ayto-mad:4-184bc2fb48','aux-ayto-mad',4,'¿Forman parte del expediente administrativo las notas, borradores y opiniones de carácter auxiliar?','["No, salvo que se trate de informes preceptivos o facultativos solicitados antes de la resolución", "Sí, todos ellos, porque reflejan la actividad interna del órgano y deben estar a disposición de los interesados", "No, y además deben destruirse al terminar el procedimiento"]'::jsonb,0,'Art. 70.4 Ley 39/2015','Tampoco forman parte las comunicaciones e informes internos o entre órganos o entidades administrativas, ni los juicios de valor emitidos por las Administraciones.',null),
('aux-ayto-mad:4-50bb4487f0','aux-ayto-mad',4,'Al remitir un expediente electrónico, este debe ir acompañado de:','["Un índice numerado de todos los documentos que contenga", "El original en papel de cada uno de los documentos que lo integran", "Una copia completa en soporte óptico, como un CD o un DVD"]'::jsonb,0,'Art. 70.2 Ley 39/2015','El índice garantiza la integridad del expediente y permite su recuperación.',null),
('aux-ayto-mad:5-3b7018ba27','aux-ayto-mad',5,'Según la Ley 7/1985, son elementos del municipio:','["La población, el patrimonio y el Pleno", "El término municipal, el padrón y el presupuesto", "El territorio, la población y la organización"]'::jsonb,2,'Art. 11.2 LBRL','El municipio es la entidad local básica de la organización territorial del Estado.',null),
('aux-ayto-mad:5-65d0a4636c','aux-ayto-mad',5,'La Junta de Gobierno Local existe:','["En los municipios de más de 5.000 habitantes y en los de menos si lo disponen su reglamento orgánico o el Pleno", "En todos los municipios, sea cual sea su población, como órgano de asistencia permanente al Alcalde en sus funciones", "Solo en los municipios de gran población, regulados en el título X de la Ley 7/1985, reguladora de las Bases del Régimen Local"]'::jsonb,0,'Art. 20.1 b) LBRL','El Alcalde, los Tenientes de Alcalde y el Pleno existen en todos los Ayuntamientos.',null),
('aux-ayto-mad:5-743b1e9f0f','aux-ayto-mad',5,'¿Qué servicio deben prestar los municipios de más de 50.000 habitantes, además de los exigidos a los más pequeños?','["Transporte colectivo urbano de viajeros", "Alumbrado público", "Biblioteca pública"]'::jsonb,0,'Art. 26.1 d) LBRL','La biblioteca es obligatoria desde 5.000 habitantes, las instalaciones deportivas desde 20.000 y el alumbrado en todos.',null),
('aux-ayto-mad:5-32298157ec','aux-ayto-mad',5,'Según el artículo 1 de la Ley 7/1985, los Municipios son:','["Entidades instrumentales de las Comunidades Autónomas para la prestación de los servicios públicos en su territorio", "Entidades básicas de la organización territorial del Estado y cauces inmediatos de participación ciudadana en los asuntos públicos", "Divisiones territoriales del Estado para el cumplimiento de sus actividades"]'::jsonb,1,'Art. 1.1 LBRL','El art. 1.1 los define como entidades básicas de la organización territorial del Estado y cauces inmediatos de participación ciudadana, que gestionan con autonomía los intereses propios de sus colectividades.',null),
('aux-ayto-mad:5-2bac6e7216','aux-ayto-mad',5,'¿Cuál de las siguientes NO es una Entidad Local territorial según el artículo 3.1 de la Ley 7/1985?','["La Isla en los archipiélagos balear y canario", "La Comarca", "La Provincia"]'::jsonb,1,'Art. 3 LBRL','Son entidades locales territoriales el Municipio, la Provincia y la Isla en los archipiélagos. Las Comarcas, las Áreas Metropolitanas y las Mancomunidades gozan de la condición de entidades locales, pero no son territoriales (art. 3.2).',null),
('aux-ayto-mad:5-4d9fe8a026','aux-ayto-mad',5,'Según la Ley 7/1985, las Mancomunidades de Municipios:','["Son entidades locales territoriales, como el Municipio y la Provincia", "Gozan de la condición de Entidades Locales, pero no son entidades locales territoriales", "No tienen la condición de Entidad Local"]'::jsonb,1,'Art. 3.2 c) LBRL','El art. 3.2 incluye las Mancomunidades entre las entidades que gozan de la condición de Entidades Locales, junto con las Comarcas y las Áreas Metropolitanas.',null),
('aux-ayto-mad:5-67fc230814','aux-ayto-mad',5,'¿Cuál de las siguientes potestades corresponde en todo caso a los municipios según el artículo 4 de la Ley 7/1985?','["La potestad expropiatoria", "La potestad legislativa", "La potestad jurisdiccional"]'::jsonb,0,'Art. 4.1 d) LBRL','Corresponden a los municipios, entre otras, las potestades reglamentaria y de autoorganización, tributaria y financiera, de planificación, expropiatoria, de ejecución forzosa y sancionadora, y de revisión de oficio.',null),
('aux-ayto-mad:5-43c090da51','aux-ayto-mad',5,'Según la Ley 7/1985, el control de legalidad de los acuerdos y actos de las entidades locales lo ejercen:','["Los Tribunales", "Las Comunidades Autónomas", "El Delegado del Gobierno"]'::jsonb,0,'Art. 6.2 LBRL','Según el art. 6.2, los Tribunales ejercen el control de legalidad de los acuerdos y actos de las entidades locales.',null),
('aux-ayto-mad:5-b6133a3e1a','aux-ayto-mad',5,'Según el artículo 7 de la Ley 7/1985, las competencias de las Entidades Locales son:','["Propias, delegadas o encomendadas por los particulares", "Propias o atribuidas por delegación", "Exclusivas, compartidas o concurrentes"]'::jsonb,1,'Art. 7.1 LBRL','Las competencias de las Entidades Locales son propias o atribuidas por delegación.',null),
('aux-ayto-mad:5-4318f0ec22','aux-ayto-mad',5,'Las competencias propias de los Municipios solo podrán ser determinadas:','["Por Ley", "Por reglamento del Gobierno", "Por acuerdo del Pleno municipal"]'::jsonb,0,'Art. 7.2 LBRL','Según el art. 7.2, solo podrán ser determinadas por Ley y se ejercen en régimen de autonomía y bajo la propia responsabilidad.',null),
('aux-ayto-mad:5-e50421d01c','aux-ayto-mad',5,'Según la Ley 7/1985, son elementos del Municipio:','["El término municipal, los vecinos y el presupuesto", "El territorio, la población y la organización", "El territorio, la población y el patrimonio"]'::jsonb,1,'Art. 11.2 LBRL','El art. 11.2 dice que son elementos del Municipio el territorio, la población y la organización.',null),
('aux-ayto-mad:5-8bd50762a7','aux-ayto-mad',5,'El término municipal es, según la Ley 7/1985:','["El conjunto de núcleos de población del municipio", "El territorio en que el ayuntamiento ejerce sus competencias", "El territorio que figura en el padrón municipal como residencia de los vecinos"]'::jsonb,1,'Art. 12.1 LBRL','El término municipal es el territorio en que el ayuntamiento ejerce sus competencias. Cada municipio pertenece a una sola provincia (art. 12.2).',null),
('aux-ayto-mad:5-be31d1d98d','aux-ayto-mad',5,'La creación de nuevos municipios solo podrá realizarse sobre la base de núcleos de población territorialmente diferenciados de al menos:','["4.000 habitantes", "2.000 habitantes", "5.000 habitantes"]'::jsonb,0,'Art. 13.2 LBRL','El art. 13.2 exige núcleos de al menos 4.000 habitantes, que sean financieramente sostenibles y no supongan una peor calidad de los servicios.',null),
('aux-ayto-mad:5-d2dfa79446','aux-ayto-mad',5,'El municipio resultante de una fusión mediante convenio no podrá segregarse hasta que transcurran:','["Diez años desde la adopción del convenio de fusión", "Cuatro años, la duración de un mandato", "Cinco años desde la adopción del convenio de fusión"]'::jsonb,0,'Art. 13.4 LBRL','Según el art. 13.4, no podrá segregarse hasta transcurridos diez años desde la adopción del convenio de fusión.',null),
('aux-ayto-mad:5-b8641295ce','aux-ayto-mad',5,'Los cambios de denominación de los Municipios solo tendrán carácter oficial cuando, tras anotarse en el Registro estatal de entidades locales, se publiquen en:','["El boletín oficial de la Comunidad Autónoma", "El «Boletín Oficial del Estado»", "El «Boletín Oficial» de la Provincia"]'::jsonb,1,'Art. 14.1 LBRL','El art. 14.1 exige la anotación en el Registro estatal y la publicación en el «Boletín Oficial del Estado».',null),
('aux-ayto-mad:5-c8aeaa7ddd','aux-ayto-mad',5,'Quien viva en varios municipios deberá inscribirse en el Padrón:','["De todos ellos, indicando cuál es su residencia principal", "Del municipio donde tenga su domicilio fiscal", "Únicamente del municipio en el que habite durante más tiempo al año"]'::jsonb,2,'Art. 15 LBRL','Toda persona que viva en España está obligada a empadronarse en el municipio donde resida habitualmente; si vive en varios, solo en el que habite más tiempo al año.',null),
('aux-ayto-mad:5-e8c2e28c26','aux-ayto-mad',5,'Según la Ley 7/1985, la condición de vecino se adquiere:','["Cuando el Ayuntamiento aprueba la revisión anual del Padrón", "Al año de residir de forma continuada en el municipio", "En el mismo momento de su inscripción en el Padrón"]'::jsonb,2,'Art. 15 LBRL','Según el art. 15, la condición de vecino se adquiere en el mismo momento de la inscripción en el Padrón.',null),
('aux-ayto-mad:5-7387168a17','aux-ayto-mad',5,'Las certificaciones de los datos del Padrón municipal tienen carácter de:','["Prueba de la residencia legal en España de los extranjeros a todos los efectos", "Documento privado con valor de simple declaración del vecino", "Documento público y fehaciente para todos los efectos administrativos"]'::jsonb,2,'Art. 16.1 LBRL','Sus datos prueban la residencia y el domicilio habitual, y sus certificaciones son documento público y fehaciente para todos los efectos administrativos. En cambio, no prueban la residencia legal de los extranjeros (art. 18.2).',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:5-75f4e6f5b9','aux-ayto-mad',5,'La inscripción en el Padrón de los extranjeros no comunitarios sin autorización de residencia de larga duración deberá renovarse:','["Cada dos años", "Cada año", "Cada cinco años"]'::jsonb,0,'Art. 16.1 LBRL','Debe ser objeto de renovación periódica cada dos años; si no se renueva, puede declararse su caducidad sin audiencia previa.',null),
('aux-ayto-mad:5-af1205ad16','aux-ayto-mad',5,'¿Cuál de los siguientes datos es obligatorio en la inscripción en el Padrón municipal?','["El certificado o título escolar o académico que se posea", "El número de teléfono de contacto del vecino", "La dirección de correo electrónico para recibir notificaciones"]'::jsonb,0,'Art. 16.2 LBRL','El título escolar o académico es dato obligatorio (art. 16.2 g). El teléfono y el correo electrónico son de aportación voluntaria y no se ceden en ningún caso.',null),
('aux-ayto-mad:5-a8f653b06c','aux-ayto-mad',5,'La formación, mantenimiento, revisión y custodia del Padrón municipal corresponde:','["Al Ayuntamiento", "Al Instituto Nacional de Estadística", "A la Diputación Provincial"]'::jsonb,0,'Art. 17.1 LBRL','Corresponde al Ayuntamiento, de acuerdo con la legislación del Estado. El INE coordina los padrones de todos los municipios.',null),
('aux-ayto-mad:5-4e57524b92','aux-ayto-mad',5,'El Consejo de Empadronamiento está presidido por:','["El Ministro de Hacienda", "El Presidente del Instituto Nacional de Estadística", "El Presidente de la Federación Española de Municipios y Provincias"]'::jsonb,1,'Art. 17.4 LBRL','Es un órgano colegiado de colaboración entre la AGE y los entes locales presidido por el Presidente del INE.',null),
('aux-ayto-mad:5-e2a146155b','aux-ayto-mad',5,'Las personas inscritas en el Padrón de españoles residentes en el extranjero se consideran vecinos del municipio que figura en su inscripción:','["Únicamente a efectos del ejercicio del derecho de sufragio", "A todos los efectos, y forman parte de la población del municipio", "A efectos fiscales y electorales, pero no forman parte de su población"]'::jsonb,0,'Art. 17.5 LBRL','Son vecinos únicamente a efectos del derecho de sufragio y no constituyen, en ningún caso, población del municipio.',null),
('aux-ayto-mad:5-3cf2a1d432','aux-ayto-mad',5,'¿Cuál de los siguientes es un derecho de los vecinos según el artículo 18 de la Ley 7/1985?','["Votar en el Pleno municipal las ordenanzas que afecten directamente a sus intereses", "Exigir el establecimiento del servicio público cuando constituya una competencia municipal propia de carácter obligatorio", "Recibir gratuitamente todos los servicios públicos municipales que soliciten"]'::jsonb,1,'Art. 18.1 g) LBRL','El art. 18.1 g) reconoce el derecho a exigir la prestación y, en su caso, el establecimiento del servicio cuando sea una competencia municipal propia de carácter obligatorio.',null),
('aux-ayto-mad:5-09dbfe3938','aux-ayto-mad',5,'Según la Ley 7/1985, la Junta de Gobierno Local existe en todos los municipios con población superior a:','["1.000 habitantes", "5.000 habitantes", "20.000 habitantes"]'::jsonb,1,'Art. 20.1 b) LBRL','Existe en los municipios de más de 5.000 habitantes y en los de menos cuando lo disponga su reglamento orgánico o lo acuerde el Pleno.',null),
('aux-ayto-mad:5-38c6ae3223','aux-ayto-mad',5,'¿Qué órganos existen en todos los ayuntamientos según el artículo 20 de la Ley 7/1985?','["El Alcalde, el Pleno y la Comisión Especial de Sugerencias y Reclamaciones", "El Alcalde, la Junta de Gobierno Local y el Pleno", "El Alcalde, los Tenientes de Alcalde y el Pleno"]'::jsonb,2,'Art. 20.1 a) LBRL','El Alcalde, los Tenientes de Alcalde y el Pleno existen en todos los ayuntamientos. También la Comisión Especial de Cuentas (art. 20.1 e).',null),
('aux-ayto-mad:5-ce15345bb5','aux-ayto-mad',5,'La Comisión Especial de Cuentas existe:','["Solo en los municipios de gran población", "En los municipios de más de 5.000 habitantes", "En todos los municipios"]'::jsonb,2,'Art. 20.1 e) LBRL','Según el art. 20.1 e), la Comisión Especial de Cuentas existe en todos los municipios.',null),
('aux-ayto-mad:5-e1bb5838f7','aux-ayto-mad',5,'En el régimen común, la Junta de Gobierno Local se integra por el Alcalde y un número de Concejales:','["Igual al número de Tenientes de Alcalde", "No superior a la mitad del número legal de los mismos", "No superior al tercio del número legal de los mismos"]'::jsonb,2,'Art. 23.1 LBRL','Se integra por el Alcalde y un número de Concejales no superior al tercio del número legal, nombrados y separados libremente por el Alcalde, dando cuenta al Pleno.',null),
('aux-ayto-mad:5-7bdae92d22','aux-ayto-mad',5,'Según el artículo 25 de la Ley 7/1985, el Municipio ejercerá en todo caso como competencia propia, en los términos de la legislación estatal y autonómica:','["La gestión de los centros de atención primaria de salud de su término", "La seguridad ciudadana en todo el término municipal, con carácter exclusivo", "Policía local, protección civil, prevención y extinción de incendios"]'::jsonb,2,'Art. 25.2 f) LBRL','Entre las materias del art. 25.2 están la policía local, la protección civil y la prevención y extinción de incendios.',null),
('aux-ayto-mad:5-dc1a7849e0','aux-ayto-mad',5,'¿Cuál de las siguientes materias figura entre las competencias propias del municipio del artículo 25.2 de la Ley 7/1985?','["Gestión de los registros civiles", "Cementerios y actividades funerarias", "Ordenación del territorio autonómico"]'::jsonb,1,'Art. 25.2 k) LBRL','El art. 25.2 k) incluye los cementerios y las actividades funerarias.',null),
('aux-ayto-mad:5-9df4ad49b0','aux-ayto-mad',5,'Según el artículo 26 de la Ley 7/1985, ¿qué servicio deben prestar todos los municipios?','["Alumbrado público", "Transporte colectivo urbano de viajeros", "Biblioteca pública"]'::jsonb,0,'Art. 26.1 a) LBRL','Todos los municipios deben prestar alumbrado público, cementerio, recogida de residuos, limpieza viaria, agua potable, alcantarillado, acceso a los núcleos y pavimentación. La biblioteca es de los de más de 5.000 y el transporte urbano de los de más de 50.000.',null),
('aux-ayto-mad:5-20030186a2','aux-ayto-mad',5,'Los municipios con población superior a 5.000 habitantes deben prestar, además de los servicios comunes a todos:','["Protección civil e instalaciones deportivas de uso público", "Parque público, biblioteca pública y tratamiento de residuos", "Transporte colectivo urbano de viajeros y medio ambiente urbano"]'::jsonb,1,'Art. 26.1 b) LBRL','Los de más de 5.000 añaden parque público, biblioteca pública y tratamiento de residuos; los de más de 20.000, protección civil, servicios sociales, incendios e instalaciones deportivas; los de más de 50.000, transporte urbano y medio ambiente urbano.',null),
('aux-ayto-mad:5-3bcf17f5b9','aux-ayto-mad',5,'El transporte colectivo urbano de viajeros es servicio obligatorio en los municipios con población superior a:','["20.000 habitantes", "50.000 habitantes", "75.000 habitantes"]'::jsonb,1,'Art. 26.1 d) LBRL','Los municipios de más de 50.000 habitantes deben prestar, además, el transporte colectivo urbano de viajeros y el medio ambiente urbano.',null),
('aux-ayto-mad:5-2b14b9a943','aux-ayto-mad',5,'La prevención y extinción de incendios es servicio obligatorio en los municipios con población superior a:','["20.000 habitantes", "50.000 habitantes", "5.000 habitantes"]'::jsonb,0,'Art. 26.1 c) LBRL','Según el art. 26.1 c), corresponde a los municipios de más de 20.000 habitantes, junto con protección civil, servicios sociales e instalaciones deportivas.',null),
('aux-ayto-mad:5-54ac357ba2','aux-ayto-mad',5,'Cuando el Estado o una Comunidad Autónoma deleguen una competencia en un municipio, la duración de la delegación no podrá ser inferior a:','["Cinco años", "Diez años", "Cuatro años"]'::jsonb,0,'Art. 27.1 LBRL','La delegación debe fijar su alcance, condiciones y duración, que no podrá ser inferior a cinco años.',null),
('aux-ayto-mad:5-fa80b2b644','aux-ayto-mad',5,'La efectividad de la delegación de competencias del Estado o de la Comunidad Autónoma en un municipio requiere:','["Su aceptación por el Municipio interesado", "Su aprobación por el Consejo de Ministros", "El informe favorable de la Diputación Provincial"]'::jsonb,0,'Art. 27.5 LBRL','Según el art. 27.5, la efectividad de la delegación requerirá su aceptación por el Municipio interesado.',null),
('aux-ayto-mad:5-08f0fe921f','aux-ayto-mad',5,'La delegación de competencias en un municipio que no vaya acompañada de dotación presupuestaria adecuada y suficiente es:','["Válida, pero el municipio puede renunciar a ella", "Anulable", "Nula"]'::jsonb,2,'Art. 27.6 LBRL','La delegación debe ir acompañada de la financiación correspondiente y es nula sin dicha dotación.',null),
('aux-ayto-mad:5-e54aa24f70','aux-ayto-mad',5,'La constitución en concejo abierto de un municipio por su localización geográfica u otras circunstancias requiere petición de la mayoría de los vecinos, aprobación por la Comunidad Autónoma y decisión favorable del Ayuntamiento por mayoría de:','["Dos tercios de sus miembros", "Mayoría absoluta de sus miembros", "Tres quintos de sus miembros"]'::jsonb,0,'Art. 29.2 LBRL','El art. 29.2 exige petición de la mayoría de los vecinos, decisión favorable por mayoría de dos tercios de los miembros del Ayuntamiento y aprobación por la Comunidad Autónoma.',null),
('aux-ayto-mad:5-6e5a9259b4','aux-ayto-mad',5,'En el régimen de Concejo Abierto, el gobierno y la administración municipales corresponden a:','["Un Alcalde y tres concejales elegidos por los vecinos", "Un Alcalde y una asamblea vecinal de la que forman parte todos los electores", "La asamblea vecinal, presidida por el vecino de más edad"]'::jsonb,1,'Art. 29.3 LBRL','Según el art. 29.3, corresponden a un Alcalde y una asamblea vecinal de la que forman parte todos los electores.',null),
('aux-ayto-mad:5-e414b7f1d1','aux-ayto-mad',5,'En los Ayuntamientos de municipios de más de 20.000 habitantes, el Pleno celebra sesión ordinaria como mínimo:','["Cada tres meses", "Cada mes", "Cada dos meses"]'::jsonb,1,'Art. 46.2 a) LBRL','Cada mes en los municipios de más de 20.000 habitantes y en las Diputaciones; cada dos meses entre 5.001 y 20.000; y cada tres hasta 5.000 habitantes.',null),
('aux-ayto-mad:5-7c0b1223b7','aux-ayto-mad',5,'El Pleno celebra sesión extraordinaria cuando lo decida el Presidente o lo solicite, al menos:','["La mitad de los Concejales de la oposición", "La tercera parte del número legal de miembros de la Corporación", "La cuarta parte del número legal de miembros de la Corporación"]'::jsonb,2,'Art. 46.2 a) LBRL','Lo puede solicitar la cuarta parte, al menos, del número legal de miembros, sin que ningún concejal pueda solicitar más de tres al año.',null),
('aux-ayto-mad:5-e8d5359584','aux-ayto-mad',5,'Solicitado un Pleno extraordinario por el número de concejales exigido, su celebración no podrá demorarse más de:','["Diez días hábiles desde la solicitud", "Quince días hábiles desde la solicitud", "Un mes desde la solicitud"]'::jsonb,1,'Art. 46.2 a) LBRL','Si no se convoca en ese plazo, queda automáticamente convocado para el décimo día hábil siguiente, a las doce horas.',null),
('aux-ayto-mad:5-0caada8335','aux-ayto-mad',5,'Las sesiones plenarias han de convocarse, salvo las extraordinarias urgentes, con una antelación mínima de:','["Tres días hábiles", "Cinco días naturales", "Dos días hábiles"]'::jsonb,2,'Art. 46.2 b) LBRL','Según el art. 46.2 b), las sesiones se convocan al menos con dos días hábiles de antelación; la urgencia debe ratificarla el Pleno.',null),
('aux-ayto-mad:5-626b87e2f7','aux-ayto-mad',5,'El Pleno de una corporación local se constituye válidamente con la asistencia de:','["Un tercio del número legal de miembros, que nunca podrá ser inferior a tres", "Un cuarto del número legal de miembros, que nunca podrá ser inferior a cinco", "La mayoría absoluta del número legal de miembros"]'::jsonb,0,'Art. 46.2 c) LBRL','Se requiere un tercio del número legal de miembros (nunca menos de tres), mantenido durante toda la sesión, y la asistencia del Presidente y del Secretario o de quienes los sustituyan.',null),
('aux-ayto-mad:5-026dbac0da','aux-ayto-mad',5,'En las votaciones del Pleno con resultado de empate:','["Se efectúa una nueva votación y, si persiste el empate, decide el voto de calidad del Presidente", "Decide directamente el voto de calidad del Presidente, sin nueva votación", "Se entiende rechazada la propuesta y no puede volver a votarse en esa sesión"]'::jsonb,0,'Art. 46.2 d) LBRL','El art. 46.2 d) prevé una nueva votación y, si persiste el empate, el voto de calidad del Presidente.',null),
('aux-ayto-mad:5-3dc3927bbe','aux-ayto-mad',5,'La ausencia de uno o varios Concejales, una vez iniciada la deliberación de un asunto, equivale a efectos de la votación a:','["La abstención", "El voto en contra", "El voto a favor"]'::jsonb,0,'Art. 46.2 d) LBRL','Según el art. 46.2 d), la ausencia una vez iniciada la deliberación equivale a la abstención.',null),
('aux-ayto-mad:5-982e8834ba','aux-ayto-mad',5,'Como regla general, los acuerdos de las corporaciones locales se adoptan por:','["Mayoría simple de los miembros presentes", "Mayoría simple del número legal de miembros", "Mayoría absoluta del número legal de miembros"]'::jsonb,0,'Art. 47.1 LBRL','Hay mayoría simple cuando los votos afirmativos son más que los negativos.',null),
('aux-ayto-mad:5-754ad6d531','aux-ayto-mad',5,'En el régimen común, la cesión gratuita de bienes a otras Administraciones o instituciones públicas requiere el voto favorable de:','["Los dos tercios del número legal de miembros de la corporación", "La mayoría absoluta del número legal de miembros de la corporación", "La mayoría simple de los miembros presentes en la sesión"]'::jsonb,1,'Art. 47.2 ñ) LBRL','Es una de las materias del art. 47.2 que requieren mayoría absoluta. En los municipios de gran población, como Madrid, se aplican las reglas propias del art. 123.2.',null),
('aux-ayto-mad:5-c520c83988','aux-ayto-mad',5,'Las normas sobre adopción de acuerdos de los municipios de gran población se contienen en:','["El artículo 123.2 de la Ley 7/1985", "El reglamento orgánico de cada municipio", "El artículo 47.2 de la Ley 7/1985"]'::jsonb,0,'Art. 47.3 LBRL','Según el art. 47.3, para los municipios del art. 121 se aplica el art. 123.2.',null),
('aux-ayto-mad:5-3390cd841d','aux-ayto-mad',5,'Los conflictos de atribuciones entre órganos de una misma Corporación local que afecten a órganos colegiados se resuelven por:','["El Pleno", "El Alcalde", "La Comunidad Autónoma"]'::jsonb,0,'Art. 50.1 LBRL','Los resuelve el Pleno cuando afectan a órganos colegiados, a sus miembros o a entidades del art. 45; en el resto de supuestos, el Alcalde o Presidente.',null),
('aux-ayto-mad:5-eb9079ee91','aux-ayto-mad',5,'Según la Ley 7/1985, los actos de las entidades locales son:','["Ejecutivos cuando pasan quince días hábiles sin requerimiento del Estado o de la Comunidad Autónoma", "Inmediatamente ejecutivos, salvo que una disposición legal establezca lo contrario o se suspenda su eficacia", "Ejecutivos cuando se publican en el boletín oficial de la Comunidad Autónoma"]'::jsonb,1,'Art. 51 LBRL','El art. 51 establece la ejecutividad inmediata, salvo disposición legal en contrario o suspensión de su eficacia.',null),
('aux-ayto-mad:5-3cf44e53f7','aux-ayto-mad',5,'Contra los actos de las entidades locales que pongan fin a la vía administrativa, con carácter previo a la vía jurisdiccional cabe:','["Recurso obligatorio de alzada", "Reclamación previa ante la Comunidad Autónoma", "Recurso potestativo de reposición"]'::jsonb,2,'Art. 52.1 LBRL','Los interesados pueden interponer con carácter previo y potestativo recurso de reposición.',null),
('aux-ayto-mad:5-046e02d870','aux-ayto-mad',5,'Ponen fin a la vía administrativa, en el régimen común, las resoluciones de:','["Solo el Pleno, cualquiera que sea el asunto", "El Pleno, los Alcaldes o Presidentes y las Juntas de Gobierno", "El Pleno y las Comisiones informativas, en las materias delegadas"]'::jsonb,1,'Art. 52.2 a) LBRL','Ponen fin a la vía administrativa las resoluciones del Pleno, de los Alcaldes o Presidentes y de las Juntas de Gobierno, salvo excepciones, y las de los órganos inferiores que resuelvan por delegación.',null),
('aux-ayto-mad:5-c3ae812465','aux-ayto-mad',5,'Cuando el Estado o la Comunidad Autónoma consideren que un acto de una entidad local infringe el ordenamiento jurídico, pueden requerirla para que lo anule en el plazo máximo de:','["Quince días hábiles", "Diez días", "Un mes"]'::jsonb,2,'Art. 65.1 LBRL','El requerimiento pide la anulación en el plazo máximo de un mes, y debe formularse dentro de los quince días hábiles siguientes a la recepción de la comunicación del acuerdo (art. 65.2).',null),
('aux-ayto-mad:5-35202ff923','aux-ayto-mad',5,'El requerimiento de anulación del artículo 65 de la Ley 7/1985 deberá formularse en el plazo de:','["Quince días hábiles desde la recepción de la comunicación del acuerdo", "Un mes desde la fecha de adopción del acuerdo por la entidad local", "Dos meses desde la publicación del acuerdo en el boletín oficial"]'::jsonb,0,'Art. 65.2 LBRL','Según el art. 65.2, debe ser motivado y formularse en el plazo de quince días hábiles desde la recepción de la comunicación del acuerdo.',null),
('aux-ayto-mad:5-8a62cca0dd','aux-ayto-mad',5,'Si una entidad local adopta actos que atenten gravemente al interés general de España, podrá suspenderlos, previo requerimiento al Presidente de la Corporación:','["El Presidente de la Comunidad Autónoma", "El Consejo de Ministros", "El Delegado del Gobierno"]'::jsonb,2,'Art. 67.1 LBRL','El Delegado del Gobierno puede suspenderlos tras requerir su anulación; después debe impugnarlos ante la jurisdicción contencioso-administrativa en diez días (art. 67.3).',null),
('aux-ayto-mad:5-7d4753cb1a','aux-ayto-mad',5,'Acordada la suspensión de un acto local por atentar gravemente al interés general de España, el Delegado del Gobierno deberá impugnarlo ante la jurisdicción contencioso-administrativa en el plazo de:','["Dos meses desde la suspensión", "Cinco días desde la suspensión", "Diez días desde la suspensión"]'::jsonb,2,'Art. 67.3 LBRL','Según el art. 67.3, deberá impugnarlo en el plazo de diez días desde la suspensión.',null),
('aux-ayto-mad:5-b1f7c3acaa','aux-ayto-mad',5,'Además de los legitimados en el régimen general, pueden impugnar los acuerdos de las entidades locales que infrinjan el ordenamiento jurídico:','["Los vecinos empadronados, sin necesidad de interés legítimo", "Los miembros de las corporaciones que se hubieran abstenido", "Los miembros de las corporaciones que hubieran votado en contra"]'::jsonb,2,'Art. 63.1 b) LBRL','El art. 63.1 legitima a la Administración del Estado y a la de las CCAA y a los miembros de las corporaciones que votaron en contra.',null),
('aux-ayto-mad:5-6048b11b04','aux-ayto-mad',5,'El requerimiento de un vecino para que la entidad local ejerza acciones en defensa de sus bienes suspende el plazo para ejercerlas por un término de:','["Dos meses", "Quince días hábiles", "Treinta días hábiles"]'::jsonb,2,'Art. 68.2 LBRL','Si en esos treinta días la entidad no ejerce las acciones, los vecinos pueden ejercerlas en nombre e interés de la entidad (art. 68.3).',null),
('aux-ayto-mad:5-e880e03a99','aux-ayto-mad',5,'Según la Ley 7/1985, las sesiones de la Junta de Gobierno Local:','["Son públicas", "Son públicas cuando traten asuntos delegados por el Pleno", "No son públicas"]'::jsonb,2,'Art. 70.1 LBRL','El art. 70.1 dice que no son públicas las sesiones de la Junta de Gobierno Local, a diferencia de las del Pleno.',null),
('aux-ayto-mad:5-9968b5c6a7','aux-ayto-mad',5,'En un municipio de más de 20.000 habitantes, las iniciativas populares deben ir suscritas al menos por el siguiente porcentaje de vecinos:','["El 10 por ciento", "El 20 por ciento", "El 15 por ciento"]'::jsonb,0,'Art. 70 bis.2 LBRL','El porcentaje es del 20 % hasta 5.000 habitantes, del 15 % de 5.001 a 20.000 y del 10 % a partir de 20.001.',null),
('aux-ayto-mad:5-9cde77fdf8','aux-ayto-mad',5,'Para someter a consulta popular asuntos de la competencia propia municipal, el Alcalde necesita acuerdo del Pleno por mayoría absoluta y autorización:','["Del Consejo de Gobierno de la Comunidad Autónoma", "Del Gobierno de la Nación", "De las Cortes Generales"]'::jsonb,1,'Art. 71 LBRL','El art. 71 exige acuerdo del Pleno por mayoría absoluta y autorización del Gobierno de la Nación. Quedan excluidos los asuntos de la Hacienda local.',null),
('aux-ayto-mad:5-be6615c986','aux-ayto-mad',5,'Los miembros de las corporaciones locales que no se integren en el grupo político de la formación por la que fueron elegidos o que abandonen su grupo tienen la consideración de:','["Miembros no adscritos", "Concejales independientes", "Grupo mixto"]'::jsonb,0,'Art. 73.3 LBRL','Tienen la consideración de miembros no adscritos, y sus derechos económicos y políticos no pueden superar los que tendrían en su grupo de procedencia.',null),
('aux-ayto-mad:5-4396d44cef','aux-ayto-mad',5,'Los miembros de las corporaciones locales que sean funcionarios de la propia Corporación para la que han sido elegidos quedan en situación de:','["Servicio activo con dispensa de funciones", "Servicios especiales", "Excedencia voluntaria"]'::jsonb,1,'Art. 74.1 a) LBRL','Quedan en servicios especiales los funcionarios de la propia corporación y los de otras administraciones que desempeñen en ella un cargo retribuido con dedicación exclusiva.',null),
('aux-ayto-mad:5-529bb33d74','aux-ayto-mad',5,'Las normas del título X de la Ley 7/1985 (municipios de gran población) se aplican, sin necesidad de decisión de la Asamblea Legislativa, a los municipios cuya población supere los:','["75.000 habitantes", "175.000 habitantes", "250.000 habitantes"]'::jsonb,2,'Art. 121.1 a) LBRL','Se aplican directamente a los de más de 250.000 habitantes y a las capitales de provincia de más de 175.000. Las capitales de provincia o autonómicas y los de más de 75.000 con circunstancias especiales necesitan decisión de la Asamblea Legislativa a iniciativa del ayuntamiento.',null),
('aux-ayto-mad:5-fe62d78a77','aux-ayto-mad',5,'Un municipio que sea capital autonómica queda incluido en el régimen de gran población cuando:','["Lo apruebe el Gobierno de la Nación mediante real decreto", "Así lo decida la Asamblea Legislativa correspondiente a iniciativa del ayuntamiento", "Lo acuerde su Pleno por mayoría absoluta del número legal de miembros"]'::jsonb,1,'Art. 121.1 LBRL','En los supuestos de los párrafos c) y d) del art. 121.1 se exige que así lo decidan las Asambleas Legislativas a iniciativa de los ayuntamientos.',null),
('aux-ayto-mad:5-8d92fff984','aux-ayto-mad',5,'Si la población oficial de un municipio de gran población baja después del límite legal:','["Vuelve al régimen común si así lo acuerda el Pleno", "Vuelve al régimen común al inicio del siguiente mandato", "Continúa rigiéndose por el régimen de gran población"]'::jsonb,2,'Art. 121.3 LBRL','Según el art. 121.3, continuará rigiéndose por ese régimen aunque su cifra oficial de población se reduzca después.',null),
('aux-ayto-mad:5-73e064c576','aux-ayto-mad',5,'En los municipios de gran población, el Alcalde podrá delegar exclusivamente la convocatoria y la presidencia del Pleno en:','["El Secretario General del Pleno", "Uno de los concejales", "Un miembro no electo de la Junta de Gobierno Local"]'::jsonb,1,'Art. 122.2 LBRL','El art. 122.2 permite al Alcalde delegar exclusivamente la convocatoria y la presidencia del Pleno en uno de los concejales.',null),
('aux-ayto-mad:5-5ce5f4c1a6','aux-ayto-mad',5,'En los municipios de gran población, el asesoramiento legal del Secretario General del Pleno es preceptivo, entre otros casos:','["Siempre que se trate de asuntos sobre materias para las que se exija una mayoría especial", "En todos los asuntos que se debatan en el Pleno", "Siempre que lo solicite cualquier concejal antes del inicio de la sesión"]'::jsonb,0,'Art. 122.5 e) LBRL','Es preceptivo cuando lo ordene el Presidente o lo pida un tercio de los miembros, en materias de mayoría especial, cuando lo exija una ley y, en la función de control, cuando lo pida el Presidente o una cuarta parte de los Concejales.',null),
('aux-ayto-mad:5-cafcef9f62','aux-ayto-mad',5,'En los municipios de gran población tiene en todo caso naturaleza orgánica la regulación de:','["Los precios públicos", "El Consejo Social de la ciudad", "Las tasas por prestación de servicios"]'::jsonb,1,'Art. 123.1 c) LBRL','Tienen naturaleza orgánica, entre otras, la regulación del Pleno, del Consejo Social, de la Comisión Especial de Sugerencias y Reclamaciones, de la participación ciudadana, de los distritos, de los niveles esenciales de la organización y del órgano económico-administrativo.',null),
('aux-ayto-mad:5-2ca8de72c3','aux-ayto-mad',5,'En los municipios de gran población, el Alcalde tiene el tratamiento de:','["Señoría", "Ilustrísima", "Excelencia"]'::jsonb,2,'Art. 124.3 LBRL','El Alcalde tiene el tratamiento de Excelencia (art. 124.3) y los Tenientes de Alcalde el de Ilustrísima (art. 125.2).',null),
('aux-ayto-mad:5-e5bbe37779','aux-ayto-mad',5,'En los municipios de gran población, los Tenientes de Alcalde tienen el tratamiento de:','["Excelencia", "Ilustrísima", "Señoría"]'::jsonb,1,'Art. 125.2 LBRL','Según el art. 125.2, los Tenientes de Alcalde tendrán el tratamiento de Ilustrísima.',null),
('aux-ayto-mad:5-027c42f798','aux-ayto-mad',5,'En los municipios de gran población, para la válida constitución de la Junta de Gobierno Local se requiere que:','["Los miembros concejales presentes sean más que los miembros presentes que no son concejales", "Estén presentes todos sus miembros que tengan la condición de concejal", "Asista el Secretario General del Pleno o quien legalmente lo sustituya"]'::jsonb,0,'Art. 126.2 LBRL','El art. 126.2 exige que el número de miembros concejales presentes sea superior al de los presentes que no tienen esa condición.',null),
('aux-ayto-mad:5-25aa7e81d5','aux-ayto-mad',5,'En los municipios de gran población, el titular del órgano de apoyo a la Junta de Gobierno Local y al concejal-secretario se nombra entre:','["Los miembros no electos de la Junta de Gobierno Local", "Funcionarios de carrera de la propia corporación del subgrupo A2", "Funcionarios de Administración local con habilitación de carácter nacional"]'::jsonb,2,'Art. 126.4 LBRL','Según el art. 126.4, su titular se nombra entre funcionarios de Administración local con habilitación de carácter nacional.',null),
('aux-ayto-mad:5-c40279e6d2','aux-ayto-mad',5,'En los municipios de gran población, la composición de los tribunales de oposiciones será:','["Predominantemente técnica, con todos sus miembros con titulación igual o superior a la exigida", "Paritaria entre representantes políticos de la corporación y personal técnico", "Determinada por los sindicatos más representativos del ayuntamiento"]'::jsonb,0,'Art. 127.1 h) LBRL','Debe ser predominantemente técnica y todos sus miembros deben tener una titulación igual o superior a la exigida para las plazas.',null),
('aux-ayto-mad:5-cc6582906b','aux-ayto-mad',5,'El Consejo Social de la Ciudad de los municipios de gran población está integrado por:','["Los Concejales Presidentes de los distritos", "Representantes de las organizaciones económicas, sociales, profesionales y de vecinos más representativas", "Los portavoces de los grupos políticos municipales y el Alcalde, que lo preside"]'::jsonb,1,'Art. 131.1 LBRL','Le corresponden, además de lo que determine el Pleno, informes, estudios y propuestas sobre desarrollo económico local, planificación estratégica y grandes proyectos urbanos.',null),
('aux-ayto-mad:5-c45f9dbf56','aux-ayto-mad',5,'Según el artículo 133 de la Ley 7/1985, la gestión económico-financiera de los municipios de gran población se ajustará, entre otros, al criterio de:','["Fiscalización previa por el Tribunal de Cuentas", "Separación de las funciones de contabilidad y de fiscalización", "Unidad de caja entre el Ayuntamiento y sus sociedades mercantiles"]'::jsonb,1,'Art. 133 b) LBRL','El art. 133 cita, entre otros, la estabilidad presupuestaria, la separación de contabilidad y fiscalización, el seguimiento de costes y la asignación de recursos por objetivos.',null),
('aux-ayto-mad:5-e0be6fe49d','aux-ayto-mad',5,'En los municipios de gran población, el titular del órgano que desarrolle las funciones de presupuestación:','["Debe ser el interventor general municipal", "Debe ser en todo caso funcionario con habilitación de carácter nacional", "No tiene que ser funcionario con habilitación de carácter nacional"]'::jsonb,2,'Art. 134.2 LBRL','Los titulares de los órganos de gestión económico-financiera deben ser funcionarios con habilitación de carácter nacional, salvo el del órgano que desarrolle las funciones de presupuestación.',null),
('aux-ayto-mad:5-1324a8cd47','aux-ayto-mad',5,'La función de control y fiscalización interna en los municipios de gran población, en su triple acepción de función interventora, control financiero y control de eficacia, corresponde a:','["La Comisión Especial de Cuentas", "El órgano de gestión tributaria", "La Intervención general municipal"]'::jsonb,2,'Art. 136.1 LBRL','Corresponde a la Intervención general municipal, que actúa con plena autonomía y cuyo titular es un funcionario con habilitación de carácter nacional.',null),
('aux-ayto-mad:5-5efcf35752','aux-ayto-mad',5,'En el seno de la Conferencia sectorial para asuntos locales existe una Conferencia de ciudades de la que forman parte la AGE, las comunidades autónomas y:','["Los alcaldes de las capitales de provincia", "Los alcaldes de los municipios del título X de la Ley 7/1985", "Los presidentes de las diputaciones provinciales"]'::jsonb,1,'Art. 138 LBRL','Según el art. 138, forman parte de ella la Administración General del Estado, las comunidades autónomas y los alcaldes de los municipios de gran población.',null),
('aux-ayto-mad:5-10de71f658','aux-ayto-mad',5,'En los municipios de gran población, únicamente pueden delegarse en las comisiones del Pleno sus competencias sobre:','["Ordenanzas y reglamentos, formas de gestión de los servicios, acciones judiciales y conflictos de competencia", "Reglamentos orgánicos y moción de censura", "Presupuestos, plantilla de personal, cuenta general y planeamiento general"]'::jsonb,0,'Art. 123.3 LBRL','El art. 123.3 solo permite delegar las competencias de los párrafos d), k), m) y ñ) en las comisiones del Pleno.',null),
('aux-ayto-mad:6-90c447c37c','aux-ayto-mad',6,'Según el TRLRHL, ¿cuál de los siguientes impuestos es de exigencia obligatoria para los ayuntamientos?','["El Impuesto sobre Construcciones, Instalaciones y Obras", "El Impuesto sobre Vehículos de Tracción Mecánica", "El Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana"]'::jsonb,1,'Art. 59 TRLRHL','Son obligatorios el IBI, el IAE y el IVTM (art. 59.1). El ICIO y el IIVTNU son potestativos: los ayuntamientos podrán establecerlos (art. 59.2).',null),
('aux-ayto-mad:6-9f578171e4','aux-ayto-mad',6,'Según el TRLRHL, los ayuntamientos podrán establecer y exigir, con carácter potestativo:','["El Impuesto sobre Actividades Económicas, el Impuesto sobre Vehículos de Tracción Mecánica y el Impuesto sobre Bienes Inmuebles", "El Impuesto sobre Bienes Inmuebles y el Impuesto sobre Actividades Económicas", "El Impuesto sobre Construcciones, Instalaciones y Obras y el Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana"]'::jsonb,2,'Art. 59.2 TRLRHL','El art. 59.2 prevé que los ayuntamientos podrán establecer el ICIO y el IIVTNU de acuerdo con la ley y sus ordenanzas fiscales.',null),
('aux-ayto-mad:6-81f2a9b1c7','aux-ayto-mad',6,'El Impuesto sobre Bienes Inmuebles es, según el TRLRHL:','["Un tributo directo de carácter personal que grava el patrimonio inmobiliario", "Un tributo indirecto que grava la transmisión de los bienes inmuebles", "Un tributo directo de carácter real que grava el valor de los bienes inmuebles"]'::jsonb,2,'Art. 60 TRLRHL','Así lo define el art. 60.',null),
('aux-ayto-mad:6-eb98993a6b','aux-ayto-mad',6,'Si sobre un inmueble urbano concurren un derecho real de usufructo y el derecho de propiedad, el hecho imponible del IBI lo realiza:','["El propietario", "Ambos, cada uno por su parte", "El titular del usufructo"]'::jsonb,2,'Art. 61.2 TRLRHL','El hecho imponible se realiza por el orden del art. 61.1 (concesión, superficie, usufructo, propiedad), y el primero que concurre determina la no sujeción por los siguientes.',null),
('aux-ayto-mad:6-8aad3d36a9','aux-ayto-mad',6,'¿Cuál es el orden de prelación de los derechos que constituyen el hecho imponible del IBI?','["Propiedad, usufructo, derecho de superficie y concesión administrativa", "Concesión administrativa, derecho de superficie, usufructo y propiedad", "Usufructo, propiedad, concesión administrativa y derecho de superficie"]'::jsonb,1,'Art. 61.1 y 2 TRLRHL','El art. 61.1 enumera la concesión, el derecho de superficie, el usufructo y la propiedad, y el art. 61.2 dispone que se siga ese orden.',null),
('aux-ayto-mad:6-b2af52eab9','aux-ayto-mad',6,'¿Cuál de los siguientes bienes NO está sujeto al IBI?','["Las carreteras y caminos de aprovechamiento público y gratuito", "Los inmuebles de la Cruz Roja Española destinados a sus fines propios", "Los bienes comunales y los montes vecinales en mano común"]'::jsonb,0,'Art. 61.5 a) TRLRHL','Las vías de aprovechamiento público y gratuito no están sujetas (art. 61.5). Los inmuebles de la Cruz Roja y los bienes comunales están sujetos pero exentos (art. 62.1).',null),
('aux-ayto-mad:6-8779df6293','aux-ayto-mad',6,'Están exentos del IBI, sin necesidad de solicitud, los inmuebles:','["Declarados monumento histórico de interés cultural", "Destinados a la enseñanza concertada", "De la Cruz Roja Española"]'::jsonb,2,'Art. 62.1 d) TRLRHL','La exención de la Cruz Roja es automática (art. 62.1). Las de los centros concertados y los monumentos de interés cultural requieren solicitud previa (art. 62.2).',null),
('aux-ayto-mad:6-a479d7dcc2','aux-ayto-mad',6,'La exención del IBI de la superficie de montes con repoblaciones forestales sujetas a proyectos aprobados tiene una duración de:','["15 años", "10 años", "25 años"]'::jsonb,0,'Art. 62.2 c) TRLRHL','Según el art. 62.2 c), dura 15 años desde el período impositivo siguiente a su solicitud.',null),
('aux-ayto-mad:6-6217fe0f05','aux-ayto-mad',6,'El tipo de gravamen mínimo y supletorio del IBI para los bienes inmuebles urbanos es:','["El 0,3 por ciento", "El 0,4 por ciento", "El 0,6 por ciento"]'::jsonb,1,'Art. 72.1 TRLRHL','El tipo mínimo y supletorio es el 0,4 % para urbanos y el 0,3 % para rústicos; el máximo, el 1,10 % para urbanos y el 0,90 % para rústicos.',null),
('aux-ayto-mad:6-2177bddacb','aux-ayto-mad',6,'El tipo de gravamen máximo del IBI para los bienes inmuebles urbanos, sin incrementos, es:','["El 1,10 por ciento", "El 1,30 por ciento", "El 0,90 por ciento"]'::jsonb,0,'Art. 72.1 TRLRHL','Según el art. 72.1, el máximo es el 1,10 % para los urbanos y el 0,90 % para los rústicos.',null),
('aux-ayto-mad:6-a7c5501c43','aux-ayto-mad',6,'El tipo de gravamen supletorio del IBI para los bienes inmuebles de características especiales es:','["El 1,3 por ciento", "El 0,6 por ciento", "El 0,4 por ciento"]'::jsonb,1,'Art. 72.2 TRLRHL','Es el 0,6 %, y los ayuntamientos pueden fijar para cada grupo un tipo entre el 0,4 % y el 1,3 %.',null),
('aux-ayto-mad:6-f180429ef6','aux-ayto-mad',6,'Las viviendas de protección oficial tienen derecho a una bonificación en la cuota íntegra del IBI durante los tres períodos impositivos siguientes al de su calificación definitiva del:','["95 por ciento", "50 por ciento", "90 por ciento"]'::jsonb,1,'Art. 73.2 TRLRHL','Es una bonificación obligatoria del 50 % durante tres períodos impositivos, a petición del interesado.',null),
('aux-ayto-mad:6-803661b448','aux-ayto-mad',6,'La bonificación obligatoria del IBI para los inmuebles de empresas de urbanización, construcción y promoción inmobiliaria que no figuren en su inmovilizado es:','["Del 50 por ciento, durante dos períodos impositivos", "Del 95 por ciento, durante cinco períodos impositivos desde el inicio de las obras", "De entre el 50 y el 90 por ciento, durante un máximo de tres períodos impositivos"]'::jsonb,2,'Art. 73.1 TRLRHL','Debe solicitarse antes del inicio de las obras y en ningún caso puede exceder de tres períodos impositivos.',null),
('aux-ayto-mad:6-c5864bd5da','aux-ayto-mad',6,'Las ordenanzas fiscales podrán regular una bonificación en la cuota íntegra del IBI a favor de los titulares de familia numerosa de hasta el:','["50 por ciento", "90 por ciento", "95 por ciento"]'::jsonb,1,'Art. 74.4 TRLRHL','Según el art. 74.4, puede ser de hasta el 90 % de la cuota íntegra.',null),
('aux-ayto-mad:6-2a6af6d8c2','aux-ayto-mad',6,'La bonificación potestativa del IBI para los inmuebles en los que se hayan instalado sistemas de aprovechamiento de la energía solar puede ser de hasta el:','["50 por ciento", "90 por ciento", "95 por ciento"]'::jsonb,0,'Art. 74.5 TRLRHL','Según el art. 74.5, hasta el 50 %, condicionada a la homologación de las instalaciones.',null),
('aux-ayto-mad:6-a3e647bbf3','aux-ayto-mad',6,'Según el TRLRHL, el IBI se devenga:','["El primer día del período impositivo, que coincide con el año natural", "El último día del año natural al que se refiere la liquidación", "El día en que se notifica el nuevo valor catastral"]'::jsonb,0,'Art. 75 TRLRHL','El impuesto se devenga el primer día del período impositivo, que coincide con el año natural.',null),
('aux-ayto-mad:6-3d505b8d08','aux-ayto-mad',6,'El hecho imponible del Impuesto sobre Actividades Económicas está constituido por:','["La obtención de rendimientos de actividades económicas en el término municipal", "La apertura de un local de negocio en el término municipal en que se ejerza la actividad", "El mero ejercicio en territorio nacional de actividades empresariales, profesionales o artísticas, en local determinado o no"]'::jsonb,2,'Art. 78.1 TRLRHL','El IAE es un tributo directo de carácter real que grava el mero ejercicio de esas actividades, estén o no especificadas en las tarifas.',null),
('aux-ayto-mad:6-7d44771406','aux-ayto-mad',6,'¿Cuál de las siguientes actividades NO constituye hecho imponible del IAE?','["Las actividades mineras", "Las actividades agrícolas", "La ganadería independiente"]'::jsonb,1,'Art. 78.2 TRLRHL','No son actividades empresariales a efectos del IAE las agrícolas, las ganaderas dependientes, las forestales y las pesqueras.',null),
('aux-ayto-mad:6-a87f27ee38','aux-ayto-mad',6,'A efectos del IAE, una actividad se ejerce con carácter empresarial, profesional o artístico cuando supone:','["La ordenación por cuenta propia de medios de producción y de recursos humanos, o de uno de ambos, para intervenir en la producción o distribución de bienes o servicios", "La obtención de ingresos superiores al salario mínimo interprofesional por la actividad desarrollada", "El alta en el régimen de trabajadores autónomos de la Seguridad Social"]'::jsonb,0,'Art. 79.1 TRLRHL','Así lo define el art. 79.1.',null),
('aux-ayto-mad:6-ed7f3a28f1','aux-ayto-mad',6,'¿Están exentas del IAE las personas físicas?','["No, solo están exentas durante los dos primeros períodos impositivos en que desarrollen la actividad", "Sí, todas las personas físicas, sean o no residentes en territorio español", "Solo si su cifra de negocios es inferior a 1.000.000 de euros"]'::jsonb,1,'Art. 82.1 c) TRLRHL','El art. 82.1 c) declara exentas a las personas físicas, sean o no residentes, sin límite de cifra de negocios.',null),
('aux-ayto-mad:6-f19eba4cde','aux-ayto-mad',6,'Están exentos del IAE los sujetos pasivos del Impuesto sobre Sociedades que tengan un importe neto de la cifra de negocios inferior a:','["2.000.000 de euros", "600.000 euros", "1.000.000 de euros"]'::jsonb,2,'Art. 82.1 c) TRLRHL','Según el art. 82.1 c), la exención alcanza a las sociedades y entidades con un importe neto de la cifra de negocios inferior a 1.000.000 de euros.',null),
('aux-ayto-mad:6-0efbb336c0','aux-ayto-mad',6,'Los sujetos pasivos que inicien el ejercicio de su actividad en territorio español están exentos del IAE:','["Durante los dos primeros períodos impositivos en que se desarrolle aquella", "Durante el primer período impositivo en que se desarrolle aquella", "Durante los tres primeros períodos impositivos"]'::jsonb,0,'Art. 82.1 b) TRLRHL','No hay inicio de actividad si esta se ejercía antes bajo otra titularidad (fusión, escisión o aportación de ramas de actividad).',null),
('aux-ayto-mad:6-161d02a142','aux-ayto-mad',6,'El Impuesto sobre Vehículos de Tracción Mecánica grava:','["La titularidad de los vehículos de tracción mecánica aptos para circular por las vías públicas", "La circulación efectiva de los vehículos por las vías urbanas del municipio", "La matriculación de vehículos nuevos en el municipio"]'::jsonb,0,'Art. 92.1 TRLRHL','Es un tributo directo que grava la titularidad de los vehículos aptos para circular, cualquiera que sea su clase y categoría.',null),
('aux-ayto-mad:6-c07d8c2d2b','aux-ayto-mad',6,'A efectos del IVTM, se considera vehículo apto para la circulación:','["El matriculado en los registros públicos correspondientes, mientras no haya causado baja en ellos", "El que tenga contratado el seguro obligatorio", "El que tenga en vigor la inspección técnica de vehículos y el seguro obligatorio"]'::jsonb,0,'Art. 92.2 TRLRHL','También se consideran aptos los vehículos con permisos temporales y matrícula turística.',null),
('aux-ayto-mad:6-0609e5e0fb','aux-ayto-mad',6,'No están sujetos al IVTM los remolques y semirremolques arrastrados por vehículos de tracción mecánica cuya carga útil no sea superior a:','["1.000 kilogramos", "500 kilogramos", "750 kilogramos"]'::jsonb,2,'Art. 92.3 b) TRLRHL','Según el art. 92.3 b), no están sujetos los remolques y semirremolques de carga útil no superior a 750 kilogramos.',null),
('aux-ayto-mad:6-e050150255','aux-ayto-mad',6,'La exención del IVTM para vehículos matriculados a nombre de personas con discapacidad para su uso exclusivo exige un grado de discapacidad:','["Igual o superior al 33 por ciento", "Igual o superior al 65 por ciento", "Igual o superior al 45 por ciento"]'::jsonb,0,'Art. 93.1 e) TRLRHL','El grado debe ser igual o superior al 33 %, y la exención no puede aplicarse a más de un vehículo simultáneamente.',null),
('aux-ayto-mad:6-47b7e3623e','aux-ayto-mad',6,'Están exentos del IVTM los autobuses destinados al transporte público urbano siempre que tengan una capacidad que exceda de:','["Nueve plazas, excluida la del conductor", "Doce plazas, incluida la del conductor", "Nueve plazas, incluida la del conductor"]'::jsonb,2,'Art. 93.1 f) TRLRHL','Según el art. 93.1 f), deben tener una capacidad que exceda de nueve plazas, incluida la del conductor.',null),
('aux-ayto-mad:6-cc7e6e01c8','aux-ayto-mad',6,'Son sujetos pasivos del IVTM las personas o entidades:','["Que conduzcan habitualmente el vehículo, aunque no figuren como titulares", "A cuyo nombre conste el vehículo en el permiso de circulación", "Que tengan contratado el seguro del vehículo"]'::jsonb,1,'Art. 94 TRLRHL','Así lo establece el art. 94.',null),
('aux-ayto-mad:6-5021398d60','aux-ayto-mad',6,'Los ayuntamientos pueden incrementar las cuotas del cuadro de tarifas del IVTM mediante un coeficiente que no podrá ser superior a:','["2", "1,5", "3"]'::jsonb,0,'Art. 95.4 TRLRHL','El coeficiente no puede superar 2, y puede ser distinto por clase de vehículo y por tramo.',null),
('aux-ayto-mad:6-23e244e204','aux-ayto-mad',6,'Las ordenanzas fiscales pueden regular en el IVTM una bonificación para los vehículos históricos o con una antigüedad mínima de veinticinco años de hasta el:','["100 por cien", "75 por ciento", "50 por ciento"]'::jsonb,0,'Art. 95.6 c) TRLRHL','El art. 95.6 c) permite una bonificación de hasta el 100 %; las bonificaciones por carburante o por motor pueden llegar al 75 %.',null),
('aux-ayto-mad:6-abc386a358','aux-ayto-mad',6,'En el IVTM, en caso de primera adquisición de un vehículo, el período impositivo:','["Coincide en todo caso con el año natural", "Comienza el 1 de enero del año siguiente al de la adquisición", "Comienza el día en que se produce la adquisición"]'::jsonb,2,'Art. 96.1 TRLRHL','El período coincide con el año natural salvo en la primera adquisición, en que comienza el día de la adquisición.',null),
('aux-ayto-mad:6-0e41371a81','aux-ayto-mad',6,'En el IVTM, el importe de la cuota se prorrateará en los casos de primera adquisición o baja definitiva del vehículo:','["Por trimestres naturales", "Por meses naturales", "Por días"]'::jsonb,0,'Art. 96.3 TRLRHL','Según el art. 96.3, se prorratea por trimestres naturales, también en la baja temporal por sustracción o robo.',null),
('aux-ayto-mad:6-be2f5c9fa6','aux-ayto-mad',6,'La gestión, liquidación, inspección y recaudación del IVTM corresponde:','["Al ayuntamiento del domicilio que conste en el permiso de circulación del vehículo", "Al ayuntamiento del domicilio fiscal del titular del vehículo", "A la Jefatura Provincial de Tráfico de la provincia de matriculación"]'::jsonb,0,'Art. 97 TRLRHL','Así lo establece el art. 97.',null),
('aux-ayto-mad:6-8b0c44993e','aux-ayto-mad',6,'El Impuesto sobre Construcciones, Instalaciones y Obras es:','["Un tributo indirecto", "Un tributo directo de carácter real", "Una tasa por el otorgamiento de la licencia urbanística"]'::jsonb,0,'Art. 100.1 TRLRHL','El ICIO es un tributo indirecto que grava la realización de construcciones, instalaciones u obras que exijan licencia, declaración responsable o comunicación previa, se hayan obtenido o presentado o no.',null),
('aux-ayto-mad:6-dea85650a3','aux-ayto-mad',6,'Es sujeto pasivo contribuyente del ICIO:','["El dueño de la construcción, instalación u obra, sea o no propietario del inmueble", "El contratista que ejecuta la obra", "El propietario del inmueble en todo caso, aunque no soporte el coste de la obra"]'::jsonb,0,'Art. 101.1 TRLRHL','Es dueño quien soporta los gastos o el coste de la obra. Si no la realiza él, son sustitutos quienes solicitan la licencia o realizan la obra (art. 101.2).',null),
('aux-ayto-mad:6-2de251b43e','aux-ayto-mad',6,'La base imponible del ICIO está constituida por:','["El presupuesto total de la obra, incluidos el IVA, las tasas y los honorarios profesionales", "El coste real y efectivo de la construcción, instalación u obra, entendido como su coste de ejecución material", "El valor catastral del inmueble una vez terminada la obra"]'::jsonb,1,'Art. 102.1 TRLRHL','No forman parte de ella el IVA, las tasas y precios públicos, los honorarios profesionales ni el beneficio empresarial del contratista.',null),
('aux-ayto-mad:6-f10070a943','aux-ayto-mad',6,'El tipo de gravamen del ICIO lo fija cada ayuntamiento, sin que pueda exceder del:','["3 por cien", "5 por cien", "4 por cien"]'::jsonb,2,'Art. 102.3 TRLRHL','Según el art. 102.3, el tipo no puede exceder del cuatro por cien.',null),
('aux-ayto-mad:6-8470c882b5','aux-ayto-mad',6,'El ICIO se devenga:','["Cuando termina la construcción, instalación u obra", "Cuando se concede la licencia de obras o se presenta la declaración responsable", "En el momento de iniciarse la construcción, instalación u obra, aun cuando no se haya obtenido la licencia"]'::jsonb,2,'Art. 102.4 TRLRHL','Así lo establece el art. 102.4.',null),
('aux-ayto-mad:6-5e91f33e49','aux-ayto-mad',6,'Las ordenanzas fiscales pueden regular una bonificación en el ICIO de hasta el 95 % para las obras declaradas de especial interés o utilidad municipal. Esa declaración corresponde:','["Al Alcalde", "Al Pleno de la Corporación", "A la Junta de Gobierno"]'::jsonb,1,'Art. 103.2 a) TRLRHL','La declaración corresponde al Pleno, previa solicitud del sujeto pasivo.',null),
('aux-ayto-mad:6-b96393522a','aux-ayto-mad',6,'El Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana grava el incremento de valor que se ponga de manifiesto a consecuencia de:','["La transmisión de la propiedad de los terrenos por cualquier título o la constitución o transmisión de derechos reales de goce limitativos del dominio", "La revisión catastral de los valores de los terrenos", "La recalificación urbanística de los terrenos aprobada por el planeamiento municipal"]'::jsonb,0,'Art. 104.1 TRLRHL','El IIVTNU es un tributo directo que grava ese incremento de valor.',null),
('aux-ayto-mad:6-57f086f313','aux-ayto-mad',6,'El incremento de valor de los terrenos que tengan la consideración de rústicos a efectos del IBI:','["Está sujeto al IIVTNU con un tipo reducido", "No está sujeto al IIVTNU", "Está exento del IIVTNU previa solicitud"]'::jsonb,1,'Art. 104.2 TRLRHL','El art. 104.2 dispone que no está sujeto; sí lo está el de los terrenos que deban considerarse urbanos a efectos del IBI.',null),
('aux-ayto-mad:6-75a44eec02','aux-ayto-mad',6,'No se produce la sujeción al IIVTNU en las transmisiones de terrenos respecto de los cuales:','["Se constate la inexistencia de incremento de valor por diferencia entre los valores de transmisión y adquisición", "Hayan pasado más de veinte años desde la adquisición del terreno por el transmitente", "El adquirente sea un familiar de segundo grado del transmitente"]'::jsonb,0,'Art. 104.5 TRLRHL','El interesado debe declarar la transmisión y aportar los títulos de transmisión y adquisición.',null),
('aux-ayto-mad:6-de57d1b731','aux-ayto-mad',6,'Está exento del IIVTNU el incremento de valor que se manifieste como consecuencia de:','["La compraventa de un local comercial", "La constitución y transmisión de derechos de servidumbre", "La herencia de la vivienda habitual del causante a favor de sus descendientes"]'::jsonb,1,'Art. 105.1 a) TRLRHL','Así lo establece el art. 105.1 a). Las transmisiones por causa de muerte a favor de descendientes o cónyuges pueden tener bonificación de hasta el 95 % (art. 108.4), pero no exención.',null),
('aux-ayto-mad:6-70299f9a49','aux-ayto-mad',6,'En las transmisiones de terrenos a título oneroso, es sujeto pasivo contribuyente del IIVTNU:','["El notario que autoriza la escritura", "El que adquiere el terreno", "El que transmite el terreno"]'::jsonb,2,'Art. 106.1 b) TRLRHL','A título oneroso es contribuyente quien transmite. A título lucrativo, quien adquiere (art. 106.1 a).',null),
('aux-ayto-mad:6-2d14b1b7bd','aux-ayto-mad',6,'En las transmisiones de terrenos a título lucrativo (por ejemplo, una donación), es sujeto pasivo contribuyente del IIVTNU:','["El que adquiere el terreno", "Ambos, de forma solidaria", "El que transmite el terreno"]'::jsonb,0,'Art. 106.1 a) TRLRHL','En las transmisiones a título lucrativo es contribuyente el adquirente, o la persona a cuyo favor se constituye o transmite el derecho real.',null),
('aux-ayto-mad:6-bb8b9fde69','aux-ayto-mad',6,'La base imponible del IIVTNU se refiere al incremento de valor experimentado a lo largo de un período máximo de:','["Veinte años", "Quince años", "Diez años"]'::jsonb,0,'Art. 107.1 TRLRHL','Según el art. 107.1, el incremento se mide a lo largo de un periodo máximo de veinte años.',null),
('aux-ayto-mad:6-3f6f43fc0a','aux-ayto-mad',6,'El tipo de gravamen del IIVTNU lo fija cada ayuntamiento, sin que pueda exceder del:','["30 por ciento", "20 por ciento", "4 por ciento"]'::jsonb,0,'Art. 108.1 TRLRHL','Según el art. 108.1, el tipo no puede exceder del 30 %; puede ser único o distinto por periodos de generación.',null),
('aux-ayto-mad:6-a542e6dc2e','aux-ayto-mad',6,'Las ordenanzas fiscales pueden regular en el IIVTNU, para las transmisiones por causa de muerte a favor de descendientes, cónyuges o ascendientes, una bonificación de hasta el:','["95 por ciento", "50 por ciento", "75 por ciento"]'::jsonb,0,'Art. 108.4 TRLRHL','Según el art. 108.4, la bonificación puede ser de hasta el 95 % de la cuota íntegra.',null),
('aux-ayto-mad:6-2af74e0588','aux-ayto-mad',6,'Cuando se transmite la propiedad de un terreno, el IIVTNU se devenga:','["En la fecha de la transmisión", "El 1 de enero del año siguiente", "Cuando se inscribe la transmisión en el Registro de la Propiedad"]'::jsonb,0,'Art. 109.1 a) TRLRHL','Se devenga en la fecha de la transmisión, a título oneroso o gratuito, entre vivos o por causa de muerte.',null),
('aux-ayto-mad:6-d84ed22c04','aux-ayto-mad',6,'Si un contrato de transmisión de un terreno queda sin efecto por mutuo acuerdo de las partes:','["No procede la devolución del IIVTNU y se considera un acto nuevo sujeto a tributación", "Procede la devolución si se pide en el plazo de un mes", "Procede la devolución del impuesto si se reclama en el plazo de cinco años desde el acuerdo"]'::jsonb,0,'Art. 109.3 TRLRHL','Según el art. 109.3, no procede la devolución y se considera un acto nuevo sujeto a tributación.',null),
('aux-ayto-mad:7-1f68419331','aux-ayto-mad',7,'Según el TRLRHL, las entidades locales podrán establecer tasas por:','["Cualquier servicio que presten, aunque sea de solicitud voluntaria y lo preste también el sector privado", "La obtención de un beneficio o aumento de valor de los bienes por la realización de obras públicas o el establecimiento de servicios locales", "La utilización privativa o el aprovechamiento especial del dominio público local y por servicios o actividades de competencia local que beneficien de modo particular a los sujetos pasivos"]'::jsonb,2,'Art. 20.1 TRLRHL','El art. 20.1 define las tasas. El beneficio por obras o servicios públicos es el hecho imponible de las contribuciones especiales (art. 28). Si el servicio es voluntario y lo presta también el sector privado, procede un precio público (art. 41).',null),
('aux-ayto-mad:7-732324e5dc','aux-ayto-mad',7,'Para que la prestación de un servicio local dé lugar a una tasa, debe darse alguna de estas circunstancias:','["Que lo solicite al menos el 10 % de los vecinos empadronados", "Que su coste supere el presupuesto del área de gobierno correspondiente", "Que no sea de solicitud o recepción voluntaria, o que no lo preste el sector privado"]'::jsonb,2,'Art. 20.1 B) TRLRHL','El art. 20.1 B) exige que el servicio no sea de solicitud o recepción voluntaria o que no lo preste o realice el sector privado.',null),
('aux-ayto-mad:7-13d77d4b7f','aux-ayto-mad',7,'A efectos de las tasas, no se considera voluntaria la solicitud o recepción del servicio cuando:','["El servicio se preste a domicilio o fuera del horario ordinario", "Venga impuesta por disposiciones legales o reglamentarias", "El solicitante sea una persona jurídica"]'::jsonb,1,'Art. 20.1 B) a) TRLRHL','No es voluntaria cuando venga impuesta por disposiciones legales o reglamentarias o cuando los bienes, servicios o actividades sean imprescindibles para la vida privada o social del solicitante.',null),
('aux-ayto-mad:7-e1ff41ebc6','aux-ayto-mad',7,'¿Cuál de los siguientes servicios NO puede ser objeto de tasa según el TRLRHL?','["El otorgamiento de licencias urbanísticas", "La recogida de residuos sólidos urbanos", "El alumbrado de vías públicas"]'::jsonb,2,'Art. 21.1 TRLRHL','No pueden exigirse tasas por el abastecimiento de aguas en fuentes públicas, el alumbrado de vías públicas, la vigilancia pública en general, la protección civil, la limpieza de la vía pública ni la enseñanza obligatoria.',null),
('aux-ayto-mad:7-507c3b02ed','aux-ayto-mad',7,'Según el TRLRHL, las entidades locales no podrán exigir tasas por:','["La limpieza de la vía pública", "La celebración de matrimonios en forma civil", "La retirada de vehículos con grúa"]'::jsonb,0,'Art. 21.1 e) TRLRHL','La limpieza de la vía pública está en la lista del art. 21.1. En cambio, los ayuntamientos pueden establecer una tasa por la celebración de matrimonios civiles (art. 20.5).',null),
('aux-ayto-mad:7-39c0531cf3','aux-ayto-mad',7,'Según el TRLRHL, los Ayuntamientos podrán establecer una tasa por:','["La enseñanza en los niveles de educación obligatoria", "La celebración de los matrimonios en forma civil", "La vigilancia pública en general"]'::jsonb,1,'Art. 20.5 TRLRHL','El art. 20.5 permite a los Ayuntamientos establecer una tasa para la celebración de los matrimonios en forma civil.',null),
('aux-ayto-mad:7-ade3645b29','aux-ayto-mad',7,'Según el TRLRHL, las tasas por la prestación de servicios y las contribuciones especiales:','["Son compatibles: las tasas no excluyen las contribuciones especiales por el establecimiento o ampliación del servicio", "Solo son compatibles si lo autoriza la Comunidad Autónoma mediante informe previo", "Son incompatibles cuando se refieren al mismo servicio"]'::jsonb,0,'Art. 22 TRLRHL','Según el art. 22, las tasas por la prestación de servicios no excluyen la exacción de contribuciones especiales por el establecimiento o ampliación de aquéllos.',null),
('aux-ayto-mad:7-3a5a6063fc','aux-ayto-mad',7,'En las tasas por servicios que beneficien a los ocupantes de viviendas o locales, tienen la condición de sustitutos del contribuyente:','["Los propietarios de los inmuebles, que pueden repercutir las cuotas sobre los beneficiarios", "Las comunidades de propietarios", "Los ocupantes de las viviendas o locales, que no pueden repercutir las cuotas"]'::jsonb,0,'Art. 23.2 a) TRLRHL','Son sustitutos del contribuyente los propietarios de los inmuebles, que pueden repercutir las cuotas sobre los respectivos beneficiarios.',null),
('aux-ayto-mad:7-813e8640ae','aux-ayto-mad',7,'En las tasas por el otorgamiento de licencias urbanísticas, tienen la condición de sustitutos del contribuyente:','["Los constructores y contratistas de obras", "Los propietarios del suelo", "Los arquitectos directores de la obra"]'::jsonb,0,'Art. 23.2 b) TRLRHL','Según el art. 23.2 b), son sustitutos del contribuyente los constructores y contratistas de obras.',null),
('aux-ayto-mad:7-4baabd0695','aux-ayto-mad',7,'En las tasas por servicios de prevención y extinción de incendios, tienen la condición de sustitutos del contribuyente:','["Las entidades o sociedades aseguradoras del riesgo", "Los ocupantes de los inmuebles", "Los propietarios de los bienes siniestrados o afectados por el servicio"]'::jsonb,0,'Art. 23.2 c) TRLRHL','Según el art. 23.2 c), son sustitutos las entidades o sociedades aseguradoras del riesgo.',null),
('aux-ayto-mad:7-b4ae0e9ac1','aux-ayto-mad',7,'Con carácter general, el importe de las tasas por utilización privativa o aprovechamiento especial del dominio público local se fija tomando como referencia:','["El valor que tendría en el mercado la utilidad derivada de la utilización si los bienes no fuesen de dominio público", "El coste real o previsible del servicio, incluidos los costes directos e indirectos", "El valor catastral del inmueble ocupado"]'::jsonb,0,'Art. 24.1 a) TRLRHL','El art. 24.1 a) toma como referencia el valor de mercado de la utilidad derivada. El coste del servicio es el límite de las tasas por prestación de servicios (art. 24.2).',null),
('aux-ayto-mad:7-21d562b99a','aux-ayto-mad',7,'Las tasas por aprovechamientos del suelo, subsuelo o vuelo de las vías públicas a favor de empresas explotadoras de servicios de suministros de interés general consisten en:','["El 3 por ciento de los ingresos brutos de facturación en el término municipal", "Una cantidad fija por metro lineal de canalización", "El 1,5 por ciento de los ingresos brutos procedentes de la facturación anual en cada término municipal"]'::jsonb,2,'Art. 24.1 c) TRLRHL','Según el art. 24.1 c), consisten en todo caso y sin excepción en el 1,5 % de los ingresos brutos de facturación anuales en cada término municipal. No se incluyen los servicios de telefonía móvil.',null),
('aux-ayto-mad:7-167fb4a51a','aux-ayto-mad',7,'El régimen especial del 1,5 % de los ingresos brutos de las empresas de suministros NO se aplica a:','["Los servicios de telefonía móvil", "Las empresas distribuidoras de electricidad", "Las empresas comercializadoras de gas"]'::jsonb,0,'Art. 24.1 c) TRLRHL','El art. 24.1 c) dice expresamente que no se incluyen en este régimen especial los servicios de telefonía móvil.',null),
('aux-ayto-mad:7-270fd2a9ea','aux-ayto-mad',7,'Con carácter general, el importe de las tasas por la prestación de un servicio o la realización de una actividad no podrá exceder, en su conjunto:','["Del coste real o previsible del servicio o actividad o, en su defecto, del valor de la prestación recibida", "Del 90 por ciento del coste del servicio", "Del valor de mercado de la utilidad obtenida por el sujeto pasivo con la prestación"]'::jsonb,0,'Art. 24.2 TRLRHL','Según el art. 24.2, no podrá exceder del coste real o previsible, incluidos costes directos e indirectos, financieros y de amortización.',null),
('aux-ayto-mad:7-b01101dcd7','aux-ayto-mad',7,'Según el TRLRHL, para determinar la cuantía de las tasas podrán tenerse en cuenta:','["Exclusivamente criterios de coste del servicio", "Criterios genéricos de capacidad económica de los sujetos obligados", "La renta de cada sujeto pasivo según su declaración del IRPF"]'::jsonb,1,'Art. 24.4 TRLRHL','El art. 24.4 permite tener en cuenta criterios genéricos de capacidad económica de los sujetos obligados.',null),
('aux-ayto-mad:7-1988e9f1f9','aux-ayto-mad',7,'Cuando el aprovechamiento especial del dominio público local lleve aparejada su destrucción o deterioro, las entidades locales:','["No podrán condonar total ni parcialmente las indemnizaciones y reintegros", "Solo podrán exigir la tasa, sin reintegro de los gastos", "Podrán condonar las indemnizaciones si el beneficiario paga la tasa"]'::jsonb,0,'Art. 24.5 TRLRHL','El beneficiario debe reintegrar los gastos de reconstrucción o reparación (o indemnizar si los daños son irreparables), además de la tasa, y la entidad no puede condonarlos.',null),
('aux-ayto-mad:7-7be76992b8','aux-ayto-mad',7,'Las tasas por recogida de residuos pueden tener una bonificación de hasta el 95 % de la cuota para las empresas de distribución alimentaria y restauración que:','["Tengan sistemas de gestión que reduzcan de forma significativa y verificable los residuos alimentarios", "Tengan menos de diez trabajadores y una cifra de negocios inferior a un millón de euros", "Estén situadas en zonas de bajas emisiones"]'::jsonb,0,'Art. 24.6 TRLRHL','La bonificación de hasta el 95 % es para quienes tengan, con entidades de economía social sin ánimo de lucro, sistemas que reduzcan de forma significativa y verificable los residuos alimentarios.',null),
('aux-ayto-mad:7-b0c0aefb98','aux-ayto-mad',7,'Los acuerdos de establecimiento de tasas por utilización privativa del dominio público o para financiar nuevos servicios deben adoptarse a la vista de:','["Un informe del Tribunal de Cuentas", "Informes técnico-económicos", "Un dictamen del Consejo de Estado"]'::jsonb,1,'Art. 25 TRLRHL','El art. 25 exige informes técnico-económicos sobre el valor de mercado o la previsible cobertura del coste, que se incorporan al expediente.',null),
('aux-ayto-mad:7-3e60a88bbd','aux-ayto-mad',7,'Cuando la naturaleza de la tasa exija su devengo periódico y así lo determine la ordenanza, el devengo tiene lugar:','["El día en que se notifica la liquidación", "El 1 de enero de cada año, y el período impositivo comprende el año natural", "El último día del año natural, y el período impositivo comprende el año natural"]'::jsonb,1,'Art. 26.2 TRLRHL','El devengo periódico tiene lugar el 1 de enero y el período es el año natural, con prorrateo en caso de inicio o cese.',null),
('aux-ayto-mad:7-648d987ee3','aux-ayto-mad',7,'Cuando por causas no imputables al sujeto pasivo el servicio por el que se pagó una tasa no se preste:','["Se compensará en la tasa del año siguiente", "Procederá la devolución del importe correspondiente", "No procede la devolución, porque el devengo ya se produjo"]'::jsonb,1,'Art. 26.3 TRLRHL','Según el art. 26.3, procederá la devolución del importe correspondiente.',null),
('aux-ayto-mad:7-154c0da403','aux-ayto-mad',7,'Según el TRLRHL, las entidades locales podrán exigir las tasas:','["Solo mediante padrón anual", "En régimen de autoliquidación", "Solo mediante liquidación notificada individualmente"]'::jsonb,1,'Art. 27.1 TRLRHL','El art. 27.1 permite exigir las tasas en régimen de autoliquidación. También los precios públicos (art. 45).',null),
('aux-ayto-mad:7-911ad08eb1','aux-ayto-mad',7,'Constituye el hecho imponible de las contribuciones especiales:','["La obtención de un beneficio o aumento de valor de los bienes del sujeto pasivo por la realización de obras públicas o el establecimiento o ampliación de servicios públicos locales", "La prestación de servicios de recepción voluntaria que también ofrece el sector privado", "La utilización privativa o el aprovechamiento especial del dominio público local por los particulares"]'::jsonb,0,'Art. 28 TRLRHL','Así lo define el art. 28.',null),
('aux-ayto-mad:7-2d24b0258d','aux-ayto-mad',7,'Las cantidades recaudadas por contribuciones especiales:','["Pueden destinarse a cualquier inversión del mismo distrito", "Se integran en el presupuesto general sin afectación a ningún gasto concreto", "Solo podrán destinarse a sufragar los gastos de la obra o del servicio por cuya razón se exigieron"]'::jsonb,2,'Art. 29.3 TRLRHL','El art. 29.3 establece la afectación de lo recaudado a la obra o servicio que motivó la contribución especial.',null),
('aux-ayto-mad:7-aa20a1d546','aux-ayto-mad',7,'En las contribuciones especiales por obras o servicios que afecten a bienes inmuebles, se consideran personas especialmente beneficiadas:','["Sus arrendatarios", "Los vecinos empadronados en ellos", "Sus propietarios"]'::jsonb,2,'Art. 30.2 a) TRLRHL','Según el art. 30.2 a), son personas especialmente beneficiadas los propietarios de los inmuebles.',null),
('aux-ayto-mad:7-c95c92aed9','aux-ayto-mad',7,'En las contribuciones especiales por el establecimiento o ampliación del servicio de extinción de incendios, se consideran también especialmente beneficiadas:','["Los fabricantes de material contra incendios", "Las empresas suministradoras de agua que deban utilizar las instalaciones", "Las compañías de seguros que desarrollen su actividad en el ramo en el término municipal"]'::jsonb,2,'Art. 30.2 c) TRLRHL','Además de los propietarios de los bienes afectados, lo son las compañías de seguros del ramo en el término municipal.',null),
('aux-ayto-mad:7-7fa1973652','aux-ayto-mad',7,'La base imponible de las contribuciones especiales está constituida, como máximo, por:','["El 100 por ciento del coste de las obras", "El 90 por ciento del coste que la entidad local soporte", "El 75 por ciento del coste de las obras"]'::jsonb,1,'Art. 31.1 TRLRHL','Según el art. 31.1, la base imponible es como máximo el 90 % del coste soportado por la entidad local.',null),
('aux-ayto-mad:7-fa60ceba2e','aux-ayto-mad',7,'El coste total presupuestado de las obras financiadas con contribuciones especiales tiene carácter de mera previsión, de modo que si el coste real es distinto:','["Se mantiene el coste presupuestado", "Solo se recalcula si el coste real es menor", "Se toma el coste real a efectos del cálculo de las cuotas"]'::jsonb,2,'Art. 31.3 TRLRHL','Si el coste real fuese mayor o menor que el previsto, se tomará el real para calcular las cuotas.',null),
('aux-ayto-mad:7-54824b3374','aux-ayto-mad',7,'Como módulos de reparto de las contribuciones especiales se aplicarán, con carácter general:','["El número de personas empadronadas en cada inmueble", "Los ingresos de los propietarios según su declaración del IRPF del año anterior", "Los metros lineales de fachada, la superficie, el volumen edificable y el valor catastral a efectos del IBI"]'::jsonb,2,'Art. 32.1 a) TRLRHL','El art. 32.1 a) cita estos módulos, que pueden aplicarse conjunta o separadamente.',null),
('aux-ayto-mad:7-4b98d6cb31','aux-ayto-mad',7,'En las contribuciones especiales por el servicio de extinción de incendios distribuidas entre aseguradoras, si la cuota de una de ellas supera el cinco por ciento de sus primas recaudadas:','["El exceso se reparte entre los propietarios de los bienes afectados", "El exceso queda condonado", "El exceso se trasladará a los ejercicios sucesivos hasta su total amortización"]'::jsonb,2,'Art. 32.1 b) TRLRHL','El reparto es proporcional a las primas del año anterior y el exceso sobre el 5 % se traslada a ejercicios sucesivos.',null),
('aux-ayto-mad:7-52729f085f','aux-ayto-mad',7,'Una vez determinada la cuota de una contribución especial, la corporación podrá conceder, a solicitud del sujeto pasivo, su fraccionamiento o aplazamiento por un plazo máximo de:','["Cinco años", "Tres años", "Diez años"]'::jsonb,0,'Art. 32.3 TRLRHL','Según el art. 32.3, el plazo máximo es de cinco años.',null),
('aux-ayto-mad:7-8b7398a84a','aux-ayto-mad',7,'Las contribuciones especiales se devengan:','["El 1 de enero del año siguiente a la terminación de la obra", "Cuando se aprueba el acuerdo concreto de imposición y ordenación", "En el momento en que las obras se hayan ejecutado o el servicio haya comenzado a prestarse"]'::jsonb,2,'Art. 33.1 TRLRHL','Se devengan al ejecutarse las obras o comenzar a prestarse el servicio; si la obra es fraccionable, por tramos. Aun así, puede exigirse el pago anticipado del coste previsto para el año siguiente (art. 33.2).',null),
('aux-ayto-mad:7-f1c15fe20e','aux-ayto-mad',7,'El sujeto pasivo de una contribución especial que transmita los bienes entre la aprobación del acuerdo de ordenación y el devengo debe comunicar la transmisión a la Administración en el plazo de:','["Tres meses desde la fecha de la transmisión", "Diez días desde la fecha de la transmisión", "Un mes desde la fecha de la transmisión"]'::jsonb,2,'Art. 33.3 TRLRHL','Debe dar cuenta de la transmisión en el plazo de un mes; si no lo hace, la Administración puede dirigir la acción de cobro contra él.',null),
('aux-ayto-mad:7-79ef102e47','aux-ayto-mad',7,'El acuerdo de realizar una obra que deba costearse mediante contribuciones especiales:','["No podrá ejecutarse hasta que se haya aprobado la ordenación concreta de estas", "Puede ejecutarse y aprobar después la ordenación de las contribuciones especiales", "Solo requiere la aprobación del proyecto de obra"]'::jsonb,0,'Art. 34.2 TRLRHL','El art. 34.2 impide ejecutar el acuerdo hasta que se haya aprobado la ordenación concreta de las contribuciones especiales, que es de inexcusable adopción.',null),
('aux-ayto-mad:7-50cba2e775','aux-ayto-mad',7,'Contra las cuotas de contribuciones especiales notificadas individualmente, los interesados pueden formular:','["Recurso de alzada ante la Comunidad Autónoma", "Reclamación ante el Tribunal de Cuentas", "Recurso de reposición ante el ayuntamiento"]'::jsonb,2,'Art. 34.4 TRLRHL','Pueden formular recurso de reposición ante el ayuntamiento sobre la procedencia de las contribuciones, el porcentaje del coste a satisfacer o las cuotas asignadas.',null),
('aux-ayto-mad:7-2f679e7389','aux-ayto-mad',7,'Para constituir una asociación administrativa de contribuyentes, el acuerdo debe tomarse por:','["La mayoría absoluta de los afectados que representen al menos dos tercios de las cuotas", "La mayoría simple de los afectados", "Dos tercios de los afectados que representen la mitad de las cuotas"]'::jsonb,0,'Art. 37 TRLRHL','El art. 37 exige mayoría absoluta de los afectados que representen, al menos, los dos tercios de las cuotas.',null),
('aux-ayto-mad:7-ad5feb9f50','aux-ayto-mad',7,'Según el TRLRHL, las entidades locales podrán establecer precios públicos por la prestación de servicios o actividades de su competencia:','["Siempre que el servicio sea de recepción obligatoria", "Siempre que no concurra ninguna de las circunstancias que obligan a exigir una tasa", "Solo cuando el servicio lo preste una sociedad mercantil municipal"]'::jsonb,1,'Art. 41 TRLRHL','Proceden precios públicos cuando el servicio es de solicitud voluntaria y lo presta también el sector privado, es decir, cuando no se da ninguna circunstancia del art. 20.1 B).',null),
('aux-ayto-mad:7-1df602728a','aux-ayto-mad',7,'Según el TRLRHL, no podrán exigirse precios públicos por:','["Los mismos servicios por los que tampoco pueden exigirse tasas, como la protección civil", "El uso de instalaciones deportivas municipales", "Las visitas a museos, exposiciones y monumentos municipales"]'::jsonb,0,'Art. 42 TRLRHL','Según el art. 42, no pueden exigirse precios públicos por los servicios del art. 21 (fuentes públicas, alumbrado, vigilancia, protección civil, limpieza viaria y enseñanza obligatoria).',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:7-fa29325fc9','aux-ayto-mad',7,'El importe de los precios públicos deberá cubrir:','["Como máximo el coste del servicio prestado", "El 90 por ciento del coste del servicio", "Como mínimo el coste del servicio prestado o de la actividad realizada"]'::jsonb,2,'Art. 44.1 TRLRHL','Deben cubrir como mínimo el coste del servicio, aunque por razones sociales, benéficas, culturales o de interés público pueden fijarse por debajo, consignando en el presupuesto la diferencia (art. 44.2).',null),
('aux-ayto-mad:7-8e065dc0f9','aux-ayto-mad',7,'Cuando por razones sociales o culturales se fije un precio público por debajo del coste del servicio:','["Deberán consignarse en el presupuesto las dotaciones para cubrir la diferencia", "Se necesita autorización previa del Ministerio de Hacienda para aplicarlo", "El precio público se convierte en tasa a todos los efectos"]'::jsonb,0,'Art. 44.2 TRLRHL','El art. 44.2 exige consignar en los presupuestos las dotaciones oportunas para la cobertura de la diferencia.',null),
('aux-ayto-mad:7-e4adc631d7','aux-ayto-mad',7,'La obligación de pagar el precio público nace:','["Cuando termine la prestación del servicio", "Desde que se inicie la prestación del servicio o la realización de la actividad", "Cuando se apruebe el padrón anual de los obligados al pago"]'::jsonb,1,'Art. 46.1 TRLRHL','Nace desde que se inicia la prestación, aunque puede exigirse el depósito previo de su importe total o parcial.',null),
('aux-ayto-mad:7-321f011450','aux-ayto-mad',7,'Las deudas por precios públicos:','["No son exigibles si el servicio era voluntario", "Solo pueden reclamarse ante la jurisdicción civil por el procedimiento ordinario", "Podrán exigirse por el procedimiento administrativo de apremio"]'::jsonb,2,'Art. 46.3 TRLRHL','Según el art. 46.3, las deudas por precios públicos podrán exigirse por el procedimiento administrativo de apremio.',null),
('aux-ayto-mad:7-31fd8342f2','aux-ayto-mad',7,'El establecimiento o modificación de los precios públicos corresponderá, según el TRLRHL:','["Al Pleno de la corporación, sin perjuicio de sus facultades de delegación", "A la Intervención General", "Al Alcalde, mediante decreto"]'::jsonb,0,'Art. 47.1 TRLRHL','Según el art. 47.1 corresponde al Pleno, que puede delegarla. Las entidades locales pueden atribuir la fijación a sus organismos autónomos salvo que los precios no cubran su coste (art. 47.2).',null),
('aux-ayto-mad:7-676ddeba94','aux-ayto-mad',7,'Las entidades locales pueden atribuir a sus organismos autónomos la fijación de los precios públicos de los servicios a su cargo, salvo cuando:','["El organismo tenga más de cien trabajadores", "Los precios se cobren en régimen de autoliquidación", "Los precios no cubran su coste"]'::jsonb,2,'Art. 47.2 TRLRHL','Según el art. 47.2, no cabe esa atribución cuando los precios no cubran su coste.',null),
('aux-ayto-mad:7-d21a39a007','aux-ayto-mad',7,'Según el TRLRHL, las entidades locales exigirán los impuestos previstos en esa ley:','["Sin necesidad de acuerdo de imposición, salvo los casos en que esta lo requiera", "Solo si lo autoriza la Comunidad Autónoma", "Previo acuerdo de imposición del Pleno en todo caso"]'::jsonb,0,'Art. 38.1 TRLRHL','El art. 38.1 dice que se exigen sin necesidad de acuerdo de imposición, salvo los casos en que la ley lo requiere.',null),
('aux-ayto-mad:8-0192fe9901','aux-ayto-mad',8,'Según la Ley de Capitalidad y de Régimen Especial de Madrid, las competencias del Ayuntamiento de Madrid son:','["Exclusivamente las propias que le asigna la legislación de régimen local", "Propias, compartidas con la Comunidad de Madrid o concurrentes con las del Estado", "Propias o atribuidas por la Administración General del Estado en régimen de delegación o de encomienda de gestión"]'::jsonb,2,'Art. 32.1 Ley 22/2006','Las competencias del Ayuntamiento de Madrid son propias o atribuidas por la Administración General del Estado por delegación o encomienda de gestión. Además, las que le transfiera o delegue la Comunidad de Madrid (art. 32.2).',null),
('aux-ayto-mad:8-256fe242eb','aux-ayto-mad',8,'Según el artículo 31 de la Ley 22/2006, el Ayuntamiento de Madrid puede promover toda clase de actividades y prestar todos los servicios públicos que afecten al interés general de los ciudadanos:','["Siempre que lo autorice previamente la Comisión Interadministrativa de Capitalidad", "Que le encomiende la Comunidad de Madrid mediante convenio", "Que no estén expresamente atribuidos a otras administraciones públicas"]'::jsonb,2,'Art. 31 Ley 22/2006','El régimen general de competencias permite al Ayuntamiento actuar en todo lo que afecte al interés general y no esté expresamente atribuido a otras administraciones; en esos casos puede hacer actividades complementarias.',null),
('aux-ayto-mad:8-a663d27922','aux-ayto-mad',8,'Según la Ley 22/2006, son competencias propias del Ayuntamiento de Madrid:','["Todas las asignadas en calidad de tales a los municipios en general y a los de gran población, por la legislación de régimen local o por la legislación sectorial", "Las que el Pleno declare como propias por mayoría absoluta", "Solo las que la propia Ley 22/2006 enumera en su título III, en materia de seguridad y movilidad"]'::jsonb,0,'Art. 33 Ley 22/2006','Son propias todas las asignadas como tales a los municipios en general y a los de gran población, por la legislación de régimen local o por la estatal o autonómica sectorial. Si la Ley 22/2006 las regula, se entienden asignadas en sus términos.',null),
('aux-ayto-mad:8-e2e1916fcd','aux-ayto-mad',8,'La encomienda de gestión al Ayuntamiento de Madrid de actividades de carácter material, técnico o de servicios de la Administración General del Estado o de la Comunidad de Madrid requiere:','["La aceptación por la Junta de Gobierno y se formaliza mediante decreto del Alcalde", "La aprobación de la Comisión Interadministrativa de Capitalidad y su publicación en el BOE", "La aceptación por el Pleno y se formaliza mediante convenio"]'::jsonb,2,'Art. 34.2 Ley 22/2006','La encomienda de gestión requiere la aceptación por el Pleno y se formaliza mediante convenio suscrito al efecto.',null),
('aux-ayto-mad:8-09b11a7ad5','aux-ayto-mad',8,'Según la Ley 22/2006, ¿qué competencia corresponde al Ayuntamiento de Madrid en materia de seguridad pública?','["La protección y custodia de autoridades, edificios, instalaciones, dependencias, infraestructuras y equipamientos municipales", "La dirección de las Fuerzas y Cuerpos de Seguridad del Estado destinados en el municipio", "La protección y custodia de las autoridades del Estado y de la Comunidad de Madrid con sede en la ciudad"]'::jsonb,0,'Art. 35.1 Ley 22/2006','El art. 35.1 atribuye al Ayuntamiento la protección y custodia de autoridades, edificios, instalaciones, dependencias, infraestructuras y equipamientos municipales, y la colaboración con las administraciones competentes en seguridad.',null),
('aux-ayto-mad:8-0783049d8a','aux-ayto-mad',8,'En materia de seguridad pública, la Ley de Capitalidad atribuye al Ayuntamiento de Madrid, en colaboración con las Administraciones competentes:','["La prevención, mantenimiento y restablecimiento de la seguridad ciudadana", "La expedición del documento nacional de identidad a los vecinos", "La coordinación de las policías locales de los municipios del área metropolitana"]'::jsonb,0,'Art. 35.2 Ley 22/2006','En colaboración con las administraciones competentes, le corresponde la prevención, mantenimiento y restablecimiento de la seguridad ciudadana, sobre todo ante actos que causen molestia social o daños en la vía pública.',null),
('aux-ayto-mad:8-34fcced2f1','aux-ayto-mad',8,'Según la Ley 22/2006, la policía municipal de Madrid ejercerá las competencias que en materia de policía judicial:','["Le delegue la Comunidad de Madrid", "Le atribuye la normativa estatal", "Le encomiende el Tribunal Superior de Justicia de Madrid"]'::jsonb,1,'Art. 35.4 Ley 22/2006','La policía municipal ejerce las competencias de policía judicial que le atribuye la normativa estatal.',null),
('aux-ayto-mad:8-ec8fe55260','aux-ayto-mad',8,'En las sesiones de la Junta Local de Seguridad de Madrid podrá participar como vocal, según la Ley 22/2006:','["Un Juez o Magistrado designado por el Consejo General del Poder Judicial", "Un Juez o Magistrado designado por la Sala de Gobierno del Tribunal Superior de Justicia", "El Delegado del Gobierno en la Comunidad de Madrid, que la presidirá"]'::jsonb,1,'Art. 36.2 Ley 22/2006','Pueden participar como vocales los mandos de las Fuerzas y Cuerpos de Seguridad del Estado con responsabilidades en el municipio y, en su caso, un Juez o Magistrado designado por la Sala de Gobierno del TSJ y un Fiscal designado por el Fiscal Jefe del TSJ.',null),
('aux-ayto-mad:8-2eef53fe6c','aux-ayto-mad',8,'El Fiscal que puede participar como vocal en la Junta Local de Seguridad de Madrid es designado por:','["La Junta de Gobierno del Ayuntamiento", "El Fiscal Jefe del Tribunal Superior de Justicia", "El Fiscal General del Estado"]'::jsonb,1,'Art. 36.2 Ley 22/2006','Según el art. 36.2, el Fiscal es designado por el Fiscal Jefe del Tribunal Superior de Justicia.',null),
('aux-ayto-mad:8-76c806a818','aux-ayto-mad',8,'La participación del Ayuntamiento de Madrid en la gestión de infraestructuras de titularidad de la Administración General del Estado:','["No impide que el Ayuntamiento ejerza sus competencias propias en materia de planeamiento, movilidad, medio ambiente y otras", "Suspende sus competencias urbanísticas sobre esas infraestructuras mientras dure la participación", "Excluye la participación de la Comunidad de Madrid en esa misma gestión"]'::jsonb,0,'Art. 37.2 Ley 22/2006','La participación no impide que el Ayuntamiento ejerza sus competencias propias (planeamiento, seguridad, protección civil, salubridad, movilidad, medio ambiente…). Además, se hace sin menoscabo de la participación de la Comunidad de Madrid (art. 37.3).',null),
('aux-ayto-mad:8-4c68a06d66','aux-ayto-mad',8,'Según el artículo 38 de la Ley 22/2006, el Ayuntamiento de Madrid ejerce sus competencias en materia de tráfico, circulación y seguridad vial sobre:','["Exclusivamente las vías urbanas de titularidad municipal", "Las vías urbanas, las travesías declaradas vías urbanas y cualquier espacio abierto a la libre circulación", "Las vías urbanas y las autopistas de titularidad estatal que atraviesan el término municipal"]'::jsonb,1,'Art. 38 Ley 22/2006','Las ejerce sobre las vías urbanas, las travesías declaradas vías urbanas y cualquier espacio abierto a la libre circulación de personas, animales y vehículos.',null),
('aux-ayto-mad:8-b8c0dd16fe','aux-ayto-mad',8,'Cuando las molestias de un vehículo por ruidos o humos sean graves o reiteradas, la ordenanza municipal puede establecer su inmovilización cautelar concediendo al titular un plazo para subsanar las deficiencias de:','["Diez días", "Cinco días", "Quince días"]'::jsonb,1,'Art. 39.3 b) Ley 22/2006','El art. 39.3 b) prevé la inmovilización cautelar y la intervención del permiso de circulación, con un plazo de cinco días para que el titular subsane las deficiencias.',null),
('aux-ayto-mad:8-237e650e4f','aux-ayto-mad',8,'Según la Ley 22/2006, las ordenanzas que regulen el tránsito en la ciudad de Madrid:','["Podrán tipificar infracciones y determinar sanciones de acuerdo con los criterios establecidos por las Leyes", "Solo pueden fijar sanciones económicas por estacionamiento indebido", "No pueden tipificar infracciones, que solo puede establecer la legislación estatal de tráfico"]'::jsonb,0,'Art. 39.2 Ley 22/2006','Las ordenanzas que regulen el tránsito pueden tipificar infracciones y determinar sanciones, de acuerdo con los criterios establecidos por las Leyes.',null),
('aux-ayto-mad:8-edc4a43826','aux-ayto-mad',8,'La autorización de pruebas deportivas corresponde al Ayuntamiento de Madrid cuando discurran:','["Íntegra y exclusivamente por el casco urbano, exceptuadas las travesías que no sean vías urbanas", "Por el casco urbano y por las carreteras de la Comunidad de Madrid colindantes", "Por cualquier vía del término municipal, incluidas las interurbanas y las travesías"]'::jsonb,0,'Art. 40 d) Ley 22/2006','Le corresponde autorizar las pruebas deportivas que discurran íntegra y exclusivamente por el casco urbano, salvo travesías que no sean vías urbanas. Si solo pasan en parte por el término municipal, emite un informe preceptivo.',null),
('aux-ayto-mad:8-38ee61df08','aux-ayto-mad',8,'Cuando una prueba deportiva discurra solo en parte de su recorrido por el término municipal de Madrid, el Ayuntamiento:','["Autoriza la prueba en todo caso, por pasar por su término", "No tiene ninguna intervención", "Emite un informe preceptivo para su autorización"]'::jsonb,2,'Art. 40 d) Ley 22/2006','En ese caso corresponde al Ayuntamiento el informe, que será preceptivo, para la autorización de la prueba deportiva.',null),
('aux-ayto-mad:8-5d95b16b66','aux-ayto-mad',8,'Según la Ley 22/2006, la competencia del Ayuntamiento de Madrid en materia de seguridad vial incluye:','["La expedición de los permisos de conducción a los residentes", "La matriculación de los vehículos de los residentes en el municipio", "La instrucción de atestados en caso de accidentes de circulación"]'::jsonb,2,'Art. 40 Ley 22/2006','Le corresponde la policía administrativa preventiva de la seguridad vial en las vías urbanas, incluida la instrucción de atestados en caso de accidentes de circulación.',null),
('aux-ayto-mad:8-973b4a0584','aux-ayto-mad',8,'El Ayuntamiento de Madrid puede acordar la inmovilización de un vehículo por incumplimiento de las normas de estacionamiento:','["Hasta que se pague la multa correspondiente", "Durante un plazo máximo de veinticuatro horas", "Hasta la identificación del conductor"]'::jsonb,2,'Art. 41.1.ª a) Ley 22/2006','El art. 41.1.ª a) permite la inmovilización por incumplimiento de las normas de estacionamiento, incluidas las que lo limitan en el tiempo, hasta la identificación del conductor.',null),
('aux-ayto-mad:8-6fe2550ca6','aux-ayto-mad',8,'¿Cuál de los siguientes es un supuesto de retirada de vehículos previsto en la Ley 22/2006?','["Circulación sin cobertura del seguro obligatorio de responsabilidad civil", "Estacionamiento indebido en las zonas de estacionamiento restringido", "Superación de los niveles máximos de emisión de ruidos"]'::jsonb,1,'Art. 41.2.ª c) Ley 22/2006','El estacionamiento indebido en zonas de estacionamiento restringido es supuesto de retirada (art. 41.2.ª c). La falta de seguro y el exceso de emisiones son supuestos de inmovilización (art. 41.1.ª).',null),
('aux-ayto-mad:8-594455385d','aux-ayto-mad',8,'¿Cuál de los siguientes es un supuesto de inmovilización (y no de retirada) de vehículos en la Ley de Capitalidad?','["Ofrecer en venta el propio vehículo estacionado en la vía pública", "Que el vehículo obstaculice o dificulte la circulación", "Circulación sin cobertura del preceptivo seguro"]'::jsonb,2,'Art. 41.1.ª d) Ley 22/2006','La circulación sin seguro es supuesto de inmovilización (art. 41.1.ª d). Obstaculizar la circulación y ofrecer el vehículo en venta en la vía pública son supuestos de retirada (art. 41.2.ª).',null),
('aux-ayto-mad:8-aa3ff2d435','aux-ayto-mad',8,'Según la Ley 22/2006, los gastos derivados de la inmovilización o retirada de un vehículo:','["Son por cuenta del titular, y su abono o garantía es requisito previo para levantar la medida", "Son por cuenta del Ayuntamiento cuando el vehículo se retira de forma remota", "Se reparten entre el titular y el conductor a partes iguales"]'::jsonb,0,'Art. 41 Ley 22/2006','Los gastos son por cuenta del titular, y su abono o la garantía de su pago es requisito previo para el alzamiento de la medida.',null),
('aux-ayto-mad:8-0ec6b9211e','aux-ayto-mad',8,'La comprobación del supuesto que legitima la retirada de un vehículo y la orden de retirada, según la Ley 22/2006:','["Requieren siempre la presencia física de un agente de la policía municipal", "Pueden efectuarse de forma remota, mediante fotografías, filmación digital u otros medios tecnológicos", "Solo pueden hacerse por un agente de movilidad tras levantar acta"]'::jsonb,1,'Art. 41.2.ª Ley 22/2006','El art. 41.2.ª permite comprobar el supuesto y ordenar la retirada de forma remota, a través de fotografías, filmación digital y otros medios tecnológicos.',null),
('aux-ayto-mad:8-9a89b3f50e','aux-ayto-mad',8,'El Ayuntamiento de Madrid podrá nombrar personal auxiliar de la policía municipal para:','["Instruir los atestados por accidentes de circulación", "Controlar la adecuada utilización de las paradas de estacionamiento en la vía pública y denunciar las conductas contrarias a sus normas", "Ordenar y dirigir el tráfico en las intersecciones"]'::jsonb,1,'Art. 44.1 Ley 22/2006','El personal auxiliar controla la utilización de las paradas de estacionamiento y denuncia las conductas contrarias a sus normas; sus denuncias sirven como elemento probatorio (art. 44.2).',null),
('aux-ayto-mad:8-b6322d2bc1','aux-ayto-mad',8,'Los funcionarios del cuerpo que el Pleno puede crear para ordenar, señalizar y dirigir el tráfico en el casco urbano de Madrid:','["Dependen funcionalmente de la Dirección General de Tráfico", "No se integran en las Fuerzas y Cuerpos de Seguridad y son agentes de la autoridad subordinados a la Policía Local", "Se integran en las Fuerzas y Cuerpos de Seguridad como policía local de movilidad"]'::jsonb,1,'Art. 45 Ley 22/2006','Estos funcionarios no se integran en las Fuerzas y Cuerpos de Seguridad y tienen la consideración de agentes de la autoridad subordinados a los miembros de la Policía Local.',null),
('aux-ayto-mad:8-101464fdce','aux-ayto-mad',8,'En el embargo de bienes por sanciones de tráfico, la Ley 22/2006 permite embargar el vehículo del responsable:','["Solo cuando se hayan embargado sin éxito sus sueldos y salarios", "Inmediatamente después del dinero en efectivo o en cuentas abiertas en entidades de depósito", "Antes que cualquier otro bien, incluido el dinero en efectivo"]'::jsonb,1,'Art. 46 Ley 22/2006','Se exceptúa el orden general de embargo: inmediatamente después del dinero en efectivo o en cuentas, se puede embargar el vehículo del responsable de la infracción.',null),
('aux-ayto-mad:8-148590c4b8','aux-ayto-mad',8,'Mediante ordenanza, el Ayuntamiento de Madrid puede imponer la obligación de exhibir en el vehículo un adhesivo justificativo del pago o la exención del:','["Impuesto sobre Vehículos de Tracción Mecánica", "Impuesto sobre Bienes Inmuebles", "Impuesto sobre Actividades Económicas de los titulares de vehículos comerciales"]'::jsonb,0,'Art. 43.2 Ley 22/2006','El art. 43.2 permite exigir un adhesivo justificativo del pago o exención del Impuesto sobre Vehículos de Tracción Mecánica a los vehículos obligados a pagarlo en Madrid.',null),
('aux-ayto-mad:8-5359fb1453','aux-ayto-mad',8,'Según la Ley de Capitalidad, cuando se desafecten inmuebles del Estado en Madrid destinados a un servicio público, podrán enajenarse de forma preferente al Ayuntamiento:','["Por subasta pública en la que el Ayuntamiento tiene derecho de tanteo", "Mediante convenio, siempre que se destinen a usos dotacionales públicos o a vivienda pública", "De forma gratuita y por ministerio de la ley, sin necesidad de convenio"]'::jsonb,1,'Art. 47 Ley 22/2006','Puede procederse mediante convenio a su enajenación preferente al Ayuntamiento (o a sus entidades de vivienda y, en su caso, a la Comunidad de Madrid) si se destinan a usos dotacionales públicos o a vivienda protegida o pública en alquiler.',null),
('aux-ayto-mad:8-5d42407e63','aux-ayto-mad',8,'El régimen de capitalidad de la Villa de Madrid regulado en el título I de la Ley 22/2006 tiene como objeto, entre otras materias:','["La gestión del patrimonio histórico de la Corona en la ciudad y de sus reales sitios", "La coordinación en la organización y celebración de actos oficiales de carácter estatal", "La financiación de los servicios de transporte metropolitano"]'::jsonb,1,'Art. 4 b) Ley 22/2006','El régimen de capitalidad comprende la seguridad en acontecimientos nacionales o internacionales, la coordinación de actos oficiales estatales, la protección en reuniones y manifestaciones de dimensión estatal, el régimen protocolario y otras materias que afecten a las tres administraciones.',null),
('aux-ayto-mad:8-ecb21d8803','aux-ayto-mad',8,'La Comisión Interadministrativa de Capitalidad está formada por:','["Igual número de miembros del Estado y de la Comunidad de Madrid y un representante del Ayuntamiento", "Mayoría de miembros del Estado, que la preside", "Igual número de miembros de las tres administraciones"]'::jsonb,2,'Art. 5.2 Ley 22/2006','La Comisión está formada por igual número de miembros de las tres administraciones (Estado, Comunidad de Madrid y Ayuntamiento).',null),
('aux-ayto-mad:8-e09c322817','aux-ayto-mad',8,'La presidencia de la Comisión Interadministrativa de Capitalidad corresponde:','["A la Presidencia de la Comunidad de Madrid", "Al Estado", "Al Alcalde de Madrid"]'::jsonb,1,'Art. 6.1 Ley 22/2006','Según el art. 6.1, la presidencia de la Comisión Interadministrativa de Capitalidad corresponde al Estado.',null),
('aux-ayto-mad:8-f7dce37fa1','aux-ayto-mad',8,'El Reglamento de la Comisión Interadministrativa de Capitalidad se aprueba:','["Por mayoría absoluta de sus miembros", "Por unanimidad de sus miembros", "Por real decreto del Consejo de Ministros"]'::jsonb,1,'Art. 6.2 Ley 22/2006','Su composición y funcionamiento se determinan en su Reglamento, que se aprueba por unanimidad de sus miembros.',null),
('aux-ayto-mad:8-9b6e993c4d','aux-ayto-mad',8,'La Comisión Interadministrativa de Capitalidad es, según la Ley 22/2006:','["Un órgano de cooperación para la mejor articulación del régimen de capitalidad", "Un órgano consultivo del Pleno del Ayuntamiento en materia de protocolo", "Un órgano de control de la legalidad de los acuerdos municipales"]'::jsonb,0,'Art. 5.1 Ley 22/2006','Se crea como órgano de cooperación para la mejor articulación del régimen de capitalidad, respetando los ámbitos competenciales de cada administración.',null),
('aux-ayto-mad:8-d05a8fc0bf','aux-ayto-mad',8,'Según el artículo 2 de la Ley 22/2006, para la efectividad de su autonomía la Ley atribuye al Ayuntamiento de Madrid competencias en materia de:','["Infraestructuras, movilidad, seguridad ciudadana y régimen jurídico y procedimiento", "Hacienda autonómica, justicia y empleo", "Educación, sanidad, vivienda y servicios sociales de atención primaria"]'::jsonb,0,'Art. 2.3 Ley 22/2006','El art. 2.3 cita las competencias en infraestructuras, movilidad, seguridad ciudadana y régimen jurídico y procedimiento.',null),
('aux-ayto-mad:8-ad1fa3b361','aux-ayto-mad',8,'En las materias no reguladas en la Ley 22/2006 se aplica a la ciudad de Madrid, en primer lugar:','["Los reglamentos orgánicos aprobados por el Pleno", "La legislación estatal básica en materia de gobierno y administración local y, en su caso, la autonómica de desarrollo", "El Texto articulado de la Ley especial para el Municipio de Madrid de 1963, en lo no derogado"]'::jsonb,1,'Art. 1.2 Ley 22/2006','Se aplica la legislación estatal básica de régimen local y, en su caso, la autonómica de desarrollo, y la restante legislación del Estado y de la Comunidad según la distribución de competencias. El texto de 1963 quedó sin efecto (disposición derogatoria).',null),
('aux-ayto-mad:8-5658bdc485','aux-ayto-mad',8,'La Ley 22/2006 dejó sin efecto los artículos no derogados del Texto articulado de la Ley especial para el Municipio de Madrid aprobado en:','["1963", "1955", "1985"]'::jsonb,0,'Disposición derogatoria única Ley 22/2006','La disposición derogatoria deja sin efecto los artículos del Texto articulado de la Ley especial para el Municipio de Madrid, aprobado por Decreto 1674/1963, de 11 de julio.',null),
('aux-ayto-mad:8-4fd216c7a3','aux-ayto-mad',8,'Según la Ley 22/2006, todas las instalaciones de las redes de servicios públicos de suministros y de interés general que discurran por el término municipal:','["Deben ser subterráneas, salvo urgencia o impracticabilidad técnica o económica", "Pueden ser aéreas si así lo decide la empresa suministradora", "Deben ser subterráneas solo en el distrito Centro y en los conjuntos históricos protegidos"]'::jsonb,0,'Disposición adicional tercera Ley 22/2006','Deben ser subterráneas; solo en caso de urgencia o de impracticabilidad técnica o económica puede autorizarse su instalación en superficie o aérea.',null),
('aux-ayto-mad:8-0794be4a5d','aux-ayto-mad',8,'Las tarjetas de estacionamiento para personas con discapacidad emitidas por el Ayuntamiento conforme al modelo europeo tienen validez:','["En todo el territorio estatal", "En la Comunidad de Madrid y en los municipios con convenio", "Solo en el término municipal de Madrid"]'::jsonb,0,'Disposición adicional quinta Ley 22/2006','Según la disposición adicional quinta, tienen validez en todo el territorio estatal, con independencia del municipio de procedencia del titular.',null),
('aux-ayto-mad:8-a0afabb234','aux-ayto-mad',8,'Según la Ley 22/2006, la legislación sectorial:','["Puede atribuir nuevas competencias al Pleno, pero no a la Junta de Gobierno", "Prevalece sobre esta Ley en la atribución de competencias a los órganos municipales", "No podrá alterar la distribución interna de competencias que hace esta Ley entre el Pleno, el Alcalde y la Junta de Gobierno"]'::jsonb,2,'Disposición adicional segunda Ley 22/2006','La legislación sectorial no puede alterar la distribución interna de competencias entre Pleno, Alcalde y Junta de Gobierno.',null),
('aux-ayto-mad:8-e31e277f22','aux-ayto-mad',8,'La Ley 22/2006, de Capitalidad y de Régimen Especial de Madrid, entró en vigor:','["Al día siguiente de su publicación en el BOE", "A los veinte días de su publicación en el BOE", "A los tres meses de su publicación en el BOE"]'::jsonb,1,'Disposición final segunda Ley 22/2006','Según su disposición final segunda, entró en vigor a los veinte días de su publicación en el «Boletín Oficial del Estado».',null),
('aux-ayto-mad:8-c97ff66a71','aux-ayto-mad',8,'El Ayuntamiento de Madrid regulará los distintos usos de las vías y espacios públicos urbanos con la finalidad de armonizarlos y hacerlos compatibles con:','["La seguridad vial, la movilidad y fluidez del tráfico, la protección del medio ambiente y de los espacios públicos y privados", "Las directrices de tráfico que fije cada año la Dirección General de Tráfico", "Solo la circulación de vehículos de motor, que tiene preferencia sobre los demás usos de la vía"]'::jsonb,0,'Art. 39.1 Ley 22/2006','Se trata de armonizar los usos peatonal, de circulación, de estacionamiento, deportivo y lúdico con la seguridad vial, la movilidad, el medio ambiente y la integridad de los espacios públicos y privados.',null),
('aux-ayto-mad:8-7829d80092','aux-ayto-mad',8,'Las denuncias realizadas por el personal auxiliar de la policía municipal en materia de estacionamiento:','["Carecen de valor probatorio si no las ratifica un agente de la policía municipal", "Tienen presunción de veracidad sin necesidad de ninguna otra prueba", "Se utilizan como elemento probatorio y al expediente se incorpora una imagen del vehículo"]'::jsonb,2,'Art. 44.2 Ley 22/2006','Se utilizan como elemento probatorio para acreditar los hechos, y al expediente se incorpora una imagen del vehículo (fotografía, filmación digital u otros medios).',null),
('aux-ayto-mad:8-5246c972e9','aux-ayto-mad',8,'Los órganos municipales que imponen sanciones de circulación pueden solicitar a otras Administraciones la ejecución de sus órdenes de embargo:','["Previa autorización judicial del juzgado de lo contencioso-administrativo competente", "De acuerdo con el principio de colaboración interadministrativa y los oportunos convenios", "Solo si el deudor reside fuera de la Comunidad de Madrid"]'::jsonb,1,'Art. 42 Ley 22/2006','El art. 42 lo permite de acuerdo con el principio de colaboración interadministrativa y los oportunos convenios.',null),
('aux-ayto-mad:9-38fe2c9443','aux-ayto-mad',9,'Según la Ley 22/2006, el órgano deliberante de representación política del Ayuntamiento de Madrid es:','["El Pleno", "La Junta de Portavoces", "La Junta de Gobierno"]'::jsonb,0,'Art. 7 a) Ley 22/2006','El art. 7 distingue el órgano deliberante de representación política (el Pleno) de los ejecutivos de dirección política y administrativa.',null),
('aux-ayto-mad:9-593e8ef50e','aux-ayto-mad',9,'¿Cuál de los siguientes NO es un órgano ejecutivo de dirección política y administrativa del Ayuntamiento de Madrid según la Ley 22/2006?','["Los Tenientes de Alcalde", "El Pleno", "Los miembros no electos de la Junta de Gobierno"]'::jsonb,1,'Art. 7 Ley 22/2006','Son ejecutivos el Alcalde, la Junta de Gobierno, los Tenientes de Alcalde, los Concejales con responsabilidades de gobierno, los miembros no electos de la Junta de Gobierno y los que fije el Reglamento orgánico. El Pleno es el órgano deliberante.',null),
('aux-ayto-mad:9-6bd80f3152','aux-ayto-mad',9,'La responsabilidad penal del Alcalde, los Tenientes de Alcalde y los Concejales del Ayuntamiento de Madrid será exigible conforme a lo que disponga:','["La Ley de Enjuiciamiento Criminal en exclusiva", "La Ley Orgánica del Poder Judicial", "El Reglamento Orgánico del Pleno"]'::jsonb,1,'Art. 8 Ley 22/2006','Según el art. 8 (fuero), su responsabilidad penal y la civil por el ejercicio de sus cargos es exigible conforme a la Ley Orgánica del Poder Judicial.',null),
('aux-ayto-mad:9-067f39357a','aux-ayto-mad',9,'Según la Ley 22/2006, el Pleno del Ayuntamiento de Madrid está formado por:','["El Alcalde, los Concejales y los Concejales Presidentes de Distrito con voz pero sin voto", "Los Concejales y los miembros no electos de la Junta de Gobierno", "El Alcalde y los Concejales"]'::jsonb,2,'Art. 9.1 Ley 22/2006','El Pleno está formado por el Alcalde y los Concejales, sin perjuicio de que los miembros no electos de la Junta de Gobierno asistan e intervengan en sus deliberaciones.',null),
('aux-ayto-mad:9-8b95fface0','aux-ayto-mad',9,'Las sesiones del Pleno del Ayuntamiento de Madrid son públicas, pero podrán ser secretos el debate y votación de los asuntos que puedan afectar al derecho del artículo 18.1 de la Constitución cuando así se acuerde por:','["Mayoría absoluta", "Unanimidad", "Mayoría simple"]'::jsonb,0,'Art. 9.2 Ley 22/2006','Pueden ser secretos el debate y votación de asuntos que afecten al honor, la intimidad personal y familiar y la propia imagen (art. 18.1 CE) cuando así se acuerde por mayoría absoluta.',null),
('aux-ayto-mad:9-9325a675b7','aux-ayto-mad',9,'Las Comisiones del Pleno del Ayuntamiento de Madrid están formadas por:','["Un Concejal por cada grupo político, con voto ponderado según su representación", "Los Concejales que designe el Alcalde entre los miembros de la Junta de Gobierno", "Los Concejales que designen los grupos políticos en proporción a su representación en el Pleno"]'::jsonb,2,'Art. 9.2 Ley 22/2006','El Pleno puede funcionar en Comisiones formadas por los Concejales que designen los grupos políticos en proporción a su representación en el Pleno.',null),
('aux-ayto-mad:9-e9f654f257','aux-ayto-mad',9,'Según la Ley 22/2006, quien convoca y preside las sesiones del Pleno es:','["El Alcalde, salvo que se haya elegido un Presidente del Pleno", "El Presidente del Pleno, que es siempre un Concejal distinto del Alcalde", "El Secretario General del Pleno"]'::jsonb,0,'Art. 10.1 Ley 22/2006','El Alcalde convoca y preside las sesiones del Pleno, aunque puede promover que el Pleno elija entre los Concejales un Presidente y un Vicepresidente.',null),
('aux-ayto-mad:9-7f23b00d36','aux-ayto-mad',9,'El Presidente del Pleno del Ayuntamiento de Madrid, cuando se designe, es elegido:','["Por el Pleno entre los Concejales, a iniciativa del Alcalde y al inicio del mandato", "Por el Alcalde entre los miembros de la Junta de Gobierno", "Por la Junta de Portavoces entre los Concejales de más edad"]'::jsonb,0,'Art. 10.2 Ley 22/2006','A iniciativa del Alcalde, el Pleno puede elegir entre los Concejales a su Presidente y Vicepresidente al inicio del mandato.',null),
('aux-ayto-mad:9-c9d27819b4','aux-ayto-mad',9,'En la elección del Presidente del Pleno, si ningún Concejal obtiene la mayoría absoluta en primera votación:','["Resulta elegido el Concejal de mayor edad entre los que hayan obtenido votos", "Se repite la votación hasta que alguno alcance la mayoría absoluta", "Se repite entre los dos más votados y resulta elegido el que obtenga más votos"]'::jsonb,2,'Art. 10.2 Ley 22/2006','Se repite entre los dos Concejales más votados y resulta elegido el que obtenga más votos. En caso de empate, el candidato de la lista con más votos en las elecciones municipales.',null),
('aux-ayto-mad:9-a6614d12ef','aux-ayto-mad',9,'En caso de empate en la segunda votación para elegir al Presidente del Pleno resulta elegido:','["El candidato de la lista que hubiese obtenido mayor número de votos en las elecciones municipales", "El Concejal de mayor edad de los dos candidatos empatados", "El candidato que proponga el Alcalde"]'::jsonb,0,'Art. 10.2 Ley 22/2006','El art. 10.2 resuelve el empate a favor del candidato de la lista que obtuvo más votos en las elecciones municipales.',null),
('aux-ayto-mad:9-8d795787d8','aux-ayto-mad',9,'Los cargos de Presidente y Vicepresidente del Pleno del Ayuntamiento de Madrid se mantienen:','["Hasta la finalización del mandato", "Mientras cuenten con la confianza del Alcalde", "Durante dos años, renovables"]'::jsonb,0,'Art. 10.2 Ley 22/2006','Según el art. 10.2, dichos cargos se mantendrán hasta la finalización del mandato.',null),
('aux-ayto-mad:9-4a87e89ce4','aux-ayto-mad',9,'¿Cuál de las siguientes funciones corresponde al Presidente del Pleno según la Ley 22/2006?','["Interpretar las normas de funcionamiento del Pleno y dirigir y mantener el orden de los debates", "Dictar bandos", "Nombrar y cesar a los miembros de la Junta de Gobierno y a los Tenientes de Alcalde"]'::jsonb,0,'Art. 10.3 Ley 22/2006','El Presidente del Pleno asegura la buena marcha de sus trabajos, interpreta sus normas de funcionamiento, convoca y preside las sesiones y dirige y mantiene el orden de los debates.',null),
('aux-ayto-mad:9-dcff1f0c72','aux-ayto-mad',9,'Según la Ley 22/2006, la votación de la moción de censura al Alcalde en el Pleno será:','["Secreta, mediante papeleta depositada en urna", "Pública, a mano alzada", "Pública y mediante llamamiento nominal en todo caso"]'::jsonb,2,'Art. 11.1 b) Ley 22/2006','La votación de la moción de censura y de la cuestión de confianza es pública y se realiza mediante llamamiento nominal en todo caso, y se rige por la legislación electoral general.',null),
('aux-ayto-mad:9-954d4b2d69','aux-ayto-mad',9,'¿Cuál de las siguientes atribuciones corresponde al Pleno del Ayuntamiento de Madrid?','["La aprobación del proyecto de presupuesto", "La concesión de licencias urbanísticas y de actividad", "La determinación de los recursos propios de carácter tributario"]'::jsonb,2,'Art. 11.1 g) Ley 22/2006','La determinación de los recursos propios tributarios es atribución del Pleno. La aprobación del proyecto de presupuesto y la concesión de licencias corresponden a la Junta de Gobierno (art. 17).',null),
('aux-ayto-mad:9-60387637f6','aux-ayto-mad',9,'Según la Ley 22/2006, tienen en todo caso naturaleza orgánica los reglamentos que regulen:','["Los precios públicos de los servicios municipales", "El tráfico, la circulación de vehículos y el estacionamiento regulado", "La división de la ciudad en distritos y la determinación y regulación de sus órganos"]'::jsonb,2,'Art. 11.1 c) Ley 22/2006','Tienen naturaleza orgánica, entre otras, la regulación del Pleno, la de los órganos de participación ciudadana, la división en distritos y sus órganos, la organización política y administrativa y la del Tribunal Económico-Administrativo Municipal.',null),
('aux-ayto-mad:9-5e504352f2','aux-ayto-mad',9,'¿Cuál de las siguientes materias NO figura entre las que tienen en todo caso naturaleza orgánica según el artículo 11 de la Ley 22/2006?','["La regulación de los tributos municipales", "La regulación de los órganos y procedimientos de participación ciudadana", "La regulación del Tribunal Económico-Administrativo Municipal de Madrid"]'::jsonb,0,'Art. 11.1 c) Ley 22/2006','Los tributos no están en la lista de materias orgánicas. Sí lo están el Tribunal Económico-Administrativo Municipal y la participación ciudadana.',null),
('aux-ayto-mad:9-6e1760234b','aux-ayto-mad',9,'La aprobación de la cuenta general del ejercicio corresponde, en el Ayuntamiento de Madrid:','["Al Pleno", "A la Junta de Gobierno", "Al Alcalde"]'::jsonb,0,'Art. 11.1 h) Ley 22/2006','El Pleno aprueba los presupuestos, autoriza gastos en las materias de su competencia y aprueba la cuenta general del ejercicio.',null),
('aux-ayto-mad:9-5e960f6585','aux-ayto-mad',9,'La aprobación de los estatutos de las fundaciones municipales corresponde, en el Ayuntamiento de Madrid:','["Al Pleno", "Al Alcalde mediante decreto", "A la Junta de Gobierno"]'::jsonb,0,'Art. 11.1 l) Ley 22/2006','Corresponde al Pleno aprobar los estatutos de organismos autónomos, entidades públicas empresariales y sociedades mercantiles, y también los de las fundaciones. La Junta de Gobierno aprueba solo los proyectos (art. 17.1 a).',null),
('aux-ayto-mad:9-eee710feee','aux-ayto-mad',9,'Establecer el régimen retributivo de los miembros del Pleno, del Alcalde y de los miembros de la Junta de Gobierno corresponde:','["Al Alcalde, dando cuenta al Pleno", "Al Pleno", "A la Junta de Gobierno"]'::jsonb,1,'Art. 11.1 ñ) Ley 22/2006','Es atribución del Pleno, que además no puede delegarla (art. 11.3).',null),
('aux-ayto-mad:9-ab54a1c835','aux-ayto-mad',9,'La creación de escalas, subescalas y clases de funcionarios en el Ayuntamiento de Madrid corresponde:','["Al Pleno", "A la Junta de Gobierno", "Al Alcalde"]'::jsonb,0,'Art. 11.1 p) Ley 22/2006','Corresponde al Pleno crear escalas, subescalas y clases de funcionarios y atribuirles la condición de agente de la autoridad.',null),
('aux-ayto-mad:9-dc48e90028','aux-ayto-mad',9,'Según el artículo 11.2 de la Ley 22/2006, requiere mayoría absoluta del número legal de miembros del Pleno:','["La aprobación de las ordenanzas fiscales", "La aprobación y modificación de los reglamentos de naturaleza orgánica", "La aprobación de los presupuestos generales del Ayuntamiento"]'::jsonb,1,'Art. 11.2 Ley 22/2006','Requieren mayoría absoluta los acuerdos de los párrafos c) (reglamentos orgánicos), e) (término municipal y símbolos), f) (organizaciones supramunicipales) y k) (transferencias y delegaciones), y los de planeamiento general. Los demás, mayoría simple.',null),
('aux-ayto-mad:9-6bdf5ec655','aux-ayto-mad',9,'Salvo los supuestos del artículo 11.2 de la Ley 22/2006, los acuerdos del Pleno del Ayuntamiento de Madrid se adoptan por:','["Mayoría simple de votos", "Mayoría de dos tercios", "Mayoría absoluta del número legal de miembros"]'::jsonb,0,'Art. 11.2 Ley 22/2006','Los acuerdos no incluidos en el art. 11.2 se adoptan por mayoría simple de votos.',null),
('aux-ayto-mad:9-1cc16de139','aux-ayto-mad',9,'La adopción o modificación de la bandera, enseña o escudo de la ciudad de Madrid requiere:','["Mayoría simple del Pleno", "Mayoría absoluta del número legal de miembros del Pleno", "Mayoría de dos tercios del Pleno"]'::jsonb,1,'Art. 11.2 Ley 22/2006','El párrafo e) del art. 11.1 (término municipal, bandera, enseña o escudo) es de los que exige mayoría absoluta según el art. 11.2.',null),
('aux-ayto-mad:9-e4805560fb','aux-ayto-mad',9,'Las delegaciones del Pleno del Ayuntamiento de Madrid solo pueden realizarse:','["En sus Comisiones", "En la Junta de Gobierno", "En el Alcalde y en la Junta de Gobierno"]'::jsonb,0,'Art. 11.3 Ley 22/2006','Según el art. 11.3, las delegaciones del Pleno sólo podrán realizarse en sus Comisiones.',null),
('aux-ayto-mad:9-948c6e556a','aux-ayto-mad',9,'¿Cuál de las siguientes atribuciones del Pleno SÍ puede delegarse en sus Comisiones?','["La aprobación de los reglamentos orgánicos y de sus modificaciones", "La aprobación de los presupuestos", "El ejercicio de acciones judiciales y administrativas en las materias de su competencia"]'::jsonb,2,'Art. 11.3 Ley 22/2006','No son delegables los párrafos a), b), c), e), f), g), h), j), k), m), ñ) y p). El ejercicio de acciones judiciales (párrafo n) no está en esa lista, por lo que puede delegarse en las Comisiones.',null),
('aux-ayto-mad:9-6c54aad628','aux-ayto-mad',9,'Según la Ley 22/2006, el dictamen de las normas municipales con carácter previo a su aprobación por el Pleno corresponde a:','["La Asesoría Jurídica", "La Junta de Gobierno", "Las Comisiones del Pleno"]'::jsonb,2,'Art. 12 b) Ley 22/2006','El art. 12 atribuye a las Comisiones el estudio e informe de los asuntos del Pleno, el dictamen de las normas municipales, el seguimiento de la gestión del Alcalde y las funciones que el Pleno les delegue.',null),
('aux-ayto-mad:9-2891ed359a','aux-ayto-mad',9,'La redacción y custodia de las actas del Pleno corresponde a:','["El Concejal Secretario de la Junta de Gobierno", "El Presidente del Pleno", "El Secretario General del Pleno"]'::jsonb,2,'Art. 13.1 a) Ley 22/2006','Corresponde al Secretario General del Pleno la redacción y custodia de las actas y su supervisión y autorización, con el visto bueno del Presidente del Pleno.',null),
('aux-ayto-mad:9-01906a86fd','aux-ayto-mad',9,'El Secretario General del Pleno prestará asesoramiento legal al Pleno y a las Comisiones cuando lo solicite el Alcalde, el Presidente o:','["La cuarta parte, al menos, de los Concejales", "La tercera parte, al menos, de los Concejales", "Cualquier grupo político"]'::jsonb,0,'Art. 13.1 e) Ley 22/2006','Según el art. 13.1 e), el asesoramiento legal procede cuando lo solicite el Alcalde, el Presidente, en su caso, o la cuarta parte, al menos, de los Concejales.',null),
('aux-ayto-mad:9-2a8be6398e','aux-ayto-mad',9,'Las funciones del Secretario General del Pleno quedan reservadas a:','["Funcionarios de Administración local con habilitación de carácter nacional", "Letrados del Ayuntamiento de Madrid", "Funcionarios del subgrupo A1 de cualquier Administración pública"]'::jsonb,0,'Art. 13.1 Ley 22/2006','Están reservadas a funcionarios de Administración local con habilitación de carácter nacional, y su nombramiento corresponde al Presidente del Pleno.',null),
('aux-ayto-mad:9-a4072acf3c','aux-ayto-mad',9,'El nombramiento del Secretario General del Pleno del Ayuntamiento de Madrid corresponde:','["Al Presidente del Pleno", "Al Pleno por mayoría absoluta", "A la Junta de Gobierno"]'::jsonb,0,'Art. 13.1 Ley 22/2006','Su nombramiento corresponde al Presidente del Pleno, por los sistemas previstos en las disposiciones legales aplicables.',null),
('aux-ayto-mad:9-1ab7dc8575','aux-ayto-mad',9,'La Secretaría de las Comisiones del Pleno corresponde al Secretario General del Pleno, quien:','["Podrá delegarla en un Concejal", "No podrá delegarla en ningún caso", "Podrá delegarla en un funcionario"]'::jsonb,2,'Art. 13.2 Ley 22/2006','El art. 13.2 permite que el Secretario General del Pleno delegue la Secretaría de las Comisiones en un funcionario.',null),
('aux-ayto-mad:9-6c63d054de','aux-ayto-mad',9,'Según la Ley 22/2006, la llevanza y custodia del registro de intereses de los miembros del Pleno corresponde:','["Al Secretario General del Pleno", "Al Interventor General", "Al Secretario de la Junta de Gobierno"]'::jsonb,0,'Art. 13.1 f) Ley 22/2006','El art. 13.1 f) atribuye al Secretario General del Pleno la llevanza y custodia del registro de intereses de los miembros del Pleno y de los miembros no electos de la Junta de Gobierno.',null),
('aux-ayto-mad:9-a6f2f661f4','aux-ayto-mad',9,'Según la Ley 22/2006, el Alcalde responde ante el Pleno:','["Por los actos de los órganos directivos que no haya delegado", "Por su gestión política", "Solo por la ejecución del presupuesto"]'::jsonb,1,'Art. 14.1 Ley 22/2006','El Alcalde impulsa la política municipal, dirige la acción de los restantes órganos ejecutivos, ejerce la superior dirección de la Administración y responde ante el Pleno por su gestión política.',null),
('aux-ayto-mad:9-f61da38dd0','aux-ayto-mad',9,'Decidir los empates con voto de calidad en todos los órganos municipales colegiados en los que participe corresponde a:','["El Alcalde", "El Teniente de Alcalde de mayor rango", "El Presidente del Pleno"]'::jsonb,0,'Art. 14.3 c) Ley 22/2006','Es atribución del Alcalde (art. 14.3 c) y, además, indelegable (art. 14.4).',null),
('aux-ayto-mad:9-c663865df2','aux-ayto-mad',9,'Según la Ley 22/2006, el nombramiento del personal funcionario, laboral y eventual al servicio del Ayuntamiento de Madrid corresponde:','["Al Pleno", "Al Alcalde", "A la Junta de Gobierno"]'::jsonb,1,'Art. 14.3 ñ) Ley 22/2006','El art. 14.3 ñ) atribuye al Alcalde el nombramiento del personal funcionario, laboral y eventual. La separación del servicio de los funcionarios corresponde a la Junta de Gobierno (art. 17.1 m).',null),
('aux-ayto-mad:9-53e12022d1','aux-ayto-mad',9,'La ordenación de pagos en el Ayuntamiento de Madrid corresponde, según la Ley 22/2006:','["A la Junta de Gobierno", "Al Alcalde", "A la Tesorería"]'::jsonb,1,'Art. 14.3 n) Ley 22/2006','La ordenación de pagos es una atribución del Alcalde (art. 14.3 n), que puede delegar.',null),
('aux-ayto-mad:9-72405995ca','aux-ayto-mad',9,'La firma de convenios corresponde, según la Ley 22/2006:','["Al Pleno", "Al Alcalde", "A la Asesoría Jurídica"]'::jsonb,1,'Art. 14.3 k) Ley 22/2006','El art. 14.3 k) atribuye al Alcalde la firma de convenios.',null),
('aux-ayto-mad:9-27fe12855d','aux-ayto-mad',9,'Cuando el Alcalde adopte medidas en casos de extraordinaria y urgente necesidad deberá:','["Someterlas a ratificación de la Junta de Gobierno en diez días", "Comunicarlas a la Delegación del Gobierno", "Dar cuenta inmediata al Pleno"]'::jsonb,2,'Art. 14.3 f) Ley 22/2006','El Alcalde adopta las medidas necesarias en casos de extraordinaria y urgente necesidad, dando cuenta inmediata al Pleno. Esta atribución es indelegable.',null),
('aux-ayto-mad:9-48816f2d6c','aux-ayto-mad',9,'En caso de urgencia, el Alcalde puede ejercer acciones judiciales en materias de competencia del Pleno:','["Solo si lo autoriza la Asesoría Jurídica", "Dando cuenta al Pleno en la primera sesión que celebre para su ratificación", "Previa autorización de la Junta de Portavoces del Pleno"]'::jsonb,1,'Art. 14.3 i) Ley 22/2006','El art. 14.3 i) lo permite en caso de urgencia, dando cuenta al Pleno en la primera sesión que celebre para su ratificación.',null),
('aux-ayto-mad:9-aeeb3f2caf','aux-ayto-mad',9,'¿Cuál de las siguientes atribuciones del Alcalde es indelegable según la Ley 22/2006?','["Dictar bandos", "La firma de convenios", "La ordenación de pagos"]'::jsonb,0,'Art. 14.4 Ley 22/2006','No son delegables las de los párrafos b), c), d), e) en cuanto a los bandos y f). La firma de convenios y la ordenación de pagos sí pueden delegarse.',null),
('aux-ayto-mad:9-e42f363a40','aux-ayto-mad',9,'Las atribuciones del Alcalde de determinar el programa de acción política municipal y de acordar el número y denominación de las áreas solo son delegables en:','["La Junta de Gobierno", "Los Tenientes de Alcalde", "Los Concejales Presidentes de Distrito"]'::jsonb,0,'Art. 14.4 Ley 22/2006','Según el art. 14.4, las atribuciones de los párrafos a) y h) sólo serán delegables en la Junta de Gobierno.',null),
('aux-ayto-mad:9-fb52e0d7c5','aux-ayto-mad',9,'El Alcalde puede delegar o desconcentrar sus competencias delegables mediante:','["Acuerdo del Pleno", "Decreto", "Bando"]'::jsonb,1,'Art. 14.4 Ley 22/2006','El art. 14.4 dice que el Alcalde podrá delegar o desconcentrar mediante decreto.',null),
('aux-ayto-mad:9-5741ebb953','aux-ayto-mad',9,'Los Tenientes de Alcalde del Ayuntamiento de Madrid se nombran de entre:','["Todos los Concejales del Pleno, sean o no de la Junta de Gobierno", "Los miembros de la Junta de Gobierno, sean o no Concejales", "Los miembros de la Junta de Gobierno que ostenten la condición de Concejal"]'::jsonb,2,'Art. 15 Ley 22/2006','El Alcalde puede nombrarlos de entre los miembros de la Junta de Gobierno que sean Concejales. Le sustituyen por orden de nombramiento en caso de vacante, ausencia o enfermedad.',null),
('aux-ayto-mad:9-48c26b75b0','aux-ayto-mad',9,'Los Tenientes de Alcalde sustituyen al Alcalde en los casos de vacante, ausencia o enfermedad:','["Por orden de antigüedad como Concejales", "Según decida en cada caso la Junta de Gobierno", "Por el orden de su nombramiento"]'::jsonb,2,'Art. 15 Ley 22/2006','Según el art. 15, le sustituyen por el orden de su nombramiento.',null),
('aux-ayto-mad:9-6319927559','aux-ayto-mad',9,'El número de miembros de la Junta de Gobierno del Ayuntamiento de Madrid, además del Alcalde, no podrá exceder de:','["Un tercio del número legal de miembros del Pleno", "Una cuarta parte del número legal de miembros del Pleno", "La mitad del número legal de miembros del Pleno"]'::jsonb,0,'Art. 16.2 Ley 22/2006','El Alcalde nombra y separa libremente a sus miembros, cuyo número no puede exceder de un tercio del número legal de miembros del Pleno, además del Alcalde.',null),
('aux-ayto-mad:9-375f1675f4','aux-ayto-mad',9,'Según la Ley 22/2006, la Junta de Gobierno del Ayuntamiento de Madrid responde políticamente ante el Pleno:','["De forma solidaria, que excluye la responsabilidad individual", "De forma solidaria, sin perjuicio de la responsabilidad directa de cada uno de sus miembros", "Solo de forma individual, por la gestión de cada miembro"]'::jsonb,1,'Art. 16.3 Ley 22/2006','La Junta de Gobierno responde políticamente ante el Pleno de forma solidaria, sin perjuicio de la responsabilidad directa de cada miembro por su gestión.',null),
('aux-ayto-mad:9-66ac17265a','aux-ayto-mad',9,'La Secretaría de la Junta de Gobierno del Ayuntamiento de Madrid corresponde a:','["El Secretario General del Pleno", "Uno de sus miembros, designado por el Alcalde", "Un funcionario con habilitación de carácter nacional"]'::jsonb,1,'Art. 16.4 Ley 22/2006','Corresponde a uno de sus miembros, designado por el Alcalde, que redacta las actas y certifica los acuerdos.',null),
('aux-ayto-mad:9-e9c5c70f54','aux-ayto-mad',9,'Las sesiones de la Junta de Gobierno del Ayuntamiento de Madrid son:','["Secretas, aunque podrán ser públicas por acuerdo de la propia Junta", "Públicas, salvo que el Alcalde acuerde lo contrario por razón del asunto", "Siempre secretas, sin excepción"]'::jsonb,0,'Art. 16.5 Ley 22/2006','Son secretas, pero pueden ser públicas por acuerdo de la propia Junta cuando la naturaleza de los asuntos lo haga procedente.',null),
('aux-ayto-mad:9-a1041cdd88','aux-ayto-mad',9,'A las sesiones de la Junta de Gobierno podrán asistir los concejales que no pertenezcan a ella:','["Nunca, porque las sesiones son secretas", "Siempre, con voz pero sin voto, si lo comunican con antelación", "Cuando sean convocados expresamente por el Alcalde"]'::jsonb,2,'Art. 16.5 Ley 22/2006','Pueden asistir los concejales no pertenecientes a la Junta y los titulares de órganos directivos cuando sean convocados expresamente por el Alcalde.',null),
('aux-ayto-mad:9-ec1eab4074','aux-ayto-mad',9,'¿A quién corresponde la aprobación del proyecto de presupuesto del Ayuntamiento de Madrid?','["Al Pleno", "A la Junta de Gobierno", "Al Alcalde"]'::jsonb,1,'Art. 17.1 c) Ley 22/2006','La Junta de Gobierno aprueba el proyecto de presupuesto (art. 17.1 c), indelegable; el Pleno aprueba el presupuesto (art. 11.1 h).',null),
('aux-ayto-mad:9-9e6af2f682','aux-ayto-mad',9,'El ejercicio de la potestad sancionadora y la concesión de licencias corresponde, en el Ayuntamiento de Madrid:','["Al Pleno", "A la Junta de Gobierno", "Al Alcalde"]'::jsonb,1,'Art. 17.1 k) Ley 22/2006','El art. 17.1 k) atribuye a la Junta de Gobierno el ejercicio de la potestad sancionadora y la concesión de licencias.',null),
('aux-ayto-mad:9-6c99890a2f','aux-ayto-mad',9,'Aprobar la relación de puestos de trabajo y la oferta de empleo público del Ayuntamiento de Madrid corresponde:','["Al Alcalde", "Al Pleno", "A la Junta de Gobierno"]'::jsonb,2,'Art. 17.1 m) Ley 22/2006','El art. 17.1 m) atribuye a la Junta de Gobierno la RPT, las retribuciones, la oferta de empleo público, las bases de las convocatorias y la separación del servicio de los funcionarios, entre otras.',null),
('aux-ayto-mad:9-4f321a12bc','aux-ayto-mad',9,'La aprobación de las modificaciones presupuestarias en el Ayuntamiento de Madrid corresponde a la Junta de Gobierno, salvo:','["Las que superen el 10 % del presupuesto inicial, que corresponden al Pleno por mayoría absoluta", "Las transferencias de crédito entre áreas de gobierno, que corresponden al Alcalde", "La concesión de un crédito extraordinario o un suplemento de crédito, que corresponde al Pleno"]'::jsonb,2,'Art. 17.1 g) Ley 22/2006','La Junta de Gobierno aprueba todas las modificaciones presupuestarias, salvo el crédito extraordinario o el suplemento de crédito, que corresponden en todo caso al Pleno.',null),
('aux-ayto-mad:9-3fac849e7d','aux-ayto-mad',9,'La designación de los miembros de las mesas de contratación y sus presidentes corresponde, en el Ayuntamiento de Madrid:','["A la Junta de Gobierno", "Al Alcalde", "Al Pleno"]'::jsonb,0,'Art. 17.1 e) Ley 22/2006','La Junta de Gobierno tiene las competencias de gestión en materia de contratos, concesiones y patrimonio, incluida la designación de los miembros de las mesas de contratación.',null),
('aux-ayto-mad:9-25ee8f0a64','aux-ayto-mad',9,'La Junta de Gobierno aprueba los proyectos de ordenanzas y reglamentos, incluidos los orgánicos, con excepción de:','["Las ordenanzas fiscales y los precios públicos", "Los reglamentos de los distritos", "Las normas reguladoras del Pleno y sus Comisiones"]'::jsonb,2,'Art. 17.1 a) Ley 22/2006','Según el art. 17.1 a), la excepción son las normas reguladoras del Pleno y sus Comisiones.',null),
('aux-ayto-mad:9-15f616c8ad','aux-ayto-mad',9,'¿Cuál de las siguientes atribuciones de la Junta de Gobierno es indelegable según la Ley 22/2006?','["La concesión de licencias", "La aprobación del proyecto de presupuesto", "La creación, modificación o supresión de ficheros de datos personales"]'::jsonb,1,'Art. 17.2 Ley 22/2006','No son delegables las de los párrafos a), b), c), d), h) e i): proyectos normativos, planes y directrices, proyecto de presupuesto, planeamiento, organización y estructura, y acciones judiciales.',null),
('aux-ayto-mad:9-d8a3c2e12b','aux-ayto-mad',9,'Para ser titular o miembro de un órgano ejecutivo de dirección política y administrativa del Ayuntamiento de Madrid se requiere en todo caso:','["Tener la condición de funcionario de carrera", "Ser Concejal electo en las últimas elecciones municipales", "Ser mayor de edad, disfrutar del derecho de sufragio activo y pasivo en las elecciones municipales y no estar inhabilitado por sentencia firme"]'::jsonb,2,'Art. 18.1 Ley 22/2006','El art. 18.1 exige ser mayor de edad, disfrutar de los derechos de sufragio activo y pasivo en las elecciones municipales y no estar inhabilitado por sentencia judicial firme.',null),
('aux-ayto-mad:9-29306748e1','aux-ayto-mad',9,'El Alcalde puede nombrar miembros de la Junta de Gobierno que no sean concejales. Sus derechos económicos y prestaciones sociales serán los que establezca:','["La Junta de Gobierno", "El Alcalde en el decreto de nombramiento", "El Pleno"]'::jsonb,2,'Art. 16.2 Ley 22/2006','Según el art. 16.2, sus derechos económicos y prestaciones sociales serán los que establezca el Pleno.',null),
('aux-ayto-mad:9-86ac71e031','aux-ayto-mad',9,'La revisión de oficio de los propios actos y disposiciones de carácter general y la declaración de lesividad de sus actos corresponde, sin posibilidad de delegación:','["Al Pleno", "A la Asesoría Jurídica", "A la Junta de Gobierno"]'::jsonb,0,'Art. 11.1 m) y 11.3 Ley 22/2006','El Pleno revisa de oficio sus propios actos y disposiciones generales y declara la lesividad de sus actos (párrafo m), atribución que no puede delegar. El Alcalde y la Junta de Gobierno hacen lo mismo con sus propios actos.',null),
('aux-ayto-mad:10-5018604bdf','aux-ayto-mad',10,'Según la Ley 22/2006, la Administración del Ayuntamiento de Madrid se organiza y actúa de acuerdo con los principios de:','["Legalidad, autonomía, solidaridad, subsidiariedad y lealtad institucional", "Jerarquía, eficacia, descentralización funcional, desconcentración, coordinación y servicio al ciudadano", "Jerarquía, competencia, unidad de gestión, publicidad, transparencia y participación ciudadana"]'::jsonb,1,'Art. 19.1 Ley 22/2006','El art. 19.1 enumera los principios de jerarquía, eficacia, descentralización funcional, desconcentración, coordinación y servicio al ciudadano, con sometimiento pleno a la Ley y al Derecho.',null),
('aux-ayto-mad:10-376d50a27c','aux-ayto-mad',10,'En sus relaciones con los ciudadanos, la Administración del Ayuntamiento de Madrid actúa de conformidad con los principios de:','["Transparencia y participación", "Jerarquía y desconcentración", "Información, colaboración y coordinación"]'::jsonb,0,'Art. 19.3 Ley 22/2006','En sus relaciones con otras administraciones se rige por la información, colaboración, coordinación y respeto competencial; con los ciudadanos, por la transparencia y la participación.',null),
('aux-ayto-mad:10-de628a381e','aux-ayto-mad',10,'La Administración del Ayuntamiento de Madrid sirve con objetividad a los intereses generales de la ciudad:','["Bajo la superior dirección del Alcalde", "Bajo la superior dirección de la Junta de Gobierno", "Bajo la superior dirección del Pleno"]'::jsonb,0,'Art. 19.2 Ley 22/2006','Según el art. 19.2, actúa bajo la superior dirección del Alcalde.',null),
('aux-ayto-mad:10-7cebee58f0','aux-ayto-mad',10,'El órgano directivo al que corresponde el control interno de la gestión económica y financiera del sector público municipal y la función contable es:','["La Intervención General", "La Tesorería", "El Tribunal Económico-Administrativo Municipal"]'::jsonb,0,'Art. 23.1 Ley 22/2006','La Intervención General ejerce el control interno y la función contable con plena autonomía respecto de las autoridades cuya gestión controle.',null),
('aux-ayto-mad:10-dee22ad1ac','aux-ayto-mad',10,'La Intervención General del Ayuntamiento de Madrid ejerce su función:','["Con plena autonomía respecto de las autoridades y entidades cuya gestión controle", "Bajo la dependencia jerárquica del Alcalde y de la Junta de Gobierno", "Bajo la dependencia del Pleno, al que rinde cuentas cada trimestre"]'::jsonb,0,'Art. 23.1 Ley 22/2006','El art. 23.1 dice que la función se ejercerá con plena autonomía respecto de las autoridades y demás entidades cuya gestión controle.',null),
('aux-ayto-mad:10-df9ab65701','aux-ayto-mad',10,'El nombramiento del titular de la Intervención General del Ayuntamiento de Madrid corresponde a:','["La Junta de Gobierno", "El Alcalde", "El Pleno"]'::jsonb,0,'Art. 23.2 Ley 22/2006','Debe ser un funcionario de Administración local con habilitación de carácter nacional, nombrado por la Junta de Gobierno previa convocatoria pública.',null),
('aux-ayto-mad:10-1435d073b4','aux-ayto-mad',10,'El titular de la Tesorería del Ayuntamiento de Madrid deberá ser:','["Un funcionario del Cuerpo Superior de Inspectores de Hacienda del Estado", "Un funcionario de Administración local con habilitación de carácter nacional", "Cualquier funcionario del Ayuntamiento del subgrupo A1"]'::jsonb,1,'Art. 24.2 Ley 22/2006','Igual que el Interventor General, el Tesorero debe ser funcionario con habilitación de carácter nacional, nombrado por la Junta de Gobierno previa convocatoria pública.',null),
('aux-ayto-mad:10-2f0e8f7942','aux-ayto-mad',10,'La gestión de los recursos y disponibilidades financieras del Ayuntamiento de Madrid corresponde a:','["La Agencia Tributaria Madrid", "La Intervención General", "La Tesorería"]'::jsonb,2,'Art. 24.1 Ley 22/2006','La Tesorería es el órgano directivo que gestiona los recursos y disponibilidades financieras en los términos del Texto Refundido de la Ley Reguladora de las Haciendas Locales.',null),
('aux-ayto-mad:10-fc46022f1f','aux-ayto-mad',10,'La provisión de los puestos de Interventor General y de Tesorero del Ayuntamiento de Madrid requiere en todo caso:','["La aprobación de la Comunidad de Madrid", "El informe favorable del Pleno", "Una previa convocatoria pública"]'::jsonb,2,'Arts. 23.2 y 24.2 Ley 22/2006','La provisión se efectúa por los sistemas del art. 99 de la Ley 7/1985 y requiere, en todo caso, una previa convocatoria pública.',null),
('aux-ayto-mad:10-e779136066','aux-ayto-mad',10,'Conoce y resuelve las reclamaciones sobre la aplicación de los tributos y la imposición de sanciones tributarias del Ayuntamiento de Madrid:','["El Tribunal Económico-Administrativo Municipal de Madrid", "La Agencia Tributaria Madrid", "El Tribunal Económico-Administrativo Regional de Madrid"]'::jsonb,0,'Art. 25.1 a) Ley 22/2006','Corresponde al Tribunal Económico-Administrativo Municipal de Madrid.',null),
('aux-ayto-mad:10-89d5bb8412','aux-ayto-mad',10,'Contra la resolución del Tribunal Económico-Administrativo Municipal de Madrid solo cabe:','["Reclamación ante el Tribunal Económico-Administrativo Central", "Recurso de alzada ante el Pleno", "Recurso contencioso-administrativo"]'::jsonb,2,'Art. 25.2 Ley 22/2006','Su resolución pone fin a la vía administrativa y contra ella solo cabe recurso contencioso-administrativo.',null),
('aux-ayto-mad:10-89995e8cf9','aux-ayto-mad',10,'Antes de la reclamación ante el Tribunal Económico-Administrativo Municipal, el interesado puede presentar:','["Con carácter obligatorio, el recurso de reposición del artículo 14.2 del TRLRHL", "Con carácter potestativo, el recurso de reposición del artículo 14.2 del TRLRHL", "Recurso de alzada ante la Junta de Gobierno"]'::jsonb,1,'Art. 25.3 Ley 22/2006','El recurso de reposición previo es potestativo; contra su resolución cabe reclamación económico-administrativa ante el Tribunal municipal.',null),
('aux-ayto-mad:10-9c98c38b8c','aux-ayto-mad',10,'El Tribunal Económico-Administrativo Municipal de Madrid estará constituido por:','["Cinco miembros", "Un número impar de miembros, con un mínimo de tres", "Un número impar de miembros, con un mínimo de cinco"]'::jsonb,1,'Art. 25.4 Ley 22/2006','Está constituido por un número impar de miembros, con un mínimo de tres, designados por el Pleno.',null),
('aux-ayto-mad:10-9a0dd781a4','aux-ayto-mad',10,'Los miembros del Tribunal Económico-Administrativo Municipal de Madrid son designados por:','["La Junta de Gobierno, entre funcionarios del Ayuntamiento", "El Pleno, por mayoría absoluta de sus miembros, entre personas de reconocida competencia técnica", "El Alcalde, entre personas de reconocida competencia técnica, dando cuenta al Pleno"]'::jsonb,1,'Art. 25.4 Ley 22/2006','Los designa el Pleno, con el voto favorable de la mayoría absoluta de sus miembros, entre personas de reconocida competencia técnica.',null),
('aux-ayto-mad:10-0667e9a216','aux-ayto-mad',10,'¿Cuál de las siguientes es causa de cese de los miembros del Tribunal Económico-Administrativo Municipal de Madrid?','["El fin del mandato de la Corporación que los designó", "La pérdida de confianza del Alcalde", "Ser condenados mediante sentencia firme por delito doloso"]'::jsonb,2,'Art. 25.4 Ley 22/2006','Cesan a petición propia, por acuerdo del Pleno con la misma mayoría que para su nombramiento, por condena firme por delito doloso o por sanción firme por falta disciplinaria muy grave o grave.',null),
('aux-ayto-mad:10-ccdeae5c8a','aux-ayto-mad',10,'El funcionamiento del Tribunal Económico-Administrativo Municipal de Madrid se basará en criterios de:','["Independencia técnica, celeridad y gratuidad", "Contradicción, oralidad y publicidad", "Jerarquía, eficacia y economía"]'::jsonb,0,'Art. 25.5 Ley 22/2006','El art. 25.5 cita los criterios de independencia técnica, celeridad y gratuidad.',null),
('aux-ayto-mad:10-9ac8ca9368','aux-ayto-mad',10,'El expediente disciplinario de un miembro del Tribunal Económico-Administrativo Municipal de Madrid solo puede incoarlo y resolverlo:','["El Presidente del propio Tribunal", "La Junta de Gobierno", "El Pleno"]'::jsonb,2,'Art. 25.4 Ley 22/2006','Según el art. 25.4, solamente el Pleno podrá acordar la incoación y la resolución del correspondiente expediente disciplinario.',null),
('aux-ayto-mad:10-13c28d15a9','aux-ayto-mad',10,'Según la Ley 22/2006, el ente autónomo de gestión tributaria del Ayuntamiento de Madrid:','["Debe crearlo obligatoriamente la Junta de Gobierno", "Lo crea la Comunidad de Madrid mediante ley a propuesta del Ayuntamiento", "Puede crearlo el Pleno para la gestión integral del sistema tributario municipal"]'::jsonb,2,'Art. 26.1 Ley 22/2006','El Pleno podrá crear un ente autónomo de gestión tributaria que ejerza como propias las competencias municipales de gestión tributaria. En Madrid es la Agencia Tributaria Madrid.',null),
('aux-ayto-mad:10-80eae3c61c','aux-ayto-mad',10,'La función de recaudación del ente autónomo de gestión tributaria del Ayuntamiento de Madrid la ejerce:','["Su titular y los funcionarios adscritos al mismo", "La Tesorería municipal en exclusiva", "La Agencia Estatal de Administración Tributaria por convenio"]'::jsonb,0,'Art. 26.3 Ley 22/2006','Según el art. 26.3, la recaudación la ejerce el titular del ente y los funcionarios adscritos al mismo.',null),
('aux-ayto-mad:10-93c7c26067','aux-ayto-mad',10,'La gestión integral del sistema tributario municipal de Madrid se rige por los principios de:','["Legalidad, publicidad y transparencia", "Capacidad económica, progresividad y no confiscatoriedad", "Eficiencia, suficiencia, agilidad y unidad en la gestión"]'::jsonb,2,'Art. 26.1 Ley 22/2006','El art. 26.1 cita los principios de eficiencia, suficiencia, agilidad y unidad en la gestión.',null),
('aux-ayto-mad:10-fb816649e7','aux-ayto-mad',10,'La asistencia jurídica al Alcalde, a la Junta de Gobierno y a los órganos directivos del Ayuntamiento de Madrid corresponde a:','["El Secretario General del Pleno", "Los Abogados del Estado, mediante convenio con el Ministerio de Justicia", "Los Letrados del Ayuntamiento de Madrid integrados en la Asesoría Jurídica"]'::jsonb,2,'Art. 28.1 Ley 22/2006','Comprende el asesoramiento jurídico y la representación y defensa en juicio del Ayuntamiento y de sus organismos autónomos y entidades públicas empresariales.',null),
('aux-ayto-mad:10-8e3536c244','aux-ayto-mad',10,'El titular de la Asesoría Jurídica del Ayuntamiento de Madrid es nombrado y separado por:','["La Junta de Gobierno", "El Pleno", "El Alcalde"]'::jsonb,0,'Art. 28.2 Ley 22/2006','La Asesoría Jurídica es un órgano directivo cuyo titular nombra y separa la Junta de Gobierno.',null),
('aux-ayto-mad:10-88d08e081f','aux-ayto-mad',10,'El titular de la Asesoría Jurídica del Ayuntamiento de Madrid debe ser elegido entre:','["Abogados en ejercicio con más de diez años de experiencia profesional", "Letrados del Ayuntamiento con más de cinco años de servicio", "Funcionarios a los que se exija el título de licenciado en Derecho o funcionarios con habilitación de carácter nacional"]'::jsonb,2,'Art. 28.2 Ley 22/2006','Se elige entre funcionarios del Estado, de las CCAA o de los entes locales a los que se exija la licenciatura en Derecho, o entre funcionarios de Administración local con habilitación de carácter nacional.',null),
('aux-ayto-mad:10-03513857e9','aux-ayto-mad',10,'Los Letrados del Ayuntamiento de Madrid pueden asumir el asesoramiento y la defensa en juicio de las sociedades mercantiles locales:','["En todo caso y de forma gratuita", "Mediante la suscripción del oportuno convenio con compensación económica a la Hacienda municipal", "Nunca, porque solo defienden al Ayuntamiento y a sus organismos autónomos"]'::jsonb,1,'Art. 28.5 Ley 22/2006','El art. 28.5 lo permite mediante convenio en el que se fija la compensación económica a abonar a la Hacienda municipal.',null),
('aux-ayto-mad:10-6c39509885','aux-ayto-mad',10,'Los Abogados del Estado pueden representar, defender y asesorar al Ayuntamiento de Madrid:','["Solo ante el Tribunal Constitucional y previa autorización del Pleno", "En todo caso, cuando lo pida el Alcalde", "Mediante convenio de colaboración, a propuesta o previa audiencia del titular de la Asesoría Jurídica"]'::jsonb,2,'Art. 28.6 Ley 22/2006','El art. 28.6 lo permite mediante convenio, a propuesta o previa audiencia del titular de la Asesoría Jurídica.',null),
('aux-ayto-mad:10-6f2afdefea','aux-ayto-mad',10,'Los Letrados del Ayuntamiento de Madrid pueden asumir la defensa en juicio de las autoridades y empleados municipales cuando:','["El empleado sea demandante, pero no cuando sea demandado o acusado", "Los procedimientos se sigan por actos u omisiones relacionados con el cargo y no exista conflicto de intereses", "Lo solicite el empleado, cualquiera que sea el motivo del procedimiento"]'::jsonb,1,'Art. 29 Ley 22/2006','En los términos que fije el Pleno, pueden defenderlos cualquiera que sea su posición procesal, si el procedimiento se debe a actos u omisiones relacionados con el cargo y no hay conflicto de intereses.',null),
('aux-ayto-mad:10-1489ac7bb3','aux-ayto-mad',10,'Ante los juzgados y tribunales, los Letrados del Ayuntamiento de Madrid tienen los derechos, deberes y prerrogativas establecidos para:','["Los abogados colegiados en ejercicio ante esos juzgados", "Los letrados de las Comunidades Autónomas", "La representación y defensa en juicio de la Administración General del Estado"]'::jsonb,2,'Art. 30.1 Ley 22/2006','Según el art. 30.1, tienen los mismos derechos, deberes y prerrogativas que la asistencia jurídica de la Administración General del Estado.',null),
('aux-ayto-mad:10-fa91efb36a','aux-ayto-mad',10,'Además de los supuestos del artículo 52.2 de la LBRL, ponen fin a la vía administrativa en el Ayuntamiento de Madrid los actos dictados por los órganos municipales cuando ejerzan competencias atribuidas por el Alcalde y la Junta de Gobierno mediante:','["Desconcentración", "Encomienda de gestión", "Delegación"]'::jsonb,0,'Art. 53 Ley 22/2006','El art. 53 añade los actos dictados en ejercicio de competencias atribuidas por el Alcalde y la Junta de Gobierno mediante la técnica de la desconcentración.',null),
('aux-ayto-mad:10-bc4339d686','aux-ayto-mad',10,'Según la Ley 22/2006, la práctica de las notificaciones de los actos del Ayuntamiento de Madrid:','["Podrá encomendarse a personal auxiliar municipal habilitado al efecto", "Solo puede hacerla un agente de la policía municipal", "Corresponde en exclusiva al operador designado para prestar el servicio postal universal"]'::jsonb,0,'Art. 50.1 Ley 22/2006','El art. 50.1 permite encomendarla a personal auxiliar municipal habilitado; sus notificaciones dejan constancia fehaciente de la recepción o el rechazo (art. 50.2).',null),
('aux-ayto-mad:10-307cfca8f1','aux-ayto-mad',10,'Según la Ley 22/2006, el tablón de edictos del Ayuntamiento de Madrid podrá realizarse a través de medios electrónicos, garantizando el libre acceso mediante terminales en:','["Las oficinas de Correos de la ciudad", "Las sedes de los grupos políticos municipales y de las asociaciones vecinales", "Todas las Juntas de Distrito y dependencias municipales"]'::jsonb,2,'Art. 51.2 Ley 22/2006','Debe garantizarse el libre acceso con terminales de acceso al tablón en todas las Juntas de Distrito y dependencias municipales.',null),
('aux-ayto-mad:10-49bea4ba67','aux-ayto-mad',10,'El Alcalde y la Junta de Gobierno pueden imponer multas coercitivas como medio de ejecución forzosa de sus actos de hasta:','["1.500 euros", "3.000 euros", "6.000 euros"]'::jsonb,1,'Art. 52.1 Ley 22/2006','Pueden imponer multas coercitivas de hasta 3.000 euros, actualizables con el IPC, reiteradas por periodos de 15 días.',null),
('aux-ayto-mad:10-c10d3676ec','aux-ayto-mad',10,'Las multas coercitivas del artículo 52 de la Ley 22/2006 pueden reiterarse por cuantos períodos sean suficientes para cumplir lo ordenado, de:','["30 días", "15 días", "10 días"]'::jsonb,1,'Art. 52.1 Ley 22/2006','Según el art. 52.1, se reiteran por cuantos períodos de 15 días sean suficientes para cumplir lo ordenado.',null),
('aux-ayto-mad:10-970349e244','aux-ayto-mad',10,'Según la Ley 22/2006, la multa coercitiva es:','["Incompatible con la sanción por los mismos hechos", "Independiente de las sanciones que puedan imponerse y compatible con ellas", "Una sanción administrativa más grave que la multa ordinaria por infringir la ordenanza"]'::jsonb,1,'Art. 52.2 Ley 22/2006','La multa coercitiva es independiente de las sanciones y compatible con ellas.',null),
('aux-ayto-mad:10-a4e64368e5','aux-ayto-mad',10,'En la imposición de sanciones por incumplir las ordenanzas, la Ley 22/2006 permite sustituir la sanción económica por:','["Una amonestación pública en el Boletín del Ayuntamiento con el nombre del infractor", "El doble de la sanción en días de arresto domiciliario", "Trabajos en beneficio de la comunidad o asistencia obligatoria a cursos de formación, entre otras medidas"]'::jsonb,2,'Art. 52.3 Ley 22/2006','Por resolución motivada puede sustituirse por trabajos en beneficio de la comunidad, cursos de formación, sesiones individualizadas u otras medidas de sensibilización o reparación.',null),
('aux-ayto-mad:10-7de24dfdc4','aux-ayto-mad',10,'Las funciones de fe pública de los actos de los órganos unipersonales del Ayuntamiento de Madrid, salvo las atribuidas a determinados secretarios, las ejercen los titulares de órganos directivos o funcionarios que determine:','["La Junta de Gobierno", "El Pleno", "El Secretario General del Pleno"]'::jsonb,0,'Art. 55 Ley 22/2006','Según el art. 55, las ejercen los titulares de órganos directivos o funcionarios que determine la Junta de Gobierno.',null),
('aux-ayto-mad:10-a772c4a90f','aux-ayto-mad',10,'Según la Ley 22/2006, el Ayuntamiento de Madrid podrá dotarse de un Boletín propio:','["Con formato electrónico o informático", "Solo en formato papel", "Que sustituye la publicación de sus normas en el Boletín Oficial de la Comunidad de Madrid"]'::jsonb,0,'Art. 51.1 Ley 22/2006','Puede dotarse de un Boletín propio electrónico o informático, sin perjuicio de la obligación de publicar en los diarios oficiales correspondientes.',null),
('aux-ayto-mad:10-933ffd5c38','aux-ayto-mad',10,'Corresponde también a los Letrados del Ayuntamiento de Madrid la representación y defensa en juicio:','["Del Pleno, en los términos que se determinen por este", "De los grupos políticos municipales", "De los vecinos que lo soliciten frente a otras administraciones"]'::jsonb,0,'Art. 28.4 Ley 22/2006','El art. 28.4 les atribuye también la representación y defensa en juicio del Pleno, en los términos que este determine.',null),
('aux-ayto-mad:10-607b10e5a6','aux-ayto-mad',10,'Según la Ley 22/2006, la organización de la Administración del Ayuntamiento de Madrid corresponde:','["A la Comunidad de Madrid, mediante ley", "Al Estado, mediante real decreto", "Al propio Ayuntamiento, en el marco de esta Ley"]'::jsonb,2,'Art. 20 Ley 22/2006','El art. 20 dice que la organización de la Administración del Ayuntamiento de Madrid corresponde al mismo en el marco de esta Ley.',null),
('aux-ayto-mad:10-b27bcd30b8','aux-ayto-mad',10,'El ente autónomo de gestión tributaria, cuando se crea, ejerce las competencias municipales de gestión en materia tributaria:','["Por delegación del Alcalde", "Como propias", "Por encomienda de gestión de la Tesorería"]'::jsonb,1,'Art. 26.1 Ley 22/2006','El art. 26.1 dice que es responsable de ejercer como propias las competencias municipales de gestión tributaria.',null),
('aux-ayto-mad:10-6cf8a13637','aux-ayto-mad',10,'El Tribunal Económico-Administrativo Municipal de Madrid también puede, si se lo piden los órganos municipales competentes:','["Aprobar las ordenanzas fiscales", "Dictaminar los proyectos de ordenanzas fiscales", "Liquidar los tributos municipales"]'::jsonb,1,'Art. 25.1 c) Ley 22/2006','El art. 25.1 c) prevé que elabore estudios y propuestas tributarias y dictamine los proyectos de ordenanzas fiscales cuando se lo pidan los órganos competentes.',null),
('aux-ayto-mad:11-16b701a5ec','aux-ayto-mad',11,'¿Cuál de los siguientes es un órgano superior, y no directivo, en los municipios de gran población?','["El interventor general municipal", "El Secretario General del Pleno", "Los miembros de la Junta de Gobierno Local"]'::jsonb,2,'Art. 130.1 LBRL','Son órganos superiores el Alcalde y los miembros de la Junta de Gobierno Local. El Secretario General del Pleno y el interventor general son órganos directivos.',null),
('aux-ayto-mad:11-01bcfdbae6','aux-ayto-mad',11,'El nombramiento de los coordinadores generales y directores generales de los municipios de gran población debe hacerse, como regla general, entre funcionarios de carrera del subgrupo:','["A1", "A1 o A2", "A2"]'::jsonb,0,'Art. 130.3 LBRL','Se nombran entre funcionarios de carrera del subgrupo A1, salvo que el Reglamento Orgánico permita, por las funciones del puesto, que su titular no sea funcionario.',null),
('aux-ayto-mad:11-2285a55da0','aux-ayto-mad',11,'Acordar al inicio del mandato el número, denominación y competencias de las áreas en que se estructura la Administración municipal corresponde:','["Al Alcalde", "Al Pleno", "A la Junta de Gobierno"]'::jsonb,0,'Art. 14.3 h) Ley 22/2006','Es atribución del Alcalde, en el marco de las normas orgánicas aprobadas por el Pleno, y solo es delegable en la Junta de Gobierno (art. 14.4).',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:11-9ec16acb44','aux-ayto-mad',11,'Establecer la organización y estructura de la Administración municipal ejecutiva y nombrar y cesar a los titulares de los órganos directivos corresponde:','["Al Pleno", "Al Alcalde", "A la Junta de Gobierno"]'::jsonb,2,'Art. 17.1 h) Ley 22/2006','Corresponde a la Junta de Gobierno, en el marco de las normas orgánicas del Pleno, y es indelegable (art. 17.2).',null),
('aux-ayto-mad:11-29607027de','aux-ayto-mad',11,'Según la Ley 22/2006, la creación de órganos directivos en el ámbito de la Administración del Ayuntamiento de Madrid corresponde a:','["El Pleno, por mayoría absoluta del número legal de miembros", "La Junta de Gobierno, en el marco del Reglamento orgánico", "El Alcalde, mediante decreto"]'::jsonb,1,'Art. 21.1 Ley 22/2006','El art. 21.1 atribuye a la Junta de Gobierno, en el marco del Reglamento orgánico, la creación de órganos directivos.',null),
('aux-ayto-mad:11-2053f6c7dc','aux-ayto-mad',11,'Los titulares de los órganos directivos del Ayuntamiento de Madrid serán nombrados atendiendo a criterios de:','["Mérito y capacidad mediante concurso de méritos en todo caso", "Confianza política y antigüedad", "Competencia profesional y experiencia"]'::jsonb,2,'Art. 21.2 Ley 22/2006','Se nombran atendiendo a criterios de competencia profesional y experiencia, según lo que determine el Reglamento orgánico.',null),
('aux-ayto-mad:11-8836e0b170','aux-ayto-mad',11,'Los titulares de los órganos directivos del Ayuntamiento de Madrid quedan sometidos al régimen de incompatibilidades de:','["La legislación de régimen local aplicable a los concejales", "La Ley 53/1984, de Incompatibilidades del Personal al Servicio de las Administraciones Públicas", "La Ley 3/2015, reguladora del ejercicio del alto cargo de la Administración General del Estado"]'::jsonb,1,'Art. 21.4 Ley 22/2006','El art. 21.4 los somete a la Ley 53/1984 y a otras normas estatales o autonómicas aplicables. Los miembros de los órganos ejecutivos de gobierno se rigen por las incompatibilidades de los concejales (art. 18.2).',null),
('aux-ayto-mad:11-f7ac770bc6','aux-ayto-mad',11,'En los municipios de gran población, la determinación de los niveles esenciales de la organización municipal (grandes áreas de gobierno, coordinadores generales y direcciones generales) tiene naturaleza:','["Orgánica, y su aprobación corresponde al Pleno", "Reglamentaria ordinaria, y la aprueba la Junta de Gobierno Local", "De simple acto organizativo del Alcalde"]'::jsonb,0,'Art. 123.1 c) LBRL','El art. 123.1 c) incluye entre los reglamentos orgánicos la determinación de los niveles esenciales de la organización municipal, sin perjuicio de que el Alcalde fije el número de cada uno de esos órganos.',null),
('aux-ayto-mad:11-49a0fca8eb','aux-ayto-mad',11,'En los municipios de gran población, los coordinadores generales dependen directamente de:','["El Secretario General del Pleno", "Los miembros de la Junta de Gobierno Local", "Los directores generales"]'::jsonb,1,'Art. 123.1 c) LBRL','El art. 123.1 c) describe a los coordinadores generales como dependientes directamente de los miembros de la Junta de Gobierno Local, con funciones de coordinación de las direcciones generales de su área.',null),
('aux-ayto-mad:11-ce1ec2a1f6','aux-ayto-mad',11,'Según la Ley 7/1985, en los municipios de gran población corresponde al Alcalde, dentro de los niveles esenciales aprobados por el Pleno:','["Crear nuevas áreas de gobierno sin límite", "Aprobar el reglamento orgánico que regula la organización municipal", "Determinar el número de cada uno de los órganos y establecer niveles complementarios inferiores"]'::jsonb,2,'Art. 123.1 c) LBRL','El art. 123.1 c) deja a salvo las atribuciones del Alcalde para determinar el número de cada uno de esos órganos y establecer niveles complementarios inferiores.',null),
('aux-ayto-mad:11-a6a04bb451','aux-ayto-mad',11,'¿Cuál de los siguientes es un órgano directivo en los municipios de gran población según la Ley 7/1985?','["El titular de la asesoría jurídica", "Los miembros de la Junta de Gobierno Local", "El Alcalde"]'::jsonb,0,'Art. 130.1 B) LBRL','Son órganos directivos los coordinadores generales, los directores generales, el titular del órgano de apoyo a la Junta de Gobierno, el titular de la asesoría jurídica, el Secretario general del Pleno, el interventor general y, en su caso, el titular del órgano de gestión tributaria.',null),
('aux-ayto-mad:11-f05f052c93','aux-ayto-mad',11,'Tienen también la consideración de órganos directivos en los municipios de gran población:','["Los Concejales Presidentes de Distrito", "Los titulares de los máximos órganos de dirección de los organismos autónomos y entidades públicas empresariales locales", "Los portavoces de los grupos políticos y los concejales con delegación especial"]'::jsonb,1,'Art. 130.2 LBRL','Así lo establece el art. 130.2.',null),
('aux-ayto-mad:11-9ed139fc52','aux-ayto-mad',11,'En los municipios de gran población, los órganos superiores y directivos quedan sometidos al régimen de incompatibilidades de:','["El Estatuto Básico del Empleado Público", "La Ley 53/1984, de Incompatibilidades del personal al servicio de las Administraciones públicas", "La Ley Orgánica del Régimen Electoral General, como los concejales"]'::jsonb,1,'Art. 130.4 LBRL','Así lo establece el art. 130.4.',null),
('aux-ayto-mad:11-afa02d9b0f','aux-ayto-mad',11,'Según el Reglamento Orgánico del Gobierno y de la Administración del Ayuntamiento de Madrid, ¿cuántas Áreas de Gobierno puede haber como máximo?','["15", "12", "18"]'::jsonb,0,'Art. 40.2 ROGA','El número de Áreas de Gobierno no podrá exceder de 15; su número, denominación y atribuciones los determina el alcalde.',null),
('aux-ayto-mad:11-eb4e2647bc','aux-ayto-mad',11,'¿A quién corresponde determinar el número, la denominación y las atribuciones de las Áreas de Gobierno del Ayuntamiento de Madrid?','["Al Pleno, a propuesta del alcalde", "A la Junta de Gobierno", "Al alcalde"]'::jsonb,2,'Art. 40.2 ROGA','Corresponde al alcalde, al amparo de los arts. 123.1.c) y 124.4.k) de la LBRL, determinar el número, denominación y atribuciones de las Áreas.',null),
('aux-ayto-mad:11-2314e29e77','aux-ayto-mad',11,'¿Qué constituyen las Áreas de Gobierno en la organización municipal de Madrid?','["Los órganos complementarios de la Junta de Gobierno", "Los niveles esenciales de la organización municipal", "Las unidades de gestión desconcentrada de los distritos"]'::jsonb,1,'Art. 40.1 ROGA','Las Áreas de Gobierno constituyen los niveles esenciales de la organización municipal y comprenden uno o varios sectores funcionalmente homogéneos.',null),
('aux-ayto-mad:11-79da005225','aux-ayto-mad',11,'Además de las Direcciones Generales u órganos similares, ¿con qué órgano contará en todo caso cada Área de Gobierno?','["Con un Consejo Sectorial de participación", "Con una Intervención Delegada", "Con una Secretaría General Técnica"]'::jsonb,2,'Art. 41.1 ROGA','Las Áreas de Gobierno, en las que podrá existir uno o más coordinadores generales, contarán con una Secretaría General Técnica y se estructurarán en Direcciones Generales u órganos similares.',null),
('aux-ayto-mad:11-72b347208f','aux-ayto-mad',11,'¿Cuántos coordinadores generales puede haber en un Área de Gobierno?','["Solo uno", "Uno o más", "Como máximo dos"]'::jsonb,1,'Art. 41.1 ROGA','El art. 41.1 prevé que en las Áreas de Gobierno «podrá existir uno o más coordinadores generales»; si hay varios, el acuerdo de organización delimita los sectores de cada uno (art. 46.2).',null),
('aux-ayto-mad:11-c62907c4b6','aux-ayto-mad',11,'¿Cuál es el orden jerárquico de los órganos directivos de las Áreas de Gobierno, de mayor a menor?','["Coordinador general, secretario general técnico y director general", "Secretario general técnico, coordinador general y director general", "Coordinador general, director general y secretario general técnico"]'::jsonb,0,'Art. 42.2 ROGA','Los órganos directivos se ordenan jerárquicamente así: coordinador general, secretario general técnico, director general u órgano asimilado.',null),
('aux-ayto-mad:11-2de01dea89','aux-ayto-mad',11,'¿Quiénes son los jefes superiores de cada Área de Gobierno?','["Los coordinadores generales", "Los concejales de Gobierno y los consejeros-delegados de Gobierno", "Los tenientes de alcalde"]'::jsonb,1,'Art. 42.1 ROGA','Los concejales de Gobierno y consejeros-delegados de Gobierno son los jefes superiores del Área de Gobierno correspondiente.',null),
('aux-ayto-mad:11-eb37c80394','aux-ayto-mad',11,'¿Quién nombra y cesa a los coordinadores generales, secretarios generales técnicos y directores generales del Ayuntamiento de Madrid?','["El concejal de Gobierno del Área", "El alcalde", "La Junta de Gobierno"]'::jsonb,2,'Art. 49.1 ROGA','Los titulares de estos órganos directivos son nombrados y cesados por la Junta de Gobierno; el titular del Área solo propone el nombramiento (art. 44.j).',null),
('aux-ayto-mad:11-e5c3d04f23','aux-ayto-mad',11,'¿Qué puesto directivo no puede proveerse, en ningún caso, con personal que no tenga la condición de funcionario?','["El de secretario general técnico", "El de coordinador general", "El de director general"]'::jsonb,0,'Art. 49.3 ROGA','Los puestos de coordinador general pueden proveerse con personal no funcionario, pero esta excepción no se aplica a los secretarios generales técnicos.',null),
('aux-ayto-mad:11-7f9bdc2ba4','aux-ayto-mad',11,'¿Qué forma revisten las decisiones administrativas que adoptan los órganos directivos del Ayuntamiento de Madrid?','["Decreto", "Resolución", "Acuerdo"]'::jsonb,1,'Art. 50.1 ROGA','Las decisiones de los órganos directivos revisten la forma de resolución; las de los concejales de Gobierno, de Coordinación y delegados, la de decreto (art. 39).',null),
('aux-ayto-mad:11-3b5ebdbda9','aux-ayto-mad',11,'¿Qué forma revisten las resoluciones administrativas que adoptan los concejales de Gobierno?','["La de acuerdo", "La de decreto", "La de resolución"]'::jsonb,1,'Art. 39.1 ROGA','Las resoluciones de los concejales de Gobierno, de Coordinación y delegados revisten la forma de decreto y se denominan decretos del concejal correspondiente.',null),
('aux-ayto-mad:11-83a679080e','aux-ayto-mad',11,'¿Qué rango tienen los secretarios generales técnicos?','["El de subdirector general", "El de director general", "El de coordinador general"]'::jsonb,1,'Art. 47.1 ROGA','A los secretarios generales técnicos, con rango de director general, les corresponden la gestión de los servicios comunes y las demás funciones del art. 47.',null),
('aux-ayto-mad:11-a1c90591a9','aux-ayto-mad',11,'¿De quién dependen directamente, con carácter general, los secretarios generales técnicos?','["Del alcalde", "Del coordinador general del Área", "Del titular del Área de Gobierno correspondiente"]'::jsonb,2,'Art. 47.3 ROGA','Los secretarios generales técnicos dependen directamente del titular del Área de Gobierno; excepcionalmente pueden depender funcionalmente de un Área de Coordinación o Delegada.',null),
('aux-ayto-mad:11-698f6a6cc9','aux-ayto-mad',11,'¿Cuál de estas funciones corresponde al secretario general técnico de un Área de Gobierno?','["La gestión de los servicios comunes", "La fiscalización interna de los gastos del Área", "El nombramiento de los directores generales"]'::jsonb,0,'Art. 47.1 a) ROGA','Entre sus funciones están la gestión de los servicios comunes, la coordinación en ese ámbito y la asistencia jurídica y técnica al titular del Área.',null),
('aux-ayto-mad:11-4a301b3b88','aux-ayto-mad',11,'¿Bajo la dependencia directa de quién ejercen sus funciones los directores generales?','["De un coordinador general o de un concejal de Coordinación o delegado", "De la Junta de Gobierno, directamente", "Del secretario general técnico del Área"]'::jsonb,0,'Art. 48.1 ROGA','Los directores generales dirigen y gestionan uno o varios ámbitos funcionalmente homogéneos bajo la dependencia directa de un coordinador general o de un concejal de Coordinación o delegado.',null),
('aux-ayto-mad:11-b096cb3581','aux-ayto-mad',11,'¿A quién corresponde la elaboración, seguimiento y control del presupuesto anual que se asigne a una Dirección General?','["Al director general", "Al coordinador general", "Al secretario general técnico"]'::jsonb,0,'Art. 48.2 d) ROGA','Entre las funciones generales de los directores generales figura la elaboración, seguimiento y control del presupuesto anual que se les asigne.',null),
('aux-ayto-mad:11-d6d4732a43','aux-ayto-mad',11,'¿Quién propone a la Junta de Gobierno el nombramiento de los titulares de los órganos directivos de un Área?','["El alcalde", "El concejal de Gobierno o consejero-delegado titular del Área", "El concejal-delegado de la Dirección General"]'::jsonb,1,'Art. 44 j) ROGA','Corresponde a los concejales de Gobierno y consejeros-delegados de Gobierno proponer a la Junta de Gobierno el nombramiento de los titulares de los órganos directivos de su Área.',null),
('aux-ayto-mad:11-e71902b758','aux-ayto-mad',11,'¿A quién corresponde resolver los conflictos entre los órganos directivos dependientes de un Área de Gobierno?','["Al coordinador general", "Al concejal de Gobierno o consejero-delegado de Gobierno del Área", "A la Junta de Gobierno"]'::jsonb,1,'Art. 44 i) ROGA','Resolver los conflictos entre los órganos directivos dependientes de su Área es una de las funciones del art. 44.',null),
('aux-ayto-mad:11-9925687641','aux-ayto-mad',11,'¿Quiénes son los consejeros-delegados de Gobierno?','["Los miembros de la Junta de Gobierno que no son concejales", "Los tenientes de alcalde con Área de Gobierno", "Los concejales que coordinan un ámbito bajo un concejal de Gobierno"]'::jsonb,0,'Art. 36.1 ROGA','Son consejeros-delegados de Gobierno los miembros de la Junta de Gobierno que no ostenten la condición de concejal; tienen las mismas funciones que los concejales de Gobierno.',null),
('aux-ayto-mad:11-733c1e5f80','aux-ayto-mad',11,'¿Qué diferencia a los concejales de Coordinación de los concejales de Gobierno?','["Que no forman parte de la Junta de Gobierno", "Que solo pueden dirigir una Dirección General", "Que los nombra el Pleno"]'::jsonb,0,'Art. 37.1 ROGA','Los concejales de Coordinación no forman parte de la Junta de Gobierno y actúan bajo la superior dirección de un concejal de Gobierno o consejero-delegado.',null),
('aux-ayto-mad:11-929b204d2e','aux-ayto-mad',11,'¿Cuál de estas funciones de los concejales de Gobierno no tienen los concejales de Coordinación ni los concejales-delegados?','["Ejercer la dirección e inspección de su Área", "Resolver los conflictos entre los órganos directivos de su Área", "Elevar al Pleno las propuestas de su Área"]'::jsonb,2,'Art. 45.1 ROGA','Tienen las funciones del art. 44 salvo las letras b), c), d), e) y j): entre ellas, elevar propuestas al Pleno (letra c).',null),
('aux-ayto-mad:11-27a5f4449a','aux-ayto-mad',11,'¿Cómo se denomina el primer teniente de alcalde del Ayuntamiento de Madrid?','["Teniente de alcalde decano", "Alcalde accidental", "Vicealcalde"]'::jsonb,2,'Art. 34.4 ROGA','El primer teniente de alcalde se denomina vicealcalde.',null),
('aux-ayto-mad:11-4d477d041f','aux-ayto-mad',11,'¿Qué tratamiento tienen los tenientes de alcalde del Ayuntamiento de Madrid?','["El de señoría", "El de excelencia", "El de ilustrísima"]'::jsonb,2,'Art. 34.3 ROGA','Los tenientes de alcalde tienen el tratamiento de ilustrísima.',null),
('aux-ayto-mad:11-f22c93c4a8','aux-ayto-mad',11,'¿Entre quiénes nombra el alcalde a los tenientes de alcalde?','["Entre los miembros de la Junta de Gobierno, sean o no concejales", "Entre los concejales que formen parte de la Junta de Gobierno", "Entre todos los concejales del Pleno"]'::jsonb,1,'Art. 34.1 ROGA','El alcalde puede nombrar tenientes de alcalde entre los concejales que formen parte de la Junta de Gobierno; le sustituyen por orden de nombramiento.',null),
('aux-ayto-mad:11-9e12651f13','aux-ayto-mad',11,'¿Qué órgano ejerce la función de control y fiscalización interna de la gestión económico-financiera del Ayuntamiento de Madrid?','["La Tesorería municipal", "El órgano de contabilidad del Área de Hacienda", "La Intervención General"]'::jsonb,2,'Art. 59.1 ROGA','La función interventora, de control financiero y de control de eficacia corresponde a la Intervención General del Ayuntamiento de Madrid.',null),
('aux-ayto-mad:11-49e53bc0be','aux-ayto-mad',11,'¿A qué Área se adscribe orgánicamente la Intervención General del Ayuntamiento de Madrid?','["A la competente en materia de Coordinación Territorial", "A la competente en materia de Hacienda", "A la Alcaldía"]'::jsonb,1,'Art. 59.2 ROGA','La Intervención General actúa con plena autonomía, pero se adscribe orgánicamente al Área competente en materia de Hacienda.',null),
('aux-ayto-mad:11-9c24c53643','aux-ayto-mad',11,'¿Entre quiénes se nombra al tesorero municipal del Ayuntamiento de Madrid?','["Entre funcionarios de Administración Local con habilitación de carácter nacional", "Entre funcionarios de carrera de cualquier Administración con título de licenciado", "Libremente por el alcalde entre profesionales con experiencia"]'::jsonb,0,'Art. 60.1 ROGA','Las funciones de tesorería, excluida la recaudación, las ejerce el tesorero, nombrado entre funcionarios de Administración Local con habilitación de carácter nacional.',null),
('aux-ayto-mad:11-f039fec99b','aux-ayto-mad',11,'¿Qué función queda excluida de las que ejerce el tesorero municipal del Ayuntamiento de Madrid?','["La custodia de fondos", "El pago de las obligaciones", "La recaudación"]'::jsonb,2,'Art. 60.1 ROGA','Las funciones públicas de tesorería se ejercen por el tesorero municipal, excluida la recaudación.',null),
('aux-ayto-mad:11-b3ad1a9f4d','aux-ayto-mad',11,'¿Qué órgano es el encargado de la asistencia jurídica del Ayuntamiento de Madrid y de sus organismos públicos?','["La Asesoría Jurídica", "La Secretaría General Técnica de cada Área", "La Secretaría General del Pleno"]'::jsonb,0,'Art. 51.1 ROGA','La Asesoría Jurídica, en la que se integra el Cuerpo de Letrados, es el órgano encargado de la asistencia jurídica del Ayuntamiento y de sus organismos públicos.',null),
('aux-ayto-mad:11-736e2e5912','aux-ayto-mad',11,'¿Qué órgano aprueba el Proyecto de Presupuesto General del Ayuntamiento de Madrid que elabora el Área competente en Hacienda?','["El Pleno, directamente", "El alcalde", "La Junta de Gobierno"]'::jsonb,2,'Art. 58.2 a) ROGA','Las funciones de presupuestación del Área de Hacienda incluyen la elaboración del Proyecto de Presupuesto General para su aprobación por la Junta de Gobierno.',null),
('aux-ayto-mad:12-3196bef13f','aux-ayto-mad',12,'En los municipios de gran población, la creación de los distritos y la determinación del porcentaje mínimo de recursos presupuestarios que deben gestionar corresponde a:','["El Pleno", "La Junta de Gobierno Local", "El Alcalde"]'::jsonb,0,'Art. 128.2 LBRL','Corresponde al Pleno crear los distritos, regularlos y fijar en norma orgánica el porcentaje mínimo de recursos que gestionarán en su conjunto.',null),
('aux-ayto-mad:12-cd070b641f','aux-ayto-mad',12,'Nombrar y cesar a los Presidentes de los Distritos corresponde:','["Al Pleno", "A la Junta de Gobierno", "Al Alcalde"]'::jsonb,2,'Art. 14.3 d) Ley 22/2006','El Alcalde nombra y cesa a los miembros de la Junta de Gobierno, a los Tenientes de Alcalde y a los Presidentes de los Distritos.',null),
('aux-ayto-mad:12-d9b68cb18c','aux-ayto-mad',12,'Según la Ley 22/2006, la creación de Distritos como divisiones territoriales con órganos de gestión desconcentrada es, para el Pleno:','["Potestativa", "Obligatoria", "Necesaria solo si lo pide el 10 % de los vecinos"]'::jsonb,1,'Art. 22.1 Ley 22/2006','El art. 22.1 dice que el Pleno deberá crear Distritos, para impulsar y desarrollar la participación ciudadana en la gestión de los asuntos municipales.',null),
('aux-ayto-mad:12-67b9814680','aux-ayto-mad',12,'La Presidencia de un Distrito del Ayuntamiento de Madrid corresponderá:','["A un vecino del Distrito elegido por la Junta Municipal", "En todo caso a un Concejal", "A un funcionario con la categoría de director general"]'::jsonb,1,'Art. 22.2 Ley 22/2006','Según el art. 22.2, la Presidencia del Distrito corresponderá en todo caso a un Concejal.',null),
('aux-ayto-mad:12-28be7036be','aux-ayto-mad',12,'Según la Ley 7/1985, los municipios del régimen común podrán establecer órganos territoriales de gestión desconcentrada para:','["Facilitar la participación ciudadana en la gestión de los asuntos locales y mejorarla, sin perjuicio de la unidad de gobierno y gestión del municipio", "Crear entidades locales menores con personalidad jurídica propia y presupuesto independiente", "Sustituir al Pleno en las materias de interés de cada barrio"]'::jsonb,0,'Art. 24.1 LBRL','Así lo establece el art. 24.1. En los municipios de gran población se aplica el régimen de distritos del art. 128 (art. 24.2).',null),
('aux-ayto-mad:12-9a51b5ef1e','aux-ayto-mad',12,'En los municipios de gran población, el régimen de gestión desconcentrada aplicable es:','["El de las entidades locales menores", "El de las juntas vecinales potestativas", "El de los distritos regulado en el artículo 128 de la Ley 7/1985"]'::jsonb,2,'Art. 24.2 LBRL','Según el art. 24.2, en los municipios del art. 121 se aplica el régimen de gestión desconcentrada del art. 128.',null),
('aux-ayto-mad:12-17397787e4','aux-ayto-mad',12,'En los municipios de gran población, la creación de distritos es:','["Obligatoria", "Obligatoria solo en los de más de un millón de habitantes", "Potestativa"]'::jsonb,0,'Art. 128.1 LBRL','El art. 128.1 dice que los ayuntamientos deberán crear distritos, dotados de órganos de gestión desconcentrada.',null),
('aux-ayto-mad:12-1491917f45','aux-ayto-mad',12,'En los municipios de gran población, la regulación de la división del municipio en distritos y de sus órganos tiene naturaleza:','["Orgánica", "De ordenanza fiscal", "De decreto de Alcaldía"]'::jsonb,0,'Art. 123.1 c) LBRL','La división en distritos y la regulación de sus órganos figuran entre las materias de naturaleza orgánica del art. 123.1 c), sin perjuicio de las atribuciones del Alcalde sobre su administración ejecutiva.',null),
('aux-ayto-mad:12-f295bf8831','aux-ayto-mad',12,'¿En cuántos distritos se divide el término municipal de Madrid según el Reglamento Orgánico de los Distritos?','["20", "22", "21"]'::jsonb,2,'Art. 3.1 RO 6/2021','El término municipal de Madrid se divide en 21 distritos, del 01 Centro al 21 Barajas.',null),
('aux-ayto-mad:12-d126180ed5','aux-ayto-mad',12,'¿Qué órgano puede alterar el número, la denominación y los límites territoriales de los distritos de Madrid?','["La Junta de Gobierno, a propuesta del área de coordinación territorial", "El Pleno, modificando el Reglamento Orgánico de los Distritos", "El alcalde, por decreto"]'::jsonb,1,'Art. 3.2 RO 6/2021','Corresponde al Pleno, mediante la modificación del reglamento orgánico, alterar el número, denominación y límites de los distritos y barrios.',null),
('aux-ayto-mad:12-ba7d21a980','aux-ayto-mad',12,'¿Qué número corresponde al distrito de Barajas en la división del municipio de Madrid?','["17", "19", "21"]'::jsonb,2,'Art. 3.1 RO 6/2021','Barajas es el distrito 21; el 17 es Villaverde y el 19, Vicálvaro.',null),
('aux-ayto-mad:12-07b7b46603','aux-ayto-mad',12,'¿Qué porcentaje mínimo del presupuesto del Ayuntamiento de Madrid deben gestionar los distritos en su conjunto?','["El 11 %", "El 8 %", "El 15 %"]'::jsonb,0,'Art. 7 RO 6/2021','Los recursos gestionados por los distritos en su conjunto no serán en ningún caso inferiores al 11 % del presupuesto del Ayuntamiento.',null),
('aux-ayto-mad:12-f3afc9e211','aux-ayto-mad',12,'¿Quién nombra y separa libremente al concejal presidente del distrito?','["El Pleno", "La Junta de Gobierno", "El alcalde"]'::jsonb,2,'Art. 5 b) RO 6/2021','Son órganos del distrito, entre otros, el concejal presidente, nombrado y separado libremente por el alcalde.',null),
('aux-ayto-mad:12-b06dd11c91','aux-ayto-mad',12,'¿Qué es la Junta Municipal del Distrito según el Reglamento Orgánico de los Distritos?','["El órgano directivo que gestiona los servicios del distrito", "El órgano colegiado de representación político-vecinal del distrito", "El órgano de participación ciudadana con capacidad de adoptar iniciativas"]'::jsonb,1,'Art. 5 a) RO 6/2021','La Junta Municipal es el órgano colegiado de representación político-vecinal, en el que junto a cargos electos participan los vocales vecinos.',null),
('aux-ayto-mad:12-b44f175ab0','aux-ayto-mad',12,'¿Quién determina el número de miembros de cada Junta Municipal de Distrito?','["El alcalde, al nombrar al concejal presidente", "El Pleno del Ayuntamiento, al inicio de cada mandato", "La propia Junta Municipal, en su sesión constitutiva"]'::jsonb,1,'Art. 8.1 RO 6/2021','El número de miembros lo determina el Pleno al inicio de cada mandato, repartiéndolos en proporción a la representación de cada grupo.',null),
('aux-ayto-mad:12-1c54e725b1','aux-ayto-mad',12,'¿Quién nombra a los vocales vecinos de las Juntas Municipales de Distrito?','["El alcalde, a propuesta de los grupos políticos", "El concejal presidente, a propuesta de las asociaciones vecinales", "El Pleno, a propuesta de la Junta de Gobierno"]'::jsonb,0,'Art. 8.2 b) RO 6/2021','Los vocales vecinos son nombrados entre vecinos por el alcalde a propuesta de los grupos políticos (también art. 69.1).',null),
('aux-ayto-mad:12-43d9f2c96b','aux-ayto-mad',12,'¿Qué órgano es el deliberante y consultivo de la Junta Municipal del Distrito?','["El consejo de proximidad", "La comisión de vocales vecinos", "La junta de portavoces"]'::jsonb,2,'Art. 8.3 RO 6/2021','La junta de portavoces es el órgano deliberante y consultivo de la junta municipal del distrito.',null),
('aux-ayto-mad:12-5a88041bc2','aux-ayto-mad',12,'¿Hasta cuántos concejales de su grupo municipal pueden asistir a cada grupo político en la Junta Municipal del Distrito?','["Uno, con voz pero sin voto", "Hasta tres, con voz y voto", "Hasta dos, con voz pero sin voto"]'::jsonb,2,'Art. 9 RO 6/2021','Cada grupo puede estar asistido hasta por dos concejales designados por su grupo municipal, que intervienen con voz pero sin voto.',null),
('aux-ayto-mad:12-e2d75165a5','aux-ayto-mad',12,'Si en la sesión constitutiva de la Junta Municipal del Distrito no concurre la mayoría absoluta de sus miembros, ¿cuándo se celebra la sesión?','["Dos días después, con cualquier número de miembros presentes", "A los cinco días, con la mayoría absoluta", "Al día siguiente, con un tercio de los miembros"]'::jsonb,0,'Art. 10.2 RO 6/2021','Si no concurre la mayoría absoluta, se celebra sesión dos días después, quedando constituida cualquiera que sea el número de presentes.',null),
('aux-ayto-mad:12-c9fed29a40','aux-ayto-mad',12,'¿Con qué periodicidad celebra la Junta Municipal del Distrito sesión plenaria ordinaria?','["Una vez al mes, excepto en agosto", "Una vez al mes, todos los meses del año", "Una vez cada dos meses"]'::jsonb,0,'Art. 14.2 RO 6/2021','La junta municipal celebra sesión plenaria ordinaria una vez al mes, a excepción del mes de agosto.',null),
('aux-ayto-mad:12-60a49fb4fb','aux-ayto-mad',12,'¿Qué proporción de los miembros de la Junta Municipal del Distrito puede solicitar una sesión extraordinaria?','["Al menos un tercio de los miembros presentes", "La mayoría absoluta del número legal de miembros", "Al menos la cuarta parte del número legal de miembros"]'::jsonb,2,'Art. 15.1 RO 6/2021','Hay sesión extraordinaria cuando lo decide el concejal presidente o lo solicita la cuarta parte, al menos, del número legal de miembros.',null),
('aux-ayto-mad:12-5b3fe9a93c','aux-ayto-mad',12,'¿Cuántas sesiones extraordinarias al año puede solicitar como máximo cada miembro de la Junta Municipal del Distrito?','["Tres", "Dos", "Cinco"]'::jsonb,0,'Art. 15.2 RO 6/2021','Ningún miembro de la junta municipal puede solicitar más de tres sesiones extraordinarias al año.',null),
('aux-ayto-mad:12-5b6f712d62','aux-ayto-mad',12,'Solicitada una sesión extraordinaria de la Junta Municipal del Distrito, ¿cuánto puede demorarse como máximo su celebración?','["Diez días hábiles", "Quince días hábiles", "Un mes"]'::jsonb,1,'Art. 15.4 RO 6/2021','La celebración no puede demorarse más de quince días hábiles desde la solicitud; si no se convoca, queda convocada automáticamente para el décimo día hábil siguiente.',null),
('aux-ayto-mad:12-9d7420819c','aux-ayto-mad',12,'En las sesiones extraordinarias urgentes de la Junta Municipal del Distrito, ¿qué ocurre si no se aprecia la urgencia?','["Se aplaza la sesión al día siguiente", "Se tratan los asuntos como sesión ordinaria", "Se levanta acto seguido la sesión"]'::jsonb,2,'Art. 16.2 RO 6/2021','El primer punto del orden del día es el pronunciamiento sobre la urgencia; si no se aprecia, se levanta acto seguido la sesión.',null),
('aux-ayto-mad:12-da3009fc19','aux-ayto-mad',12,'¿Con qué asistencia se constituye válidamente la Junta Municipal del Distrito?','["Un tercio del número legal de sus miembros, con presidente y secretario", "La mayoría absoluta de sus miembros, con presidente y secretario", "Un cuarto del número legal, sin necesidad del secretario"]'::jsonb,0,'Art. 23.2 RO 6/2021','Se constituye con un tercio del número legal de miembros y, en todo caso, con la presencia del presidente y del secretario o sus sustitutos.',null),
('aux-ayto-mad:12-61d08445e9','aux-ayto-mad',12,'¿Por qué mayoría adopta sus acuerdos la Junta Municipal del Distrito como regla general?','["Por mayoría absoluta del número legal de miembros", "Por mayoría de dos tercios de los presentes", "Por mayoría simple de los miembros presentes"]'::jsonb,2,'Art. 33.1 RO 6/2021','Como regla general, por mayoría simple de los presentes: cuando los votos afirmativos son más que los negativos.',null),
('aux-ayto-mad:12-2f188160d8','aux-ayto-mad',12,'¿Qué forma revisten las decisiones de la Junta Municipal del Distrito en el ejercicio de sus competencias?','["La de decreto", "La de resolución", "La de acuerdo"]'::jsonb,2,'Art. 12.2 RO 6/2021','Revisten la forma de acuerdo y se denominan «Acuerdo de la Junta Municipal del Distrito de…».',null),
('aux-ayto-mad:12-4b636fd930','aux-ayto-mad',12,'¿A quién corresponde resolver las recusaciones planteadas contra los miembros de la Junta Municipal del Distrito?','["Al secretario del distrito", "Al concejal presidente", "A la propia Junta Municipal del Distrito"]'::jsonb,2,'Art. 12.1 e) RO 6/2021','Entre las competencias de la junta municipal está resolver las recusaciones contra sus miembros.',null),
('aux-ayto-mad:12-d155e891b3','aux-ayto-mad',12,'¿Cuándo se celebra el debate sobre el estado del distrito?','["Cada dos años, en el primer semestre", "Anualmente, en el último trimestre del año", "Anualmente, durante el primer semestre, salvo el año de elecciones municipales"]'::jsonb,2,'Art. 54.1 RO 6/2021','Se celebra cada año en el primer semestre, en sesión extraordinaria; no hay debate el año en que se celebren elecciones municipales.',null),
('aux-ayto-mad:12-307f372b14','aux-ayto-mad',12,'¿Con qué antelación mínima debe convocarse la sesión del debate sobre el estado del distrito?','["Diez días hábiles", "Cinco días hábiles", "Quince días hábiles"]'::jsonb,0,'Art. 54.2 RO 6/2021','Esta sesión extraordinaria debe convocarse con diez días hábiles, al menos, de antelación.',null),
('aux-ayto-mad:12-97ee4acb66','aux-ayto-mad',12,'¿Qué forma revisten las resoluciones administrativas del concejal presidente del distrito?','["La de resolución", "La de decreto", "La de acuerdo"]'::jsonb,1,'Art. 58.2 RO 6/2021','Revisten la forma de decreto y se denominan decretos del concejal presidente del distrito.',null),
('aux-ayto-mad:12-b2e3db3ca3','aux-ayto-mad',12,'¿Quién nombra y cesa al coordinador del distrito?','["El alcalde, a propuesta de la Junta Municipal", "El concejal presidente, libremente", "La Junta de Gobierno, a propuesta del concejal presidente"]'::jsonb,2,'Art. 61.1 RO 6/2021','El coordinador del distrito es nombrado y cesado por la Junta de Gobierno a propuesta del concejal presidente.',null),
('aux-ayto-mad:12-5b71f45408','aux-ayto-mad',12,'¿Qué rango tiene el coordinador del distrito?','["El de subdirector general", "El de coordinador general", "El de director general"]'::jsonb,2,'Art. 61.2 RO 6/2021','El coordinador del distrito ostenta a todos los efectos el rango de director general.',null),
('aux-ayto-mad:12-3f9bffda41','aux-ayto-mad',12,'¿Qué forma revisten las decisiones administrativas de los coordinadores de distrito?','["La de decreto", "La de acuerdo", "La de resolución"]'::jsonb,2,'Art. 62.2 RO 6/2021','Las decisiones administrativas que adopten los coordinadores de distrito revisten la forma de resolución.',null),
('aux-ayto-mad:12-be93da2904','aux-ayto-mad',12,'¿Entre quiénes se nombra al secretario del distrito?','["Entre funcionarios con habilitación de carácter nacional", "Entre funcionarios de carrera del subgrupo A1", "Entre funcionarios de carrera de los subgrupos A1 o A2"]'::jsonb,1,'Art. 63.2 RO 6/2021','El secretario del distrito se nombra, a propuesta del concejal presidente, entre funcionarios de carrera del subgrupo A1.',null),
('aux-ayto-mad:12-dda5116b08','aux-ayto-mad',12,'¿De quién depende orgánica y funcionalmente el interventor delegado de cada distrito?','["De la Intervención General", "Del coordinador del distrito", "Del concejal presidente del distrito"]'::jsonb,0,'Art. 65 RO 6/2021','Cada distrito cuenta con un interventor delegado que actúa bajo la dependencia orgánica y funcional de la Intervención General y por delegación de esta.',null),
('aux-ayto-mad:12-d6d8c4205a','aux-ayto-mad',12,'¿Cuál de estas personas no puede ser vocal vecino de una Junta Municipal de Distrito de Madrid?','["Quien sea concejal de otro ayuntamiento", "Quien esté empadronado en otro distrito de Madrid", "Quien sea funcionario del Ayuntamiento de Madrid"]'::jsonb,0,'Art. 68 c) RO 6/2021','No pueden ser vocales vecinos quienes sean concejales de otro ayuntamiento, vocales de otra Junta Municipal o incurran en las causas de inelegibilidad o incompatibilidad de los concejales.',null),
('aux-ayto-mad:12-66df2e8da8','aux-ayto-mad',12,'¿Cuántas inasistencias injustificadas consecutivas a sesiones de la Junta Municipal permiten al alcalde cesar a un vocal vecino?','["Tres", "Cinco", "Dos"]'::jsonb,0,'Art. 71 b) RO 6/2021','Puede cesarse al vocal vecino por inasistencia injustificada a tres sesiones consecutivas o a cinco alternas en un año.',null),
('aux-ayto-mad:12-b4af324c9c','aux-ayto-mad',12,'¿Quién suple al concejal presidente del distrito en caso de vacante, ausencia o enfermedad?','["El coordinador del distrito", "Un concejal de los grupos municipales adscrito al distrito designado por el alcalde", "El vocal vecino portavoz del grupo mayoritario"]'::jsonb,1,'Art. 59 RO 6/2021','La concejalía presidencia es suplida por una concejalía de los grupos municipales adscrita al distrito, designada por el alcalde.',null),
('aux-ayto-mad:13-3f56beb45f','aux-ayto-mad',13,'Podrá prescindirse de los trámites de consulta, audiencia e información públicas en el caso de normas:','["Que afecten a derechos de los ciudadanos, o cuando concurran razones de urgencia", "Tributarias o sancionadoras, o cuando concurran razones graves de interés público", "Presupuestarias u organizativas, o cuando concurran razones graves de interés público"]'::jsonb,2,'Art. 133.4 Ley 39/2015','Excepción prevista para normas presupuestarias u organizativas o razones graves de interés público.',null),
('aux-ayto-mad:13-ba78b876b2','aux-ayto-mad',13,'Con carácter previo a la elaboración de un proyecto de ley o reglamento, se sustanciará una consulta pública a través del portal web sobre:','["La opinión del Consejo de Estado y del órgano proponente", "Los problemas que se pretenden solucionar, la necesidad y oportunidad, los objetivos y las posibles soluciones alternativas", "El texto articulado completo del proyecto, el informe de impacto normativo, la memoria económica y el dictamen del Consejo de Estado"]'::jsonb,1,'Art. 133.1 Ley 39/2015','Son los cuatro aspectos de la consulta pública previa.',null),
('aux-ayto-mad:13-d55f6b0eb3','aux-ayto-mad',13,'Para que entren en vigor y produzcan efectos jurídicos, las normas con rango de ley, los reglamentos y disposiciones administrativas habrán de:','["Publicarse en el diario oficial correspondiente", "Firmarse por el Rey y comunicarse a las Cortes Generales", "Comunicarse a todos los Ayuntamientos y Diputaciones afectados"]'::jsonb,0,'Art. 131 Ley 39/2015','La publicación en el diario oficial es requisito de entrada en vigor.',null),
('aux-ayto-mad:13-3cc7317355','aux-ayto-mad',13,'¿Cuáles son los principios de buena regulación del art. 129 de la Ley 39/2015?','["Necesidad, eficacia, proporcionalidad, seguridad jurídica, publicidad y jerarquía", "Igualdad, mérito, capacidad y publicidad", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia"]'::jsonb,2,'Art. 129.1 Ley 39/2015','Son seis principios de buena regulación.',null),
('aux-ayto-mad:13-7632cf9e5d','aux-ayto-mad',13,'Los reglamentos y disposiciones administrativas NO podrán:','["Tipificar delitos, faltas o infracciones administrativas, establecer penas o sanciones, ni tributos", "Desarrollar una ley", "Regular la organización interna de la Administración ni el funcionamiento de sus órganos colegiados y unidades administrativas"]'::jsonb,0,'Art. 128.2 Ley 39/2015','Tampoco vulnerar la Constitución o las leyes ni regular materias reservadas a las Cortes o a las Asambleas autonómicas.',null),
('aux-ayto-mad:13-3918b61c7a','aux-ayto-mad',13,'Según la Ley 39/2015, el Gobierno de la Nación ejercerá la iniciativa legislativa en los términos de la Constitución mediante:','["La iniciativa legislativa popular", "La elaboración y aprobación de los anteproyectos de ley y la remisión de los proyectos de ley a las Cortes Generales", "Las proposiciones de ley del Senado"]'::jsonb,1,'Art. 127 Ley 39/2015','También podrá aprobar reales decretos-leyes y reales decretos legislativos.',null),
('aux-ayto-mad:13-291e0b9cc0','aux-ayto-mad',13,'Según el principio de eficiencia del art. 129.6, la iniciativa normativa debe:','["Evitar cargas administrativas innecesarias o accesorias y racionalizar la gestión de los recursos públicos", "Aprobarse sin consulta pública previa ni trámite de audiencia, para reducir la duración del procedimiento normativo", "Aumentar los trámites para garantizar el control"]'::jsonb,0,'Art. 129.6 Ley 39/2015','Eficiencia: evitar cargas innecesarias o accesorias.',null),
('aux-ayto-mad:13-fed88b82f6','aux-ayto-mad',13,'El Plan Anual Normativo que deben aprobar las Administraciones contiene:','["Las normas derogadas el año anterior", "Las iniciativas reglamentarias, pero no las legales, que se aprobarán en los cuatro años siguientes", "Las iniciativas legales o reglamentarias que vayan a ser elevadas para su aprobación en el año siguiente"]'::jsonb,2,'Art. 132.1 Ley 39/2015','Se aprueba anualmente y se publica en el Portal de la Transparencia.',null),
('aux-ayto-mad:13-420097bd22','aux-ayto-mad',13,'Según el art. 128.3 de la Ley 39/2015, las disposiciones administrativas:','["Se ajustarán al orden de jerarquía, salvo que la de rango inferior sea posterior en el tiempo y regule una materia más específica", "Tienen todas el mismo rango, y prevalece la posterior", "Se ajustarán al orden de jerarquía y ninguna podrá vulnerar los preceptos de otra de rango superior"]'::jsonb,2,'Art. 128.3 Ley 39/2015','Principio de jerarquía normativa.',null),
('aux-ayto-mad:13-f1412a83e1','aux-ayto-mad',13,'Según el art. 130.1, las Administraciones Públicas revisarán periódicamente su normativa vigente para:','["Adaptarla a los principios de buena regulación y comprobar en qué medida han conseguido sus objetivos", "Adaptarla a los principios de buena regulación, sin necesidad de evaluar si ha conseguido sus objetivos", "Remitirla al Tribunal Constitucional para que verifique su adecuación a la Constitución y a los Estatutos de Autonomía"]'::jsonb,0,'Art. 130.1 Ley 39/2015','El resultado de la evaluación se plasma en un informe que se hará público.',null),
('aux-ayto-mad:13-50fb6d3067','aux-ayto-mad',13,'La consulta pública previa a la elaboración de un proyecto normativo, a través del portal web de la Administración competente, es un instrumento de:','["Participación ciudadana en la elaboración de normas", "Control parlamentario del Gobierno", "Rendición de cuentas de los altos cargos ante el Congreso"]'::jsonb,0,'Art. 133.1 Ley 39/2015','Busca la opinión de los sujetos y organizaciones más representativas potencialmente afectados por la futura norma.',null),
('aux-ayto-mad:13-072e3710a4','aux-ayto-mad',13,'Según la Ley 7/1985, la aprobación de las Ordenanzas locales se ajusta al siguiente procedimiento:','["Aprobación inicial por la Junta de Gobierno, información pública y aprobación definitiva por el Alcalde", "Aprobación por el Pleno y publicación inmediata, sin información pública", "Aprobación inicial por el Pleno, información pública y audiencia, y aprobación definitiva por el Pleno"]'::jsonb,2,'Art. 49 LBRL','El art. 49 fija aprobación inicial por el Pleno, información pública y audiencia a los interesados durante al menos treinta días, y resolución de reclamaciones con aprobación definitiva por el Pleno.',null),
('aux-ayto-mad:13-172dcc8ea7','aux-ayto-mad',13,'El plazo mínimo de información pública y audiencia a los interesados en la aprobación de las ordenanzas locales del régimen común es de:','["Veinte días", "Treinta días", "Quince días"]'::jsonb,1,'Art. 49 b) LBRL','El art. 49 b) fija un plazo mínimo de treinta días para presentar reclamaciones y sugerencias.',null),
('aux-ayto-mad:13-077d194909','aux-ayto-mad',13,'Si durante la información pública de una ordenanza local no se presenta ninguna reclamación o sugerencia:','["Debe repetirse el trámite de información pública", "Se entiende definitivamente adoptado el acuerdo hasta entonces provisional", "El Pleno debe adoptar igualmente un acuerdo de aprobación definitiva"]'::jsonb,1,'Art. 49 LBRL','Según el último párrafo del art. 49, el acuerdo provisional se entiende definitivamente adoptado.',null),
('aux-ayto-mad:13-af974ebaff','aux-ayto-mad',13,'Según la Ley 7/1985, las ordenanzas de las corporaciones locales se publicarán en:','["El «Boletín Oficial» de la Provincia", "El «Boletín Oficial del Estado»", "El tablón de edictos del Ayuntamiento, exclusivamente"]'::jsonb,0,'Art. 70.2 LBRL','Las ordenanzas se publican en el «Boletín Oficial» de la Provincia (en Madrid, el Boletín Oficial de la Comunidad de Madrid) y no entran en vigor hasta su publicación completa y el transcurso del plazo del art. 65.2.',null),
('aux-ayto-mad:13-858fde8914','aux-ayto-mad',13,'Según el artículo 70.2 de la Ley 7/1985, las ordenanzas locales del régimen común entran en vigor:','["Cuando se haya publicado completamente su texto y haya transcurrido el plazo del artículo 65.2", "A los veinte días de su publicación completa en el Boletín Oficial del Estado", "Al día siguiente de su aprobación definitiva por el Pleno"]'::jsonb,0,'Art. 70.2 LBRL','No entran en vigor hasta que se publica completamente su texto y transcurre el plazo de quince días hábiles del art. 65.2 (el plazo de requerimiento del Estado o la Comunidad Autónoma).',null),
('aux-ayto-mad:13-1f8cfde60b','aux-ayto-mad',13,'La potestad reglamentaria de los municipios figura en la Ley 7/1985 como:','["Una potestad que solo tienen los municipios de gran población y las diputaciones", "Una potestad delegada por la Comunidad Autónoma", "Una potestad que les corresponde en todo caso, como administraciones públicas territoriales"]'::jsonb,2,'Art. 4.1 a) LBRL','El art. 4.1 a) atribuye en todo caso a municipios, provincias e islas las potestades reglamentaria y de autoorganización.',null),
('aux-ayto-mad:13-1b9af3d4f3','aux-ayto-mad',13,'En el régimen común de la Ley 7/1985, la aprobación del reglamento orgánico y de las ordenanzas corresponde:','["Al Alcalde", "A la Junta de Gobierno Local, por delegación del Pleno", "Al Pleno, sin posibilidad de delegación"]'::jsonb,2,'Art. 22.2 d) y 22.4 LBRL','El art. 22.2 d) atribuye al Pleno la aprobación del reglamento orgánico y de las ordenanzas, y el art. 22.4 impide delegarla.',null),
('aux-ayto-mad:13-cb195c87a6','aux-ayto-mad',13,'En los municipios de gran población, la aprobación de los proyectos de ordenanzas y reglamentos, incluidos los orgánicos (salvo las normas del Pleno y sus comisiones), corresponde a:','["El Alcalde", "La Junta de Gobierno Local", "Las comisiones del Pleno"]'::jsonb,1,'Art. 127.1 a) LBRL','La Junta de Gobierno aprueba los proyectos y el Pleno aprueba y modifica las ordenanzas y reglamentos (art. 123.1 d).',null),
('aux-ayto-mad:13-6205d1723c','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, la iniciativa para aprobar las normas de competencia del Pleno corresponde a:','["La Junta de Gobierno, en exclusiva", "El Alcalde, los Grupos políticos y los Concejales Presidentes de Distrito", "La Junta de Gobierno, los Grupos políticos y los Concejales, y un número de ciudadanos igual o superior al 10 % de los vecinos"]'::jsonb,2,'Art. 48.2 Ley 22/2006','El art. 48.2 reconoce la iniciativa de la Junta de Gobierno (proyectos), de los Grupos políticos y Concejales (proposiciones) y de al menos el 10 % de los vecinos.',null),
('aux-ayto-mad:13-a9350089e6','aux-ayto-mad',13,'Según la Ley 22/2006, queda excluida en todo caso de la iniciativa ciudadana para aprobar normas del Pleno:','["La materia urbanística", "La materia tributaria local", "La regulación de los distritos"]'::jsonb,1,'Art. 48.2 Ley 22/2006','El art. 48.2 excluye en todo caso de la iniciativa ciudadana la materia tributaria local.',null),
('aux-ayto-mad:13-69cdc1e1c6','aux-ayto-mad',13,'En el procedimiento de aprobación de los proyectos de normas del Pleno del Ayuntamiento de Madrid, si el proyecto afecta a los derechos e intereses legítimos de los ciudadanos, la Junta de Gobierno lo somete a alegaciones durante un plazo:','["No inferior a veinte días hábiles", "De quince días naturales", "No inferior a treinta días naturales"]'::jsonb,2,'Art. 48.3 a) Ley 22/2006','La Junta de Gobierno aprueba el proyecto inicial y lo somete a alegaciones durante un plazo no inferior a treinta días naturales.',null),
('aux-ayto-mad:13-36007793b1','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, una vez examinadas las alegaciones, el proyecto definitivo de una norma del Pleno:','["Lo aprueba directamente el Alcalde mediante decreto, sin pasar por el Pleno", "Lo aprueba la Junta de Gobierno y lo remite al Pleno con las alegaciones y la memoria de su valoración", "Se publica en el BOCM y entra en vigor sin pasar por el Pleno"]'::jsonb,1,'Art. 48.3 b) Ley 22/2006','El proyecto definitivo lo aprueba la Junta de Gobierno y lo remite al Pleno, acompañado de todas las alegaciones y de la memoria que recoja su valoración.',null),
('aux-ayto-mad:13-7caabc95e0','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, tras el dictamen de la Comisión competente, el Pleno aprueba la norma:','["En acto único", "En dos votaciones, inicial y definitiva", "Previa nueva información pública de treinta días"]'::jsonb,0,'Art. 48.3 d) Ley 22/2006','Según el art. 48.3 d), el Pleno, en acto único, aprobará la norma.',null),
('aux-ayto-mad:13-805bc93de3','aux-ayto-mad',13,'Las normas aprobadas por el Pleno del Ayuntamiento de Madrid se publican íntegramente en el Boletín Oficial de la Comunidad de Madrid y entran en vigor:','["Cuando transcurren quince días hábiles desde su publicación completa", "Al día siguiente de su publicación, salvo que la propia norma disponga otra cosa", "A los veinte días de su publicación"]'::jsonb,1,'Art. 48.3 e) Ley 22/2006','Según el art. 48.3 e), entran en vigor al día siguiente de su publicación en el BOCM, salvo que la norma disponga otra cosa, sin perjuicio de su publicación en el Boletín de la Ciudad de Madrid.',null),
('aux-ayto-mad:13-6f0336b4ed','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, las proposiciones normativas de los Grupos políticos y de los Concejales se remiten en primer lugar:','["Al Alcalde, para que decida si las tramita y las somete a alegaciones", "A la Comisión correspondiente, acompañadas de una memoria, para su dictamen", "A la Junta de Gobierno, para que apruebe un proyecto inicial"]'::jsonb,1,'Art. 48.4 a) Ley 22/2006','La proposición, con una memoria de su autor, se remite a la Comisión correspondiente para su dictamen; después, si afecta a derechos de los ciudadanos, se somete a alegaciones.',null),
('aux-ayto-mad:13-12aa39f0d5','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, toda proposición o enmienda que suponga aumento de los créditos o disminución de los ingresos del ejercicio en curso requiere para su tramitación:','["La conformidad de la Junta de Gobierno", "La mayoría absoluta del Pleno", "El informe favorable de la Intervención General"]'::jsonb,0,'Art. 48.6 Ley 22/2006','Según el art. 48.6, requiere la conformidad de la Junta de Gobierno para su tramitación.',null),
('aux-ayto-mad:13-b52fba95a9','aux-ayto-mad',13,'La aprobación de las normas del Pleno del Ayuntamiento de Madrid, además de publicarse, se comunica a:','["La Administración General del Estado y la Administración de la Comunidad de Madrid", "El Tribunal Superior de Justicia de Madrid", "La Federación Española de Municipios y Provincias y la Federación de Municipios de Madrid"]'::jsonb,0,'Art. 48.3 f) Ley 22/2006','El art. 48.3 f) exige comunicar la aprobación a la Administración General del Estado y a la de la Comunidad de Madrid.',null),
('aux-ayto-mad:13-eb980c5262','aux-ayto-mad',13,'El procedimiento del artículo 48 de la Ley 22/2006 se aplica a la elaboración y aprobación de ordenanzas, reglamentos y estatutos de organismos autónomos y entidades públicas empresariales, con excepción de:','["Las ordenanzas fiscales", "El planeamiento urbanístico, que se rige por su normativa específica", "Los reglamentos orgánicos"]'::jsonb,1,'Art. 48.1 Ley 22/2006','Según el art. 48.1, se exceptúa el planeamiento urbanístico, que se rige por su normativa específica.',null),
('aux-ayto-mad:13-7fbb7ddb19','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, la iniciativa para aprobar el Presupuesto general corresponde:','["En exclusiva a la Junta de Gobierno", "Al Alcalde y a la Comisión de Hacienda", "A la Junta de Gobierno y a los Grupos políticos"]'::jsonb,0,'Art. 49.1 Ley 22/2006','El art. 49.1 atribuye la iniciativa en exclusiva a la Junta de Gobierno.',null),
('aux-ayto-mad:13-f6baac55c0','aux-ayto-mad',13,'El Proyecto de Presupuesto del Ayuntamiento de Madrid se expone al público, previo anuncio en el BOCM, durante:','["Quince días naturales", "Veinte días hábiles", "Treinta días naturales"]'::jsonb,0,'Art. 49.3 Ley 22/2006','Se expone al público quince días naturales, durante los cuales los interesados pueden examinarlo y presentar alegaciones.',null),
('aux-ayto-mad:13-53178602be','aux-ayto-mad',13,'El Proyecto de Presupuesto del Ayuntamiento de Madrid se remitirá al Pleno antes del:','["15 de octubre", "1 de diciembre", "1 de noviembre"]'::jsonb,2,'Art. 49.5 Ley 22/2006','Según el art. 49.5, se remitirá al Pleno antes del día 1 de noviembre.',null),
('aux-ayto-mad:13-fc6fdbbe23','aux-ayto-mad',13,'Las alegaciones al Proyecto de Presupuesto del Ayuntamiento de Madrid pueden fundarse, entre otros motivos, en:','["La falta de inversiones en el distrito del alegante respecto del ejercicio anterior", "La disconformidad con las prioridades políticas del gasto", "Omitir el crédito necesario para cumplir obligaciones exigibles al municipio"]'::jsonb,2,'Art. 49.4 Ley 22/2006','Solo caben alegaciones por omitir créditos para obligaciones exigibles o por manifiesta insuficiencia de los ingresos respecto de los gastos, o de estos respecto de las necesidades.',null),
('aux-ayto-mad:13-3eda72801f','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, la aprobación y modificación de los reglamentos de naturaleza orgánica requiere:','["Mayoría absoluta del número legal de miembros del Pleno", "Mayoría simple del Pleno", "Dos tercios del Pleno"]'::jsonb,0,'Art. 11.2 Ley 22/2006','El art. 11.2 exige mayoría absoluta para los acuerdos del párrafo c) del art. 11.1 (reglamentos orgánicos).',null),
('aux-ayto-mad:13-58d870a040','aux-ayto-mad',13,'En el Ayuntamiento de Madrid, la aprobación de las ordenanzas y reglamentos municipales no orgánicos se adopta por el Pleno por:','["Mayoría simple de votos", "Mayoría absoluta del número legal de miembros", "Mayoría de tres quintos"]'::jsonb,0,'Art. 11.2 Ley 22/2006','El párrafo d) del art. 11.1 no está entre los que requieren mayoría absoluta, así que se aplica la mayoría simple.',null),
('aux-ayto-mad:13-34cf2f1078','aux-ayto-mad',13,'El Alcalde de Madrid puede dictar bandos para:','["Recordar y precisar los términos del cumplimiento de normas en vigor o hacer apelaciones a la población por circunstancias especiales", "Modificar ordenanzas en caso de urgencia sin pasar por el Pleno, dando cuenta después", "Aprobar normas que obliguen a los vecinos con rango de ordenanza"]'::jsonb,0,'Art. 14.3 e) Ley 22/2006','Los bandos sirven para recordar y precisar los términos de normas en vigor o para hacer apelaciones a la población con motivo de acontecimientos o circunstancias especiales; no crean normas nuevas.',null),
('aux-ayto-mad:13-be90fffc72','aux-ayto-mad',13,'Según la Ley 22/2006, las ordenanzas municipales de Madrid pueden establecer los casos concretos en los que pueda imponerse la multa coercitiva y graduar su cuantía, sin superar en ningún caso:','["6.000 euros", "1.500 euros y sus actualizaciones anuales conforme al IPC", "3.000 euros y sus actualizaciones anuales conforme al IPC"]'::jsonb,2,'Art. 52.2 Ley 22/2006','Según el art. 52.2, la ordenanza no podrá superar en ningún caso el límite máximo de 3.000 euros, actualizable con el IPC.',null),
('aux-ayto-mad:13-e178d25df7','aux-ayto-mad',13,'Según la Ley 22/2006, la Junta de Gobierno aprueba los proyectos de los estatutos de:','["Los organismos autónomos, entidades públicas empresariales, sociedades mercantiles y fundaciones", "Los grupos políticos municipales", "Las asociaciones vecinales inscritas en el registro municipal de entidades ciudadanas"]'::jsonb,0,'Art. 17.1 a) Ley 22/2006','La Junta de Gobierno aprueba los proyectos de esos estatutos; su aprobación definitiva corresponde al Pleno (art. 11.1 l).',null),
('aux-ayto-mad:14-31fab45bcc','aux-ayto-mad',14,'La Ley 9/2017 de Contratos del Sector Público califica como contratos de obras, concesión de obras, concesión de servicios, suministro y servicios a:','["Los contratos que regula en su sección de calificación de contratos", "Los contratos patrimoniales de compraventa y arrendamiento de bienes inmuebles", "Los convenios de colaboración entre Administraciones"]'::jsonb,0,'Art. 12.1 LCSP','Son los contratos que se califican según las normas de esa sección: obras, concesión de obras, concesión de servicios, suministro y servicios.',null),
('aux-ayto-mad:14-5b9afbe804','aux-ayto-mad',14,'El contrato de obras tiene por objeto, entre otros:','["La adquisición o el arrendamiento de bienes muebles necesarios para una obra", "La gestión de un servicio público, con o sin ejecución previa de una obra por el contratista", "La ejecución de una obra, aislada o conjuntamente con la redacción del proyecto"]'::jsonb,2,'Art. 13.1 LCSP','Tiene por objeto la ejecución de una obra, aislada o conjuntamente con la redacción del proyecto, o los trabajos del Anexo I.',null),
('aux-ayto-mad:14-a8f9418302','aux-ayto-mad',14,'Los contratos de suministro tienen por objeto:','["La adquisición o el arrendamiento de bienes inmuebles, con o sin opción de compra, y de derechos sobre ellos", "La prestación de una actividad o de un resultado distinto de una obra, a cambio de un precio cierto", "La adquisición, el arrendamiento financiero o el arrendamiento de productos o bienes muebles"]'::jsonb,2,'Art. 16.1 LCSP','Tienen por objeto la adquisición, el arrendamiento financiero o el arrendamiento, con o sin opción de compra, de productos o bienes muebles.',null),
('aux-ayto-mad:14-6a28ee4cad','aux-ayto-mad',14,'Los contratos de servicios son aquellos cuyo objeto son:','["La adquisición, el arrendamiento financiero o el arrendamiento, con o sin opción de compra, de productos o bienes muebles", "Prestaciones de hacer consistentes en una actividad o dirigidas a un resultado distinto de una obra o suministro", "La adquisición o el arrendamiento de bienes inmuebles, valores negociables o derechos de propiedad incorporal sobre ellos"]'::jsonb,1,'Art. 17 LCSP','Son prestaciones de hacer consistentes en el desarrollo de una actividad o dirigidas a un resultado distinto de una obra o un suministro.',null),
('aux-ayto-mad:14-e5ca30945a','aux-ayto-mad',14,'Los contratos de suministros y servicios de prestación sucesiva tienen un plazo máximo de duración de:','["Cuatro años, más dos de posibles prórrogas anuales", "Diez años, incluidas las posibles prórrogas", "Cinco años, incluidas las posibles prórrogas"]'::jsonb,2,'Art. 29.4 LCSP','Cinco años, incluyendo las posibles prórrogas.',null),
('aux-ayto-mad:14-c1b7acaeef','aux-ayto-mad',14,'Los contratos menores:','["No pueden durar más de un año ni ser objeto de prórroga", "No pueden durar más de un año, pero pueden prorrogarse una vez", "Pueden durar hasta dos años, sin posibilidad de prórroga"]'::jsonb,0,'Art. 29.8 LCSP','No pueden tener una duración superior a un año ni ser objeto de prórroga.',null),
('aux-ayto-mad:14-bcc383b770','aux-ayto-mad',14,'El recurso especial en materia de contratación tiene carácter:','["Obligatorio", "Previo al recurso de alzada", "Potestativo"]'::jsonb,2,'Art. 44.7 LCSP','Tiene carácter potestativo y es gratuito para los recurrentes.',null),
('aux-ayto-mad:14-9aeab4399c','aux-ayto-mad',14,'El plazo para interponer el recurso especial en materia de contratación es de:','["Dos meses", "Quince días hábiles", "Diez días naturales"]'::jsonb,1,'Art. 50.1 LCSP','El plazo es de quince días hábiles.',null),
('aux-ayto-mad:14-072e9c7f51','aux-ayto-mad',14,'El perfil de contratante se difunde:','["Exclusivamente a través de Internet", "En la prensa nacional", "En el BOE"]'::jsonb,0,'Art. 63 LCSP','Los órganos de contratación difunden exclusivamente a través de Internet su perfil de contratante.',null),
('aux-ayto-mad:14-f499ddb02d','aux-ayto-mad',14,'Pueden contratar con el sector público las personas naturales o jurídicas que:','["Tengan plena capacidad de obrar, no estén incursas en prohibición de contratar y acrediten su solvencia", "Tengan plena capacidad de obrar y estén inscritas en el registro mercantil desde hace al menos cinco años", "Tengan domicilio social en España y plena capacidad de obrar, estén inscritas en el Registro Mercantil y acrediten su solvencia"]'::jsonb,0,'Art. 65.1 LCSP','Se exige plena capacidad de obrar, no estar incursas en prohibición de contratar y acreditar la solvencia (o clasificación cuando se exija).',null),
('aux-ayto-mad:14-28de4fe050','aux-ayto-mad',14,'La garantía provisional, cuando se exige, no puede ser superior al:','["2 % del valor estimado del contrato, IVA excluido", "10 % del presupuesto base de licitación, IVA incluido", "3 % del presupuesto base de licitación, IVA excluido"]'::jsonb,2,'Art. 106.2 LCSP','No puede superar el 3 % del presupuesto base de licitación, excluido el IVA.',null),
('aux-ayto-mad:14-548096cdfd','aux-ayto-mad',14,'La garantía definitiva es, con carácter general, del:','["2 % del valor estimado", "5 % del precio final ofertado, IVA excluido", "10 % del precio con IVA"]'::jsonb,1,'Art. 107.1 LCSP','Es del 5 % del precio final ofertado, excluido el IVA.',null),
('aux-ayto-mad:14-0f6073ce81','aux-ayto-mad',14,'Son contratos menores de obras los de valor estimado inferior a:','["40.000 euros", "15.000 euros", "100.000 euros"]'::jsonb,0,'Art. 118.1 LCSP','Obras: valor estimado inferior a 40.000 €. Suministro o servicios: inferior a 15.000 €.',null),
('aux-ayto-mad:14-baaecdf797','aux-ayto-mad',14,'Son contratos menores de suministro o de servicios los de valor estimado inferior a:','["6.000 euros", "15.000 euros", "30.000 euros"]'::jsonb,1,'Art. 118.1 LCSP','Suministro o servicios: inferior a 15.000 €. Obras: inferior a 40.000 €.',null),
('aux-ayto-mad:14-cadd0d5611','aux-ayto-mad',14,'Con carácter ordinario, la adjudicación se realiza por:','["El diálogo competitivo, utilizando como único criterio el precio más bajo ofertado", "El procedimiento negociado con publicidad, con pluralidad de criterios basados en la mejor relación calidad-precio", "El procedimiento abierto o el restringido, con pluralidad de criterios basados en la mejor relación calidad-precio"]'::jsonb,2,'Art. 131.2 LCSP','Ordinariamente por procedimiento abierto o restringido, con pluralidad de criterios basados en la mejor relación calidad-precio.',null),
('aux-ayto-mad:14-bffd5c4ecb','aux-ayto-mad',14,'Los contratos se adjudican utilizando una pluralidad de criterios en base a:','["La menor huella de carbono", "La mayor experiencia acreditada de la empresa", "La mejor relación calidad-precio"]'::jsonb,2,'Art. 145.1 LCSP','Se adjudican con pluralidad de criterios en base a la mejor relación calidad-precio.',null),
('aux-ayto-mad:14-32b4e59f03','aux-ayto-mad',14,'Si el contrato no es susceptible de recurso especial, la formalización debe hacerse:','["No más tarde de los quince días naturales siguientes a la publicación de la adjudicación", "No más tarde de un mes desde la notificación de la adjudicación a todos los licitadores participantes", "No más tarde de los quince días hábiles siguientes a la notificación de la adjudicación"]'::jsonb,2,'Art. 153.3 LCSP','No más tarde de los quince días hábiles siguientes a la notificación de la adjudicación.',null),
('aux-ayto-mad:14-e05f4f0291','aux-ayto-mad',14,'En el procedimiento abierto:','["Solo pueden presentar proposición las empresas inscritas en el Registro Oficial de Licitadores", "Solo pueden presentar proposición las empresas invitadas por el órgano de contratación", "Todo empresario interesado puede presentar una proposición, excluida toda negociación"]'::jsonb,2,'Art. 156.1 LCSP','Todo empresario interesado puede presentar una proposición, quedando excluida toda negociación.',null),
('aux-ayto-mad:14-4cd80b5eda','aux-ayto-mad',14,'En el procedimiento restringido pueden presentar proposiciones:','["Solo los empresarios que, a su solicitud y en atención a su solvencia, sean seleccionados", "Solo los empresarios inscritos en el Registro Oficial de Licitadores y Empresas Clasificadas", "Todos los empresarios interesados, excluida toda negociación de los términos del contrato"]'::jsonb,0,'Art. 160.2 LCSP','Cualquier empresa puede solicitar participar, pero solo presentan proposiciones las seleccionadas.',null),
('aux-ayto-mad:14-3e469cf2bd','aux-ayto-mad',14,'En el procedimiento restringido, el número mínimo de empresarios invitados no puede ser inferior a:','["Diez", "Cinco", "Dos"]'::jsonb,1,'Art. 162.2 LCSP','No puede ser inferior a cinco.',null),
('aux-ayto-mad:14-305c6f66a2','aux-ayto-mad',14,'En los procedimientos con negociación, la adjudicación recae en el licitador elegido:','["Por sorteo público entre los candidatos que hayan acreditado la solvencia exigida en los pliegos", "Atendiendo únicamente al precio más bajo, sin negociación", "Tras negociar las condiciones del contrato con uno o varios candidatos"]'::jsonb,2,'Art. 166.1 LCSP','Recae en el licitador justificadamente elegido tras negociar las condiciones con uno o varios candidatos.',null),
('aux-ayto-mad:14-46eda3f172','aux-ayto-mad',14,'En la tramitación urgente del expediente, el plazo de inicio de la ejecución del contrato no podrá exceder de:','["Un mes, contado desde la formalización", "Una semana, contada desde la formalización", "Tres meses, contados desde la adjudicación"]'::jsonb,0,'Art. 119.2 c) LCSP','La urgencia reduce además a la mitad los plazos de licitación, adjudicación y formalización.',null),
('aux-ayto-mad:14-372e0851e8','aux-ayto-mad',14,'El orden jurisdiccional contencioso-administrativo es competente para resolver las cuestiones relativas a:','["Los despidos del personal del contratista y las reclamaciones de los subcontratistas por los pagos pendientes", "La preparación, adjudicación, efectos, modificación y extinción de los contratos administrativos", "Los efectos y extinción de los contratos privados de los poderes adjudicadores que no sean Administraciones"]'::jsonb,1,'Art. 27.1 a) LCSP','El orden civil conoce de los efectos y extinción de los contratos privados.',null),
('aux-ayto-mad:14-2b87ba324b','aux-ayto-mad',14,'Es causa de resolución del contrato la demora en el cumplimiento de los plazos que suponga un retraso injustificado superior a:','["Un mes, en todo caso", "Un quinto del plazo de duración inicial del contrato, sin incluir las prórrogas", "Un tercio del plazo de duración inicial del contrato, incluidas las prórrogas"]'::jsonb,2,'Art. 211.1 d) LCSP','Es una de las causas de resolución del art. 211.',null),
('aux-ayto-mad:14-f7ac8aa247','aux-ayto-mad',14,'Un encargo a un medio propio personificado que cumpla los requisitos legales:','["Es un contrato menor, si no supera los 15.000 euros", "Es un contrato de servicios no armonizado", "No tendrá la consideración de contrato"]'::jsonb,2,'Art. 32.1 LCSP','Requiere, entre otros, que más del 80 % de la actividad del ente se realice para el poder adjudicador que lo controla.',null),
('aux-ayto-mad:14-9f3e132265','aux-ayto-mad',14,'En el procedimiento de licitación con negociación, cuando se limite el número de candidatos, el mínimo será de:','["Cinco", "Tres", "Diez"]'::jsonb,1,'Art. 169.2 LCSP','El número mínimo de invitados es tres.',null),
('aux-ayto-mad:14-1766f47735','aux-ayto-mad',14,'La garantía definitiva puede constituirse, entre otras formas:','["Mediante pagaré personal del contratista o mediante prenda sobre maquinaria, sin necesidad de aval", "En efectivo o valores, mediante aval o mediante contrato de seguro de caución", "Mediante hipoteca sobre bienes inmuebles del contratista o de un tercero, o mediante prenda sobre sus bienes muebles"]'::jsonb,1,'Art. 108.1 LCSP','Son las formas de constitución de la garantía.',null),
('aux-ayto-mad:14-c57d7b375f','aux-ayto-mad',14,'En el ámbito de la AGE, el conocimiento y resolución de los recursos especiales en materia de contratación corresponde a:','["El Tribunal Administrativo Central de Recursos Contractuales", "La Audiencia Nacional", "El Tribunal de Cuentas"]'::jsonb,0,'Art. 45.1 LCSP','Las CCAA pueden crear órganos propios o atribuir la competencia al Tribunal estatal por convenio.',null),
('aux-ayto-mad:14-2fac797dd9','aux-ayto-mad',14,'En la AGE, el anuncio de licitación se publica en el perfil de contratante y, además:','["En el BOE", "En un periódico de tirada nacional", "En el tablón de anuncios del Ministerio exclusivamente"]'::jsonb,0,'Art. 135.1 LCSP','Si el contrato está sujeto a regulación armonizada, también en el DOUE.',null),
('aux-ayto-mad:14-385bc25383','aux-ayto-mad',14,'La información publicada en el perfil de contratante debe mantenerse durante un periodo de tiempo de, al menos:','["10 años", "5 años", "6 meses"]'::jsonb,1,'Art. 63.1 LCSP','El acceso al perfil es libre y se difunde exclusivamente a través de Internet.',null),
('aux-ayto-mad:14-8a1e24739d','aux-ayto-mad',14,'Con carácter general, la duración de la prohibición de contratar no podrá exceder de:','["Diez años", "Cinco años", "Tres años"]'::jsonb,2,'Art. 72.6 LCSP','Salvo que la sentencia o resolución firme establezca otro plazo.',null),
('aux-ayto-mad:14-89d8a44e84','aux-ayto-mad',14,'Según el art. 2.1 LCSP, un contrato es oneroso cuando:','["Se paga siempre en metálico", "Supera los 15.000 euros de valor estimado, en el caso de los contratos de servicios y suministros", "El contratista obtiene algún tipo de beneficio económico, directo o indirecto"]'::jsonb,2,'Art. 2.1 LCSP','La ley se aplica a los contratos onerosos celebrados por las entidades del sector público.',null),
('aux-ayto-mad:14-e072d61a69','aux-ayto-mad',14,'El valor estimado de los contratos de obras, suministros y servicios se calcula:','["Sin incluir las posibles prórrogas", "Por el importe total pagadero, sin incluir el IVA", "Por el importe total pagadero, incluido el IVA"]'::jsonb,1,'Art. 101.1 a) LCSP','Se tienen en cuenta las eventuales prórrogas y modificaciones previstas.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:14-6e9770b157','aux-ayto-mad',14,'La publicación de la información de los contratos menores en el perfil de contratante se realizará:','["Diariamente", "Solo si superan 15.000 euros", "Al menos trimestralmente"]'::jsonb,2,'Art. 63.4 LCSP','Quedan exceptuados los de valor inferior a 5.000 euros pagados mediante anticipo de caja fija o similar.',null),
('aux-ayto-mad:14-627839f0fd','aux-ayto-mad',14,'Los contratos podrán modificarse durante su vigencia, cuando así se haya advertido expresamente en el pliego, hasta un máximo del:','["100 % del precio inicial", "20 % del precio inicial", "50 % del precio inicial"]'::jsonb,1,'Art. 204.1 LCSP','Para las modificaciones no previstas en el pliego rige el art. 205.',null),
('aux-ayto-mad:14-3fcc1fb635','aux-ayto-mad',14,'En la tramitación de emergencia:','["No puede contratarse", "Hay que tramitar siempre un procedimiento abierto con plazos reducidos a la mitad, como en la tramitación urgente", "El órgano de contratación puede ordenar la ejecución sin obligación de tramitar expediente de contratación"]'::jsonb,2,'Art. 120.1 a) LCSP','El inicio de la ejecución no puede exceder de un mes desde el acuerdo.',null),
('aux-ayto-mad:14-9304c162a9','aux-ayto-mad',14,'Cuando haya varios criterios de adjudicación, el plazo máximo para adjudicar será de:','["Un mes desde la apertura de las proposiciones, salvo que el pliego indique otro", "Quince días desde la apertura de las proposiciones, sin que el pliego pueda fijar otro", "Dos meses desde la apertura de las proposiciones, salvo que el pliego indique otro"]'::jsonb,2,'Art. 158.2 LCSP','Con un único criterio (el precio), el plazo es de quince días.',null),
('aux-ayto-mad:14-94c013d7e4','aux-ayto-mad',14,'Los contratos de suministro de la AGE y sus organismos están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["750.000 euros", "5.404.000 euros", "140.000 euros"]'::jsonb,2,'Art. 21.1 LCSP','Para otras entidades el umbral es de 216.000 euros.',null),
('aux-ayto-mad:14-9e71b92917','aux-ayto-mad',14,'Las concesiones de obras y de servicios que comprendan la ejecución de obras tendrán un plazo de duración máximo de:','["40 años", "10 años", "25 años"]'::jsonb,0,'Art. 29.6 a) LCSP','Las concesiones de servicios sin obras no sanitarios, 25 años; los sanitarios del art. 29.6 c), 10 años.',null),
('aux-ayto-mad:14-d42b76d1f0','aux-ayto-mad',14,'Para que el contratista pueda ceder sus derechos y obligaciones a un tercero, es requisito que el cedente tenga ejecutado al menos:','["La totalidad de la prestación", "Un 20 % del importe del contrato", "Un 50 % del importe del contrato o de su duración"]'::jsonb,1,'Art. 214.2 b) LCSP','Además, se necesita autorización previa del órgano de contratación.',null),
('aux-ayto-mad:14-d669e1529e','aux-ayto-mad',14,'La duración de un acuerdo marco no podrá exceder, salvo casos excepcionales justificados, de:','["Dos años", "Diez años", "Cuatro años"]'::jsonb,2,'Art. 219.2 LCSP','Es la duración máxima ordinaria de los acuerdos marco.',null),
('aux-ayto-mad:14-2f9837ae70','aux-ayto-mad',14,'La prórroga de un contrato será obligatoria para el empresario siempre que su preaviso se produzca, al menos, con una antelación de:','["Dos meses respecto de la finalización del plazo de duración del contrato", "Seis meses respecto de la finalización del plazo de duración del contrato", "Quince días respecto de la finalización del plazo de duración del contrato"]'::jsonb,0,'Art. 29.2 LCSP','La prórroga no puede producirse por consentimiento tácito de las partes.',null),
('aux-ayto-mad:14-c2a3020292','aux-ayto-mad',14,'Los contratos de servicios sociales y otros del anexo IV están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["750.000 euros", "216.000 euros", "5.404.000 euros"]'::jsonb,0,'Art. 22.1 LCSP','Es un umbral específico para los servicios del anexo IV.',null),
('aux-ayto-mad:14-97fd9f080c','aux-ayto-mad',14,'Tanto en la concesión de obras como en la de servicios es necesaria la transferencia al concesionario de:','["El riesgo operacional", "La potestad sancionadora", "La titularidad del servicio público"]'::jsonb,0,'Arts. 14.4 y 15.2 LCSP','El concesionario asume el riesgo operacional en la explotación.',null),
('aux-ayto-mad:14-8849160d80','aux-ayto-mad',14,'La inscripción en el Registro Oficial de Licitadores y Empresas Clasificadas del Sector Público acredita, salvo prueba en contrario:','["Las condiciones de aptitud del empresario frente a todos los órganos de contratación del sector público", "Las condiciones de aptitud del empresario solo frente a los órganos de contratación de la Administración General del Estado", "Las condiciones de aptitud del empresario, pero solo frente a los órganos de contratación de la Administración General del Estado"]'::jsonb,0,'Art. 96.1 LCSP','Acredita personalidad, capacidad, representación, solvencia y ausencia de prohibiciones.',null),
('aux-ayto-mad:14-f5dd1c5b82','aux-ayto-mad',14,'Las entidades del sector público no podrán celebrar otros contratos que:','["Aquellos que sean necesarios para el cumplimiento y realización de sus fines institucionales", "Los que demanden los ciudadanos a través de los procesos de participación ciudadana y presupuestos participativos", "Los que superen 40.000 euros y estén previstos en el plan anual de contratación aprobado por el órgano"]'::jsonb,0,'Art. 28.1 LCSP','Principio de necesidad e idoneidad del contrato.',null),
('aux-ayto-mad:14-eaeae431fa','aux-ayto-mad',14,'Según el art. 197 LCSP, la ejecución del contrato se realizará:','["A riesgo compartido al 50 %", "A riesgo del responsable del contrato", "A riesgo y ventura del contratista"]'::jsonb,2,'Art. 197 LCSP','Sin perjuicio de lo previsto para el contrato de obras en el art. 239.',null),
('aux-ayto-mad:14-f650fc70da','aux-ayto-mad',14,'Están sujetos a regulación armonizada los contratos de obras y concesiones de valor estimado igual o superior a:','["5.404.000 euros", "1.000.000 euros", "216.000 euros"]'::jsonb,0,'Art. 20.1 LCSP','Umbral vigente según el texto consolidado del BOE (los umbrales se revisan periódicamente).',null),
('aux-ayto-mad:14-414b778078','aux-ayto-mad',14,'Para que un ente sea medio propio personificado, más del ___ de sus actividades deben llevarse a cabo en el ejercicio de los cometidos que le confíe el poder adjudicador:','["50 %", "100 %", "80 %"]'::jsonb,2,'Art. 32.2 b) LCSP','Más del 80 % de su actividad debe dirigirse al poder adjudicador que lo controla.',null),
('aux-ayto-mad:14-21f285ca09','aux-ayto-mad',14,'En la concesión de obras, la contraprestación a favor del concesionario consiste en:','["Un precio fijo pagado por adelantado por la Administración, sin derecho a explotar la obra", "Una subvención anual a cargo de la Administración concedente, sin derecho a explotar la obra", "El derecho a explotar la obra, o dicho derecho acompañado del de percibir un precio"]'::jsonb,2,'Art. 14.1 LCSP','La concesión implica la transferencia del riesgo operacional al concesionario.',null),
('aux-ayto-mad:14-a76caa297f','aux-ayto-mad',14,'Si transcurren dos meses desde la interposición del recurso especial sin que se notifique su resolución:','["Se entiende estimado por silencio administrativo y la adjudicación queda sin efecto, debiendo el órgano de contratación adjudicar al siguiente licitador", "El contrato se anula", "El interesado podrá considerarlo desestimado a efectos de interponer recurso contencioso-administrativo"]'::jsonb,2,'Art. 57.5 LCSP','El silencio en el recurso especial es desestimatorio.',null),
('aux-ayto-mad:14-e404a20dad','aux-ayto-mad',14,'Si el licitador propuesto no cumplimenta adecuadamente el requerimiento de documentación en plazo, se le exigirá una penalidad del:','["5 % del presupuesto base de licitación, IVA incluido", "3 % del presupuesto base de licitación, IVA excluido", "10 % del precio de adjudicación"]'::jsonb,1,'Art. 150.2 LCSP','Se entiende que ha retirado su oferta.',null),
('aux-ayto-mad:14-57db65a88f','aux-ayto-mad',14,'Los expedientes de resolución contractual deberán ser instruidos y resueltos en el plazo máximo de:','["Seis meses", "Ocho meses", "Tres meses"]'::jsonb,1,'Art. 212.8 LCSP','Plazo máximo de ocho meses.',null),
('aux-ayto-mad:14-0bbad2fa21','aux-ayto-mad',14,'Los órganos de contratación designarán un responsable del contrato al que corresponderá:','["Adjudicar el contrato, fijar el precio de licitación y resolver el recurso especial en materia de contratación que interpongan los licitadores excluidos", "Fijar el precio del contrato y resolver las reclamaciones de los licitadores sobre la adjudicación, previo informe de la mesa de contratación y de los servicios jurídicos", "Supervisar su ejecución y adoptar las decisiones y dictar las instrucciones necesarias para asegurar la correcta realización de la prestación"]'::jsonb,2,'Art. 62.1 LCSP','Su designación es obligatoria.',null),
('aux-ayto-mad:14-65252753c2','aux-ayto-mad',14,'Las penalidades por demora en la ejecución, salvo que el pliego disponga otras, serán diarias en la proporción de:','["1 euro por cada 100 euros", "0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido", "0,10 euros por cada 1.000 euros"]'::jsonb,1,'Art. 193.3 LCSP','Cada vez que las penalidades alcancen un múltiplo del 5 % del precio se puede resolver el contrato.',null),
('aux-ayto-mad:14-1fc451353b','aux-ayto-mad',14,'Si se interpone recurso especial contra la adjudicación, como regla general:','["La adjudicación se anula automáticamente y se retrotrae el procedimiento", "Quedará en suspenso la tramitación del procedimiento", "El contrato se formaliza igualmente"]'::jsonb,1,'Art. 53 LCSP','Salvo en contratos basados en acuerdos marco o sistemas dinámicos de adquisición.',null),
('aux-ayto-mad:14-6f9c1291a0','aux-ayto-mad',14,'El procedimiento abierto simplificado puede utilizarse en contratos de obras de valor estimado igual o inferior a:','["2.000.000 de euros", "500.000 euros, IVA excluido", "100.000 euros, IVA excluido"]'::jsonb,0,'Art. 159.1 LCSP','Para suministros y servicios hay un umbral inferior.',null),
('aux-ayto-mad:14-8bfef88ea2','aux-ayto-mad',14,'Contra la resolución del recurso especial en materia de contratación:','["Cabe recurso potestativo de reposición ante el mismo tribunal administrativo, y después recurso contencioso-administrativo", "No cabe ningún recurso", "Solo procederá la interposición de recurso contencioso-administrativo"]'::jsonb,2,'Art. 59.1 LCSP','La resolución es directamente ejecutiva.',null),
('aux-ayto-mad:14-3284c95a2e','aux-ayto-mad',14,'En los contratos de servicios del anexo IV y en los que tengan por objeto prestaciones de carácter intelectual, los criterios relacionados con la calidad deben representar, al menos:','["El 30 % de la puntuación asignable", "El 75 % de la puntuación asignable", "El 51 % de la puntuación asignable"]'::jsonb,2,'Art. 145.4 LCSP','Garantiza que la calidad pese más que el precio en esos contratos.',null),
('aux-ayto-mad:14-a9c85eb9fc','aux-ayto-mad',14,'NO procede el recurso especial en materia de contratación respecto de los procedimientos de adjudicación que se sigan:','["Por el trámite de emergencia", "Mediante procedimiento restringido", "Mediante procedimiento abierto"]'::jsonb,0,'Art. 44.4 LCSP','No cabe recurso especial en la tramitación de emergencia.',null),
('aux-ayto-mad:14-05a9b8d7ef','aux-ayto-mad',14,'Si la demora en el pago por la Administración fuese superior a seis meses, el contratista tendrá derecho a:','["Resolver el contrato y al resarcimiento de los perjuicios", "Una prórroga del contrato por un plazo igual al de la demora", "Ceder el contrato a un tercero sin necesidad de autorización del órgano de contratación"]'::jsonb,0,'Art. 198.6 LCSP','Si la demora supera cuatro meses puede suspender el cumplimiento del contrato.',null),
('aux-ayto-mad:14-234f1759d2','aux-ayto-mad',14,'La garantía complementaria que puede exigirse en casos especiales puede ser de hasta un 5 %, de modo que la garantía total pueda alcanzar:','["Un 10 % del precio del contrato", "Un 15 % del precio del contrato", "Un 8 % del precio del contrato, IVA incluido"]'::jsonb,0,'Art. 107.2 LCSP','La garantía definitiva ordinaria es del 5 % y la complementaria hasta otro 5 %.',null),
('aux-ayto-mad:14-0aa1c2c176','aux-ayto-mad',14,'La Administración tiene la obligación de abonar el precio dentro de los ___ siguientes a la fecha de aprobación de las certificaciones o documentos de conformidad:','["Quince días", "Treinta días", "Sesenta días"]'::jsonb,1,'Art. 198.4 LCSP','Si se retrasa, debe abonar intereses de demora y la indemnización por costes de cobro.',null),
('aux-ayto-mad:14-0285a01186','aux-ayto-mad',14,'Contra las actuaciones susceptibles de recurso especial en materia de contratación:','["Cabe recurso extraordinario de revisión previo, en los supuestos del art. 125 de la Ley 39/2015", "Cabe además recurso de alzada ante el titular del departamento ministerial", "No procederá la interposición de recursos administrativos ordinarios"]'::jsonb,2,'Art. 44.5 LCSP','El recurso especial sustituye a los recursos ordinarios.',null),
('aux-ayto-mad:14-0449399d8b','aux-ayto-mad',14,'¿Puede prorrogarse un contrato por consentimiento tácito de las partes?','["Sí, si es un contrato menor", "No, en ningún caso", "Sí, si lo autoriza el responsable del contrato"]'::jsonb,1,'Art. 29.2 LCSP','La prórroga la acuerda el órgano de contratación y nunca es tácita.',null),
('aux-ayto-mad:14-8e9640cb18','aux-ayto-mad',14,'Es una prohibición de contratar del art. 71.1:','["Haber sido adjudicatario de otro contrato con la misma Administración en los últimos tres años", "Haber sido condenado mediante sentencia firme por determinados delitos, como cohecho o prevaricación", "Tener menos de diez trabajadores"]'::jsonb,1,'Art. 71.1 a) LCSP','Otras: sanciones firmes, concurso, incumplimiento de obligaciones tributarias o de Seguridad Social…',null),
('aux-ayto-mad:14-4020ebec9f','aux-ayto-mad',14,'Cada una de las penalidades no podrá ser superior al ___ del precio del contrato, ni el total superar el 50 %:','["20 %", "30 %", "10 %"]'::jsonb,2,'Art. 192.1 LCSP','Límites de las penalidades contractuales.',null),
('aux-ayto-mad:14-01e1506297','aux-ayto-mad',14,'En los contratos de las Administraciones Públicas, el pago aplazado del precio:','["Es obligatorio en los contratos de obras de valor estimado superior a 5.000.000 de euros", "Está prohibido, salvo excepciones como el arrendamiento financiero", "Solo se permite en contratos menores y en los de suministro de bienes"]'::jsonb,1,'Art. 102.8 LCSP','Se prohíbe salvo los supuestos legalmente previstos.',null),
('aux-ayto-mad:15-bb6024bb72','aux-ayto-mad',15,'Según el art. 8.2 del TREBEP, los empleados públicos se clasifican en:','["Funcionarios de carrera, personal laboral, personal eventual y personal directivo", "Funcionarios de carrera, funcionarios interinos, personal laboral, personal eventual y personal directivo profesional", "Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual"]'::jsonb,2,'Art. 8.2 TREBEP','Se clasifican en funcionarios de carrera, funcionarios interinos, personal laboral (fijo, por tiempo indefinido o temporal) y personal eventual.',null),
('aux-ayto-mad:15-ac26f09f0d','aux-ayto-mad',15,'Las funciones que implican participación directa o indirecta en el ejercicio de potestades públicas corresponden:','["Exclusivamente a los funcionarios de carrera, nunca a los interinos", "Al personal laboral fijo y a los funcionarios de carrera, en los términos que establezca la ley de cada Administración", "Exclusivamente a los funcionarios públicos"]'::jsonb,2,'Art. 9.2 TREBEP','Corresponden exclusivamente a los funcionarios públicos, en los términos que establezca la ley de desarrollo de cada Administración.',null),
('aux-ayto-mad:15-cefce8a58c','aux-ayto-mad',15,'Un funcionario interino nombrado para cubrir una plaza vacante puede ocuparla como máximo:','["Cinco años", "Un año", "Tres años"]'::jsonb,2,'Art. 10.1 a) TREBEP','Las plazas vacantes pueden cubrirse por interinos cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de tres años.',null),
('aux-ayto-mad:15-7d6528ecd2','aux-ayto-mad',15,'El nombramiento de interinos por exceso o acumulación de tareas tiene un plazo máximo de:','["Seis meses dentro de un periodo de doce", "Nueve meses dentro de un periodo de dieciocho", "Doce meses dentro de un periodo de veinticuatro"]'::jsonb,1,'Art. 10.1 d) TREBEP','El plazo máximo es de nueve meses dentro de un periodo de dieciocho meses.',null),
('aux-ayto-mad:15-ff4f6cbc03','aux-ayto-mad',15,'El nombramiento de interinos para ejecutar programas de carácter temporal no puede superar:','["Dos años, ampliable hasta seis meses más por las leyes de Función Pública que se dicten en desarrollo del Estatuto", "Cuatro años, ampliable hasta doce meses más por las leyes de Función Pública", "Tres años, ampliable hasta doce meses más por las leyes de Función Pública"]'::jsonb,2,'Art. 10.1 c) TREBEP','No puede ser superior a tres años, ampliable hasta doce meses más por las leyes de Función Pública de cada Administración.',null),
('aux-ayto-mad:15-bca3e78100','aux-ayto-mad',15,'El personal eventual realiza funciones:','["De carácter técnico permanente, previstas en la relación de puestos de trabajo de cada Administración", "De confianza, pero que implican el ejercicio de potestades públicas", "Expresamente calificadas como de confianza o asesoramiento especial"]'::jsonb,2,'Art. 12.1 TREBEP','El personal eventual solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial.',null),
('aux-ayto-mad:15-3d268ef525','aux-ayto-mad',15,'Haber sido personal eventual, ¿puede constituir mérito para el acceso a la función pública?','["Solo en la promoción interna", "Sí, si se prestaron servicios más de un año", "No"]'::jsonb,2,'Art. 12.4 TREBEP','La condición de personal eventual no puede constituir mérito para el acceso a la Función Pública o para la promoción interna.',null),
('aux-ayto-mad:15-9283b2f482','aux-ayto-mad',15,'¿Cuál de estos es un derecho individual que se ejerce de forma colectiva?','["La inamovilidad en la condición de funcionario", "El ejercicio de la huelga", "Las vacaciones"]'::jsonb,1,'Art. 15 TREBEP','Son derechos individuales ejercidos colectivamente la libertad sindical, la negociación colectiva y participación, la huelga, el planteamiento de conflictos colectivos y la reunión.',null),
('aux-ayto-mad:15-9bf00b3be2','aux-ayto-mad',15,'¿Cuántos días de permiso por asuntos particulares tienen los funcionarios al año?','["Ocho días", "Cuatro días", "Seis días"]'::jsonb,2,'Art. 48 k) TREBEP','Por asuntos particulares, seis días al año.',null),
('aux-ayto-mad:15-fe71ef6380','aux-ayto-mad',15,'¿Cuántos días de permiso corresponden por matrimonio o registro de pareja de hecho?','["Quince días", "Diez días", "Veinte días"]'::jsonb,0,'Art. 48 l) TREBEP','Quince días por matrimonio o registro o constitución formalizada por documento público de pareja de hecho.',null),
('aux-ayto-mad:15-d95723d22e','aux-ayto-mad',15,'¿Qué duración tiene el permiso por nacimiento para la madre biológica según el TREBEP vigente?','["Diecinueve semanas", "Dieciséis semanas", "Veinticuatro semanas"]'::jsonb,0,'Art. 49 a) TREBEP','Tras la última reforma son diecinueve semanas (treinta y dos en caso de familia monoparental). Muchos tests antiguos siguen diciendo dieciséis.',null),
('aux-ayto-mad:15-eee5d38d49','aux-ayto-mad',15,'¿Cuántos días de vacaciones retribuidas tienen los funcionarios por año completo de servicio?','["Veinticinco días hábiles", "Veintidós días hábiles", "Treinta días naturales"]'::jsonb,1,'Art. 50.1 TREBEP','Veintidós días hábiles, o los que correspondan proporcionalmente si el tiempo de servicio fue menor.',null),
('aux-ayto-mad:15-45aa1a79e8','aux-ayto-mad',15,'¿Qué edad mínima se exige para participar en los procesos selectivos?','["Diecisiete años", "Veintiún años", "Dieciséis años"]'::jsonb,2,'Art. 56.1 c) TREBEP','Tener cumplidos dieciséis años y no exceder, en su caso, la edad máxima de jubilación forzosa.',null),
('aux-ayto-mad:15-086abd1839','aux-ayto-mad',15,'¿Cuáles son los sistemas selectivos de los funcionarios de carrera?','["Oposición, concurso y entrevista personal, que pueden utilizarse indistintamente según lo que decida cada convocatoria", "Oposición y concurso-oposición; el concurso, con carácter ordinario y sin necesidad de previsión en una ley", "Oposición y concurso-oposición; el concurso, solo con carácter excepcional y en virtud de ley"]'::jsonb,2,'Art. 61.6 TREBEP','Son la oposición y el concurso-oposición. El concurso de valoración de méritos solo cabe excepcionalmente y en virtud de ley.',null),
('aux-ayto-mad:15-33379aea05','aux-ayto-mad',15,'¿Cuál de los siguientes NO es un requisito para adquirir la condición de funcionario de carrera?','["Superar el proceso selectivo", "Haber prestado servicios previos como interino", "Tomar posesión dentro del plazo establecido"]'::jsonb,1,'Art. 62.1 TREBEP','Se requiere superar el proceso selectivo, el nombramiento publicado en el diario oficial, el acatamiento de la Constitución (y Estatuto de Autonomía y resto del ordenamiento) y la toma de posesión.',null),
('aux-ayto-mad:15-4b7f46f799','aux-ayto-mad',15,'¿Cuál de las siguientes NO es causa de pérdida de la condición de funcionario de carrera?','["La pérdida de la nacionalidad", "La excedencia voluntaria", "La renuncia"]'::jsonb,1,'Art. 63 TREBEP','Son causas la renuncia, la pérdida de la nacionalidad, la jubilación total, la pena de inhabilitación firme y la sanción firme de separación del servicio. La excedencia es una situación administrativa.',null),
('aux-ayto-mad:15-361abf06f0','aux-ayto-mad',15,'La jubilación forzosa de los funcionarios se declara al cumplir:','["60 años, pudiendo solicitar la prolongación hasta los 65", "65 años, pudiendo solicitar la prolongación hasta los 70", "67 años, sin posibilidad de solicitar la prolongación de la permanencia en el servicio activo"]'::jsonb,1,'Art. 67.3 TREBEP','Se declara a los sesenta y cinco años, aunque el funcionario puede solicitar la prolongación de la permanencia hasta los setenta.',null),
('aux-ayto-mad:15-d54b55cbe0','aux-ayto-mad',15,'¿Qué titulación se exige para acceder a un cuerpo del subgrupo C2?','["Certificado de escolaridad o de estudios primarios", "Técnico Superior o equivalente a efectos profesionales", "Graduado en Educación Secundaria Obligatoria"]'::jsonb,2,'Art. 76 TREBEP','Para el subgrupo C2 se exige el título de Graduado en ESO; para el C1, Bachiller o Técnico.',null),
('aux-ayto-mad:15-fd438c7195','aux-ayto-mad',15,'¿Cuál de estas NO es una situación administrativa de los funcionarios de carrera?','["Comisión de servicios", "Suspensión de funciones", "Excedencia"]'::jsonb,0,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones. La comisión de servicios es una forma de provisión de puestos.',null),
('aux-ayto-mad:15-0ab8580cd0','aux-ayto-mad',15,'Para obtener la excedencia voluntaria por interés particular hay que haber prestado servicios efectivos durante un mínimo de:','["Tres años, consecutivos o no, en cualquier Administración", "Un año inmediatamente anterior a la solicitud", "Cinco años inmediatamente anteriores"]'::jsonb,2,'Art. 89.2 TREBEP','Se exige haber prestado servicios efectivos en cualquier Administración durante un mínimo de cinco años inmediatamente anteriores.',null),
('aux-ayto-mad:15-c663c11dbf','aux-ayto-mad',15,'La excedencia por cuidado de cada hijo tiene una duración:','["No superior a cinco años", "No superior a tres años", "Sin límite"]'::jsonb,1,'Art. 89.4 TREBEP','El periodo de excedencia por cuidado de cada hijo no puede ser superior a tres años.',null),
('aux-ayto-mad:15-48379ad687','aux-ayto-mad',15,'La suspensión firme de funciones por sanción disciplinaria no puede exceder de:','["Seis años", "Tres años", "Dos años"]'::jsonb,0,'Art. 90.2 TREBEP','No puede exceder de seis años. Si supera seis meses, el funcionario pierde su puesto de trabajo (art. 90.1).',null),
('aux-ayto-mad:15-4205450b94','aux-ayto-mad',15,'Según el TREBEP, las faltas disciplinarias se clasifican en:','["Muy graves, graves y leves", "Muy graves y graves", "Graves y leves"]'::jsonb,0,'Art. 95.1 TREBEP','Las faltas disciplinarias pueden ser muy graves, graves y leves.',null),
('aux-ayto-mad:15-55519f2cb6','aux-ayto-mad',15,'¿Cuál de las siguientes sanciones NO aparece expresamente en la lista del art. 96.1 del TREBEP?','["Demérito", "Traslado forzoso", "Multa económica"]'::jsonb,2,'Art. 96.1 TREBEP','Recoge la separación del servicio, el despido disciplinario, la suspensión firme de funciones, el traslado forzoso, el demérito, el apercibimiento y cualquier otra que establezca una ley.',null),
('aux-ayto-mad:15-9344575c90','aux-ayto-mad',15,'¿Cuándo prescriben las faltas leves?','["A los dos años", "A los seis meses", "A los tres meses"]'::jsonb,1,'Art. 97 TREBEP','Las faltas muy graves prescriben a los tres años, las graves a los dos años y las leves a los seis meses.',null),
('aux-ayto-mad:15-07871ffd80','aux-ayto-mad',15,'¿Cuándo prescriben las sanciones impuestas por faltas leves?','["Al año", "A los seis meses", "A los dos años"]'::jsonb,0,'Art. 97 TREBEP','Las sanciones por faltas muy graves prescriben a los tres años, las graves a los dos años y las leves al año.',null),
('aux-ayto-mad:15-e46bff7036','aux-ayto-mad',15,'La suspensión provisional como medida cautelar en un expediente disciplinario no puede exceder de:','["Seis meses, salvo paralización del procedimiento imputable al interesado", "Un año, salvo paralización del procedimiento imputable a la Administración que lo tramita", "Tres meses, salvo paralización del procedimiento imputable al interesado"]'::jsonb,0,'Art. 98.3 TREBEP','No puede exceder de seis meses, salvo en caso de paralización del procedimiento imputable al interesado.',null),
('aux-ayto-mad:15-fc7b5e67f1','aux-ayto-mad',15,'Las retribuciones básicas están integradas por:','["El sueldo asignado a cada subgrupo, los trienios y el complemento de destino del puesto que se ocupe", "El sueldo asignado a cada subgrupo o grupo y los trienios", "La productividad y las gratificaciones por servicios extraordinarios"]'::jsonb,1,'Art. 23 TREBEP','Los trienios consisten en una cantidad por cada tres años de servicio.',null),
('aux-ayto-mad:15-02a3c3b85c','aux-ayto-mad',15,'Los Delegados de Personal representan a los funcionarios en unidades electorales que cuenten con:','["Más de 50 funcionarios", "Entre 6 y 49 funcionarios", "Menos de 6 funcionarios"]'::jsonb,1,'Art. 39.2 TREBEP','A partir de 50 funcionarios hay Juntas de Personal.',null),
('aux-ayto-mad:15-960a806a8e','aux-ayto-mad',15,'El plazo de prescripción de las sanciones comenzará a contarse:','["Desde la comisión de la falta", "Desde la incoación del expediente", "Desde la firmeza de la resolución sancionadora"]'::jsonb,2,'Art. 97 TREBEP','El de las faltas, desde que se hubieran cometido, o desde el cese de su comisión si son continuadas.',null),
('aux-ayto-mad:15-88f93074d6','aux-ayto-mad',15,'El personal eventual:','["Solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, y su nombramiento y cese son libres", "Accede mediante concurso de méritos", "Tiene derecho a la inamovilidad tras dos años de servicio, y su nombramiento corresponde al órgano de selección tras un concurso de méritos con convocatoria pública"]'::jsonb,0,'Art. 12.1 y 12.3 TREBEP','El cese tiene lugar, en todo caso, cuando se produzca el de la autoridad a la que preste su función de confianza.',null),
('aux-ayto-mad:15-b0302ec5b6','aux-ayto-mad',15,'Según el art. 54.11, los empleados públicos garantizarán la atención al ciudadano en:','["La lengua que lo solicite siempre que sea oficial en el territorio", "La lengua oficial que solicite y, si lo pide, también en inglés", "Castellano exclusivamente"]'::jsonb,0,'Art. 54.11 TREBEP','Es otro principio de conducta.',null),
('aux-ayto-mad:15-91a4aafabb','aux-ayto-mad',15,'En las ofertas de empleo público se reservará un cupo para personas con discapacidad no inferior al:','["10 % de las vacantes", "7 % de las vacantes", "2 % de las vacantes"]'::jsonb,1,'Art. 59.1 TREBEP','De ese cupo, al menos el 2 % de las plazas para personas con discapacidad intelectual.',null),
('aux-ayto-mad:15-f1ab8c08f7','aux-ayto-mad',15,'Por traslado de domicilio sin cambio de residencia, el funcionario tiene un permiso de:','["Un día", "Dos días", "Tres días"]'::jsonb,0,'Art. 48 b) TREBEP','Permiso de un día por traslado de domicilio.',null),
('aux-ayto-mad:15-097b0f2070','aux-ayto-mad',15,'La funcionaria víctima de violencia de género que reduzca su jornada en un tercio o menos:','["Pierde las retribuciones básicas", "Mantendrá sus retribuciones íntegras", "Solo cobra el 50 %"]'::jsonb,1,'Art. 49 d) TREBEP','Si la reducción es mayor, la disminución de retribuciones es proporcional.',null),
('aux-ayto-mad:15-8be7ba2752','aux-ayto-mad',15,'Las faltas leves se sancionarán:','["Por el procedimiento previsto para las faltas graves y muy graves", "Solo por un juez", "Por un procedimiento sumario con audiencia al interesado"]'::jsonb,2,'Art. 98.1 TREBEP','Las faltas muy graves y graves exigen el procedimiento previamente establecido.',null),
('aux-ayto-mad:15-c9dab1c2ad','aux-ayto-mad',15,'El permiso parental para el cuidado de hijo o menor acogido por tiempo superior a un año, hasta que cumpla ocho años, tiene una duración máxima de:','["Cuatro semanas retribuidas", "Un año", "Ocho semanas, y no es retribuido"]'::jsonb,2,'Art. 49 g) TREBEP','Se requiere un preaviso de quince días.',null),
('aux-ayto-mad:15-af3f06cc16','aux-ayto-mad',15,'El teletrabajo de los empleados públicos:','["Tendrá carácter voluntario y reversible, salvo en supuestos excepcionales debidamente justificados", "Es irreversible una vez concedido y solo puede revocarse como sanción disciplinaria tras el expediente correspondiente", "Es obligatorio para los puestos cuyas funciones permitan prestarse a distancia, salvo renuncia justificada del empleado"]'::jsonb,0,'Art. 47 bis.2 TREBEP','Se realizará en los términos de las normas que se dicten en desarrollo del Estatuto.',null),
('aux-ayto-mad:15-cd7b922db1','aux-ayto-mad',15,'Por accidente o enfermedad grave de un familiar de primer grado de consanguinidad o afinidad, el funcionario tiene un permiso de:','["Tres días naturales", "Cinco días hábiles", "Dos días hábiles"]'::jsonb,1,'Art. 48 a) TREBEP','Para familiares de segundo grado, cuatro días hábiles.',null),
('aux-ayto-mad:15-b536ef17e0','aux-ayto-mad',15,'La oferta de empleo público deberá desarrollarse dentro del plazo improrrogable de:','["Tres años", "Dos años", "Cinco años"]'::jsonb,0,'Art. 70.1 TREBEP','La oferta puede contener hasta un 10 % adicional de plazas.',null),
('aux-ayto-mad:15-d39a3eeed7','aux-ayto-mad',15,'Los funcionarios pueden solicitar la prolongación de la permanencia en el servicio activo, una vez cumplida la edad de jubilación forzosa, como máximo hasta:','["Los sesenta y siete años", "Los sesenta y ocho años", "Los setenta años"]'::jsonb,2,'Art. 67.3 TREBEP','La jubilación forzosa se declara al cumplir 65 años.',null),
('aux-ayto-mad:15-952be9d078','aux-ayto-mad',15,'Quedan excluidas de la obligatoriedad de la negociación:','["La evaluación del desempeño", "Las decisiones que afecten a las potestades de organización de las Administraciones Públicas", "Los criterios generales de acceso, carrera, provisión, sistemas de clasificación de puestos y planes de recursos humanos"]'::jsonb,1,'Art. 37.2 a) TREBEP','Las demás opciones son materias objeto de negociación (art. 37.1).',null),
('aux-ayto-mad:15-cee46235a9','aux-ayto-mad',15,'Los procedimientos de provisión de puestos de trabajo de los funcionarios de carrera son, con carácter general:','["El concurso y la libre designación con convocatoria pública", "La oposición y el concurso-oposición", "El concurso y la libre designación sin convocatoria pública"]'::jsonb,0,'Art. 78.2 TREBEP','El concurso es el procedimiento normal de provisión.',null),
('aux-ayto-mad:15-085c0000b1','aux-ayto-mad',15,'La suspensión de funciones determinará la pérdida del puesto de trabajo cuando exceda de:','["Seis meses", "Un año", "Un mes"]'::jsonb,0,'Art. 90.1 TREBEP','El funcionario suspenso queda privado del ejercicio de sus funciones.',null),
('aux-ayto-mad:15-ba9e5e3ac5','aux-ayto-mad',15,'La libre designación con convocatoria pública consiste en:','["La apreciación discrecional por el órgano competente de la idoneidad de los candidatos en relación con los requisitos del puesto", "Una prueba de conocimientos eliminatoria sobre las funciones del puesto, seguida de la valoración de méritos por una comisión técnica independiente", "La antigüedad del candidato"]'::jsonb,0,'Art. 80.1 TREBEP','Se aplica a los puestos que determinen las leyes por su especial responsabilidad.',null),
('aux-ayto-mad:15-e6e3bdea13','aux-ayto-mad',15,'Según el art. 54.6 TREBEP, los empleados públicos:','["Pueden aceptar regalos de cualquier valor siempre que los declaren a su superior jerárquico en el plazo de diez días desde su recepción y los inscriban en el registro", "Rechazarán cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales, sociales y de cortesía", "Solo pueden aceptar regalos de otros empleados públicos o de los ciudadanos, siempre que no superen el valor que fije cada Administración en su código ético"]'::jsonb,1,'Art. 54.6 TREBEP','Es un principio de conducta.',null),
('aux-ayto-mad:15-1e347a5376','aux-ayto-mad',15,'Durante la suspensión provisional como medida cautelar, el funcionario:','["Percibirá las retribuciones complementarias, pero no las básicas", "No percibe ninguna retribución", "Percibirá las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo"]'::jsonb,2,'Art. 98.3 TREBEP','Si la suspensión se eleva a definitiva, deberá devolver lo percibido.',null),
('aux-ayto-mad:15-54f98acec8','aux-ayto-mad',15,'NO pueden formar parte de los órganos de selección:','["El personal de elección o designación política, los funcionarios interinos y el personal eventual", "Los funcionarios del mismo cuerpo o escala al que se aspira a ingresar y el personal laboral fijo de la misma Administración", "El personal laboral fijo y los funcionarios de carrera que hayan preparado a aspirantes en los cinco años anteriores"]'::jsonb,0,'Art. 60.2 TREBEP','Los órganos de selección son colegiados y tienden a la paridad.',null),
('aux-ayto-mad:15-f3659885a0','aux-ayto-mad',15,'Los nacionales de los Estados miembros de la Unión Europea pueden acceder como funcionarios en igualdad de condiciones que los españoles, salvo a los empleos que impliquen:','["Funciones administrativas, de gestión o de auxilio, aunque no impliquen ejercicio de potestades públicas", "Participación en el ejercicio del poder público o en las funciones de salvaguardia de los intereses del Estado", "Trabajos en entidades locales"]'::jsonb,1,'Art. 57.1 TREBEP','Los extranjeros con residencia legal pueden acceder como personal laboral (art. 57.4).',null),
('aux-ayto-mad:15-99433524b5','aux-ayto-mad',15,'Las pagas extraordinarias de los funcionarios serán:','["Dos al año, cada una por el importe de una mensualidad de retribuciones básicas y de la totalidad de las complementarias, salvo excepciones", "Tres al año, cada una por el importe de una mensualidad de retribuciones básicas y de la mitad de las complementarias, que se abonan en marzo, junio y diciembre", "Cuatro al año"]'::jsonb,0,'Art. 22.4 TREBEP','Son dos pagas al año.',null),
('aux-ayto-mad:15-42dc192330','aux-ayto-mad',15,'La renuncia voluntaria a la condición de funcionario:','["No está permitida mientras el funcionario no haya cumplido la edad de jubilación, salvo que lo autorice expresamente el Consejo de Gobierno por razones excepcionales de interés público", "No necesita aceptación expresa y surte efectos desde su presentación, aunque el funcionario esté sujeto a expediente disciplinario o haya sido procesado por un delito", "Habrá de ser manifestada por escrito y será aceptada expresamente por la Administración, salvo que el funcionario esté sujeto a expediente disciplinario o procesado"]'::jsonb,2,'Art. 64 TREBEP','La renuncia no inhabilita para volver a ingresar por el procedimiento de selección.',null),
('aux-ayto-mad:15-a9cbc043d4','aux-ayto-mad',15,'Transcurridos tres años desde el nombramiento de un interino en plaza vacante, esta:','["Solo podrá ser ocupada por personal funcionario de carrera, salvo que el proceso selectivo quede desierto", "Se convierte automáticamente en plaza en propiedad del interino que la ocupa, sin necesidad de proceso selectivo", "Se amortiza automáticamente y el interino cesa sin derecho a indemnización, aunque el proceso selectivo no se haya convocado"]'::jsonb,0,'Art. 10.4 TREBEP','Se produce el fin de la relación de interinidad.',null),
('aux-ayto-mad:15-04aff95351','aux-ayto-mad',15,'Es un derecho individual de los empleados públicos del art. 14 TREBEP:','["La negociación colectiva y la participación en la determinación de las condiciones de trabajo", "La formación continua y la actualización permanente de sus conocimientos", "La huelga y el planteamiento de conflictos colectivos de trabajo en su unidad"]'::jsonb,1,'Art. 14 g) TREBEP','Los demás citados son derechos individuales ejercidos colectivamente (art. 15).',null),
('aux-ayto-mad:15-7996759a41','aux-ayto-mad',15,'Durante los dos primeros años de excedencia por cuidado de hijos o familiares, el funcionario tiene derecho a:','["Seguir percibiendo las retribuciones básicas y la reserva de un puesto en la misma localidad", "La reserva del puesto de trabajo que desempeñaba", "Ascender automáticamente de grado"]'::jsonb,1,'Art. 89.4 TREBEP','Transcurrido ese periodo, la reserva lo es a un puesto en la misma localidad y de igual retribución.',null),
('aux-ayto-mad:15-0cab6766a5','aux-ayto-mad',15,'Las sanciones impuestas por faltas graves prescriben a los:','["Dos años", "Seis meses", "Tres años"]'::jsonb,0,'Art. 97 TREBEP','Las muy graves a los tres años y las leves al año.',null),
('aux-ayto-mad:15-1348f33a4b','aux-ayto-mad',15,'Las faltas muy graves prescriben a los:','["Tres años", "Cinco años", "Seis meses"]'::jsonb,0,'Art. 97 TREBEP','Las graves a los dos años y las leves a los seis meses.',null),
('aux-ayto-mad:15-31415142da','aux-ayto-mad',15,'A efectos de vacaciones de los funcionarios, los sábados:','["Se consideran siempre días hábiles, cualquiera que sea el horario del funcionario", "Se consideran hábiles solo en agosto", "No se consideran días hábiles, salvo en los horarios especiales"]'::jsonb,2,'Art. 50.1 TREBEP','Las vacaciones son de 22 días hábiles.',null),
('aux-ayto-mad:15-0dadd37586','aux-ayto-mad',15,'La parte de jornada no realizada sin justificación dará lugar a:','["La deducción proporcional de haberes, que no tendrá carácter sancionador", "Una sanción disciplinaria grave, previa tramitación del expediente correspondiente", "Ninguna consecuencia económica, aunque deberá recuperarse en otro momento de la semana"]'::jsonb,0,'Art. 30.1 TREBEP','La deducción no es una sanción.',null),
('aux-ayto-mad:15-f3449817c7','aux-ayto-mad',15,'Para participar en la promoción interna, los funcionarios deben poseer una antigüedad de, al menos:','["Cinco años de servicio activo en cualquier cuerpo o escala de la misma Administración pública", "Dos años de servicio activo en el inferior subgrupo o grupo de clasificación profesional", "Tres años de servicio activo en el mismo cuerpo o escala, de los cuales al menos uno en la misma Administración"]'::jsonb,1,'Art. 18.2 TREBEP','Además de la titulación y demás requisitos exigidos.',null),
('aux-ayto-mad:15-0cfea8600c','aux-ayto-mad',15,'Durante los dos primeros meses de excedencia por razón de violencia de género, la funcionaria tendrá derecho a:','["Percibir las retribuciones íntegras y, en su caso, las prestaciones familiares por hijo a cargo", "Percibir solo las retribuciones básicas, pero no las complementarias ni las prestaciones familiares por hijo a cargo", "No percibir retribución alguna, aunque se le reserva el puesto de trabajo y se computa el tiempo a efectos de antigüedad"]'::jsonb,0,'Art. 89.5 TREBEP','Durante los seis primeros meses tiene reserva del puesto, prorrogable por periodos de tres meses hasta dieciocho.',null),
('aux-ayto-mad:15-392a2bf190','aux-ayto-mad',15,'La designación del personal directivo profesional atenderá a principios de:','["Antigüedad en el cuerpo, y en caso de empate, mérito y capacidad mediante procedimientos que garanticen la publicidad y la concurrencia", "Mérito y capacidad y criterios de idoneidad, mediante procedimientos que garanticen la publicidad y concurrencia", "Sorteo entre funcionarios del subgrupo A1"]'::jsonb,1,'Art. 13.2 TREBEP','Así lo establece el art. 13.2.',null),
('aux-ayto-mad:15-a9747b89ac','aux-ayto-mad',15,'Los trienios consisten en una cantidad, igual para cada subgrupo o grupo, por cada:','["Cinco años de servicio", "Tres años de servicio", "Dos años de servicio"]'::jsonb,1,'Art. 23 b) TREBEP','Retribución básica por antigüedad.',null),
('aux-ayto-mad:15-992424ed02','aux-ayto-mad',15,'Las retribuciones de los funcionarios de carrera se clasifican en:','["Directas e indirectas", "Ordinarias y extraordinarias", "Básicas y complementarias"]'::jsonb,2,'Art. 22.1 TREBEP','Las pagas extraordinarias son dos al año.',null),
('aux-ayto-mad:15-a43fd1080a','aux-ayto-mad',15,'Los Pactos y Acuerdos, salvo que se establezca otra cosa:','["Caducan al año de su firma, salvo que se renueven expresamente", "Se prorrogarán de año en año si no media denuncia expresa de una de las partes", "Se prorrogarán por periodos de cuatro años, salvo que una de las partes los denuncie con seis meses de antelación"]'::jsonb,1,'Art. 38.11 TREBEP','Prórroga anual salvo denuncia.',null),
('aux-ayto-mad:15-942928c5c0','aux-ayto-mad',15,'Por fallecimiento de un familiar de primer grado en la misma localidad, el permiso es de:','["Cinco días hábiles", "Dos días hábiles", "Tres días hábiles"]'::jsonb,2,'Art. 48 a) TREBEP','Si es en distinta localidad, cinco días hábiles.',null),
('aux-ayto-mad:15-a0b0afd2e9','aux-ayto-mad',15,'Las Mesas de Negociación quedarán válidamente constituidas cuando las organizaciones sindicales presentes representen, como mínimo:','["Un tercio de los miembros de los órganos unitarios de representación en el ámbito de que se trate", "La mayoría absoluta de los miembros de los órganos unitarios de representación en el ámbito de que se trate", "El 10 % de los miembros de los órganos unitarios de representación"]'::jsonb,1,'Art. 35.1 TREBEP','Ninguna de las partes puede superar quince miembros (art. 35.4).',null),
('aux-ayto-mad:15-6556a3c45e','aux-ayto-mad',15,'Los órganos de selección no podrán proponer el acceso a la condición de funcionario de un número superior de aprobados al de plazas convocadas:','["En ningún caso, y cualquier propuesta que lo contravenga será nula de pleno derecho", "Salvo que la convocatoria prevea otra cosa", "Salvo en la Administración Local, cuando lo acuerde el Pleno"]'::jsonb,1,'Art. 61.8 TREBEP','Regla general con la excepción prevista.',null),
('aux-ayto-mad:15-fc353aa00a','aux-ayto-mad',15,'La excedencia por cuidado de un familiar hasta el segundo grado que no pueda valerse por sí mismo tiene una duración no superior a:','["Tres años", "Un año", "Cinco años"]'::jsonb,0,'Art. 89.4 TREBEP','Igual que la excedencia por cuidado de cada hijo.',null),
('aux-ayto-mad:15-707254eec0','aux-ayto-mad',15,'Si la incapacidad temporal impide disfrutar las vacaciones en el año natural, podrán disfrutarse una vez finalizada, siempre que no hayan transcurrido más de:','["Tres años", "Dieciocho meses a partir del final del año en que se hayan originado", "Seis meses a partir del final del año en que se hayan originado"]'::jsonb,1,'Art. 50.2 TREBEP','Las vacaciones no pueden sustituirse por una cuantía económica, salvo cese no voluntario.',null),
('aux-ayto-mad:15-021e42ac8d','aux-ayto-mad',15,'En el permiso por nacimiento, ¿cuántas semanas inmediatas posteriores al parto son de descanso obligatorio?','["Seis semanas", "Dos semanas", "Cuatro semanas"]'::jsonb,0,'Art. 49 a) TREBEP','Las seis semanas posteriores al parto son obligatorias e ininterrumpidas.',null),
('aux-ayto-mad:15-e18c16db79','aux-ayto-mad',15,'Es una falta muy grave según el art. 95.2 TREBEP:','["El descuido leve en el trabajo", "La falta de puntualidad ocasional", "El abandono del servicio"]'::jsonb,2,'Art. 95.2 c) TREBEP','Otras faltas muy graves: desobediencia abierta, acoso laboral, etc.',null),
('aux-ayto-mad:15-5fc8072e19','aux-ayto-mad',15,'La sanción de separación del servicio de los funcionarios solo podrá imponerse por:','["Faltas graves cometidas de forma reiterada", "Faltas graves reiteradas en el plazo de un año", "La comisión de faltas muy graves"]'::jsonb,2,'Art. 96.1 a) TREBEP','En los interinos implica la revocación del nombramiento.',null),
('aux-ayto-mad:15-393a240cdc','aux-ayto-mad',15,'La duración del mandato de los Delegados de Personal y de las Juntas de Personal es de:','["Tres años", "Cinco años", "Cuatro años"]'::jsonb,2,'Art. 42 TREBEP','Pueden ser reelegidos en sucesivos procesos electorales.',null),
('aux-ayto-mad:15-4b3706ea2b','aux-ayto-mad',15,'Según el TREBEP, ¿cuál es el procedimiento normal de provisión de puestos de trabajo de los funcionarios de carrera?','["La adscripción provisional", "La comisión de servicios", "El concurso"]'::jsonb,2,'Art. 78 TREBEP','La libre designación con convocatoria pública es el otro procedimiento ordinario, reservado a puestos determinados por su especial responsabilidad o confianza.',null),
('aux-ayto-mad:15-1131bfa3d0','aux-ayto-mad',15,'¿Cuál de las siguientes NO es una situación administrativa de los funcionarios de carrera según el artículo 85 del TREBEP?','["Servicios especiales", "Servicio en otras Administraciones Públicas", "Expectativa de destino indefinida"]'::jsonb,2,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones.',null),
('aux-ayto-mad:15-13313cd6fa','aux-ayto-mad',15,'Los funcionarios que acceden a la condición de diputado o senador de las Cortes Generales pasan a la situación de:','["Servicios especiales", "Servicio activo con dispensa de funciones", "Excedencia voluntaria por interés particular"]'::jsonb,0,'Art. 87.1 TREBEP','Tienen derecho a reingresar al servicio activo en la misma localidad y en las mismas condiciones y con las retribuciones correspondientes a su categoría.',null),
('aux-ayto-mad:15-eee82e17d4','aux-ayto-mad',15,'Según el TREBEP, los funcionarios en situación de servicios especiales:','["Pierden la condición de funcionario mientras dure la situación", "Solo tienen derecho al cómputo de trienios, pero no a la reserva de puesto", "Tienen derecho a que se les compute el tiempo en esa situación a efectos de ascensos, reconocimiento de trienios y derechos en el régimen de Seguridad Social"]'::jsonb,2,'Art. 87.2 TREBEP','No se les aplica, sin embargo, el régimen de derechos pasivos si les corresponde otro.',null),
('aux-ayto-mad:15-b04388f6bc','aux-ayto-mad',15,'Según el TREBEP, en las ofertas de empleo público se reserva para personas con discapacidad intelectual, dentro del cupo general, al menos:','["El 1 % de las plazas ofertadas", "El 5 % de las plazas ofertadas", "El 2 % de las plazas ofertadas"]'::jsonb,2,'Art. 59.1 TREBEP','El cupo total para personas con discapacidad no es inferior al 7 %, y de él al menos el 2 % es para personas con discapacidad intelectual.',null),
('aux-ayto-mad:16-0bfeec995d','aux-ayto-mad',16,'La Ley Orgánica 3/2007 tiene por objeto:','["Establecer medidas de protección integral contra la violencia de género y de igualdad de oportunidades en el empleo", "Hacer efectivo el derecho de igualdad de trato entre mujeres y hombres, pero solo en el ámbito del empleo público y de la negociación colectiva", "Hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres"]'::jsonb,2,'Art. 1.1 LO 3/2007','Su objeto es hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres.',null),
('aux-ayto-mad:16-08a6459c59','aux-ayto-mad',16,'El principio de igualdad de trato entre mujeres y hombres supone:','["La paridad obligatoria en todos los órganos públicos y privados, con independencia de su composición", "La ausencia de discriminación directa por razón de sexo, pero no de la indirecta, que se rige por la normativa laboral", "La ausencia de toda discriminación, directa o indirecta, por razón de sexo"]'::jsonb,2,'Art. 3 LO 3/2007','Supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, especialmente por maternidad, obligaciones familiares y estado civil.',null),
('aux-ayto-mad:16-b55a16a603','aux-ayto-mad',16,'Se considera discriminación directa por razón de sexo la situación en que una persona:','["Sufre una desventaja particular respecto de personas del otro sexo por una disposición, criterio o práctica aparentemente neutros", "Es tratada igual que otra persona en una situación distinta", "Es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable"]'::jsonb,2,'Art. 6.1 LO 3/2007','Es la situación de quien es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable. El trato por disposición aparentemente neutra es la discriminación indirecta.',null),
('aux-ayto-mad:16-66da1b1986','aux-ayto-mad',16,'El acoso sexual es cualquier comportamiento, verbal o físico, de naturaleza sexual que:','["Se repita al menos tres veces y lo denuncie la persona afectada o un tercero", "Tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona", "Produzca una lesión física acreditada"]'::jsonb,1,'Art. 7.1 LO 3/2007','Tiene el propósito o produce el efecto de atentar contra la dignidad de una persona, en particular cuando crea un entorno intimidatorio, degradante u ofensivo.',null),
('aux-ayto-mad:16-211f85a22f','aux-ayto-mad',16,'Todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad constituye:','["Discriminación directa por razón de sexo", "Discriminación indirecta por razón de sexo, salvo que la empresa acredite una justificación objetiva", "Acoso por razón de sexo"]'::jsonb,0,'Art. 8 LO 3/2007','Constituye discriminación directa por razón de sexo.',null),
('aux-ayto-mad:16-4dda33c712','aux-ayto-mad',16,'Según la LO 3/2007, el principio de igualdad de trato y oportunidades informará la actuación de todos los Poderes Públicos con carácter:','["Voluntario", "Transversal", "Subsidiario"]'::jsonb,1,'Art. 15 LO 3/2007','Informará, con carácter transversal, la actuación de todos los Poderes Públicos.',null),
('aux-ayto-mad:16-803a389f2a','aux-ayto-mad',16,'¿Qué empresas deben elaborar y aplicar un plan de igualdad?','["Solo las empresas públicas y las que contraten con la Administración, cualquiera que sea su plantilla", "Todas, cualquiera que sea su plantilla", "Las de cincuenta o más trabajadores"]'::jsonb,2,'Art. 45.2 LO 3/2007','Las empresas de cincuenta o más trabajadores.',null),
('aux-ayto-mad:16-125157f3d2','aux-ayto-mad',16,'Según la LO 3/2007, hay composición equilibrada cuando las personas de cada sexo:','["No superan el 60 % ni son menos del 40 %", "No superan el 55 % ni son menos del 45 %", "No superan el 70 % ni son menos del 30 %"]'::jsonb,0,'Disp. adicional 1.ª LO 3/2007','Las personas de cada sexo no superan el sesenta por ciento ni son menos del cuarenta por ciento.',null),
('aux-ayto-mad:16-7baf769388','aux-ayto-mad',16,'El Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado se aprueba por el Gobierno:','["Cada año", "Solo cuando lo pide el Congreso", "Al inicio de cada legislatura"]'::jsonb,2,'Art. 64 LO 3/2007','Su cumplimiento se evalúa anualmente por el Consejo de Ministros.',null),
('aux-ayto-mad:16-75c8b68769','aux-ayto-mad',16,'En los litigios sobre acoso sexual y acoso por razón de sexo, está legitimada:','["El sindicato mayoritario en todo caso", "Únicamente la persona acosada", "El Ministerio Fiscal en exclusiva"]'::jsonb,1,'Art. 12.3 LO 3/2007','La persona acosada es la única legitimada.',null),
('aux-ayto-mad:16-3e62739a8e','aux-ayto-mad',16,'Según el art. 6.3 de la LO 3/2007, toda orden de discriminar, directa o indirectamente, por razón de sexo:','["Se considerará en todo caso discriminatoria", "Es válida si procede de un superior", "No tiene relevancia jurídica si no llega a ejecutarse"]'::jsonb,0,'Art. 6.3 LO 3/2007','La orden de discriminar es en sí misma discriminación.',null),
('aux-ayto-mad:16-c8b9c9420b','aux-ayto-mad',16,'Las acciones positivas para hacer efectivo el derecho a la igualdad pueden adoptarlas:','["Solo las empresas de más de 250 trabajadores, dentro de su plan de igualdad negociado con la representación legal de los trabajadores", "Solo el Gobierno y las Administraciones públicas", "Los poderes públicos y también las personas físicas y jurídicas privadas"]'::jsonb,2,'Art. 11 LO 3/2007','Deben ser razonables y proporcionadas.',null),
('aux-ayto-mad:16-1f27994825','aux-ayto-mad',16,'Los proyectos de disposiciones de carácter general y los planes de especial relevancia que se sometan a la aprobación del Consejo de Ministros deberán incorporar:','["Un informe económico de la UE", "Un informe sobre su impacto por razón de género", "La firma de todas las Comunidades Autónomas"]'::jsonb,1,'Art. 19 LO 3/2007','Es el informe de impacto de género.',null),
('aux-ayto-mad:16-1d706db2b5','aux-ayto-mad',16,'Según la LO 3/2007, se considera discriminación por razón de sexo cualquier trato adverso o efecto negativo producido como consecuencia de:','["Su cambio de domicilio", "Su ascenso profesional o la obtención de un puesto de libre designación tras un procedimiento de provisión con convocatoria pública", "La presentación por una persona de una queja, reclamación, denuncia o demanda destinada a impedir su discriminación"]'::jsonb,2,'Art. 9 LO 3/2007','Es la garantía de indemnidad frente a represalias.',null),
('aux-ayto-mad:16-97b590ca70','aux-ayto-mad',16,'Entre los criterios de actuación de las Administraciones en el empleo público, la LO 3/2007 incluye:','["Reservar los puestos directivos a la persona más antigua", "Establecer cuotas obligatorias del 60 % de mujeres en todos los órganos de selección y valoración", "Promover la presencia equilibrada de mujeres y hombres en los órganos de selección y valoración"]'::jsonb,2,'Art. 51 d) LO 3/2007','También establecer medidas efectivas para eliminar cualquier discriminación retributiva.',null),
('aux-ayto-mad:16-db38db45ff','aux-ayto-mad',16,'En los procedimientos (no penales) en que se aleguen actuaciones discriminatorias por razón de sexo, corresponde probar la ausencia de discriminación a:','["La persona demandante", "El juez", "La persona demandada"]'::jsonb,2,'Art. 13.1 LO 3/2007','Es la inversión de la carga de la prueba; no se aplica a los procesos penales.',null),
('aux-ayto-mad:17-3f355155c4','aux-ayto-mad',17,'Según la Ley 31/1995, su objeto es:','["Establecer las sanciones por accidentes laborales", "Promover la seguridad y la salud de los trabajadores mediante la aplicación de medidas y actividades para prevenir los riesgos derivados del trabajo", "Regular las prestaciones de la Seguridad Social por accidente de trabajo y enfermedad profesional"]'::jsonb,1,'Art. 2.1 Ley 31/1995','El art. 2.1 fija como objeto promover la seguridad y la salud de los trabajadores mediante la aplicación de medidas y el desarrollo de las actividades necesarias para la prevención de riesgos derivados del trabajo.',null),
('aux-ayto-mad:17-77a735b99e','aux-ayto-mad',17,'Las disposiciones de carácter laboral de la Ley 31/1995 y de sus normas reglamentarias tienen el carácter de:','["Normas orientativas sin fuerza obligatoria", "Derecho necesario mínimo indisponible, mejorable en los convenios colectivos", "Derecho dispositivo, que puede excluirse por convenio colectivo"]'::jsonb,1,'Art. 2.2 Ley 31/1995','Según el art. 2.2, tienen en todo caso el carácter de Derecho necesario mínimo indisponible, y pueden ser mejoradas y desarrolladas en los convenios colectivos.',null),
('aux-ayto-mad:17-7d8636ae0e','aux-ayto-mad',17,'Según la Ley 31/1995, se entiende por «prevención»:','["El conjunto de actividades o medidas adoptadas o previstas en todas las fases de actividad de la empresa para evitar o disminuir los riesgos derivados del trabajo", "La posibilidad de que un trabajador sufra un determinado daño derivado del trabajo", "Cualquier equipo destinado a ser llevado o sujetado por el trabajador para que le proteja de uno o varios riesgos"]'::jsonb,0,'Art. 4.1.º Ley 31/1995','Así lo define el art. 4.1.º. La posibilidad de sufrir un daño es el «riesgo laboral» (art. 4.2.º) y el equipo que protege al trabajador es el «equipo de protección individual» (art. 4.8.º).',null),
('aux-ayto-mad:17-eed923c132','aux-ayto-mad',17,'Según la Ley 31/1995, para calificar un riesgo laboral desde el punto de vista de su gravedad se valorarán conjuntamente:','["El coste de las medidas preventivas y el tamaño de la empresa", "La probabilidad de que se produzca el daño y su severidad", "La duración de la exposición y el número de trabajadores afectados"]'::jsonb,1,'Art. 4.2.º Ley 31/1995','Según el art. 4.2.º, se valoran conjuntamente la probabilidad de que se produzca el daño y la severidad del mismo.',null),
('aux-ayto-mad:17-22820eb618','aux-ayto-mad',17,'Según la Ley 31/1995, son «daños derivados del trabajo»:','["Solo los accidentes de trabajo que causen baja médica", "Las pérdidas económicas de la empresa por accidentes y por bajas laborales", "Las enfermedades, patologías o lesiones sufridas con motivo u ocasión del trabajo"]'::jsonb,2,'Art. 4.3.º Ley 31/1995','Así lo define el art. 4.3.º.',null),
('aux-ayto-mad:17-f09fdf51a2','aux-ayto-mad',17,'Según la Ley 31/1995, el «riesgo laboral grave e inminente» es aquel que:','["Ya se ha materializado en un accidente grave", "Afecta a más de la mitad de la plantilla y exige la intervención de la Inspección de Trabajo", "Resulte probable racionalmente que se materialice en un futuro inmediato y pueda suponer un daño grave para la salud"]'::jsonb,2,'Art. 4.4.º Ley 31/1995','Así lo define el art. 4.4.º.',null),
('aux-ayto-mad:17-1c91eebf53','aux-ayto-mad',17,'Según la Ley 31/1995, un «equipo de trabajo» es:','["El conjunto de trabajadores que desarrollan una misma tarea", "Cualquier equipo destinado a ser llevado por el trabajador para protegerse", "Cualquier máquina, aparato, instrumento o instalación utilizada en el trabajo"]'::jsonb,2,'Art. 4.6.º Ley 31/1995','Así lo define el art. 4.6.º. El equipo llevado por el trabajador para protegerse es el equipo de protección individual (art. 4.8.º).',null),
('aux-ayto-mad:17-88b99f860e','aux-ayto-mad',17,'Según la Ley 31/1995, el deber de protección de los trabajadores frente a los riesgos laborales es también un deber:','["De los sindicatos más representativos", "Exclusivo de los servicios de prevención ajenos con los que se concierte", "De las Administraciones públicas respecto del personal a su servicio"]'::jsonb,2,'Art. 14.1 Ley 31/1995','Según el art. 14.1, este deber de protección constituye, igualmente, un deber de las Administraciones públicas respecto del personal a su servicio.',null),
('aux-ayto-mad:17-45848acbb5','aux-ayto-mad',17,'Según la Ley 31/1995, el coste de las medidas relativas a la seguridad y la salud en el trabajo:','["Recae sobre los trabajadores cuando se trate de equipos de protección individual", "No deberá recaer en modo alguno sobre los trabajadores", "Se reparte entre empresario y trabajadores a partes iguales"]'::jsonb,1,'Art. 14.5 Ley 31/1995','El art. 14.5 dice que no deberá recaer en modo alguno sobre los trabajadores.',null),
('aux-ayto-mad:17-d06231bbdb','aux-ayto-mad',17,'¿Cuál de los siguientes es un principio de la acción preventiva del artículo 15 de la Ley 31/1995?','["Adoptar medidas que antepongan la protección colectiva a la individual", "Evaluar todos los riesgos antes de intentar evitarlos", "Anteponer la protección individual a la colectiva"]'::jsonb,0,'Art. 15.1 h) Ley 31/1995','Entre los principios están evitar los riesgos, evaluar los que no se puedan evitar, combatirlos en su origen, adaptar el trabajo a la persona y anteponer la protección colectiva a la individual.',null),
('aux-ayto-mad:17-c654c768f6','aux-ayto-mad',17,'Según los principios de la acción preventiva, el empresario debe:','["Sustituir lo peligroso por lo que entrañe poco o ningún peligro", "Asegurar los riesgos en lugar de evitarlos", "Trasladar los riesgos a los servicios de prevención ajenos"]'::jsonb,0,'Art. 15.1 f) Ley 31/1995','Es uno de los principios generales del art. 15.1.',null),
('aux-ayto-mad:17-3e8a2e6f4b','aux-ayto-mad',17,'Según la Ley 31/1995, la efectividad de las medidas preventivas deberá prever:','["Solo las conductas dolosas del trabajador", "Las distracciones o imprudencias no temerarias que pudiera cometer el trabajador", "Únicamente los riesgos que ya se hayan materializado en la empresa en los últimos años"]'::jsonb,1,'Art. 15.4 Ley 31/1995','Así lo establece el art. 15.4.',null),
('aux-ayto-mad:17-043425d2e9','aux-ayto-mad',17,'Según la Ley 31/1995, los equipos de protección individual deberán utilizarse:','["Cuando los riesgos no se puedan evitar o limitar suficientemente por medios técnicos de protección colectiva o por la organización del trabajo", "Solo cuando lo pida el trabajador", "Siempre, como primera medida preventiva, antes que la protección colectiva"]'::jsonb,0,'Art. 17.2 Ley 31/1995','Según el art. 17.2, los EPI se usan cuando los riesgos no pueden evitarse o limitarse suficientemente por medios de protección colectiva o medidas de organización.',null),
('aux-ayto-mad:17-5d66f05531','aux-ayto-mad',17,'En las empresas que cuenten con representantes de los trabajadores, la información sobre los riesgos se facilitará a través de dichos representantes, pero deberá informarse directamente a cada trabajador de:','["Las sanciones impuestas a la empresa por la Inspección de Trabajo", "Los riesgos específicos que afecten a su puesto de trabajo o función y de las medidas aplicables", "La evaluación de riesgos de toda la empresa"]'::jsonb,1,'Art. 18.1 Ley 31/1995','Así lo establece el último párrafo del art. 18.1.',null),
('aux-ayto-mad:17-b97752ece3','aux-ayto-mad',17,'La formación en materia preventiva que el empresario debe garantizar a cada trabajador se impartirá:','["Solo en el momento de la contratación, dentro del período de prueba", "Fuera de la jornada de trabajo y sin compensación", "Siempre que sea posible, dentro de la jornada de trabajo o, en su defecto, en otras horas descontando el tiempo invertido"]'::jsonb,2,'Art. 19.2 Ley 31/1995','Según el art. 19.2, se imparte dentro de la jornada o, en su defecto, en otras horas con descuento del tiempo invertido, y su coste no recae en ningún caso sobre los trabajadores.',null),
('aux-ayto-mad:17-0545e65698','aux-ayto-mad',17,'El empresario debe garantizar la formación preventiva de cada trabajador:','["Una sola vez, al inicio de la relación laboral", "En el momento de su contratación, cualquiera que sea la modalidad o duración, y cuando cambien sus funciones o se introduzcan nuevas tecnologías", "Solo a los trabajadores con contrato indefinido, al finalizar el período de prueba"]'::jsonb,1,'Art. 19.1 Ley 31/1995','Así lo establece el art. 19.1, que añade que se repetirá periódicamente si fuera necesario.',null),
('aux-ayto-mad:17-268e759ad0','aux-ayto-mad',17,'Según la Ley 31/1995, el trabajador tiene derecho a interrumpir su actividad y abandonar el lugar de trabajo cuando considere que su actividad entraña:','["Un riesgo grave e inminente para su vida o su salud", "Un riesgo para los bienes de la empresa", "Cualquier riesgo laboral, aunque sea leve"]'::jsonb,0,'Art. 21.2 Ley 31/1995','El art. 21.2 reconoce ese derecho en caso de riesgo grave e inminente para su vida o su salud.',null),
('aux-ayto-mad:17-0c1ae84cd7','aux-ayto-mad',17,'Si los representantes de los trabajadores acuerdan la paralización de la actividad por riesgo grave e inminente, la autoridad laboral anulará o ratificará la paralización en el plazo de:','["Tres días hábiles", "Cuarenta y ocho horas", "Veinticuatro horas"]'::jsonb,2,'Art. 21.3 Ley 31/1995','El acuerdo se comunica de inmediato a la empresa y a la autoridad laboral, que en veinticuatro horas lo anula o ratifica.',null),
('aux-ayto-mad:17-d569e44e0c','aux-ayto-mad',17,'Cuando no sea posible reunir con urgencia al órgano de representación del personal, el acuerdo de paralización por riesgo grave e inminente podrá adoptarse por:','["Decisión mayoritaria de los Delegados de Prevención", "El servicio de prevención ajeno", "El trabajador de mayor antigüedad"]'::jsonb,0,'Art. 21.3 Ley 31/1995','Así lo prevé el segundo párrafo del art. 21.3.',null),
('aux-ayto-mad:17-0dbbb02858','aux-ayto-mad',17,'El incumplimiento por los funcionarios públicos de sus obligaciones en materia de prevención de riesgos tendrá la consideración de:','["Simple incumplimiento sin consecuencias disciplinarias", "Falta, conforme a la normativa sobre régimen disciplinario de los funcionarios", "Delito contra la seguridad de los trabajadores en todo caso"]'::jsonb,1,'Art. 29.3 Ley 31/1995','Para los trabajadores es incumplimiento laboral (art. 58.1 ET); para los funcionarios, falta según su régimen disciplinario.',null),
('aux-ayto-mad:17-c8e3413aae','aux-ayto-mad',17,'Entre las obligaciones de los trabajadores en materia de prevención figura:','["No poner fuera de funcionamiento y utilizar correctamente los dispositivos de seguridad existentes", "Pagar los equipos de protección individual que se le entreguen para su uso personal", "Elaborar la evaluación de riesgos de su puesto"]'::jsonb,0,'Art. 29.2.3.º Ley 31/1995','Es una de las obligaciones del art. 29.2.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-ayto-mad:17-4349f44b7e','aux-ayto-mad',17,'Ante una situación que, a su juicio, entrañe un riesgo para la seguridad y la salud, el trabajador debe informar de inmediato a:','["El Comité de Empresa, exclusivamente", "Su superior jerárquico directo y a los trabajadores designados para actividades de prevención o, en su caso, al servicio de prevención", "La Inspección de Trabajo y Seguridad Social, antes que a nadie"]'::jsonb,1,'Art. 29.2.4.º Ley 31/1995','Así lo establece el art. 29.2.4.º.',null),
('aux-ayto-mad:17-11c9f64b6c','aux-ayto-mad',17,'En las empresas o centros de trabajo con seis o más trabajadores, la participación de estos en la prevención se canaliza:','["A través de sus representantes y de la representación especializada de la Ley 31/1995", "A través del servicio de prevención ajeno", "Directamente, mediante asambleas de todos los trabajadores del centro"]'::jsonb,0,'Art. 34.1 Ley 31/1995','Así lo establece el art. 34.1.',null),
('aux-ayto-mad:17-abcb818ed5','aux-ayto-mad',17,'Según la Ley 31/1995, los Delegados de Prevención son:','["Técnicos de prevención designados por el empresario entre su personal", "Inspectores de Trabajo especializados en prevención", "Los representantes de los trabajadores con funciones específicas en materia de prevención de riesgos en el trabajo"]'::jsonb,2,'Art. 35.1 Ley 31/1995','Así los define el art. 35.1.',null),
('aux-ayto-mad:17-237f12eb5a','aux-ayto-mad',17,'Los Delegados de Prevención son designados:','["Por la Inspección de Trabajo", "Por el empresario entre los trabajadores con formación preventiva", "Por y entre los representantes del personal"]'::jsonb,2,'Art. 35.2 Ley 31/1995','Según el art. 35.2, son designados por y entre los representantes del personal, salvo otros sistemas fijados en convenio (art. 35.4).',null),
('aux-ayto-mad:17-cf4eeabc12','aux-ayto-mad',17,'En una empresa de 101 a 500 trabajadores, el número de Delegados de Prevención es:','["4", "3", "2"]'::jsonb,1,'Art. 35.2 Ley 31/1995','La escala es: 50 a 100, 2; 101 a 500, 3; 501 a 1.000, 4; 1.001 a 2.000, 5; 2.001 a 3.000, 6; 3.001 a 4.000, 7; más de 4.000, 8.',null),
('aux-ayto-mad:17-141d161d25','aux-ayto-mad',17,'En las empresas de más de 4.000 trabajadores, el número de Delegados de Prevención es:','["10", "7", "8"]'::jsonb,2,'Art. 35.2 Ley 31/1995','Según la escala del art. 35.2, de 4.001 en adelante corresponden 8 Delegados de Prevención.',null),
('aux-ayto-mad:17-28b26bc0f7','aux-ayto-mad',17,'En las empresas de hasta treinta trabajadores, el Delegado de Prevención será:','["El Delegado de Personal", "Designado por el empresario", "Elegido directamente por los trabajadores"]'::jsonb,0,'Art. 35.2 Ley 31/1995','En las de hasta 30 trabajadores lo es el Delegado de Personal; en las de 31 a 49 habrá un Delegado de Prevención elegido por y entre los Delegados de Personal.',null),
('aux-ayto-mad:17-7b279b8699','aux-ayto-mad',17,'Para calcular el número de Delegados de Prevención, los trabajadores con contrato de duración determinada superior a un año se computan:','["Según los días trabajados en el último año", "Como medio trabajador", "Como trabajadores fijos de plantilla"]'::jsonb,2,'Art. 35.3 a) Ley 31/1995','Los de contrato superior a un año se computan como fijos; los de hasta un año, según los días trabajados (cada 200 días o fracción, un trabajador más).',null),
('aux-ayto-mad:17-d63397604b','aux-ayto-mad',17,'Para el cómputo de Delegados de Prevención, los contratados por término de hasta un año se computan:','["Un trabajador más por cada cien días trabajados", "Un trabajador más por cada doscientos días trabajados o fracción en el año anterior", "Como trabajadores fijos de plantilla"]'::jsonb,1,'Art. 35.3 b) Ley 31/1995','Así lo establece el art. 35.3 b).',null),
('aux-ayto-mad:17-827aef1ee7','aux-ayto-mad',17,'Los informes que deben emitir los Delegados de Prevención sobre las decisiones del artículo 33 deberán elaborarse en un plazo de:','["Quince días, o en el tiempo imprescindible si se trata de prevenir riesgos inminentes", "Un mes", "Diez días, o cinco si se trata de prevenir riesgos inminentes"]'::jsonb,0,'Art. 36.3 Ley 31/1995','Transcurrido el plazo sin informe, el empresario puede poner en práctica su decisión.',null),
('aux-ayto-mad:17-d376a57271','aux-ayto-mad',17,'La decisión negativa del empresario a adoptar las medidas propuestas por el Delegado de Prevención:','["Deberá ser motivada", "No necesita motivación", "Debe ser autorizada por la Inspección de Trabajo"]'::jsonb,0,'Art. 36.4 Ley 31/1995','Según el art. 36.4, deberá ser motivada.',null),
('aux-ayto-mad:17-54248f6a5e','aux-ayto-mad',17,'El tiempo que dedican los Delegados de Prevención a las reuniones del Comité de Seguridad y Salud se considera:','["Tiempo no retribuido", "Tiempo de trabajo efectivo, sin imputación al crédito horario", "Tiempo imputable al crédito de horas sindicales"]'::jsonb,1,'Art. 37.1 Ley 31/1995','También lo es el tiempo de otras reuniones convocadas por el empresario sobre prevención y el de determinadas visitas.',null),
('aux-ayto-mad:17-59183f4ab9','aux-ayto-mad',17,'El tiempo dedicado por los Delegados de Prevención a su formación preventiva:','["Se imputa a su crédito horario", "Es tiempo libre no retribuido, aunque su coste lo asume el empresario", "Se considera tiempo de trabajo a todos los efectos y su coste no puede recaer sobre ellos"]'::jsonb,2,'Art. 37.2 Ley 31/1995','Así lo establece el art. 37.2.',null),
('aux-ayto-mad:17-ec69002207','aux-ayto-mad',17,'El Comité de Seguridad y Salud es, según la Ley 31/1995:','["Un órgano unipersonal de la empresa encargado de la prevención", "El órgano paritario y colegiado de participación destinado a la consulta regular y periódica de las actuaciones de la empresa en prevención", "El órgano de la Administración laboral que sanciona los incumplimientos de la normativa de prevención"]'::jsonb,1,'Art. 38.1 Ley 31/1995','Así lo define el art. 38.1.',null),
('aux-ayto-mad:17-1ac4227be6','aux-ayto-mad',17,'El Comité de Seguridad y Salud se constituirá en todas las empresas o centros de trabajo que cuenten con:','["30 o más trabajadores", "100 o más trabajadores", "50 o más trabajadores"]'::jsonb,2,'Art. 38.2 Ley 31/1995','Según el art. 38.2, se constituye en las empresas o centros con 50 o más trabajadores.',null),
('aux-ayto-mad:17-aa8889c907','aux-ayto-mad',17,'El Comité de Seguridad y Salud está formado por:','["Los Delegados de Prevención y los Delegados Sindicales", "Los Delegados de Prevención y el empresario o sus representantes en igual número", "El empresario y los técnicos del servicio de prevención"]'::jsonb,1,'Art. 38.2 Ley 31/1995','Es un órgano paritario. Los Delegados Sindicales y los responsables técnicos de la prevención participan con voz pero sin voto.',null),
('aux-ayto-mad:17-e841067730','aux-ayto-mad',17,'En las reuniones del Comité de Seguridad y Salud, los Delegados Sindicales participan:','["Solo como observadores, sin voz", "Con voz pero sin voto", "Con voz y voto"]'::jsonb,1,'Art. 38.2 Ley 31/1995','Así lo establece el art. 38.2.',null),
('aux-ayto-mad:17-088a330fde','aux-ayto-mad',17,'El Comité de Seguridad y Salud se reunirá:','["Trimestralmente y siempre que lo solicite alguna de las representaciones", "Semestralmente", "Mensualmente y cuando lo convoque el empresario"]'::jsonb,0,'Art. 38.3 Ley 31/1995','Según el art. 38.3, se reúne trimestralmente y siempre que lo solicite alguna de las representaciones; adopta sus propias normas de funcionamiento.',null),
('aux-ayto-mad:17-30c1e7f3d8','aux-ayto-mad',17,'En las empresas que no cuenten con Comité de Seguridad y Salud por no alcanzar el número mínimo de trabajadores, sus competencias las ejercen:','["El Comité de Empresa", "Los Delegados de Prevención", "El empresario"]'::jsonb,1,'Art. 36.1 Ley 31/1995','Así lo establece el último párrafo del art. 36.1.',null),
('aux-ayto-mad:17-78eb1d7865','aux-ayto-mad',17,'Entre las facultades del Comité de Seguridad y Salud figura:','["Aprobar el presupuesto de la empresa", "Imponer sanciones a los trabajadores que incumplan las medidas de prevención", "Conocer e informar la memoria y programación anual de servicios de prevención"]'::jsonb,2,'Art. 39.2 d) Ley 31/1995','Es una de las facultades del art. 39.2.',null),
('aux-ayto-mad:17-1bf40ba2a5','aux-ayto-mad',17,'En el ámbito de las Administraciones públicas se constituirá, con carácter general:','["Un Comité de Seguridad y Salud por cada centro de trabajo", "Un Comité para el personal funcionario y otro para el laboral", "Un único Comité de Seguridad y Salud en el ámbito de los órganos de representación del personal"]'::jsonb,2,'Art. 34.3 d) Ley 31/1995','Lo integran los Delegados de Prevención de ese ámbito, para personal funcionario, estatutario y laboral, y representantes de la Administración en número no superior al de Delegados.',null),
('aux-ayto-mad:17-22798d532e','aux-ayto-mad',17,'Los trabajadores y sus representantes pueden recurrir a la Inspección de Trabajo y Seguridad Social si consideran que las medidas del empresario:','["Son más costosas de lo necesario para la empresa", "No son suficientes para garantizar la seguridad y la salud en el trabajo", "Afectan a su retribución"]'::jsonb,1,'Art. 40.1 Ley 31/1995','Así lo establece el art. 40.1.',null),
('aux-ayto-mad:17-475aa438da','aux-ayto-mad',17,'Los Delegados de Prevención pueden presentarse en el lugar de los hechos para conocer las circunstancias de los daños producidos en la salud de los trabajadores:','["Solo dentro de su jornada laboral", "Solo con autorización previa del empresario", "Aun fuera de su jornada laboral"]'::jsonb,2,'Art. 36.2 c) Ley 31/1995','Según el art. 36.2 c), pueden presentarse aún fuera de su jornada laboral.',null),
('aux-ayto-mad:18-fd420fca27','aux-ayto-mad',18,'Según la Ley 39/2015, cada Administración dispondrá de:','["Un Registro Electrónico General", "Un registro único estatal", "Un registro en papel por cada órgano"]'::jsonb,0,'Art. 16.1 Ley 39/2015','Cada Administración dispondrá de un Registro Electrónico General.',null),
('aux-ayto-mad:18-cb0c94d962','aux-ayto-mad',18,'¿Dónde NO se pueden presentar documentos dirigidos a las Administraciones según el art. 16.4 de la Ley 39/2015?','["En las oficinas de asistencia en materia de registros", "En las representaciones diplomáticas u oficinas consulares", "En cualquier comercio colaborador"]'::jsonb,2,'Art. 16.4 Ley 39/2015','Se pueden presentar en los registros electrónicos, en Correos, en representaciones diplomáticas u oficinas consulares, en las oficinas de asistencia en materia de registros y donde establezcan las disposiciones vigentes.',null),
('aux-ayto-mad:18-7e745c2a9a','aux-ayto-mad',18,'Cada Administración debe mantener, para los documentos electrónicos de procedimientos finalizados:','["Un archivo electrónico único", "Un archivo por cada funcionario", "Un archivo en papel"]'::jsonb,0,'Art. 17.1 Ley 39/2015','Debe mantener un archivo electrónico único de los documentos electrónicos de procedimientos finalizados.',null),
('aux-ayto-mad:18-8e34628169','aux-ayto-mad',18,'Tras presentar un documento en el registro electrónico se emite automáticamente:','["Una resolución de admisión a trámite firmada por el órgano competente para resolver, con indicación del plazo máximo para hacerlo", "Un recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada", "Un justificante sin fecha, que se completa el primer día hábil siguiente"]'::jsonb,1,'Art. 16.3 Ley 39/2015','El registro emite automáticamente un recibo consistente en una copia autenticada del documento, con fecha, hora y número de entrada.',null),
('aux-ayto-mad:18-55af533af5','aux-ayto-mad',18,'Una vez digitalizados por la oficina de asistencia, los documentos originales presentados presencialmente:','["Se remiten siempre al archivo central de la consejería que tramita el expediente, para su custodia hasta que se dicte la resolución", "Se devuelven al interesado, salvo que una norma determine su custodia por la Administración", "Se destruyen una vez transcurridos quince días hábiles desde su presentación"]'::jsonb,1,'Art. 16.5 Ley 39/2015','Los originales se devuelven al interesado, sin perjuicio de los supuestos en que la norma determine la custodia por la Administración.',null),
('aux-ayto-mad:18-340b1b2b71','aux-ayto-mad',18,'Las Administraciones deben hacer pública y mantener actualizada:','["Una relación de las oficinas en las que se presta asistencia para la presentación electrónica de documentos", "La lista de los funcionarios que digitalizan documentos en cada oficina", "La lista de los interesados que han presentado documentos en papel durante el último año"]'::jsonb,0,'Art. 16.7 Ley 39/2015','El art. 16.7 obliga a publicar y actualizar la relación de oficinas de asistencia en materia de registros.',null),
('aux-ayto-mad:18-d1fa877de6','aux-ayto-mad',18,'Los documentos electrónicos deben conservarse en un formato que permita garantizar:','["Su integridad mientras el procedimiento esté en tramitación, pero no después", "Su consulta durante los cinco años siguientes a la finalización del procedimiento, plazo tras el cual pueden eliminarse sin más trámite", "Su autenticidad, integridad y conservación, y su consulta con independencia del tiempo transcurrido"]'::jsonb,2,'Art. 17.2 Ley 39/2015','El art. 17.2 exige un formato que garantice autenticidad, integridad y conservación, y la consulta sin importar el tiempo transcurrido.',null),
('aux-ayto-mad:18-e1c957e578','aux-ayto-mad',18,'Los asientos en el registro electrónico se anotan:','["Respetando el orden temporal de recepción o salida de los documentos", "Agrupados por procedimientos administrativos al final de cada jornada de trabajo", "Por orden de importancia del asunto, según decida el responsable del registro"]'::jsonb,0,'Art. 16.2 Ley 39/2015','Indican la fecha del día en que se producen.',null),
('aux-ayto-mad:18-fa1f4000d7','aux-ayto-mad',18,'Los documentos que los interesados presenten en papel en las oficinas de asistencia en materia de registros:','["Se destruyen tras su presentación para evitar duplicidades", "Se remiten por valija a la unidad tramitadora, que los conserva en papel junto con el resto del expediente", "Se digitalizan para incorporarlos al expediente electrónico y se devuelven los originales al interesado"]'::jsonb,2,'Art. 16.5 Ley 39/2015','Salvo que la norma determine la custodia de los documentos por la Administración o que se trate de objetos o documentos en un soporte específico no susceptibles de digitalización.',null),
('aux-ayto-mad:18-8705e4ddb7','aux-ayto-mad',18,'Cada Administración debe mantener un archivo electrónico único de:','["Las resoluciones judiciales que le afecten", "Los expedientes de personal de todos sus funcionarios y del personal laboral a su servicio", "Los documentos electrónicos que correspondan a procedimientos finalizados"]'::jsonb,2,'Art. 17.1 Ley 39/2015','Los documentos se conservan en un formato que permita garantizar su autenticidad, integridad y conservación.',null),
('aux-ayto-mad:18-261edadf9e','aux-ayto-mad',18,'¿A través de qué dirección se accede al Registro Electrónico General del Ayuntamiento de Madrid?','["A través del portal institucional «madrid.es»", "A través del Punto de Acceso General de la Administración del Estado", "A través de la Sede Electrónica «sede.madrid.es»"]'::jsonb,2,'Art. 36.2 OACAE','El acceso al Registro Electrónico General se realiza a través de la Sede Electrónica, identificándose previamente con alguno de los medios aceptados.',null),
('aux-ayto-mad:18-b6717a1391','aux-ayto-mad',18,'¿Qué días y horas se pueden presentar documentos en el Registro Electrónico General del Ayuntamiento de Madrid?','["Todos los días del año, de 8:00 a 20:00 horas", "Los días hábiles durante las 24 horas", "Todos los días del año durante las 24 horas"]'::jsonb,2,'Art. 36.3 OACAE','En el Registro Electrónico General se pueden presentar documentos todos los días del año durante las 24 horas.',null),
('aux-ayto-mad:18-45f2131cd6','aux-ayto-mad',18,'¿Qué fecha y hora oficial indica el Registro Electrónico General del Ayuntamiento de Madrid?','["La misma que figure en la Sede Electrónica", "La del Real Instituto y Observatorio de la Armada", "La del servidor de la oficina de registro de entrada"]'::jsonb,0,'Art. 36.3 OACAE','El Registro indicará la fecha y hora oficial, que será la misma que figure en la Sede Electrónica del Ayuntamiento.',null),
('aux-ayto-mad:18-49120581a8','aux-ayto-mad',18,'¿Dónde se publican las disposiciones de creación de los registros electrónicos del Ayuntamiento de Madrid?','["En el Boletín Oficial de la Comunidad de Madrid", "En el Boletín Oficial del Estado", "En el Boletín Oficial del Ayuntamiento de Madrid"]'::jsonb,2,'Art. 36.4 OACAE','Las disposiciones de creación de los registros electrónicos se publican en el BOAM y su texto íntegro debe estar en la Sede Electrónica.',null),
('aux-ayto-mad:18-386bf526cd','aux-ayto-mad',18,'¿Qué complementa al Registro Electrónico General del Ayuntamiento de Madrid?','["Las oficinas de asistencia en materia de registro", "El Registro Electrónico General de Apoderamientos", "Los registros auxiliares de cada Área de Gobierno"]'::jsonb,0,'Art. 36.6 OACAE','El Registro Electrónico General será complementado por las oficinas de asistencia en materia de registro.',null),
('aux-ayto-mad:18-e5b10dfbeb','aux-ayto-mad',18,'¿En qué orden se anotan los asientos en el Registro Electrónico General?','["Por orden alfabético del órgano destinatario", "Agrupados por procedimiento administrativo", "Respetando el orden temporal de recepción o salida de los documentos"]'::jsonb,2,'Art. 37.2 OACAE','Los asientos se anotan respetando el orden temporal de recepción o salida e indican la fecha del día en que se producen.',null),
('aux-ayto-mad:18-a4ad265acf','aux-ayto-mad',18,'¿Qué determina, según el recibo del Registro Electrónico General, el inicio del cómputo de plazos?','["La fecha de entrada en el órgano competente", "La fecha y hora de presentación", "La fecha de emisión del recibo en papel"]'::jsonb,1,'Art. 37.5 b) OACAE','El recibo contiene la fecha y hora de presentación, que determinará el inicio del cómputo de plazos.',null),
('aux-ayto-mad:18-0209ef5467','aux-ayto-mad',18,'¿Qué puede hacer el Registro Electrónico General con documentos electrónicos que contengan código malicioso?','["Rechazarlos, informando al remitente de los motivos", "Admitirlos y aislarlos hasta que se subsanen", "Destruirlos sin informar al remitente"]'::jsonb,0,'Art. 37.7 OACAE','Se pueden rechazar los documentos con código malicioso, informando al remitente de los motivos y, si es posible, de cómo subsanarlo.',null),
('aux-ayto-mad:18-3e8caa00f9','aux-ayto-mad',18,'¿Qué naturaleza tienen las oficinas de asistencia en materia de registro del Ayuntamiento de Madrid?','["La de unidad administrativa sin rango de órgano", "La de organismo autónomo", "La de órgano administrativo"]'::jsonb,2,'Art. 39.3 OACAE','Las oficinas de asistencia en materia de registro tienen naturaleza de órgano administrativo, según el art. 5 de la Ley 40/2015.',null),
('aux-ayto-mad:18-9b72aff771','aux-ayto-mad',18,'¿Cómo se crean, modifican o suprimen las oficinas de asistencia en materia de registro del Ayuntamiento de Madrid?','["Por decreto del alcalde, sin necesidad de publicación", "Por acuerdo del Pleno publicado en el BOCM", "Por resolución del órgano competente publicada en el BOAM"]'::jsonb,2,'Art. 39.4 OACAE','Se crean, modifican o suprimen mediante resolución del órgano competente que debe publicarse en el Boletín Oficial del Ayuntamiento de Madrid.',null),
('aux-ayto-mad:18-a2afa394de','aux-ayto-mad',18,'En la recepción y digitalización de documentos por las oficinas de asistencia en materia de registro, ¿qué se hace con carácter general con los originales?','["Se devuelven a la persona interesada", "Se custodian en el archivo de la oficina", "Se remiten al órgano destinatario"]'::jsonb,0,'Art. 40.1 a) OACAE','Se devuelven los originales a la persona interesada, salvo que la norma determine su custodia o no sean susceptibles de digitalización.',null),
('aux-ayto-mad:18-2b1f852141','aux-ayto-mad',18,'¿Qué calendario se aplica a efectos del cómputo de plazos en los registros electrónicos del Ayuntamiento de Madrid?','["El calendario oficial de días inhábiles publicado en su Sede Electrónica", "El calendario laboral de la Comunidad de Madrid", "El calendario de días inhábiles del Estado publicado en el BOE"]'::jsonb,0,'Art. 41.1 OACAE','El calendario de días inhábiles publicado en la Sede Electrónica es el único que se aplica para el cómputo de plazos en los registros electrónicos.',null),
('aux-ayto-mad:18-cf0053adb5','aux-ayto-mad',18,'Si un interesado presenta un documento en el Registro Electrónico General en un día inhábil, ¿cuándo se entiende presentado a efectos de plazos en días hábiles?','["En la primera hora del primer día hábil siguiente", "A la misma hora del primer día hábil siguiente", "En el momento efectivo de la presentación"]'::jsonb,0,'Art. 41.3 OACAE','Salvo norma que permita la recepción en día inhábil, se entiende realizada en la primera hora del primer día hábil siguiente.',null),
('aux-ayto-mad:18-d968454ab2','aux-ayto-mad',18,'¿Qué puede acordar el Ayuntamiento de Madrid cuando una incidencia técnica imprevista impide el funcionamiento del registro electrónico?','["La suspensión de todos los procedimientos en curso", "Una ampliación de los plazos no vencidos", "La admisión de documentos por correo electrónico ordinario"]'::jsonb,1,'Art. 41.5 OACAE','Puede determinar una ampliación de los plazos no vencidos, publicando en la Sede Electrónica la incidencia y la ampliación concreta.',null),
('aux-ayto-mad:18-1bb094d5d1','aux-ayto-mad',18,'¿Por qué medios se almacenan los documentos que forman parte del expediente administrativo según la Ordenanza de Atención a la Ciudadanía?','["En papel y, además, en copia electrónica", "En el soporte original en que se presentaron", "Por medios electrónicos, salvo cuando no sea posible"]'::jsonb,2,'Art. 68.2 OACAE','Todos los documentos del expediente se almacenan por medios electrónicos, salvo cuando no sea posible.',null),
('aux-ayto-mad:18-2a8ffd1a9d','aux-ayto-mad',18,'¿Por qué normativa se rige el acceso de las personas a los archivos electrónicos del Ayuntamiento de Madrid?','["Por la Ley de Archivos de la Comunidad de Madrid", "Por el Reglamento Orgánico del Gobierno y de la Administración", "Por la Ordenanza de Transparencia de la Ciudad de Madrid"]'::jsonb,2,'Art. 70.1 OACAE','El acceso de las personas a los archivos electrónicos se rige por la Ordenanza de Transparencia de la Ciudad de Madrid y demás normativa de transparencia.',null),
('aux-ayto-mad:19-bf787cd347','aux-ayto-mad',19,'Las Administraciones deben asistir en el uso de medios electrónicos a:','["Los empleados públicos, para los trámites relacionados con su condición de tales", "Las personas físicas que no estén obligadas a relacionarse electrónicamente", "Las entidades sin personalidad jurídica que carezcan de medios electrónicos propios"]'::jsonb,1,'Art. 12.2 Ley 39/2015','Deben asistir a las personas físicas no obligadas, especialmente en identificación y firma, presentación de solicitudes y obtención de copias auténticas.',null),
('aux-ayto-mad:19-a4ca763cc9','aux-ayto-mad',19,'Las personas físicas, ¿pueden elegir si se comunican con las Administraciones por medios electrónicos?','["No, siempre deben usar medios electrónicos", "Solo si son mayores de 65 años", "Sí, en todo momento, salvo que estén obligadas"]'::jsonb,2,'Art. 14.1 Ley 39/2015','Pueden elegir en todo momento, salvo que estén obligadas a relacionarse electrónicamente.',null),
('aux-ayto-mad:19-50b358dc55','aux-ayto-mad',19,'¿Cuál de los siguientes NO está obligado, con carácter general, a relacionarse electrónicamente con las Administraciones?','["Una persona jurídica", "Una persona física que actúa en su propio nombre", "Un empleado público en trámites por razón de su condición"]'::jsonb,1,'Art. 14.2 Ley 39/2015','Están obligados las personas jurídicas, las entidades sin personalidad, los profesionales con colegiación obligatoria, los representantes de obligados y los empleados públicos en esos trámites.',null),
('aux-ayto-mad:19-febb9a846b','aux-ayto-mad',19,'Las personas tienen derecho a comunicarse con las Administraciones a través de:','["Los perfiles oficiales en redes sociales", "Un Punto de Acceso General electrónico", "Un número de WhatsApp oficial de cada organismo"]'::jsonb,1,'Art. 13 a) Ley 39/2015','Tienen derecho a comunicarse a través de un Punto de Acceso General electrónico de la Administración.',null),
('aux-ayto-mad:19-261b30a503','aux-ayto-mad',19,'Es un derecho de las personas en sus relaciones con las AAPP según el art. 13:','["Elegir al funcionario que tramite su expediente", "Obtener una resolución favorable si la Administración incumple el plazo máximo para resolver", "Ser tratados con respeto y deferencia por las autoridades y empleados públicos"]'::jsonb,2,'Art. 13 e) Ley 39/2015','Otros: comunicarse por el Punto de Acceso General electrónico, ser asistidos en el uso de medios electrónicos, usar lenguas cooficiales, acceso a información pública…',null),
('aux-ayto-mad:19-2d78b10ba0','aux-ayto-mad',19,'Si un interesado no obligado a relacionarse electrónicamente carece de los medios necesarios, su firma electrónica puede realizarla:','["Un funcionario habilitado, pero solo en los procedimientos que se inician de oficio", "Cualquier empleado público de la oficina, sin necesidad de consentimiento expreso del interesado", "Un funcionario habilitado, si el interesado se identifica ante él y presta su consentimiento expreso"]'::jsonb,2,'Art. 12.2 Ley 39/2015','El funcionario firma con su propio sistema; el interesado debe identificarse y prestar consentimiento expreso, del que queda constancia.',null),
('aux-ayto-mad:19-0801b1b71d','aux-ayto-mad',19,'Los funcionarios habilitados para la identificación o firma de los interesados que no disponen de medios electrónicos constan en:','["El registro electrónico de apoderamientos de la Administración correspondiente", "Un registro u otro sistema equivalente que cada Administración mantiene actualizado", "Un listado único estatal publicado en la sede electrónica del Ministerio para la Transformación Digital y de la Función Pública"]'::jsonb,1,'Art. 12.3 Ley 39/2015','La AGE, las CCAA y las Entidades Locales mantienen actualizado un registro u otro sistema equivalente de funcionarios habilitados.',null),
('aux-ayto-mad:19-ec2dff1e0b','aux-ayto-mad',19,'La obligación de relacionarse electrónicamente con la Administración para ciertos colectivos de personas físicas puede establecerse:','["Por resolución del órgano instructor en cada procedimiento concreto", "Reglamentariamente, si queda acreditado que tienen acceso y disponibilidad de los medios electrónicos", "Reglamentariamente, para cualquier persona física mayor de edad"]'::jsonb,1,'Art. 14.3 Ley 39/2015','Puede imponerse por reglamento a colectivos que, por capacidad económica, técnica o dedicación profesional, tengan acceso a esos medios.',null),
('aux-ayto-mad:19-5de517edae','aux-ayto-mad',19,'Según el artículo 13 de la Ley 39/2015, es un derecho de las personas en sus relaciones con las Administraciones Públicas:','["Ser tratadas con respeto y deferencia por las autoridades y empleados públicos, que habrán de facilitarles el ejercicio de sus derechos", "Exigir que se les atienda fuera del horario de atención al público", "Obtener siempre una resolución favorable cuando cumplan los requisitos formales"]'::jsonb,0,'Art. 13 e) Ley 39/2015','El artículo 13 recoge también, entre otros, el derecho a ser asistidas en el uso de medios electrónicos.',null),
('aux-ayto-mad:19-9631a48174','aux-ayto-mad',19,'¿Qué registro deben mantener las Administraciones de los funcionarios habilitados para expedir copias auténticas y asistir en la presentación electrónica?','["Un registro de convenios suscritos con otras Administraciones públicas", "Un registro o sistema equivalente de funcionarios habilitados", "Un registro de órganos colegiados y de sus miembros titulares y suplentes"]'::jsonb,1,'Art. 12.3 Ley 39/2015','El registro electrónico de apoderamientos recoge las representaciones otorgadas por los interesados.',null),
('aux-ayto-mad:19-96838a01e5','aux-ayto-mad',19,'¿Cuál de los siguientes está obligado a relacionarse electrónicamente con las Administraciones según el artículo 14.2 de la Ley 39/2015?','["Las personas físicas mayores de 65 años", "Las personas jurídicas", "Los autónomos sin colegiación obligatoria"]'::jsonb,1,'Art. 14.2 Ley 39/2015','También las entidades sin personalidad jurídica, los profesionales de colegiación obligatoria en el ejercicio de su actividad, sus representantes y los empleados públicos en los trámites por su condición de tales.',null),
('aux-ayto-mad:19-03e1678d5f','aux-ayto-mad',19,'Según la Ley 39/2015, si el interesado no dispone de los medios electrónicos necesarios, su identificación o firma electrónica en el procedimiento puede ser válidamente realizada por:','["Un funcionario público habilitado, mediante el uso del sistema de firma electrónica del que esté dotado", "El representante sindical del interesado", "Un notario de libre elección del interesado, que deberá dar fe del acto realizado y de la identidad del firmante"]'::jsonb,0,'Art. 12.2 Ley 39/2015','El interesado debe identificarse ante el funcionario y prestar su consentimiento expreso, que debe quedar constancia.',null),
('aux-ayto-mad:19-efca780915','aux-ayto-mad',19,'¿Qué servicio integra la atención presencial, telefónica y telemática del Ayuntamiento de Madrid?','["Madrid Contigo", "El Punto de Acceso General", "Línea Madrid"]'::jsonb,2,'Art. 14.1 OACAE','Línea Madrid se configura como el servicio integrador de la atención presencial, telefónica y telemática.',null),
('aux-ayto-mad:19-30d2022c4d','aux-ayto-mad',19,'¿Cuál es el canal telefónico de atención a la ciudadanía de Línea Madrid?','["El 010", "El 060", "El 012"]'::jsonb,0,'Art. 16.1 OACAE','El teléfono 010 es el canal telefónico de atención a la ciudadanía de Línea Madrid.',null),
('aux-ayto-mad:19-5c2d929653','aux-ayto-mad',19,'¿En qué horario está disponible el teléfono 010 del Ayuntamiento de Madrid?','["24 horas los días laborables", "De 8:00 a 22:00 todos los días del año", "24 horas todos los días del año"]'::jsonb,2,'Art. 16.4 OACAE','El 010 está disponible en horario ininterrumpido, 24 horas todos los días del año.',null),
('aux-ayto-mad:19-d31408d26a','aux-ayto-mad',19,'¿Qué coste tienen los servicios que se prestan a través del teléfono 010?','["Tienen el precio público que fije la Junta de Gobierno", "Son gratuitos y la llamada al 010 no tiene coste", "Son gratuitos, pero la llamada se cobra a tarifa local"]'::jsonb,1,'Art. 16.5 OACAE','Los servicios del 010 son gratuitos y la llamada directa al 010 no supone coste alguno en la factura de quien llama.',null),
('aux-ayto-mad:19-1467fce5c9','aux-ayto-mad',19,'¿Qué canal constituyen las Oficinas de Atención a la Ciudadanía de Línea Madrid?','["El canal presencial", "El canal telemático", "El canal especializado"]'::jsonb,0,'Art. 15.1 OACAE','Las Oficinas de Atención a la Ciudadanía constituyen el canal presencial de Línea Madrid.',null),
('aux-ayto-mad:19-4f565ec285','aux-ayto-mad',19,'¿Dónde se ubican, en principio, las Oficinas de Atención a la Ciudadanía de Línea Madrid?','["En los centros culturales de cada barrio", "En las sedes de las Áreas de Gobierno", "En las dependencias de los distritos"]'::jsonb,2,'Art. 15.2 OACAE','Existirán Oficinas de Atención a la Ciudadanía en las dependencias de los distritos o, si no es posible, en otros locales.',null),
('aux-ayto-mad:19-d787d75841','aux-ayto-mad',19,'¿Qué horario tienen las Oficinas de Atención a la Ciudadanía de Línea Madrid?','["Un horario fijo de mañana y franjas de horario de tarde", "Un horario ininterrumpido de 8:00 a 20:00", "El mismo horario que el teléfono 010"]'::jsonb,0,'Art. 15.3 OACAE','Tienen un horario fijo de atención en horario de mañana y franjas de horario de tarde.',null),
('aux-ayto-mad:19-00e232d35c','aux-ayto-mad',19,'¿A quién se facilita obligatoriamente la información administrativa general del Ayuntamiento de Madrid?','["Solo a quienes acrediten la condición de interesados", "Solo a los vecinos empadronados en Madrid", "A cualquier persona que la solicite"]'::jsonb,2,'Art. 12.1 a) OACAE','La información general se facilita obligatoriamente a cualquier persona que la solicite, sin exigir la condición de interesado.',null),
('aux-ayto-mad:19-3a6a5c9e95','aux-ayto-mad',19,'¿Qué efectos tiene la información facilitada por el sistema de atención a la ciudadanía?','["Interrumpe los plazos de prescripción", "Vincula al órgano que deba resolver el procedimiento", "No origina derechos ni expectativas de derecho"]'::jsonb,2,'Art. 13.1 OACAE','Las informaciones no originan derechos ni expectativas de derecho y no pueden invocarse para interrumpir o suspender plazos (art. 13.2).',null),
('aux-ayto-mad:19-e84d3fc360','aux-ayto-mad',19,'¿Cuál es el portal institucional del Ayuntamiento de Madrid?','["madrid.es", "decide.madrid.es", "sede.madrid.es"]'::jsonb,0,'Art. 17.1 OACAE','La web «madrid.es» es el portal institucional; «sede.madrid.es» es la Sede Electrónica.',null),
('aux-ayto-mad:19-26fba2cf9c','aux-ayto-mad',19,'¿Con qué documento deben contar las oficinas de atención especializada del Ayuntamiento de Madrid?','["Con un reglamento interno aprobado por el Pleno", "Con una carta de servicios", "Con un plan anual de calidad aprobado por el alcalde"]'::jsonb,1,'Art. 19.2 OACAE','Las oficinas de atención especializada deben contar con una carta de servicios con sus servicios, compromisos de calidad y derechos de los usuarios.',null),
('aux-ayto-mad:19-3dd26bf7f1','aux-ayto-mad',19,'¿Cuál de estas funciones no corresponde a las Oficinas de Atención a la Ciudadanía de Línea Madrid?','["Resolver los recursos contra los actos de los distritos", "Actuar como oficinas de asistencia en materia de registro", "Registrar y tramitar sugerencias, reclamaciones y felicitaciones"]'::jsonb,0,'Art. 15.1 OACAE','Entre sus funciones están orientar e informar, actuar como oficinas de registro, registrar sugerencias y reclamaciones y realizar gestiones; no resuelven recursos.',null),
('aux-ayto-mad:19-945338f92d','aux-ayto-mad',19,'¿Qué identidad tiene la atención a la ciudadanía en el Ayuntamiento de Madrid?','["Una identidad distinta para cada canal de atención", "Una identidad corporativa única y homogénea", "Una identidad propia en cada distrito"]'::jsonb,1,'Art. 11.3 OACAE','La atención a la ciudadanía tendrá una identidad corporativa única y homogénea.',null),
('aux-ayto-mad:19-33be9d3dd6','aux-ayto-mad',19,'¿Cuál es la Sede Electrónica respecto del punto de acceso general electrónico de la administración municipal de Madrid?','["Es un canal complementario del punto de acceso general", "Solo es accesible desde el punto de acceso general del Estado", "Es el punto de acceso general electrónico del Ayuntamiento"]'::jsonb,2,'Art. 33.7 OACAE','La Sede Electrónica se configura como el punto de acceso general electrónico de la administración del Ayuntamiento de Madrid.',null),
('aux-ayto-mad:20-1fa419635d','aux-ayto-mad',20,'La Comisión especial de Sugerencias y Reclamaciones de los municipios de gran población está formada por:','["Un concejal de cada grupo político y el Secretario General del Pleno", "Representantes de todos los grupos que integren el Pleno, de forma proporcional", "Representantes de las asociaciones vecinales más representativas de la ciudad"]'::jsonb,1,'Art. 132.2 LBRL','Está formada por representantes de todos los grupos del Pleno en proporción a sus miembros, y da cuenta al Pleno mediante un informe anual.',null),
('aux-ayto-mad:20-f800624c4b','aux-ayto-mad',20,'El órgano especializado para la defensa de los derechos de los vecinos ante la Administración municipal deberá dar cuenta al Pleno de su actividad mediante:','["Un informe trimestral", "Un informe anual, sin perjuicio de informes extraordinarios", "Una comparecencia semestral ante la Comisión de Vecinos"]'::jsonb,1,'Art. 27.2 Ley 22/2006','Debe dar cuenta al Pleno mediante un informe anual de las quejas y deficiencias observadas, y puede hacer informes extraordinarios por gravedad o urgencia.',null),
('aux-ayto-mad:20-ddda6e0e29','aux-ayto-mad',20,'Según la Ley 22/2006, la creación de un órgano para la defensa de los derechos de los vecinos es:','["Potestativa para el Pleno", "Obligatoria para el Pleno", "Competencia de la Junta de Gobierno"]'::jsonb,0,'Art. 27.1 Ley 22/2006','El art. 27.1 dice que el Pleno podrá crear este órgano, cuyo funcionamiento se regulará en normas de carácter orgánico.',null),
('aux-ayto-mad:20-9aa4984dcd','aux-ayto-mad',20,'¿Quiénes tienen derecho a presentar sugerencias, reclamaciones y felicitaciones sobre los servicios del Ayuntamiento de Madrid?','["Todas las personas físicas y jurídicas", "Solo las personas físicas mayores de edad", "Solo las personas empadronadas en Madrid"]'::jsonb,0,'Art. 22.1 OACAE','Todas las personas físicas y jurídicas tienen derecho a presentar sugerencias, reclamaciones y felicitaciones.',null),
('aux-ayto-mad:20-f9d89eb373','aux-ayto-mad',20,'¿Están sujetas las sugerencias, reclamaciones y felicitaciones al procedimiento administrativo común?','["No, no están sujetas a él", "Sí, como solicitudes de iniciación a instancia de parte", "Solo las reclamaciones de carácter tributario"]'::jsonb,0,'Art. 22.2 OACAE','Las sugerencias, reclamaciones y felicitaciones no están sujetas al procedimiento administrativo común.',null),
('aux-ayto-mad:20-c25aa68cd9','aux-ayto-mad',20,'¿Qué dos modalidades de sugerencias, reclamaciones y felicitaciones distingue la Ordenanza de Atención a la Ciudadanía?','["De carácter general y de carácter tributario", "Individuales y colectivas", "Presenciales y electrónicas"]'::jsonb,0,'Art. 23 OACAE','Pueden ser de carácter general o de carácter tributario, según se refieran o no a procedimientos tributarios.',null),
('aux-ayto-mad:20-44fff3963f','aux-ayto-mad',20,'¿A través de qué canal se presentan preferentemente las sugerencias, reclamaciones y felicitaciones?','["A través del portal institucional «madrid.es»", "Por el teléfono 010", "En las Oficinas de Atención a la Ciudadanía"]'::jsonb,0,'Art. 24.1 OACAE','Se pueden presentar por los distintos canales, preferentemente a través del portal institucional «madrid.es».',null),
('aux-ayto-mad:20-9ea4e67682','aux-ayto-mad',20,'¿Cuál es el plazo máximo para contestar una sugerencia o reclamación en el Ayuntamiento de Madrid?','["Dos meses desde su entrada", "Tres meses desde su entrada", "Un mes desde su entrada"]'::jsonb,0,'Art. 28.3 OACAE','El plazo de contestación no puede ser superior, en ningún caso, a dos meses desde la entrada en el Ayuntamiento.',null),
('aux-ayto-mad:20-5493aff01c','aux-ayto-mad',20,'¿Cabe recurso contra la respuesta a una sugerencia o reclamación?','["No cabe recurso alguno", "Cabe recurso potestativo de reposición", "Cabe recurso de alzada ante el alcalde"]'::jsonb,0,'Art. 25.3 OACAE','Contra su respuesta no cabe recurso alguno, sin perjuicio de que los motivos puedan exponerse en los recursos del procedimiento relacionado.',null),
('aux-ayto-mad:20-4c91aa9777','aux-ayto-mad',20,'¿Adquiere quien presenta una reclamación la condición de interesado en el procedimiento al que se refiere?','["No, en ningún caso", "Solo si la reclamación tiene carácter tributario", "Sí, desde que la reclamación es admitida"]'::jsonb,0,'Art. 25.4 OACAE','Quien presenta una sugerencia o reclamación en ningún caso adquiere la condición legal de interesado ni se abre la vía de recursos.',null),
('aux-ayto-mad:20-c9eb0e86eb','aux-ayto-mad',20,'¿Paraliza la presentación de una reclamación los plazos establecidos en la normativa?','["Sí, suspende los plazos hasta que se responda", "Solo suspende la ejecución del acto reclamado", "No, ni paraliza plazos ni suspende la ejecución del acto"]'::jsonb,2,'Art. 25.1 OACAE','Su presentación no paraliza los plazos ni suspende la ejecución de la resolución o acto al que se refiera.',null),
('aux-ayto-mad:20-713fab1cad','aux-ayto-mad',20,'¿Qué se hace con una felicitación que se refiere expresamente al buen desempeño de un empleado público?','["Se publica en el portal institucional", "Se comunica al órgano de recursos humanos para su expediente personal", "Se archiva sin más trámite"]'::jsonb,1,'Art. 25.5 OACAE','Se comunica al órgano competente en recursos humanos para su incorporación, en su caso, al expediente personal.',null),
('aux-ayto-mad:20-23924bdc97','aux-ayto-mad',20,'Si una persona desiste de su reclamación, ¿puede el Ayuntamiento seguir tramitándola?','["Solo si la reclamación fue presentada por varias personas", "Sí, de oficio por motivos de interés público", "No, el desistimiento termina siempre la tramitación"]'::jsonb,1,'Art. 26.2 OACAE','En caso de desistimiento se da por terminada, pero el Ayuntamiento puede continuar de oficio por motivos de interés público.',null),
('aux-ayto-mad:20-5fade2bf8b','aux-ayto-mad',20,'¿Cuándo puede acumularse la tramitación de reclamaciones presentadas por distintas personas?','["Cuando se presenten el mismo día", "Cuando coincidan en lo sustancial o en su contenido", "Cuando se dirijan al mismo distrito"]'::jsonb,1,'Art. 27.1 OACAE','Pueden acumularse las presentadas por distintas personas que coincidan en lo sustancial con los hechos o sean coincidentes en su contenido.',null),
('aux-ayto-mad:20-ae21e34388','aux-ayto-mad',20,'¿Cuál de estas reclamaciones puede inadmitirse según la Ordenanza de Atención a la Ciudadanía?','["La que reclame responsabilidad patrimonial al Ayuntamiento", "La presentada por una persona jurídica", "La presentada en una Oficina de Atención a la Ciudadanía"]'::jsonb,0,'Art. 29.1 l) OACAE','Entre los supuestos de inadmisión están las que tengan por objeto reclamar responsabilidad patrimonial, las que sean recursos o las del personal sobre su relación de servicio.',null),
('aux-ayto-mad:20-0b4e8c2b71','aux-ayto-mad',20,'¿Pueden inadmitirse las reclamaciones del personal municipal sobre su particular relación de servicio?','["No, deben tramitarse siempre", "Sí, es un supuesto de inadmisión", "Solo si el empleado es personal laboral"]'::jsonb,1,'Art. 29.1 j) OACAE','Las reclamaciones del personal municipal respecto a su particular relación de servicio pueden inadmitirse.',null),
('aux-ayto-mad:20-03e18f415c','aux-ayto-mad',20,'¿Qué órgano puede dar cuenta al Pleno, mediante un informe anual, de las quejas presentadas sobre los servicios municipales?','["La Intervención General", "La Junta de Gobierno", "La Comisión Especial de Sugerencias y Reclamaciones"]'::jsonb,2,'Art. 30 OACAE','La Comisión Especial de Sugerencias y Reclamaciones del art. 136 del Reglamento Orgánico del Pleno puede supervisar la actividad municipal y dar cuenta al Pleno con un informe anual.',null),
('aux-ayto-mad:20-e3089786d6','aux-ayto-mad',20,'Según los criterios de calidad de las respuestas a sugerencias y reclamaciones, ¿cuándo debe responderse?','["Lo más rápido posible, sin agotar el plazo de dos meses", "Al finalizar el plazo de dos meses, tras recabar todos los informes", "En el plazo de diez días hábiles"]'::jsonb,0,'Art. 32 a) OACAE','Uno de los criterios es la respuesta lo más rápida posible, sin necesidad de agotar el plazo de dos meses.',null),
('aux-ayto-mad:20-2de53a76ad','aux-ayto-mad',20,'Cuando en un mismo escrito se formulan varias reclamaciones, ¿cómo se responde?','["Con una única respuesta conjunta", "Con una respuesta individualizada por cada una", "Respondiendo solo a la principal"]'::jsonb,1,'Art. 27.2 OACAE','El órgano puede dividir el escrito y quien lo presentó recibe respuesta individualizada por cada reclamación incluida.',null),
('aux-ayto-mad:20-507a7aff0e','aux-ayto-mad',20,'En los municipios de gran población, para la defensa de los derechos de los vecinos ante la Administración municipal, el Pleno creará:','["Una Comisión especial de Sugerencias y Reclamaciones", "Un Consejo Social de la Ciudad", "Una Oficina del Defensor del Pueblo municipal"]'::jsonb,0,'Art. 132.1 LBRL','El art. 132.1 obliga al Pleno a crear la Comisión especial de Sugerencias y Reclamaciones, cuyo funcionamiento se regula en normas de carácter orgánico.',null),
('aux-ayto-mad:20-f9c5af388d','aux-ayto-mad',20,'El funcionamiento de la Comisión especial de Sugerencias y Reclamaciones de los municipios de gran población se regula en:','["Normas de carácter orgánico", "Un decreto del Alcalde", "Una instrucción de la Junta de Gobierno Local"]'::jsonb,0,'Art. 132.1 LBRL','Según el art. 132.1, su funcionamiento se regulará en normas de carácter orgánico; su regulación tiene naturaleza orgánica (art. 123.1 c).',null),
('aux-ayto-mad:20-228a55d32a','aux-ayto-mad',20,'La Comisión especial de Sugerencias y Reclamaciones deberá dar cuenta al Pleno de las quejas presentadas y de las deficiencias observadas mediante:','["Un informe anual, sin perjuicio de informes extraordinarios por gravedad o urgencia", "Un informe trimestral a la Junta de Gobierno", "Una memoria al final del mandato"]'::jsonb,0,'Art. 132.3 LBRL','Según el art. 132.3, da cuenta mediante un informe anual, con especificación de las sugerencias o recomendaciones no admitidas, y puede hacer informes extraordinarios.',null),
('aux-ayto-mad:20-d125a75913','aux-ayto-mad',20,'Para el desarrollo de las funciones de la Comisión especial de Sugerencias y Reclamaciones:','["Solo están obligados a colaborar los órganos directivos", "Todos los órganos de Gobierno y de la Administración municipal están obligados a colaborar con ella", "La colaboración de los órganos municipales es voluntaria"]'::jsonb,1,'Art. 132.4 LBRL','Así lo establece el art. 132.4.',null),
('aux-ayto-mad:20-f0fb0829b2','aux-ayto-mad',20,'En el régimen común, la Comisión Especial de Sugerencias y Reclamaciones existe, además de en los municipios de gran población, en aquellos en que:','["Lo pida el 10 % de los vecinos", "Lo autorice la Comunidad Autónoma a propuesta del Alcalde", "El Pleno así lo acuerde por mayoría absoluta del número legal de miembros o lo disponga su Reglamento orgánico"]'::jsonb,2,'Art. 20.1 d) LBRL','El art. 20.1 d) prevé su existencia en los municipios del título X y en los demás cuando lo acuerde el Pleno por mayoría absoluta o lo disponga el Reglamento orgánico.',null),
('aux-ayto-mad:20-c1d41e4423','aux-ayto-mad',20,'La Comisión especial de Sugerencias y Reclamaciones podrá, según la Ley 7/1985:','["Anular los actos administrativos que considere ilegales", "Imponer sanciones a los empleados municipales", "Supervisar la actividad de la Administración municipal"]'::jsonb,2,'Art. 132.3 LBRL','Según el art. 132.3, podrá supervisar la actividad de la Administración municipal.',null),
('aux-ayto-mad:21-fcf748eb16','aux-ayto-mad',21,'En Word, la tecla F12 abre:','["La revisión ortográfica y gramatical", "La ayuda de Word en un panel lateral", "El cuadro de diálogo Guardar como"]'::jsonb,2,'Word · Archivo','Mayús+F12 guarda el documento.',null),
('aux-ayto-mad:21-6796565577','aux-ayto-mad',21,'Para que una tabla de Word repita la fila de encabezado en cada página, se usa la opción:','["Combinar celdas", "Dividir tabla por páginas", "Repetir filas de título"]'::jsonb,2,'Word · Tablas','Se encuentra en Disposición de tabla.',null),
('aux-ayto-mad:21-e45040fc53','aux-ayto-mad',21,'El Control de cambios de Word se activa desde la pestaña:','["Insertar", "Inicio", "Revisar"]'::jsonb,2,'Word · Revisar','Registra inserciones, eliminaciones y cambios de formato para aceptarlos o rechazarlos.',null),
('aux-ayto-mad:21-96df6763b2','aux-ayto-mad',21,'En Word, la tecla F7 abre:','["La revisión de ortografía y gramática (panel Editor)", "El cuadro Guardar como", "La vista previa de impresión y la configuración de página"]'::jsonb,0,'Word · Revisar','Es un atajo independiente del idioma.',null),
('aux-ayto-mad:21-a771a40437','aux-ayto-mad',21,'Las notas al pie se insertan en Word desde la pestaña:','["Revisar", "Insertar > Nota", "Referencias"]'::jsonb,2,'Word · Referencias','También desde ahí se insertan notas al final, citas y bibliografía.',null),
('aux-ayto-mad:21-2b8a0e0e6a','aux-ayto-mad',21,'En Word, la tecla F4 sirve para:','["Abrir el cuadro de diálogo Guardar como", "Cerrar el documento activo", "Repetir la última acción"]'::jsonb,2,'Word · Edición','Ctrl+Y también rehace o repite.',null),
('aux-ayto-mad:21-6a1523d3e5','aux-ayto-mad',21,'En la combinación de correspondencia, el documento que contiene el texto común y los campos de combinación se llama:','["Documento principal", "Origen de datos", "Documento maestro de esquema"]'::jsonb,0,'Word · Correspondencia','El origen de datos contiene la lista de destinatarios (por ejemplo, una hoja de Excel).',null),
('aux-ayto-mad:21-09799cdbea','aux-ayto-mad',21,'El botón Mostrar todo (¶) de Word sirve para:','["Ver las marcas de párrafo y otros símbolos de formato ocultos", "Mostrar los comentarios y los cambios registrados", "Mostrar las fuentes instaladas"]'::jsonb,0,'Word · Inicio','Las marcas ocultas no se imprimen.',null),
('aux-ayto-mad:21-6a17730d6c','aux-ayto-mad',21,'Para que encabezados y pies de página distintos se apliquen a partes diferentes del documento, se insertan:','["Saltos de línea", "Saltos de página", "Saltos de sección"]'::jsonb,2,'Word · Disposición','Cada sección puede tener su propia orientación, márgenes y encabezados.',null),
('aux-ayto-mad:21-240af0adec','aux-ayto-mad',21,'La opción de Word que compara dos versiones de un documento y muestra sus diferencias está en:','["Inicio > Buscar", "Revisar > Comparar", "Insertar > Objeto"]'::jsonb,1,'Word · Revisar','Genera un documento con las diferencias como cambios marcados.',null),
('aux-ayto-mad:21-0310f1adcc','aux-ayto-mad',21,'En Word, la vista Esquema es especialmente útil para:','["Organizar la estructura del documento por niveles de título", "Imprimir etiquetas y sobres con los datos de una lista de contactos", "Ver la página como se mostraría en un navegador web, sin saltos de página"]'::jsonb,0,'Word · Vista','Permite subir y bajar niveles y mover bloques.',null),
